#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum S19kPreRuntimeBootstrapRole {
    Publisher,
    Daemon,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum S19kPreRuntimeBootstrapState {
    LiveParent(S19kPreRuntimeBootstrapRole),
    ParentLost(S19kPreRuntimeBootstrapRole),
}

static S19K_STARTUP_TOKEN_ADMITTED: AtomicBool = AtomicBool::new(false);

impl S19kPreRuntimeBootstrapState {
    pub(crate) fn role(self) -> S19kPreRuntimeBootstrapRole {
        match self {
            Self::LiveParent(role) | Self::ParentLost(role) => role,
        }
    }

    fn parent_is_live(self) -> bool {
        matches!(self, Self::LiveParent(_))
    }
}

pub(crate) fn s19k_arm_permanent_pdeathsig_from_env() -> Result<Option<S19kPreRuntimeBootstrapState>>
{
    let role = match std::env::var("DCENT_S19K_STARTUP_BOOTSTRAP") {
        Err(std::env::VarError::NotPresent) => return Ok(None),
        Ok(value) if value == "publisher-v1" => S19kPreRuntimeBootstrapRole::Publisher,
        Ok(value) if value == "daemon-v1" => S19kPreRuntimeBootstrapRole::Daemon,
        Ok(_) | Err(std::env::VarError::NotUnicode(_)) => {
            anyhow::bail!("S19k pre-runtime bootstrap role is invalid")
        }
    };
    let wrapper_pid = std::env::var("DCENT_S19K_STARTUP_WRAPPER_PID")?.parse::<i32>()?;
    let wrapper_start = std::env::var("DCENT_S19K_STARTUP_WRAPPER_START")?.parse::<u64>()?;
    anyhow::ensure!(
        wrapper_pid > 1 && wrapper_start > 0,
        "S19k bootstrap wrapper tuple is invalid"
    );
    if role == S19kPreRuntimeBootstrapRole::Publisher {
        let expected = [
            ("DCENT_S19K_STARTUP_BOOTSTRAP", "publisher-v1".to_string()),
            ("DCENT_S19K_STARTUP_WRAPPER_PID", wrapper_pid.to_string()),
            (
                "DCENT_S19K_STARTUP_WRAPPER_START",
                wrapper_start.to_string(),
            ),
            ("PATH", "/usr/bin:/bin:/usr/sbin:/sbin".to_string()),
        ]
        .into_iter()
        .map(|(key, value)| (key.as_bytes().to_vec(), value.into_bytes()))
        .collect::<BTreeMap<_, _>>();
        let actual = std::env::vars_os()
            .map(|(key, value)| {
                (
                    key.as_os_str().as_bytes().to_vec(),
                    value.as_os_str().as_bytes().to_vec(),
                )
            })
            .collect::<BTreeMap<_, _>>();
        anyhow::ensure!(
            actual == expected,
            "S19k journal publisher environment is not the exact env-i allowlist"
        );
    }
    // SAFETY: prctl is invoked with the documented scalar PR_SET/GET_PDEATHSIG
    // contracts and a valid mutable pointer for GET. No borrowed Rust memory
    // escapes the call.
    let set_result = unsafe { libc::prctl(libc::PR_SET_PDEATHSIG, libc::SIGKILL, 0, 0, 0) };
    anyhow::ensure!(
        set_result == 0,
        "S19k cannot arm permanent PDEATHSIG=SIGKILL"
    );
    let mut observed = 0i32;
    let get_result =
        unsafe { libc::prctl(libc::PR_GET_PDEATHSIG, &mut observed as *mut i32, 0, 0, 0) };
    anyhow::ensure!(
        get_result == 0 && observed == libc::SIGKILL,
        "S19k permanent PDEATHSIG readback is not SIGKILL"
    );
    let current_ppid = unsafe { libc::getppid() };
    if current_ppid == wrapper_pid {
        let stat = std::fs::read_to_string(format!("/proc/{wrapper_pid}/stat"))?;
        let (_, rest) = stat
            .rsplit_once(") ")
            .context("S19k bootstrap wrapper stat is malformed")?;
        let fields = rest.split_whitespace().collect::<Vec<_>>();
        anyhow::ensure!(
            fields.len() >= 20
                && fields[19].parse::<u64>()? == wrapper_start
                && !matches!(fields[0], "Z" | "X" | "x"),
            "S19k bootstrap wrapper lifetime is not exact/nonterminal"
        );
        match role {
            S19kPreRuntimeBootstrapRole::Publisher => s19k_require_exact_publisher_fd_set()?,
            S19kPreRuntimeBootstrapRole::Daemon => {
                s19k_require_exact_daemon_fd_set(None)?;
            }
        }
        return Ok(Some(S19kPreRuntimeBootstrapState::LiveParent(role)));
    }
    anyhow::ensure!(
        current_ppid == 1,
        "S19k bootstrap parent is neither the expected wrapper nor init"
    );
    let original_is_still_live = std::fs::read_to_string(format!("/proc/{wrapper_pid}/stat"))
        .ok()
        .and_then(|stat| stat.rsplit_once(") ").map(|(_, rest)| rest.to_string()))
        .and_then(|rest| {
            let fields = rest.split_whitespace().collect::<Vec<_>>();
            (fields.len() >= 20).then(|| (fields[0].to_string(), fields[19].parse::<u64>().ok()))
        })
        .is_some_and(|(state, start)| {
            start == Some(wrapper_start) && !matches!(state.as_str(), "Z" | "X" | "x")
        });
    anyhow::ensure!(
        !original_is_still_live,
        "S19k bootstrap was reparented while the exact wrapper remains live"
    );
    match role {
        S19kPreRuntimeBootstrapRole::Publisher => s19k_require_exact_publisher_fd_set()?,
        S19kPreRuntimeBootstrapRole::Daemon => {
            s19k_require_exact_daemon_fd_set(None)?;
        }
    }
    Ok(Some(S19kPreRuntimeBootstrapState::ParentLost(role)))
}

