// P1.2 fix (Audit C F-004): Bible/memory rule cap is ~50 work-frames/sec on
// serial work dispatch. The previous
// BM1362 values (1 ms Ã— 128 burst = 128,000 frames/sec) violated by 2,560Ã—
// and were the most likely root cause of the live `a lab unit` zero-nonce regime â€”
// FPGA WORK_TX FIFO saturated instantly with stale work the chips couldn't
// consume. New BM1362 values: 20 ms interval Ã— 1 burst = 50 frames/sec, at
// the documented cap.
const BM1368_DISPATCH_INTERVAL_MS: u64 = 25;
const BM1362_DISPATCH_INTERVAL_MS: u64 = 20;
const DEFAULT_DISPATCH_INTERVAL_MS: u64 = 50;

/// Per-step dwell between Track-1 ladder SetAddress frames (S19k AML BM1366).
///
/// Bitmain's own software enumeration never streams SetAddress frames
/// back-to-back: the S17 BM1397 factory test jig sleeps `usleep(2000)` after
/// every `BM1397_set_address` (`BM1397_software_set_address`), and the S19k Pro
/// BM1366 jig paces the identical per-chip loop at 10 ms
/// (`BM1366_WIRE_BRINGUP.md` §B1 stage 3). A zero-gap 3 Mbaud burst leaves
/// mid-chain plan addresses deterministically unlatched on the live S19k
/// (attempts 6/7: 22-of-77 plan addresses had no responder while every
/// observed responder stayed on-plan), so the stock cadence is load-bearing.
const S19K_TRACK1_LADDER_STEP_MS: u64 = 10;

/// Plan addresses still unclaimed after one parsed coverage window, or `None`
/// when any responder already holds an off-plan address.
///
/// Pure diff for the Track-1 re-enrollment pass: a parsed window whose
/// responder set is a subset of the configured plan can be repaired by
/// re-sending SetAddress for exactly the unclaimed slots (only unaddressed
/// chips latch a SetAddress), while an off-plan responder set means the
/// assignment shifted and blind fills cannot converge — the caller must keep
/// failing closed instead of repairing.
fn s19k_missing_plan_addresses(
    expected_plan: &[u8],
    observed_responders: &[u8],
) -> Option<Vec<u8>> {
    // 2026-08-29 shared-contract rebase: this diff IS the transport-neutral
    // `re_enrollment_addresses` contract in `dcentrald-common` (subset check,
    // then ascending difference) — the S19k Track-1 re-enrollment pass now
    // delegates to it instead of carrying a second copy. The wrapper name is
    // kept so every source-text pin and transcript reference stays stable;
    // the existing diff/refusal unit test pins the delegation's behavior.
    dcentrald_common::serial_chain_proof::re_enrollment_addresses(
        expected_plan,
        observed_responders,
    )
}

/// Salvage a coverage window whose plan-sized prefix is clean but whose tail
/// is unparseable (live attempt 9, 2026-08-28, `attempt9-bounded-work-proof`:
/// ttyS1 windows carried the exact 77-frame plan followed by indices 77..102+
/// rejected as `JobResponseTrailer` garbage on all three retries — late
/// ladder/echo traffic after the full plan response set).
///
/// The whole-burst validator rejects such a window outright by design (a
/// noisy stream must not authorize family-specific writes). Salvage re-runs
/// that same validator on the plan-sized prefix ONLY when the rejection
/// proves the tail is pure noise: every rejected frame must lie beyond the
/// prefix AND every tail frame must have been rejected, so a parseable tail
/// frame (a real duplicate response) can never be hidden by the slice. The
/// prefix is then held to the identical full-validator standard; admission
/// strictness on the plan itself is unchanged and the caller quarantines the
/// tail as logged evidence.
fn s19k_salvage_plan_prefix_window(
    error: &SerialChipAddressWindowError,
    responses: &[Vec<u8>],
    plan_size: usize,
) -> Option<ValidatedSerialChipAddressWindow> {
    let rejected = match error {
        SerialChipAddressWindowError::Rejected(list) => list,
        _ => return None,
    };
    if responses.len() <= plan_size || rejected.len() != responses.len() - plan_size {
        // A parseable frame beyond the prefix (real duplicate) or a window
        // no longer than the plan is never salvageable.
        return None;
    }
    if rejected
        .iter()
        .any(|entry| entry.response_index < plan_size)
    {
        // A bad frame INSIDE the plan prefix stays fatal.
        return None;
    }
    validate_serial_chip_address_window(responses[..plan_size].iter().map(Vec::as_slice)).ok()
}

/// Attempt-7 fold-in (session follow-up 3): the coverage failure diagnostics
/// rendered only the underlying window error, so the parsed-but-unusable
/// address sets were never visible in the transcript. Render the duplicate
/// (occupied-by-more-than-one-responder) and off-plan (outside the expected
/// ladder) address lists for desk triage. Diagnostic-only: callers keep
/// failing closed exactly as before.
fn s19k_coverage_denial_detail(duplicate_addresses: &[u8], off_plan_responders: &[u8]) -> String {
    let fmt = |addresses: &[u8]| {
        if addresses.is_empty() {
            "none".to_string()
        } else {
            addresses
                .iter()
                .map(|address| format!("{address:02X}"))
                .collect::<Vec<_>>()
                .join(",")
        }
    };
    format!(
        " duplicate_addresses=[{}] off_plan_responders=[{}]",
        fmt(duplicate_addresses),
        fmt(off_plan_responders)
    )
}

/// Responders observed outside the expected ladder plan (attempt-7 evidence:
/// every observed responder stayed on-plan while 22 plan addresses had no
/// responder — the off-plan list distinguishes a shifted assignment from a
/// gapped one).
fn s19k_off_plan_responders(expected_plan: &[u8], observed_responders: &[u8]) -> Vec<u8> {
    let expected: BTreeSet<u8> = expected_plan.iter().copied().collect();
    observed_responders
        .iter()
        .copied()
        .filter(|address| !expected.contains(address))
        .collect()
}

/// Duplicate assigned addresses computed straight from raw response bodies
/// when the window validator itself refused (attempt-7 site-2 render). Only
/// parseable same-family ChipAddress bodies contribute, so a rejected window
/// never fabricates addresses.
fn s19k_duplicate_addresses_from_raw_responses(responses: &[Vec<u8>]) -> Vec<u8> {
    let mut counts = BTreeMap::<u8, usize>::new();
    for response in responses {
        if let Ok(observation) = parse_serial_chip_address_body(response) {
            *counts.entry(observation.responder_address()).or_default() += 1;
        }
    }
    counts
        .into_iter()
        .filter_map(|(address, count)| (address != 0 && count > 1).then_some(address))
        .collect()
}

/// Attempt-8d evidence (2026-08-28, `attempt8-first-share-20260828`): with the
/// paced ladder landed, a session that never observes a pool `clean_jobs`
/// (`S19kCleanFunnel::cleans == 0` for the whole run) still refuses to submit
/// fully header-validated shares whose nonce also solves a wrap-retired
/// generation's ticket target. Nonce `0xD59CA636` (ttyS1 17:59:01.341,
/// ttyS2 17:59:09.165) printed `meets_pool_target=true submit_allowed=false`
/// and both extractions were dropped, even though the full 80-byte header
/// hash met the resolved (never-cleaned, still pool-live) work entry's share
/// target.
///
/// The wrap-retired refusal is load-bearing only in the post-clean regime,
/// where "retired" means the pool has already flushed that template. In a
/// never-cleaned session every earlier pool job is still valid stratum work,
/// so a share that hashes below its own resolved entry's target is
/// submittable under exactly that entry. Fail-closed unchanged everywhere
/// else: a mid-run clean (funnel armed) keeps the strict refusal, and a nonce
/// that does not meet the resolved target is still refused.
fn s19k_track1_wrap_retired_no_clean_submit_allowed(
    midrun_cleans: u32,
    retired_meets: bool,
    latest_meets_target: bool,
) -> bool {
    midrun_cleans == 0 && retired_meets && latest_meets_target
}

/// What a duplicate per-path extraction of an already-seen share candidate
/// owes the bounded-work proof (attempt-8d evidence: the pool-accepted nonce
/// `0x1CC0FC36` was rx-crc-admitted and share-attributed on `/dev/ttyS1` at
/// 17:57:16.925 and on `/dev/ttyS2` at 17:57:18.248 — one physical nonce
/// stream observed by both logical UARTs — yet only the submitting path was
/// ever credited, so the proof stayed `accepted_paths={"/dev/ttyS1"}`).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum S19kDuplicateSharePathCredit {
    /// The pool already accepted this exact share: credit this path now.
    CreditAcceptedNow,
    /// The share was submitted and its pool result is still pending: record
    /// the path so an acceptance can credit it later.
    RecordPendingResult,
    /// Not a submitted-share duplicate (or the path is not a required TX
    /// path, or already credited): nothing to do.
    NoCredit,
}

fn s19k_track1_duplicate_rx_share_credit(
    origin_known_submitted: bool,
    pool_accepted: bool,
    path_is_required_tx: bool,
    path_already_credited: bool,
) -> S19kDuplicateSharePathCredit {
    if !path_is_required_tx || path_already_credited {
        return S19kDuplicateSharePathCredit::NoCredit;
    }
    if pool_accepted {
        S19kDuplicateSharePathCredit::CreditAcceptedNow
    } else if origin_known_submitted {
        S19kDuplicateSharePathCredit::RecordPendingResult
    } else {
        S19kDuplicateSharePathCredit::NoCredit
    }
}

/// Equality-keyed duplicate-path record for one submitted share key.
/// `S19kSubmittedShareKey` embeds `WorkGeneration`, which is not `Ord`, so
/// the pending-result table is a small bounded vector (it only ever holds
/// keys whose origin is still live in the capacity-bounded submitted-origin
/// sidecar) instead of an ordered map.
fn s19k_record_duplicate_rx_share_path(
    pending: &mut Vec<(S19kSubmittedShareKey, BTreeSet<String>)>,
    key: S19kSubmittedShareKey,
    path: &str,
) {
    if let Some(paths) = pending
        .iter_mut()
        .find(|(candidate, _)| *candidate == key)
        .map(|(_, paths)| paths)
    {
        paths.insert(path.to_string());
        return;
    }
    if pending.len() >= S19K_SUBMITTED_SHARE_ORIGIN_CAPACITY {
        pending.remove(0);
    }
    let mut paths = BTreeSet::new();
    paths.insert(path.to_string());
    pending.push((key, paths));
}

/// Drain the recorded duplicate paths for one share key (pool result arrived).
fn s19k_take_duplicate_rx_share_paths(
    pending: &mut Vec<(S19kSubmittedShareKey, BTreeSet<String>)>,
    key: &S19kSubmittedShareKey,
) -> BTreeSet<String> {
    let Some(position) = pending.iter().position(|(candidate, _)| candidate == key) else {
        return BTreeSet::new();
    };
    pending.remove(position).1
}

// ---------------------------------------------------------------------------
// Work-dispatch safety (shared pure policy â†’ serial adapter)
// ---------------------------------------------------------------------------

/// Map serial-engine bring-up observations into the shared matrix.
///
/// Pure and host-testable â€” serial must not invent a second admission matrix.
pub(crate) fn serial_work_dispatch_inputs(
    soc_watchdog: WatchdogSafetyState,
    heartbeat_requirement: HeartbeatRequirement,
    controller_heartbeats: &[ControllerHeartbeatObservation],
    thermal: ThermalSafetyState,
) -> WorkDispatchSafetyInputs {
    WorkDispatchSafetyInputs {
        watchdog: soc_watchdog,
        heartbeat_requirement,
        controllers: controller_heartbeats.to_vec(),
        thermal,
        previously_revoked: false,
    }
}

/// Serial SoC watchdog contribution.
///
/// - Path does not own a SafetyWatchdogOwner (legacy) â†’ DisabledByConfiguration
/// - Exact path after successful `enter_exact_serial_mining` â†’ Armed
/// - Exact path expected ownership but enter failed â†’ Unavailable
pub(crate) fn serial_watchdog_safety_state(
    owns_soc_watchdog: bool,
    mining_enter_ok: bool,
) -> WatchdogSafetyState {
    match (owns_soc_watchdog, mining_enter_ok) {
        (false, _) => WatchdogSafetyState::DisabledByConfiguration,
        (true, true) => WatchdogSafetyState::Armed,
        (true, false) => WatchdogSafetyState::Unavailable,
    }
}

/// Heartbeat pillar for serial PIC / NoPic / passthrough custody.
pub(crate) fn serial_heartbeat_inputs(
    passthrough: bool,
    nopic: bool,
    dspic_addr: Option<u8>,
    dspic_heartbeat_ok: bool,
    cycle_id: u64,
) -> (HeartbeatRequirement, Vec<ControllerHeartbeatObservation>) {
    if passthrough || nopic {
        return (HeartbeatRequirement::NoneRequired, Vec::new());
    }
    let Some(addr) = dspic_addr else {
        // Exact AM2 without a known dsPIC addr cannot honestly claim HB green.
        return (HeartbeatRequirement::AllControllersSameCycle, Vec::new());
    };
    (
        HeartbeatRequirement::AllControllersSameCycle,
        vec![ControllerHeartbeatObservation {
            controller_id: addr,
            heartbeat_ok: dspic_heartbeat_ok,
            cycle_id,
        }],
    )
}

/// Thermal pillar after pre-stratum proof (AM2) or Amlogic cooling owner.
pub(crate) fn serial_thermal_safety_state(
    thermal_proof_present: bool,
    thermal_emergency: bool,
) -> ThermalSafetyState {
    if thermal_emergency {
        ThermalSafetyState::Emergency
    } else if thermal_proof_present {
        ThermalSafetyState::Ready
    } else {
        // Paths without a thermal owner (legacy residual / passthrough) do not
        // invent Ready â€” NotReady refuses dispatch fail-closed.
        ThermalSafetyState::NotReady
    }
}

/// Admit standard UART work dispatch on the serial lifecycle latch.
pub(crate) fn serial_admit_standard_work_dispatch<'a>(
    life: &'a mut WorkDispatchLifecycle,
    inputs: &WorkDispatchSafetyInputs,
) -> Result<&'a WorkDispatchAdmissionReceipt, WorkDispatchSafetyError> {
    life.admit(inputs)
}

/// Terminal revoke for the serial lifecycle.
pub(crate) fn serial_revoke_work_dispatch(
    life: &mut WorkDispatchLifecycle,
    cause: DispatchRevocationCause,
    profile_max_pwm: u8,
) -> (SafetyAction, bool) {
    life.revoke(cause, profile_max_pwm)
}

/// Revoke work dispatch and honor `stop_feed` by terminally closing SoC WDT
/// feed ownership (exact `WatchdogFeedStopSignal` and/or legacy feed owner).
///
/// Stock parity: a mid-run revoke must stop kicks immediately, not only during
/// late SHUTDOWN teardown.
pub(crate) fn serial_revoke_and_stop_watchdog_feed(
    life: &mut WorkDispatchLifecycle,
    cause: DispatchRevocationCause,
    profile_max_pwm: u8,
    exact_feed_stop: Option<&crate::runtime::watchdog_feed_gate::WatchdogFeedStopSignal>,
    legacy_feed_owner: &mut Option<crate::daemon::LegacyWatchdogFeedOwner>,
) -> SafetyAction {
    let (action, stop_feed) = serial_revoke_work_dispatch(life, cause, profile_max_pwm);
    if stop_feed {
        if let Some(sig) = exact_feed_stop {
            sig.close_terminal_lock_free();
        }
        if let Some(owner) = legacy_feed_owner.as_mut() {
            owner.close_terminal();
        }
    }
    action
}
const BM1368_MAX_WORK_ITEMS_PER_SEC: usize = 40;
const DEFAULT_MAX_WORK_ITEMS_PER_SEC: usize = 20;
const DEFAULT_SERIAL_WORK_QUEUE_DEPTH: usize = 16;
const BM1362_SERIAL_WORK_QUEUE_DEPTH: usize = 512;
/// live408: 256-deep drop-oldest + take_dispatch at ~40 Hz burned job_ids
/// 3× UART send (MULTI died at wrap-3 / T+60). Outstanding stays 256;
/// this is a 4-slot UART hold so produce matches the wire.
const BM1366_SERIAL_WORK_QUEUE_DEPTH: usize =
    dcentrald_common::s19k_bm1366_share::S19K_BM1366_HOLD_QUEUE_DEPTH;
const DEFAULT_SERIAL_TX_BURST: usize = 3;
const BM1362_SERIAL_TX_BURST: usize = 1;
/// Half-duplex BM1366: one 21 36 per actor loop. Burst-3 occupies the wire
/// ( live401: ttyS1 died T+21s, ttyS2 T+61s, TX continued).
const BM1366_SERIAL_TX_BURST: usize = 1;
/// live403: `for _ in 0..31` after the first nonce made 1 TX per ~32 RX
/// (792 MULTI_RX / 25 UART work). BM1366 skips that follow-up drain.
const BM1366_SERIAL_RX_FOLLOWUP_DRAIN: usize = 0;
const DEFAULT_SERIAL_RX_FOLLOWUP_DRAIN: usize = 31;
/// live404 hashed 21 TH/s through T+25 after a one-shot discover re-arm, then
/// both ports cliffed ~T+30. Refresh ticket+HCN on the actor (not GPIO / native).
const BM1366_PASSTHROUGH_REARM_EVERY_S: u64 = 8;
/// live405 S1 died T+71.2s at wrap-5 (80 ms → 102.4 s). live408 died at
/// wrap-3 (80 ms × 768 = 61.44 s) after the share fix. 120 ms puts wrap-3
/// at 92.16 s so same-run T+90 is not wrap-3-blocked.
const BM1366_SERIAL_TX_MIN_INTERVAL_MS: u64 = 120;
const WORK_HISTORY_PER_ID: usize = dcentrald_common::DEFAULT_WORK_HISTORY_PER_ID;
const BM1398_WORK_HISTORY_PER_ID: usize = dcentrald_common::BM1398_WORK_HISTORY_PER_ID;
const AMLOGIC_TEMP_STARTUP_GRACE_S: u64 = 30;
const AMLOGIC_TEMP_MISS_LIMIT: u8 = 3;
const AMLOGIC_THERMAL_RESTART_DELAY_S: u64 = 60;
const AMLOGIC_FAN_SPINUP_ATTEMPTS: u32 = 3;
const AMLOGIC_FAN_SPINUP_RETRY_DELAY: Duration = Duration::from_millis(250);
const APW12_139_ASSUMED_FW: u8 = 0x71;
// A started service-backed heartbeat has a four-second caller-side wall-clock
// bound in the HAL. Exact-route cancellation is published before terminal I/O,
// and this larger join window normally reclaims the heartbeat actor before its
// controller view can escape the route owner. Scheduler or kernel anomalies
// remain negative evidence and take the out-of-band hard-stop path.
const RUNTIME_THREAD_STOP_TIMEOUT: Duration = Duration::from_secs(5);

/// One pre-energization decision for voltage-controller actor topology. Exact
/// watchdog routes are admitted only when resolved ASIC identity and observed
/// controller evidence agree; later service/heartbeat branches consume this
/// value instead of re-deriving exact-route behavior from `nopic`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SerialActorTopology {
    ExactNoPic,
    ExactS19kTrack1,
    ExactAm2Bm1362,
    LegacyNoPic,
    LegacyPic,
}

impl SerialActorTopology {
    fn admit(
        native_nopic_power_owner: bool,
        s19k_track1_handoff: bool,
        is_bm1362: bool,
        observed_nopic: bool,
    ) -> Result<Self> {
        anyhow::ensure!(
            [native_nopic_power_owner, s19k_track1_handoff, is_bm1362]
                .into_iter()
                .filter(|selected| *selected)
                .count()
                <= 1,
            "serial ASIC identity selected mutually exclusive exact NoPic, S19k Track-1, and AM2 routes"
        );
        match (
            native_nopic_power_owner,
            s19k_track1_handoff,
            is_bm1362,
            observed_nopic,
        ) {
            (true, false, false, true) => Ok(Self::ExactNoPic),
            (true, false, false, false) => anyhow::bail!(
                "exact NoPic ASIC identity conflicts with observed PIC-controller topology"
            ),
            (false, true, false, true) => Ok(Self::ExactS19kTrack1),
            (false, true, false, false) => anyhow::bail!(
                "exact S19k Track-1 identity conflicts with observed PIC-controller topology"
            ),
            (false, false, true, false) => Ok(Self::ExactAm2Bm1362),
            (false, false, true, true) => anyhow::bail!(
                "exact AM2 BM1362 ASIC identity conflicts with observed NoPic topology"
            ),
            (false, false, false, true) => Ok(Self::LegacyNoPic),
            (false, false, false, false) => Ok(Self::LegacyPic),
            _ => unreachable!("mutual-exclusion check above"),
        }
    }

    fn is_exact(self) -> bool {
        matches!(
            self,
            Self::ExactNoPic | Self::ExactS19kTrack1 | Self::ExactAm2Bm1362
        )
    }

    fn is_nopic(self) -> bool {
        matches!(
            self,
            Self::ExactNoPic | Self::ExactS19kTrack1 | Self::LegacyNoPic
        )
    }
}

/// Runtime-thread owner shared by legacy serial routes and the two exact
/// watchdog compositions. Exact variants can be activated only once from the
/// watchdog-issued actor owner; a pending legacy route is materialized lazily
/// before its first registration.
enum SerialRuntimeThreads {
    Pending(Option<CancellationToken>),
    Legacy(RuntimeThreadGuard),
    NoPic(FixedThreadRosterGuard<NoPicSerialThreadSlot>),
    Am2(FixedThreadRosterGuard<Am2SerialThreadSlot>),
}

enum ExactSerialRuntimeActorAdmission {
    NoPic(ThreadRosterRuntimeAdmission<NoPicSerialThreadSlot>),
    Am2 {
        roster: ThreadRosterRuntimeAdmission<Am2SerialThreadSlot>,
        apw_topology: Am2ApwActorTopology,
    },
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Am2ApwActorTopology {
    SmartPsu,
    ExplicitBypass,
}

enum ExactSerialActorCloseoutAdmission {
    NoPicPreRuntime(ThreadRosterPreRuntimeCloseout<NoPicSerialThreadSlot>),
    NoPicRuntime(ThreadRosterRuntimeAdmission<NoPicSerialThreadSlot>),
    Am2PreRuntime(ThreadRosterPreRuntimeCloseout<Am2SerialThreadSlot>),
    Am2Runtime(ThreadRosterRuntimeAdmission<Am2SerialThreadSlot>),
}

impl SerialRuntimeThreads {
    fn new() -> Self {
        Self::Pending(Some(CancellationToken::new()))
    }

    fn activate_nopic(&mut self, owner: ThreadRosterOwner<NoPicSerialThreadSlot>) -> Result<()> {
        let token = match self {
            Self::Pending(token) => token
                .take()
                .context("serial runtime cancellation owner was already consumed")?,
            _ => anyhow::bail!("NoPic serial actor roster was activated after registration began"),
        };
        let mut guard = owner.activate(token);
        guard.resolve_conditional(
            NoPicSerialThreadSlot::Track1SafetySampler,
            false,
            "native NoPic route has no inherited-rails Track-1 safety sampler",
        )?;
        *self = Self::NoPic(guard);
        Ok(())
    }

    fn activate_s19k_track1(
        &mut self,
        owner: ThreadRosterOwner<NoPicSerialThreadSlot>,
    ) -> Result<()> {
        let token = match self {
            Self::Pending(token) => token
                .take()
                .context("serial runtime cancellation owner was already consumed")?,
            _ => anyhow::bail!("S19k Track-1 actor roster was activated after registration began"),
        };
        *self = Self::NoPic(owner.activate(token));
        Ok(())
    }

    fn spawn_track1_safety_sampler(
        &mut self,
        spawn: impl FnOnce(CancellationToken) -> Result<std::thread::JoinHandle<()>>,
    ) -> Result<()> {
        match self {
            Self::NoPic(guard) => {
                let cancellation = guard.cancellation_token();
                let slot = guard.reserve(NoPicSerialThreadSlot::Track1SafetySampler)?;
                let handle = spawn(cancellation)?;
                slot.attach(handle);
                Ok(())
            }
            _ => anyhow::bail!(
                "Track-1 safety sampler requires the exact NoPic-compatible actor roster"
            ),
        }
    }

    fn activate_am2(&mut self, owner: ThreadRosterOwner<Am2SerialThreadSlot>) -> Result<()> {
        let token = match self {
            Self::Pending(token) => token
                .take()
                .context("serial runtime cancellation owner was already consumed")?,
            _ => anyhow::bail!("AM2 serial actor roster was activated after registration began"),
        };
        *self = Self::Am2(owner.activate(token));
        Ok(())
    }

    fn ensure_legacy(&mut self) -> Result<()> {
        if let Self::Pending(token) = self {
            let token = token
                .take()
                .context("serial runtime cancellation owner was already consumed")?;
            *self = Self::Legacy(RuntimeThreadGuard::new(token));
        }
        Ok(())
    }

    fn cancellation_token(&mut self) -> Result<CancellationToken> {
        self.ensure_legacy()?;
        match self {
            Self::Legacy(guard) => Ok(guard.cancellation_token()),
            Self::NoPic(guard) => Ok(guard.cancellation_token()),
            Self::Am2(guard) => Ok(guard.cancellation_token()),
            Self::Pending(_) => unreachable!("legacy activation handled above"),
        }
    }

    fn request_stop(&self) {
        match self {
            Self::Pending(Some(token)) => token.cancel(),
            Self::Pending(None) => {}
            Self::Legacy(guard) => guard.request_stop(),
            Self::NoPic(guard) => guard.request_stop(),
            Self::Am2(guard) => guard.request_stop(),
        }
    }

    fn reserve_am2(
        &mut self,
        slot: Am2SerialThreadSlot,
    ) -> Result<ThreadSlotReservation<'_, Am2SerialThreadSlot>> {
        match self {
            Self::Am2(guard) => guard.reserve(slot),
            _ => anyhow::bail!("AM2 serial actor reservation used outside the exact AM2 roster"),
        }
    }

    fn resolve_am2_apw(&mut self, smart_psu_present: bool) -> Result<()> {
        match self {
            Self::Am2(guard) => guard.resolve_conditional(
                Am2SerialThreadSlot::ApwHeartbeat,
                smart_psu_present,
                "exact AM2 route uses an explicit non-smart PSU bypass",
            ),
            _ => anyhow::bail!("AM2 APW topology resolution used outside the exact AM2 roster"),
        }
    }

    fn reserve_serial_io(&mut self, legacy_name: &'static str) -> Result<SerialIoReservation<'_>> {
        self.ensure_legacy()?;
        match self {
            Self::Legacy(guard) => Ok(SerialIoReservation::Legacy { guard, legacy_name }),
            Self::NoPic(guard) => {
                anyhow::ensure!(
                    legacy_name == NoPicSerialThreadSlot::SerialIo.name(),
                    "NoPic exact serial roster refuses alternate I/O actor {legacy_name}"
                );
                Ok(SerialIoReservation::NoPic(
                    guard.reserve(NoPicSerialThreadSlot::SerialIo)?,
                ))
            }
            Self::Am2(guard) => {
                anyhow::ensure!(
                    legacy_name == Am2SerialThreadSlot::SerialIo.name(),
                    "AM2 exact serial roster refuses alternate I/O actor {legacy_name}"
                );
                Ok(SerialIoReservation::Am2(
                    guard.reserve(Am2SerialThreadSlot::SerialIo)?,
                ))
            }
            Self::Pending(_) => unreachable!("legacy activation handled above"),
        }
    }

    fn spawn_serial_io(
        &mut self,
        actor_name: &'static str,
        spawn: impl FnOnce() -> Result<std::thread::JoinHandle<()>>,
    ) -> Result<()> {
        let slot = self.reserve_serial_io(actor_name)?;
        let handle = spawn()?;
        slot.attach(handle);
        Ok(())
    }

    fn reserve_pic_heartbeat(&mut self) -> Result<ThreadSlotReservation<'_, Am2SerialThreadSlot>> {
        match self {
            Self::Am2(guard) => guard.reserve(Am2SerialThreadSlot::DspicHeartbeat),
            Self::Pending(_) | Self::Legacy(_) => anyhow::bail!(
                "legacy serial routes cannot register a PIC heartbeat; exact AM2 BM1362 actor authority is required"
            ),
            Self::NoPic(_) => {
                anyhow::bail!("NoPic exact serial route cannot register a dsPIC heartbeat")
            }
        }
    }

    fn spawn_pic_heartbeat(
        &mut self,
        spawn: impl FnOnce() -> Result<std::thread::JoinHandle<()>>,
    ) -> Result<()> {
        let slot = self.reserve_pic_heartbeat()?;
        let handle = spawn()?;
        slot.attach(handle);
        Ok(())
    }

    fn seal_exact_runtime(
        &mut self,
        am2_apw_topology: Option<Am2ApwActorTopology>,
    ) -> Result<ExactSerialRuntimeActorAdmission> {
        match self {
            Self::NoPic(guard) => {
                anyhow::ensure!(
                    am2_apw_topology.is_none(),
                    "NoPic actor admission cannot consume AM2 APW topology"
                );
                Ok(ExactSerialRuntimeActorAdmission::NoPic(
                    guard.seal_runtime_admission()?,
                ))
            }
            Self::Am2(guard) => {
                let apw_topology =
                    am2_apw_topology.context("AM2 actor admission requires typed APW topology")?;
                let roster = guard.seal_runtime_admission()?;
                match apw_topology {
                    Am2ApwActorTopology::SmartPsu => anyhow::ensure!(
                        roster.running(Am2SerialThreadSlot::ApwHeartbeat),
                        "smart-APW runtime requires a registered APW-heartbeat actor"
                    ),
                    Am2ApwActorTopology::ExplicitBypass => anyhow::ensure!(
                        roster.topology_not_applicable(Am2SerialThreadSlot::ApwHeartbeat),
                        "explicit APW bypass requires topology non-applicability evidence"
                    ),
                }
                Ok(ExactSerialRuntimeActorAdmission::Am2 {
                    roster,
                    apw_topology,
                })
            }
            Self::Pending(_) | Self::Legacy(_) => {
                anyhow::bail!("exact serial actor admission used outside an exact route roster")
            }
        }
    }

    async fn stop_and_join(
        &mut self,
        timeout: Duration,
        closeout_admission: Option<ExactSerialActorCloseoutAdmission>,
    ) -> SerialRuntimeThreadStop {
        if let Err(error) = self.ensure_legacy() {
            return SerialRuntimeThreadStop::InitializationFailed(error);
        }
        match self {
            Self::Legacy(guard) => {
                SerialRuntimeThreadStop::Legacy(guard.stop_and_join(timeout).await)
            }
            Self::NoPic(guard) => {
                let preparation = match closeout_admission {
                    Some(ExactSerialActorCloseoutAdmission::NoPicPreRuntime(admission)) => guard
                        .resolve_unstarted_conditionals_for_closeout(
                            admission,
                            "exact NoPic runtime actor phase was not admitted before closeout",
                        ),
                    Some(ExactSerialActorCloseoutAdmission::NoPicRuntime(admission)) => {
                        guard.validate_runtime_admitted_closeout(admission)
                    }
                    _ => {
                        guard.reject_unbound_closeout();
                        Err(anyhow::anyhow!(
                            "NoPic actor roster closeout lacks matching route-domain authority"
                        ))
                    }
                };
                if let Err(error) = preparation {
                    warn!(%error, "NoPic actor roster closeout admission failed");
                }
                SerialRuntimeThreadStop::NoPic(guard.stop_and_join(timeout).await)
            }
            Self::Am2(guard) => {
                let preparation = match closeout_admission {
                    Some(ExactSerialActorCloseoutAdmission::Am2PreRuntime(admission)) => guard
                        .resolve_unstarted_conditionals_for_closeout(
                            admission,
                            "exact AM2 runtime actor phase was not admitted before closeout",
                        ),
                    Some(ExactSerialActorCloseoutAdmission::Am2Runtime(admission)) => {
                        guard.validate_runtime_admitted_closeout(admission)
                    }
                    _ => {
                        guard.reject_unbound_closeout();
                        Err(anyhow::anyhow!(
                            "AM2 actor roster closeout lacks matching route-domain authority"
                        ))
                    }
                };
                if let Err(error) = preparation {
                    warn!(%error, "AM2 actor roster closeout admission failed");
                }
                SerialRuntimeThreadStop::Am2(guard.stop_and_join(timeout).await)
            }
            Self::Pending(_) => unreachable!("legacy activation handled above"),
        }
    }
}

enum SerialIoReservation<'a> {
    Legacy {
        guard: &'a mut RuntimeThreadGuard,
        legacy_name: &'static str,
    },
    NoPic(ThreadSlotReservation<'a, NoPicSerialThreadSlot>),
    Am2(ThreadSlotReservation<'a, Am2SerialThreadSlot>),
}

impl SerialIoReservation<'_> {
    fn attach(self, handle: std::thread::JoinHandle<()>) {
        match self {
            Self::Legacy { guard, legacy_name } => guard.push(legacy_name, handle),
            Self::NoPic(slot) => slot.attach(handle),
            Self::Am2(slot) => slot.attach(handle),
        }
    }
}

enum SerialRuntimeThreadStop {
    InitializationFailed(anyhow::Error),
    Legacy(ThreadStopSummary),
    NoPic(ThreadRosterStop<NoPicSerialThreadSlot>),
    Am2(ThreadRosterStop<Am2SerialThreadSlot>),
}

impl SerialRuntimeThreadStop {
    fn any_timed_out(&self) -> bool {
        match self {
            Self::InitializationFailed(_) => true,
            Self::Legacy(stop) => stop.any_timed_out(),
            Self::NoPic(stop) => stop.any_timed_out(),
            Self::Am2(stop) => stop.any_timed_out(),
        }
    }

    fn panicked_worker_names(&self) -> Vec<&'static str> {
        match self {
            Self::InitializationFailed(_) => Vec::new(),
            Self::Legacy(stop) => stop.panicked_worker_names(),
            Self::NoPic(stop) => stop.panicked_worker_names(),
            Self::Am2(stop) => stop.panicked_worker_names(),
        }
    }

    fn into_nopic_receipt(self) -> Result<ThreadRosterQuiescenceReceipt<NoPicSerialThreadSlot>> {
        match self {
            Self::NoPic(stop) => stop
                .into_receipt()
                .context("NoPic exact serial actor roster did not close cleanly"),
            Self::InitializationFailed(error) => Err(error),
            Self::Legacy(_) | Self::Am2(_) => {
                anyhow::bail!("NoPic watchdog closeout received the wrong serial actor roster")
            }
        }
    }

    fn into_am2_receipt(self) -> Result<ThreadRosterQuiescenceReceipt<Am2SerialThreadSlot>> {
        match self {
            Self::Am2(stop) => stop
                .into_receipt()
                .context("AM2 exact serial actor roster did not close cleanly"),
            Self::InitializationFailed(error) => Err(error),
            Self::Legacy(_) | Self::NoPic(_) => {
                anyhow::bail!("AM2 watchdog closeout received the wrong serial actor roster")
            }
        }
    }
}
const AM2_BM1362_SERIAL_FENCE_POLL_INTERVAL: Duration = Duration::from_millis(10);
const NOPIC_WATCHDOG_BRINGUP_GRACE: Duration = Duration::from_secs(120);
const NOPIC_SAFETY_LIVENESS_INTERVAL: Duration = Duration::from_secs(2);
const S19K_TRACK1_WATCHDOG_REQUESTED_TIMEOUT_S: u32 = 30;
const S19K_TRACK1_WATCHDOG_EFFECTIVE_TIMEOUT_S: u32 = 30;
const S19K_TRACK1_WATCHDOG_KICK_INTERVAL_S: u64 = 5;

/// Move-only authority proving the kernel admitted the exact watchdog SLA
/// reviewed for the S19k Track-1 stock-handoff bench.  Keeping this separate
/// from [`WatchdogArmReceipt`] prevents "armed at some timeout" from silently
/// becoming authority to kill the exact stock owner.
#[must_use = "S19k Track-1 watchdog SLA authority must be consumed by the route claim"]
#[derive(Debug)]
struct S19kTrack1WatchdogSlaAdmission;

fn admit_s19k_track1_watchdog_sla(
    receipt: &WatchdogArmReceipt,
) -> Result<S19kTrack1WatchdogSlaAdmission> {
    anyhow::ensure!(
        receipt.requested_timeout_s == S19K_TRACK1_WATCHDOG_REQUESTED_TIMEOUT_S
            && receipt.effective_timeout_s == S19K_TRACK1_WATCHDOG_EFFECTIVE_TIMEOUT_S
            && receipt.kick_interval_s == S19K_TRACK1_WATCHDOG_KICK_INTERVAL_S,
        "S19k Track-1 watchdog SLA refused: required requested/effective/kick={}/{}/{}s, observed {}/{}/{}s",
        S19K_TRACK1_WATCHDOG_REQUESTED_TIMEOUT_S,
        S19K_TRACK1_WATCHDOG_EFFECTIVE_TIMEOUT_S,
        S19K_TRACK1_WATCHDOG_KICK_INTERVAL_S,
        receipt.requested_timeout_s,
        receipt.effective_timeout_s,
        receipt.kick_interval_s,
    );
    Ok(S19kTrack1WatchdogSlaAdmission)
}
const AM2_BM1362_WATCHDOG_BRINGUP_GRACE: Duration = Duration::from_secs(180);
const AM2_BM1362_SAFETY_LIVENESS_INTERVAL: Duration = Duration::from_secs(2);
const AM2_BM1362_REQUIRED_AIRFLOW_MIN_RPM: u32 = 1800;
/// Match the established hybrid-runtime rule: twenty consecutive 1 Hz
/// selected-dsPIC heartbeat failures revoke voltage-maintenance authority.
const AM2_BM1362_PIC_HEARTBEAT_MAX_FAILURES: u32 = 20;
const AM2_BM1362_PIC_HEARTBEAT_ATTEMPT_BUDGET_S: u32 = 3;
const AM2_BM1362_EMERGENCY_CUT_MARGIN_S: u32 = 2;
const AM2_BM1362_MIN_WATCHDOG_TIMEOUT_S: u32 =
    2 * (AM2_BM1362_PIC_HEARTBEAT_ATTEMPT_BUDGET_S + AM2_BM1362_EMERGENCY_CUT_MARGIN_S);
/// Ordinary APW wire loss is allowed three consecutive 1 Hz attempts before
/// explicit cutoff. Typed ownership, safety-generation, policy, and protocol
/// failures bypass this budget and terminate immediately.
const AM2_BM1362_APW_HEARTBEAT_MAX_FAILURES: u32 = 3;
const AM2_BM1362_THERMAL_POLL_TIMEOUT: Duration = Duration::from_secs(3);
const AM2_BM1362_TERMINAL_SAFE_OFF_ATTEMPTS: usize = 2;
const HASHBOARD_EEPROM_WRITE_DENYLIST: [u8; 8] = [0x50, 0x51, 0x52, 0x53, 0x54, 0x55, 0x56, 0x57];

#[derive(Debug)]
struct FanTachSnapshot {
    available: bool,
    expected_channels: usize,
    readings: Vec<(u8, u32)>,
}

const S19K_TRACK1_MIN_SPINNING_FANS: usize = 2;
const S19K_TRACK1_MIN_FAN_RPM: u32 = 2_000;
const S19K_TRACK1_THERMAL_MAX_AGE: Duration = Duration::from_secs(5);

fn serial_published_voltage_mv(configured_voltage_mv: u16, inherited_unread_rail: bool) -> u16 {
    if inherited_unread_rail {
        // Track-1 deliberately inherits the Braiins rail without issuing a
        // voltage command or taking a voltage readback owner. Publishing the
        // configured request here would fabricate an observation; the API's
        // established zero value means unknown/unmeasured voltage.
        0
    } else {
        configured_voltage_mv
    }
}

#[derive(Debug, Clone)]
enum S19kTrack1SafetyUpdate {
    Pending,
    Sample {
        sampled_at: Instant,
        hottest_c: f32,
        temperature_coverage_complete: bool,
        missing_temperature_slots: Vec<u8>,
        tach_available: bool,
        expected_fan_channels: usize,
        fan_readings: Vec<(u8, u32)>,
        spinning_fans: usize,
    },
    Failed(String),
}

impl S19kTrack1SafetyUpdate {
    fn admits_watchdog_liveness(&self, now: Instant, dangerous_temp_c: f32) -> bool {
        matches!(
            self,
            Self::Sample {
                sampled_at,
                hottest_c,
                temperature_coverage_complete: true,
                tach_available: true,
                expected_fan_channels,
                fan_readings,
                spinning_fans,
                ..
            } if now.saturating_duration_since(*sampled_at) <= S19K_TRACK1_THERMAL_MAX_AGE
                && *hottest_c < dangerous_temp_c
                && *expected_fan_channels >= S19K_TRACK1_MIN_SPINNING_FANS
                && fan_readings.len() == *expected_fan_channels
                && *spinning_fans >= S19K_TRACK1_MIN_SPINNING_FANS
        )
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum S19kJobAttributionVariant {
    Raw,
    EspF8,
    Shift3,
}

impl S19kJobAttributionVariant {
    fn retry_candidates(raw: u8) -> [(u8, Self); 3] {
        [
            (raw, Self::Raw),
            (raw & BM1366_JOB_ID_MASK, Self::EspF8),
            (raw >> 3, Self::Shift3),
        ]
    }

    fn counter_index(self) -> usize {
        match self {
            Self::Raw => 0,
            Self::EspF8 => 1,
            Self::Shift3 => 2,
        }
    }

    /// Stable evidence/API spelling. Do not expose `Debug` formatting as a
    /// wire contract: variant renames must be an explicit schema decision.
    fn evidence_name(self) -> &'static str {
        match self {
            Self::Raw => "Raw",
            Self::EspF8 => "EspF8",
            Self::Shift3 => "Shift3",
        }
    }
}

impl FanTachSnapshot {
    fn rpms(&self) -> Vec<u32> {
        self.readings.iter().map(|(_, rpm)| *rpm).collect()
    }
}

async fn sample_fan_tach(fan: Arc<dyn FanAccess>) -> Result<FanTachSnapshot> {
    tokio::task::spawn_blocking(move || {
        let readings = fan.get_per_fan_rpm();
        FanTachSnapshot {
            // Read availability after sampling so a sampler error that revokes
            // the owner's evidence is part of this snapshot.
            available: fan.tach_available(),
            expected_channels: fan.fan_count() as usize,
            readings,
        }
    })
    .await
    .context("fan tach sampling worker did not complete")
}

#[derive(Debug, Clone, Copy)]
struct Am2ThermalObservation {
    temp_c: f32,
    source: crate::s19j_hybrid_mining::Am2ThermalSource,
}

impl Am2ThermalObservation {
    fn chain_temp_source(self) -> &'static str {
        match self.source {
            crate::s19j_hybrid_mining::Am2ThermalSource::DspicBoardSensor => {
                dcentrald_api::ChainTempSource::BOARD_SENSOR
            }
            crate::s19j_hybrid_mining::Am2ThermalSource::XadcSocDie => {
                dcentrald_api::ChainTempSource::SOC_DIE_FALLBACK
            }
        }
    }
}

/// Keep synchronous dsPIC/XADC reads off the Tokio safety loop and put a hard
/// deadline around loss of thermal observability. A timed-out blocking worker
/// may finish its read in the background, but its supervisor ownership is
/// permanently revoked and the caller immediately enters terminal safe-off.
async fn poll_am2_thermal_bounded(
    mut supervisor: crate::s19j_hybrid_mining::Am2ThermalSupervisor,
    stage: crate::s19j_hybrid_mining::Am2ThermalPollStage,
    capture_cold_baseline: bool,
) -> Result<(
    crate::s19j_hybrid_mining::Am2ThermalSupervisor,
    Am2ThermalObservation,
)> {
    let worker = tokio::task::spawn_blocking(move || {
        if capture_cold_baseline {
            supervisor.maybe_capture_die_baseline();
        }
        let result = supervisor.poll_and_check(stage);
        (supervisor, result)
    });
    let (supervisor, result) = tokio::time::timeout(AM2_BM1362_THERMAL_POLL_TIMEOUT, worker)
        .await
        .context("AM2 BM1362 thermal poll exceeded its 3-second safety deadline")?
        .context("AM2 BM1362 thermal polling worker failed")?;
    let temp_c = result?;
    let source = supervisor
        .effective_source()
        .context("AM2 BM1362 thermal poll returned a value without source provenance")?;
    Ok((supervisor, Am2ThermalObservation { temp_c, source }))
}

fn require_am2_bringup_active(shutdown: &CancellationToken, stage: &'static str) -> Result<()> {
    if shutdown.is_cancelled() {
        anyhow::bail!("shutdown requested during AM2 BM1362 bring-up at {stage}");
    }
    Ok(())
}

async fn wait_am2_bringup_active(
    shutdown: &CancellationToken,
    duration: Duration,
    stage: &'static str,
) -> Result<()> {
    tokio::select! {
        _ = shutdown.cancelled() => {
            anyhow::bail!("shutdown requested during AM2 BM1362 bring-up wait at {stage}")
        }
        _ = tokio::time::sleep(duration) => Ok(()),
    }
}

async fn wait_am2_apw_heartbeat_stable(
    shutdown: &CancellationToken,
    terminal_exit: &mut mpsc::UnboundedReceiver<String>,
    progress: &AtomicU64,
    duration: Duration,
    stage: &'static str,
) -> Result<()> {
    wait_am2_apw_heartbeat_stable_with_post_wait(
        shutdown,
        terminal_exit,
        progress,
        duration,
        stage,
        || {},
    )
    .await
}

async fn wait_am2_apw_heartbeat_stable_with_post_wait<F>(
    shutdown: &CancellationToken,
    terminal_exit: &mut mpsc::UnboundedReceiver<String>,
    progress: &AtomicU64,
    duration: Duration,
    stage: &'static str,
    post_wait: F,
) -> Result<()>
where
    F: FnOnce(),
{
    let initial_progress = progress.load(Ordering::Acquire);
    tokio::select! {
        biased;
        exit = terminal_exit.recv() => match exit {
            Some(reason) => anyhow::bail!(
                "AM2 BM1362 APW heartbeat failed during {stage}: {reason}"
            ),
            None if shutdown.is_cancelled() => anyhow::bail!(
                "shutdown requested during AM2 BM1362 bring-up wait at {stage}"
            ),
            None => anyhow::bail!(
                "AM2 BM1362 APW heartbeat actor exited without a terminal receipt during {stage}"
            ),
        },
        _ = shutdown.cancelled() => {
            anyhow::bail!("shutdown requested during AM2 BM1362 bring-up wait at {stage}")
        }
        _ = tokio::time::sleep(duration) => {}
    }

    post_wait();
    match terminal_exit.try_recv() {
        Ok(reason) => anyhow::bail!("AM2 BM1362 APW heartbeat failed during {stage}: {reason}"),
        Err(mpsc::error::TryRecvError::Disconnected) if shutdown.is_cancelled() => {
            anyhow::bail!("shutdown requested during AM2 BM1362 bring-up wait at {stage}")
        }
        Err(mpsc::error::TryRecvError::Disconnected) => anyhow::bail!(
            "AM2 BM1362 APW heartbeat actor exited without a terminal receipt during {stage}"
        ),
        Err(mpsc::error::TryRecvError::Empty) => {}
    }
    if shutdown.is_cancelled() {
        anyhow::bail!("shutdown requested during AM2 BM1362 bring-up wait at {stage}");
    }
    let observed_progress = progress.load(Ordering::Acquire);
    if observed_progress <= initial_progress {
        anyhow::bail!("AM2 BM1362 APW heartbeat made no successful progress during {stage}");
    }
    Ok(())
}

async fn admit_fan_motion_at_pwm(
    fan: Arc<dyn FanAccess>,
    safety: &mut FanTachSafety,
    pwm: u8,
    stage: &'static str,
) -> Result<FanCommandReceipt> {
    let receipt = set_fan_speed_checked_blocking(
        Arc::clone(&fan),
        pwm,
        "Amlogic pre-energize fan command/readback",
    )
    .await
    .with_context(|| format!("Amlogic {stage} fan command/readback failed"))?;
    for attempt in 1..=AMLOGIC_FAN_SPINUP_ATTEMPTS {
        let snapshot = sample_fan_tach(fan.clone()).await?;
        let rpms = snapshot.rpms();
        let state = safety.observe_required_airflow(
            snapshot.available,
            receipt.observed_pwm(),
            snapshot.expected_channels,
            &rpms,
        );
        match state {
            FanTachSafetyState::Healthy => {
                info!(
                    stage,
                    attempt,
                    pwm = receipt.observed_pwm(),
                    readings = ?snapshot.readings,
                    "Amlogic pre-energize fan-motion admission accepted"
                );
                return Ok(receipt);
            }
            FanTachSafetyState::AirflowNotCommanded
            | FanTachSafetyState::EvidenceUnavailable { .. } => {
                anyhow::bail!("Amlogic {stage} pre-energize tach evidence unavailable: {state:?}");
            }
            FanTachSafetyState::Debouncing { .. } | FanTachSafetyState::Failed { .. }
                if attempt < AMLOGIC_FAN_SPINUP_ATTEMPTS =>
            {
                warn!(stage, attempt, ?state, readings = ?snapshot.readings, "Amlogic fans have not established motion; retrying before power admission");
                tokio::time::sleep(AMLOGIC_FAN_SPINUP_RETRY_DELAY).await;
            }
            _ => {
                anyhow::bail!(
                    "Amlogic {stage} pre-energize fan-motion admission refused after {} attempts: state={state:?}, readings={:?}",
                    AMLOGIC_FAN_SPINUP_ATTEMPTS,
                    snapshot.readings
                );
            }
        }
    }
    anyhow::bail!("Amlogic {stage} pre-energize fan-motion admission did not complete")
}

async fn admit_fan_airflow_envelope(
    fan: Arc<dyn FanAccess>,
    safety: &mut FanTachSafety,
    minimum_pwm: u8,
    maximum_pwm: u8,
) -> Result<FanCommandReceipt> {
    admit_fan_motion_at_pwm(fan.clone(), safety, maximum_pwm, "spin-up").await?;
    if minimum_pwm != maximum_pwm {
        if let Err(minimum_error) =
            admit_fan_motion_at_pwm(fan.clone(), safety, minimum_pwm, "energized minimum").await
        {
            match set_fan_speed_checked_blocking(
                Arc::clone(&fan),
                maximum_pwm,
                "Amlogic pre-energize fan ceiling restoration",
            )
            .await
            {
                Ok(_) => {
                    anyhow::bail!(
                        "Amlogic energized-minimum motion proof failed; restored startup ceiling before refusing power: {minimum_error:#}"
                    );
                }
                Err(restore_error) => {
                    anyhow::bail!(
                        "Amlogic energized-minimum motion proof failed and startup ceiling restoration also failed: motion={minimum_error:#}; restore={restore_error}"
                    );
                }
            }
        }
    }
    // Leave startup at the retained ceiling. The low-point observation above
    // proves the later proportional controller may safely return to its floor.
    set_fan_speed_checked_blocking(
        fan,
        maximum_pwm,
        "Amlogic final pre-energize fan command/readback",
    )
    .await
    .context("Amlogic final pre-energize fan command/readback failed")
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum S19kNativeCoolingStage {
    PreWatchdog,
    PostPower,
    PostResetRelease,
}

/// Stock S19k policy pins `min_fan_rpm=2000`; native authority requires that
/// floor independently on every retained channel. The generic Amlogic
/// plausibility floor (300 RPM) is intentionally not an energize admission.
const S19K_NATIVE_MIN_FAN_RPM: u32 = 2_000;
const S19K_NATIVE_OWNER_EVIDENCE_MAX_AGE: Duration = Duration::from_secs(5);

fn s19k_native_four_fan_rpm_admitted(readings: &[(u8, u32)]) -> bool {
    dcentrald_silicon_profiles::s19k_nopic_admission::admit_bm1366_airflow(None, readings).is_ok()
}

#[allow(clippy::too_many_arguments)]
fn s19k_native_receipt_timeline_admitted(
    pre_cooling: Instant,
    pre_thermal: Instant,
    power_completed: Instant,
    powered_cooling: Instant,
    powered_thermal: Instant,
    reset_release_completed: Instant,
    post_cooling: Instant,
    post_thermal: Instant,
    now: Instant,
) -> bool {
    pre_cooling <= power_completed
        && pre_thermal <= power_completed
        && power_completed <= powered_cooling
        && power_completed <= powered_thermal
        && powered_cooling <= reset_release_completed
        && powered_thermal <= reset_release_completed
        && reset_release_completed <= post_cooling
        && reset_release_completed <= post_thermal
        && power_completed.saturating_duration_since(pre_cooling)
            <= S19K_NATIVE_OWNER_EVIDENCE_MAX_AGE
        && power_completed.saturating_duration_since(pre_thermal)
            <= S19K_NATIVE_OWNER_EVIDENCE_MAX_AGE
        && powered_cooling.saturating_duration_since(power_completed)
            <= S19K_NATIVE_OWNER_EVIDENCE_MAX_AGE
        && powered_thermal.saturating_duration_since(power_completed)
            <= S19K_NATIVE_OWNER_EVIDENCE_MAX_AGE
        && now.saturating_duration_since(post_cooling) <= S19K_NATIVE_OWNER_EVIDENCE_MAX_AGE
        && now.saturating_duration_since(post_thermal) <= S19K_NATIVE_OWNER_EVIDENCE_MAX_AGE
}

/// Fresh four-channel command/readback/tach evidence. Construction remains
/// private to the checked sampling path; an environment variable or a bare
/// `FanCommandReceipt` cannot mint native cold-start authority.
struct S19kNativeCoolingAdmission {
    stage: S19kNativeCoolingStage,
    observed_at: Instant,
    _command: FanCommandReceipt,
    _readings: [(u8, u32); 4],
}

async fn admit_s19k_native_cooling(
    fan: Arc<dyn FanAccess>,
    safety: &mut FanTachSafety,
    minimum_pwm: u8,
    maximum_pwm: u8,
    stage: S19kNativeCoolingStage,
) -> Result<S19kNativeCoolingAdmission> {
    let command =
        admit_fan_airflow_envelope(Arc::clone(&fan), safety, minimum_pwm, maximum_pwm).await?;
    let snapshot = sample_fan_tach(fan).await?;
    anyhow::ensure!(
        snapshot.available && snapshot.expected_channels == 4 && snapshot.readings.len() == 4,
        "native S19k cooling admission requires all four fresh tach channels"
    );
    let readings: [(u8, u32); 4] =
        snapshot
            .readings
            .try_into()
            .map_err(|readings: Vec<(u8, u32)>| {
                anyhow::anyhow!(
                    "native S19k cooling admission observed {} tach channels instead of four",
                    readings.len()
                )
            })?;
    anyhow::ensure!(
        s19k_native_four_fan_rpm_admitted(&readings),
        "native S19k cooling admission requires all four tachs at or above {S19K_NATIVE_MIN_FAN_RPM} RPM: {readings:?}"
    );
    Ok(S19kNativeCoolingAdmission {
        stage,
        observed_at: Instant::now(),
        _command: command,
        _readings: readings,
    })
}

/// Complete fresh inlet/outlet telemetry for both mapped boards.
struct S19kNativeThermalAdmission {
    stage: S19kNativeCoolingStage,
    observed_at: Instant,
    _hottest_celsius: f32,
}

fn admit_s19k_native_temperatures(
    snapshot: dcentrald_hal::platform::amlogic::AmlogicTemperatureSnapshot,
    dangerous_temp_c: u8,
    stage: S19kNativeCoolingStage,
) -> Result<S19kNativeThermalAdmission> {
    anyhow::ensure!(
        snapshot.required_coverage().is_complete() && snapshot.readings().len() == 4,
        "native S19k thermal admission requires four fresh channels across physical addresses 2 and 3"
    );
    let hottest = snapshot
        .hottest_celsius()
        .context("native S19k thermal admission has no finite reading")?;
    anyhow::ensure!(
        hottest.is_finite() && hottest < f32::from(dangerous_temp_c),
        "native S19k thermal admission refused hottest temperature {hottest:.1} C"
    );
    Ok(S19kNativeThermalAdmission {
        stage,
        observed_at: Instant::now(),
        _hottest_celsius: hottest,
    })
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum NoPicFanLoopDisposition {
    Continue,
    SafeOffAndStop,
}

fn nopic_fan_loop_disposition(state: &FanTachSafetyState) -> NoPicFanLoopDisposition {
    match state {
        FanTachSafetyState::Healthy | FanTachSafetyState::Debouncing { .. } => {
            NoPicFanLoopDisposition::Continue
        }
        FanTachSafetyState::AirflowNotCommanded
        | FanTachSafetyState::Failed { .. }
        | FanTachSafetyState::EvidenceUnavailable { .. } => NoPicFanLoopDisposition::SafeOffAndStop,
    }
}

fn observed_dspic_firmware(version: Option<u8>) -> Result<DspicFirmware> {
    let version = version.context(
        "dsPIC firmware was not observed; refusing protocol-dependent heartbeat startup",
    )?;
    let firmware = DspicFirmware::from_version(version);
    if !dspic_runtime_protocol_is_proven(firmware) {
        anyhow::bail!(
            "unsupported observed dsPIC firmware 0x{version:02X}; refusing protocol-dependent heartbeat startup"
        );
    }
    Ok(firmware)
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum NoPicPowerState {
    NeverOwned,
    MayBeEnergized,
    EnabledByDaemon,
}

struct NoPicPsuGuard {
    state: NoPicPowerState,
    lifecycle_owner: Option<dcentrald_hal::platform::amlogic::AmlogicPowerThermalLifecycleOwner>,
    s19k_native_reset_before_cut: bool,
}

pub(crate) struct NoPicSafeOffReceipt {
    power: dcentrald_hal::platform::amlogic::PsuSafeOffReceipt,
    management_fabric: dcentrald_hal::i2c::I2cServiceCloseReceipt,
    teardown_budget: Option<TeardownBudgetView>,
    _s19k_native_resets: Option<dcentrald_hal::platform::amlogic::S19kNativeAllResetsAsserted>,
}

/// Move-only timing progress for one exact-serial cutoff. The checked hardware
/// receipt remains route-specific; this capability proves only that the
/// load-bearing cut ran inside the watchdog-issued absolute schedule.
struct ExactSerialTeardownProgress {
    teardown_budget: TeardownBudgetView,
    cutoff_started_at: Instant,
    cutoff_completed_at: Instant,
}

impl ExactSerialTeardownProgress {
    fn after_worker_timed_cut(
        teardown_budget: TeardownBudgetView,
        cutoff_started_at: Instant,
        cutoff_completed_at: Instant,
    ) -> Result<Self> {
        teardown_budget.require_not_before_start(cutoff_started_at)?;
        teardown_budget.require_completed_at(TeardownStage::CutoffStart, cutoff_started_at)?;
        teardown_budget.require_completed_at(TeardownStage::CutoffComplete, cutoff_completed_at)?;
        Ok(Self {
            teardown_budget,
            cutoff_started_at,
            cutoff_completed_at,
        })
    }

    fn after_nopic_checked_cut(
        teardown_budget: TeardownBudgetView,
        timed_cut: TimedTerminalOwnerOperation<NoPicEmergencyCutReceipt>,
    ) -> Result<Self> {
        let TimedTerminalOwnerOperation {
            value: _checked_cut,
            started_at,
            completed_at,
        } = timed_cut;
        Self::after_worker_timed_cut(teardown_budget, started_at, completed_at)
    }

    fn after_s19k_track1_checked_cut(
        teardown_budget: TeardownBudgetView,
        timed_cut: TimedTerminalOwnerOperation<S19kTrack1SafeOffReceipt>,
    ) -> (S19kTrack1SafeOffReceipt, Result<Self>) {
        let TimedTerminalOwnerOperation {
            value: checked_cut,
            started_at,
            completed_at,
        } = timed_cut;
        let timing = Self::after_worker_timed_cut(teardown_budget, started_at, completed_at);
        (checked_cut, timing)
    }

    fn after_am2_checked_cut(
        teardown_budget: Option<TeardownBudgetView>,
        timed_cut: TimedTerminalOwnerOperation<Am2FirstStageCutAttempt>,
    ) -> (Am2FirstStageCutAttempt, Result<Self>) {
        let TimedTerminalOwnerOperation {
            value: first_stage_cut,
            started_at,
            completed_at,
        } = timed_cut;
        let timing = match &first_stage_cut.result {
            Ok(_) => match teardown_budget {
                Some(budget) => Self::after_worker_timed_cut(budget, started_at, completed_at),
                None => Err(anyhow::anyhow!(
                    "AM2 teardown budget was unavailable at first-stage cutoff"
                )),
            },
            Err(error) => Err(anyhow::anyhow!(
                "AM2 checked first-stage cutoff failed: {error:#}"
            )),
        };
        (first_stage_cut, timing)
    }

    fn complete(self, completed_at: Instant) -> Result<ExactSerialTeardownReceipt> {
        self.teardown_budget
            .require_completed_at(TeardownStage::CutoffStart, self.cutoff_started_at)?;
        self.teardown_budget
            .require_completed_at(TeardownStage::CutoffComplete, self.cutoff_completed_at)?;
        self.teardown_budget
            .require_completed_at(TeardownStage::CleanupComplete, completed_at)?;
        Ok(ExactSerialTeardownReceipt {
            teardown_budget: self.teardown_budget,
        })
    }
}

/// Run/issuer-bound proof that exact-serial cutoff and cleanup completed within
/// their shared schedule. Only the exact watchdog manifests can consume it.
pub(crate) struct ExactSerialTeardownReceipt {
    teardown_budget: TeardownBudgetView,
}

impl ExactSerialTeardownReceipt {
    pub(crate) fn same_teardown_budget(&self, authority: &TeardownDisarmAuthority) -> bool {
        self.teardown_budget.same_budget(authority)
    }
}

fn remaining_exact_serial_cleanup(
    teardown_budget: Option<&TeardownBudgetView>,
    requested: Duration,
) -> Duration {
    match teardown_budget {
        Some(budget) => budget
            .remaining_capped_at(TeardownStage::CleanupComplete, requested, Instant::now())
            .unwrap_or(Duration::ZERO),
        None => requested,
    }
}

/// Checked evidence that an urgent GPIO cutoff was issued before bounded
/// closeout. This deliberately cannot satisfy the watchdog shutdown manifest:
/// only [`NoPicSafeOffReceipt`], minted by a repeated checked readback after all
/// mutation domains and runtime actors are fenced, has terminal authority.
struct NoPicEmergencyCutReceipt {
    _power: dcentrald_hal::platform::amlogic::PsuSafeOffReceipt,
    _s19k_native_resets: Option<dcentrald_hal::platform::amlogic::S19kNativeAllResetsAsserted>,
}

/// Move-only proof that the exact native owner transferred S19k reset-before-
/// cut and polarity-bound terminal lifecycle custody into the retained guard.
struct S19kNativeTerminalCustodyAdmission;

impl NoPicSafeOffReceipt {
    pub(crate) fn power(&self) -> &dcentrald_hal::platform::amlogic::PsuSafeOffReceipt {
        &self.power
    }

    pub(crate) fn management_fabric(&self) -> &dcentrald_hal::i2c::I2cServiceCloseReceipt {
        &self.management_fabric
    }

    pub(crate) fn same_teardown_budget(&self, authority: &TeardownDisarmAuthority) -> bool {
        self.teardown_budget
            .as_ref()
            .is_some_and(|budget| budget.same_budget(authority))
    }
}

impl NoPicPsuGuard {
    fn new() -> Self {
        crate::terminal_io_owner::prepare();
        Self {
            state: NoPicPowerState::NeverOwned,
            lifecycle_owner: None,
            s19k_native_reset_before_cut: false,
        }
    }

    fn prepare_enable(
        &mut self,
        fan_max_pwm: u8,
        lifecycle_owner: dcentrald_hal::platform::amlogic::AmlogicPowerThermalLifecycleOwner,
    ) -> Result<()> {
        let recipe = lifecycle_owner.gpio437_recipe()?;
        bind_nopic_teardown_recipe(&NOPIC_TEARDOWN_RECIPE, recipe)?;
        self.state = NoPicPowerState::MayBeEnergized;
        self.lifecycle_owner = Some(lifecycle_owner);
        self.s19k_native_reset_before_cut = false;
        arm_nopic_teardown(fan_max_pwm);
        Ok(())
    }

    fn prepare_s19k_native_enable(
        &mut self,
        fan_max_pwm: u8,
        lifecycle_owner: dcentrald_hal::platform::amlogic::AmlogicPowerThermalLifecycleOwner,
    ) {
        self.state = NoPicPowerState::MayBeEnergized;
        self.lifecycle_owner = Some(lifecycle_owner);
        self.s19k_native_reset_before_cut = true;
        arm_s19k_native_teardown(fan_max_pwm);
    }

    fn mark_enabled(&mut self) {
        debug_assert_eq!(self.state, NoPicPowerState::MayBeEnergized);
        self.state = NoPicPowerState::EnabledByDaemon;
    }

    fn owns_power(&self) -> bool {
        self.state != NoPicPowerState::NeverOwned
    }

    fn admit_s19k_native_terminal_custody(&self) -> Result<S19kNativeTerminalCustodyAdmission> {
        anyhow::ensure!(
            self.owns_power()
                && self.s19k_native_reset_before_cut
                && self.lifecycle_owner.is_some(),
            "native S19k terminal custody requires an owned polarity-bound lifecycle and reset-before-cut closeout"
        );
        Ok(S19kNativeTerminalCustodyAdmission)
    }

    /// Issue an early independent GPIO cutoff without consuming the owner.
    /// Terminal closeout repeats checked safe-off after every mutation domain
    /// is fenced, so this is latency reduction rather than final evidence.
    fn first_stage_safe_off(&self) -> Result<NoPicEmergencyCutReceipt> {
        if !self.owns_power() {
            anyhow::bail!("NoPic first-stage safe-off requested without an owned power lease");
        }
        let owner = self
            .lifecycle_owner
            .as_ref()
            .context("NoPic first-stage management-fabric lifecycle owner was unavailable")?;
        let resets = self
            .s19k_native_reset_before_cut
            .then(dcentrald_hal::platform::amlogic::assert_s19k_native_all_resets_checked);
        let power = owner
            .latch_terminal_and_disable_psu_checked()
            .map(|(_, receipt)| receipt)
            .context("checked NoPic first-stage GPIO437 safe-off failed");
        match (resets.transpose(), power) {
            (Ok(resets), Ok(power)) => Ok(NoPicEmergencyCutReceipt {
                _power: power,
                _s19k_native_resets: resets,
            }),
            (Err(reset_error), Ok(_)) => Err(anyhow::Error::from(reset_error).context(
                "native S19k GPIO437 reached checked SafeOff, but reset assertion was incomplete",
            )),
            (Ok(_), Err(power_error)) => Err(power_error),
            (Err(reset_error), Err(power_error)) => Err(anyhow::anyhow!(
                "native S19k reset-before-cut failed ({reset_error}); checked GPIO437 SafeOff also failed ({power_error:#})"
            )),
        }
    }

    fn safe_off(
        &mut self,
        teardown_budget: Option<TeardownBudgetView>,
        management_fabric_deadline: Instant,
    ) -> Result<NoPicSafeOffReceipt> {
        if !self.owns_power() {
            anyhow::bail!("NoPic software safe-off requested without an owned power lease");
        }
        // Native S19k always attempts the complete reset trio before any raw-1
        // GPIO437 cut. Failure withholds the typed closeout but never suppresses
        // the subsequent power-cut attempt.
        let first_resets = self
            .s19k_native_reset_before_cut
            .then(dcentrald_hal::platform::amlogic::assert_s19k_native_all_resets_checked);
        let first_resets = first_resets.transpose();
        let fabric_close = self
            .lifecycle_owner
            .as_mut()
            .context("NoPic management-fabric lifecycle owner was unavailable")
            .and_then(|owner| {
                let _ = owner.latch_terminal_safe_off();
                owner
                    .close_and_join_until(management_fabric_deadline)
                    .map_err(anyhow::Error::from)
            });
        // Repeat the checked load-bearing cutoff after the bus fd and worker
        // are gone. A close failure cannot suppress this physical-safe-
        // direction attempt, but it withholds the typed watchdog receipt.
        let final_resets = self
            .s19k_native_reset_before_cut
            .then(dcentrald_hal::platform::amlogic::assert_s19k_native_all_resets_checked);
        let final_resets = final_resets.transpose();
        let power = self
            .lifecycle_owner
            .as_ref()
            .context("NoPic terminal GPIO owner was unavailable")
            .and_then(|owner| {
                owner
                    .latch_terminal_and_disable_psu_checked()
                    .map(|(_, receipt)| receipt)
                    .map_err(anyhow::Error::from)
            })
            .context("checked NoPic GPIO437 safe-off failed");
        let (management_fabric, receipt) = match (fabric_close, power) {
            (Ok(fabric), Ok(power)) => (fabric, power),
            (Err(fabric_error), Ok(_)) => {
                return Err(fabric_error.context(
                    "NoPic GPIO437 is at checked SafeOff, but management I2C did not close cleanly",
                ));
            }
            (Ok(_), Err(power_error)) => return Err(power_error),
            (Err(fabric_error), Err(power_error)) => {
                return Err(anyhow::anyhow!(
                    "NoPic management I2C close failed ({fabric_error:#}); checked GPIO437 safe-off also failed ({power_error:#})"
                ));
            }
        };
        let reset_receipt = match (first_resets, final_resets) {
            (Ok(_), Ok(final_receipt)) => final_receipt,
            (Err(first), Ok(_)) => {
                return Err(anyhow::Error::from(first).context(
                    "native S19k power reached checked SafeOff, but first reset assertion failed",
                ));
            }
            (Ok(_), Err(final_error)) => {
                return Err(anyhow::Error::from(final_error).context(
                    "native S19k power reached checked SafeOff, but terminal reset recheck failed",
                ));
            }
            (Err(first), Err(final_error)) => {
                return Err(anyhow::anyhow!(
                    "native S19k power reached checked SafeOff, but both reset assertions failed: first={first}; final={final_error}"
                ));
            }
        };
        self.state = NoPicPowerState::NeverOwned;
        Ok(NoPicSafeOffReceipt {
            power: receipt,
            management_fabric,
            teardown_budget,
            _s19k_native_resets: reset_receipt,
        })
    }
}

impl Drop for NoPicPsuGuard {
    fn drop(&mut self) {
        if !self.owns_power() {
            return;
        }
        self.state = NoPicPowerState::NeverOwned;
        let lifecycle_owner = self.lifecycle_owner.take();
        let s19k_native_reset_before_cut = self.s19k_native_reset_before_cut;
        crate::terminal_io_owner::dispatch("nopic-drop-safe-off", move || {
            let mut lifecycle_owner = lifecycle_owner;
            let resets_checked = if s19k_native_reset_before_cut {
                match dcentrald_hal::platform::amlogic::assert_s19k_native_all_resets_checked() {
                    Ok(_) => true,
                    Err(error) => {
                        warn!(%error, "native S19k drop could not assert every reset before GPIO437 cut");
                        false
                    }
                }
            } else {
                true
            };
            let (owner_cut_attempted, cut_checked) = if let Some(owner) = lifecycle_owner.as_ref() {
                let transition = owner.latch_terminal_safe_off();
                if !transition.no_controller_mutation_stage_in_flight() {
                    error!(
                        generation = transition.generation(),
                        "NoPic drop fenced management I2C with a controller mutation still in flight"
                    );
                }
                let cut_checked = match owner.latch_terminal_and_disable_psu_checked() {
                    Ok(_) => true,
                    Err(e) => {
                        warn!(error = %e, "Failed to disable NoPic PSU during shutdown");
                        false
                    }
                };
                (true, cut_checked)
            } else {
                (false, false)
            };
            // Safety (cut-hash-before-noise + PWM-30 home cap, per
            // ): CUT PSU POWER FIRST so the heat
            // source (the hashboards) is removed, THEN hold fans at the quiet
            // home cap for coast-down. NEVER blast a home-unit's fans to 100%:
            // once the chips are de-energized there is no active thermal load
            // that justifies a jet, and these are home/space-heater units the
            // operator works beside.
            //
            // (Was: 100% fan-blast for 2 s applied BEFORE the PSU cut â€” a direct
            // inversion of cut-hash-before-noise and a violation of the absolute
            // PWM-30 home cap. Audit wf_4a84d55e ABSENT finding, 2026-05-29.)
            if !owner_cut_attempted {
                let cut = if s19k_native_reset_before_cut {
                    dcentrald_hal::platform::amlogic::disable_s19k_track1_psu_checked()
                } else {
                    disable_nopic_retained_psu_checked()
                };
                match cut {
                    Ok(_) => {}
                    Err(e) => {
                        warn!(error = %e, "Failed to disable NoPic PSU without lifecycle owner during shutdown");
                    }
                }
            }
            let mut management_joined = lifecycle_owner.is_none();
            if let Some(owner) = lifecycle_owner.as_mut() {
                match owner.close_and_join_until(Instant::now() + Duration::from_secs(2)) {
                    Ok(_) => management_joined = true,
                    Err(error) => {
                        warn!(%error, "NoPic drop-safe-off could not join the management I2C worker");
                    }
                }
            }
            if s19k_native_reset_before_cut {
                let final_resets =
                    dcentrald_hal::platform::amlogic::assert_s19k_native_all_resets_checked();
                if let Err(error) = &final_resets {
                    warn!(%error, "native S19k drop post-join reset assertion failed; continuing to final raw-1 cut");
                }
                let final_cut = dcentrald_hal::platform::amlogic::disable_s19k_track1_psu_checked();
                if let Err(error) = &final_cut {
                    warn!(%error, "native S19k drop post-join raw-1 cut failed");
                }
                // Drop has no custody of the runtime actor/watchdog joins. It
                // therefore must never clear the process panic arm, even when
                // its local reset/cut/fabric legs happened to succeed.
                let _ = (
                    resets_checked,
                    cut_checked,
                    management_joined,
                    final_resets,
                    final_cut,
                );
            }
            // Quiet coast-down at PWM 30 (home cap). The Amlogic PWM period is
            // 100_000 ns (AMLOGIC_PWM_PERIOD_NS), so PWM 30 = 30_000 ns duty â€”
            // NOT 100_000 (100% jet). Best-effort; fans run off the control-board
            // rail and stay powered after the hashboard PSU is disabled.
            let _ = std::fs::write("/sys/class/pwm/pwmchip0/pwm0/duty_cycle", "30000");
            let _ = std::fs::write("/sys/class/pwm/pwmchip0/pwm1/duty_cycle", "30000");
        });
    }
}

fn checked_nopic_emergency_safe_off(guard: &mut NoPicPsuGuard) -> Result<NoPicEmergencyCutReceipt> {
    if guard.owns_power() {
        guard.first_stage_safe_off()
    } else {
        anyhow::bail!("checked NoPic emergency safe-off requested without an owned power lease")
    }
}

/// Process-global flag, armed the moment a NoPic (am3-aml) run energizes the PSU.
/// Release builds use `panic = "abort"`, which BYPASSES `NoPicPsuGuard::Drop`, and
/// NoPic (TAS5782M DAC voltage) has NO PIC heartbeat watchdog â€” so without this a
/// panic leaves the hashboards energized indefinitely (fire risk). The `main()`
/// crash panic hook reads this to cut PSU power. Mirrors the am2 `AM2_TEARDOWN_PARAMS`
/// pattern (W24-CRASH-1). Stores the home fan cap, already clamped to PWM_SAFETY_MAX.
static NOPIC_TEARDOWN_ARMED: std::sync::OnceLock<u8> = std::sync::OnceLock::new();
// Published from the retained lifecycle owner before the generic crash arm.
// A later marker/config change cannot change the abort-time polarity.
static NOPIC_TEARDOWN_RECIPE: std::sync::OnceLock<
    dcentrald_common::amlogic_gpio437::Gpio437DriveRecipe,
> = std::sync::OnceLock::new();

fn bind_nopic_teardown_recipe(
    cell: &std::sync::OnceLock<dcentrald_common::amlogic_gpio437::Gpio437DriveRecipe>,
    recipe: dcentrald_common::amlogic_gpio437::Gpio437DriveRecipe,
) -> Result<()> {
    if cell.set(recipe).is_err() {
        anyhow::ensure!(
            cell.get() == Some(&recipe),
            "NoPic crash recipe cannot change population target"
        );
    }
    Ok(())
}

#[cfg(test)]
#[test]
fn nopic_crash_recipe_is_immutable_and_requires_qualified_target() {
    use dcentrald_common::amlogic_gpio437::resolve_drive_recipe;
    let cell = std::sync::OnceLock::new();
    assert!(resolve_drive_recipe("am3-unresolved").is_err());
    assert!(cell.get().is_none());
    let original = resolve_drive_recipe("am3-s21").unwrap();
    bind_nopic_teardown_recipe(&cell, original).unwrap();
    bind_nopic_teardown_recipe(&cell, original).unwrap();
    // Even equal raw levels do not make another target the same authority.
    let sibling = resolve_drive_recipe("am3-s19xp").unwrap();
    assert!(bind_nopic_teardown_recipe(&cell, sibling).is_err());
    assert_eq!(cell.get(), Some(&original));
}

fn disable_nopic_retained_psu_checked(
) -> dcentrald_hal::Result<dcentrald_hal::platform::amlogic::PsuSafeOffReceipt> {
    let recipe = NOPIC_TEARDOWN_RECIPE.get().copied().ok_or_else(|| {
        dcentrald_hal::HalError::Platform(
            "NoPic crash cutoff lacks an identity-qualified retained recipe".into(),
        )
    })?;
    dcentrald_hal::platform::amlogic::disable_psu_with_retained_recipe_checked(recipe)
}

/// Native cold-start is a different process-scoped crash route from generic
/// S21 NoPic and inherited-rail Track-1. It is armed before the first reset or
/// GPIO437 mutation and cleared only by a checked all-reset + raw-1 terminal
/// closeout. `panic = "abort"` cannot rely on the guard's Drop implementation.
static S19K_NATIVE_TEARDOWN_ARMED: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// Arm the NoPic (am3-aml) panic-hook teardown â€” call at the instant the NoPic PSU
/// is energized. Idempotent (OnceLock::set). `fan_max_pwm` is clamped to the home
/// PWM_SAFETY_MAX so the coast-down can never blast.
pub fn arm_nopic_teardown(fan_max_pwm: u8) {
    let _ = NOPIC_TEARDOWN_ARMED.set(fan_max_pwm.min(dcentrald_hal::fan::PWM_SAFETY_MAX));
}

fn arm_s19k_native_teardown(fan_max_pwm: u8) {
    // Publish the SKU-specific polarity/reset route first. A panic between
    // these stores therefore takes the safe S19k branch, never generic S21.
    S19K_NATIVE_TEARDOWN_ARMED.store(true, std::sync::atomic::Ordering::Release);
    arm_nopic_teardown(fan_max_pwm);
}

fn disarm_s19k_native_teardown_after_checked_terminal_reset_and_cut() {
    S19K_NATIVE_TEARDOWN_ARMED.store(false, std::sync::atomic::Ordering::Release);
}

/// Track-1: arm panic-hook GPIO437 SafeOff without taking a power lease.
/// The terminal path uses the explicit process-scoped S19k cut and therefore
/// does not depend on a persistent board-target marker.
/// Must not be called from GetAddress / re-arm / work TX.
static S19K_TRACK1_TEARDOWN_ARMED: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);
/// When true, the inherited-rail Track-1 owner is the install-custody
/// composition.  Its only physical mutation is the checked fixed-polarity
/// GPIO437 cut; hashboard reset writes are outside that mode's authority.
/// This bit is published before `S19K_TRACK1_TEARDOWN_ARMED` so the abort-time
/// panic hook can never momentarily select the reset-capable contract.
static S19K_TRACK1_INSTALL_CUSTODY_CUT_ONLY: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);
static S19K_TRACK1_LOUD_FAN_AUTHORIZED: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

pub fn arm_s19k_track1_teardown(explicit_loud_authority: bool) {
    arm_s19k_track1_teardown_with_contract(
        explicit_loud_authority,
        S19kTrack1SafeOffContract::ResetThenGpio437Cut,
    );
}

fn arm_s19k_track1_teardown_with_contract(
    explicit_loud_authority: bool,
    contract: S19kTrack1SafeOffContract,
) {
    arm_nopic_teardown(dcentrald_hal::fan::PWM_SAFETY_MAX);
    S19K_TRACK1_INSTALL_CUSTODY_CUT_ONLY.store(
        contract == S19kTrack1SafeOffContract::InstallCustodyGpio437Only,
        std::sync::atomic::Ordering::Release,
    );
    S19K_TRACK1_LOUD_FAN_AUTHORIZED.store(
        explicit_loud_authority,
        std::sync::atomic::Ordering::Release,
    );
    S19K_TRACK1_TEARDOWN_ARMED.store(true, std::sync::atomic::Ordering::Release);
}

/// Feed SoC-watchdog liveness while Track-1 is armed. Does not write GPIO437.
fn s19k_track1_mark_watchdog_liveness(liveness: &SafetyLiveness) {
    if S19K_TRACK1_TEARDOWN_ARMED.load(std::sync::atomic::Ordering::Acquire) {
        liveness.mark_progress();
    }
}

const S19K_LIVE_IDENTITY_ENV: &str = "DCENT_S19K_LIVE_IDENTITY_SHA256";
const S19K_LIVE_IDENTITY_SCHEMA: &str = "dcentos.s19k-braiins-live-identity/v2";
const S19K_LIVE_CPU_TUPLE: &str = "Amlogic:aarch64:4x0x41:arch8:part0xd03";
const S19K_LIVE_IDENTITY_FILE_MAX_BYTES: u64 = 1024 * 1024;
const S19K_LIVE_MTD_ROWS: [(&str, &str, &str); 6] = [
    ("00200000", "00020000", "bootloader"),
    ("00800000", "00020000", "tpl"),
    ("03200000", "00020000", "stock_system"),
    ("00500000", "00020000", "stock_config"),
    ("02000000", "00020000", "overlay"),
    ("09900000", "00020000", "system"),
];

/// Fresh, process-independent evidence bound by the /tmp runner receipt.
///
/// This remains IMPLEMENTED_EXPERIMENTAL: the Braiins files are mutable and
/// the 05:11 EEPROM preamble maps to BHB5690x only through the held Braiins
/// decoder/model corpus. It is deliberately not described as immutable SKU
/// proof. Its purpose is narrower: prevent a package/config declaration from
/// authorizing the fixed-polarity S19k signal/reset/GPIO437 path by itself.
#[derive(Debug, Clone, PartialEq, Eq)]
struct S19kLiveIdentityReceipt {
    sha256: String,
    model_sha256: String,
    profile: S19kLiveHardwareProfile,
    board_count: usize,
    physical_addresses: String,
    board_names: String,
    eeprom_slots: String,
}

/// Controller-supported S19k population classes. Model class and population
/// cardinality are separate: a three-UART unit may be homogeneous or mixed.
const S19K_NATIVE_SUPPORTED_POPULATION_PROFILES: [&str; 4] = [
    "bhb56902-only",
    "bhb56903-only",
    "mixed-bhb56902-bhb56903",
    "all-three-uarts-populated",
];

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum S19kNativeBoardModel {
    Bhb56902,
    Bhb56903,
}

impl S19kNativeBoardModel {
    fn parse(value: &str) -> Option<Self> {
        match value {
            "BHB56902" => Some(Self::Bhb56902),
            "BHB56903" => Some(Self::Bhb56903),
            _ => None,
        }
    }

    fn as_str(self) -> &'static str {
        match self {
            Self::Bhb56902 => "BHB56902",
            Self::Bhb56903 => "BHB56903",
        }
    }
}

/// Fresh board model at each controller address. `physical_address` remains a
/// stock/Braiins provenance field; it is not relabeled as connector geometry.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct S19kLiveHardwareProfile {
    boards: [Option<S19kNativeBoardModel>; 3],
}

impl S19kLiveHardwareProfile {
    fn as_str(self) -> &'static str {
        if self.boards
            == [
                None,
                Some(S19kNativeBoardModel::Bhb56903),
                Some(S19kNativeBoardModel::Bhb56903),
            ]
        {
            return "live88_two_bhb56903_slots_2_3";
        }
        if self.boards == [Some(S19kNativeBoardModel::Bhb56902); 3] {
            return "held78_three_bhb56902_slots_1_2_3";
        }
        match (self.sku_profile(), self.population_profile()) {
            ("bhb56902-only", "all-three-uarts-populated") => {
                "bhb56902-only:all-three-uarts-populated"
            }
            ("bhb56903-only", "all-three-uarts-populated") => {
                "bhb56903-only:all-three-uarts-populated"
            }
            ("mixed-bhb56902-bhb56903", "all-three-uarts-populated") => {
                "mixed-bhb56902-bhb56903:all-three-uarts-populated"
            }
            ("bhb56902-only", _) => "bhb56902-only:partial-logical-uarts-populated",
            ("bhb56903-only", _) => "bhb56903-only:partial-logical-uarts-populated",
            ("mixed-bhb56902-bhb56903", _) => {
                "mixed-bhb56902-bhb56903:partial-logical-uarts-populated"
            }
            _ => unreachable!("S19k profile constructor rejects an empty population"),
        }
    }

    fn sku_profile(self) -> &'static str {
        let has_902 = self
            .boards
            .iter()
            .any(|board| *board == Some(S19kNativeBoardModel::Bhb56902));
        let has_903 = self
            .boards
            .iter()
            .any(|board| *board == Some(S19kNativeBoardModel::Bhb56903));
        match (has_902, has_903) {
            (true, false) => S19K_NATIVE_SUPPORTED_POPULATION_PROFILES[0],
            (false, true) => S19K_NATIVE_SUPPORTED_POPULATION_PROFILES[1],
            (true, true) => S19K_NATIVE_SUPPORTED_POPULATION_PROFILES[2],
            (false, false) => "empty-population-refused",
        }
    }

    fn population_profile(self) -> &'static str {
        if self.board_count() == 3 {
            S19K_NATIVE_SUPPORTED_POPULATION_PROFILES[3]
        } else {
            "partial-logical-uarts-populated"
        }
    }

    fn board_count(self) -> usize {
        self.boards.iter().filter(|board| board.is_some()).count()
    }

    fn physical_addresses(self) -> String {
        self.boards
            .iter()
            .enumerate()
            .filter_map(|(index, board)| board.map(|_| (index + 1).to_string()))
            .collect::<Vec<_>>()
            .join(",")
    }

    fn board_names(self) -> String {
        self.boards
            .iter()
            .filter_map(|board| board.map(S19kNativeBoardModel::as_str))
            .collect::<Vec<_>>()
            .join(",")
    }

    fn eeprom_presence(self) -> [bool; 3] {
        self.boards.map(|board| board.is_some())
    }

    fn eeprom_slots(self) -> String {
        self.eeprom_presence()
            .iter()
            .enumerate()
            .map(|(index, present)| {
                format!(
                    "0x{:02x}={}",
                    0x50 + index,
                    if *present { "05:11" } else { "absent" }
                )
            })
            .collect::<Vec<_>>()
            .join(",")
    }
}

fn s19k_profile_label_supported(value: &str) -> bool {
    matches!(
        value,
        "live88_two_bhb56903_slots_2_3"
            | "held78_three_bhb56902_slots_1_2_3"
            | "bhb56902-only:partial-logical-uarts-populated"
            | "bhb56903-only:partial-logical-uarts-populated"
            | "mixed-bhb56902-bhb56903:partial-logical-uarts-populated"
            | "bhb56902-only:all-three-uarts-populated"
            | "bhb56903-only:all-three-uarts-populated"
            | "mixed-bhb56902-bhb56903:all-three-uarts-populated"
    )
}

#[derive(serde::Deserialize)]
struct S19kLiveModelRoot {
    config_descriptor: S19kLiveConfigDescriptor,
}

#[derive(serde::Deserialize)]
struct S19kLiveConfigDescriptor {
    miner: S19kLiveMinerDescriptor,
    common: S19kLiveCommonDescriptor,
}

#[derive(serde::Deserialize)]
struct S19kLiveMinerDescriptor {
    model: String,
    vendor_name: String,
    hashboards: Vec<S19kLiveHashboardDescriptor>,
}

#[derive(serde::Deserialize)]
struct S19kLiveHashboardDescriptor {
    physical_address: u8,
    #[serde(default)]
    board_name: Option<String>,
    #[serde(default)]
    serial_number: Option<String>,
    #[serde(default)]
    note: Option<String>,
}

#[derive(serde::Deserialize)]
struct S19kLiveCommonDescriptor {
    hashchain_address: S19kLiveHashchainAddress,
    is_nopic_model: bool,
}

#[derive(serde::Deserialize)]
struct S19kLiveHashchainAddress {
    start: u8,
    end: u8,
}

fn s19k_require_lower_hex_sha256(value: &str, label: &str) -> Result<()> {
    anyhow::ensure!(
        value.len() == 64
            && value
                .bytes()
                .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte)),
        "{label} must be exactly 64 lowercase hexadecimal characters"
    );
    Ok(())
}

fn s19k_read_regular_nonsymlink(path: &Path, label: &str) -> Result<Vec<u8>> {
    // One opened descriptor closes the symlink_metadata -> read(path) race.
    // O_NOFOLLOW makes the final component refusal atomic with open; fstat on
    // that same descriptor proves the bytes below came from a regular file.
    let file = OpenOptions::new()
        .read(true)
        .custom_flags(libc::O_CLOEXEC | libc::O_NOFOLLOW)
        .open(path)
        .with_context(|| {
            format!(
                "S19k live identity cannot open regular non-symlink {label} at {}",
                path.display()
            )
        })?;
    let metadata = file.metadata().with_context(|| {
        format!(
            "S19k live identity cannot fstat {label} at {}",
            path.display()
        )
    })?;
    anyhow::ensure!(
        metadata.file_type().is_file(),
        "S19k live identity {label} is not a regular non-symlink file"
    );
    let mut bytes = Vec::new();
    file.take(S19K_LIVE_IDENTITY_FILE_MAX_BYTES + 1)
        .read_to_end(&mut bytes)
        .with_context(|| {
            format!(
                "S19k live identity cannot read {label} at {}",
                path.display()
            )
        })?;
    anyhow::ensure!(
        bytes.len() as u64 <= S19K_LIVE_IDENTITY_FILE_MAX_BYTES,
        "S19k live identity {label} exceeds the 1 MiB bound"
    );
    Ok(bytes)
}

fn s19k_exact_text_file(path: &Path, label: &str, expected: &str) -> Result<()> {
    let bytes = s19k_read_regular_nonsymlink(path, label)?;
    let raw = std::str::from_utf8(&bytes)
        .with_context(|| format!("S19k live identity {label} is not UTF-8"))?;
    let value = raw.strip_suffix('\n').unwrap_or(raw);
    anyhow::ensure!(
        value == expected,
        "S19k live identity {label} is not exact {expected:?}"
    );
    Ok(())
}

fn s19k_validate_cpuinfo(cpuinfo: &str) -> Result<()> {
    let mut processors = 0usize;
    let mut implementers = 0usize;
    let mut architectures = 0usize;
    let mut parts = 0usize;
    let mut hardware = 0usize;
    for line in cpuinfo.lines() {
        let Some((key, value)) = line.split_once(':') else {
            continue;
        };
        match key.trim() {
            "processor" => processors += 1,
            "CPU implementer" => {
                implementers += 1;
                anyhow::ensure!(value.trim() == "0x41", "unexpected S19k CPU implementer");
            }
            "CPU architecture" => {
                architectures += 1;
                anyhow::ensure!(value.trim() == "8", "unexpected S19k CPU architecture");
            }
            "CPU part" => {
                parts += 1;
                anyhow::ensure!(value.trim() == "0xd03", "unexpected S19k CPU part");
            }
            "Hardware" => {
                hardware += 1;
                anyhow::ensure!(value.trim() == "Amlogic", "unexpected S19k Hardware field");
            }
            _ => {}
        }
    }
    anyhow::ensure!(
        processors == 4 && implementers == 4 && architectures == 4 && parts == 4 && hardware == 1,
        "live CPU tuple is not the held four-core Amlogic A113D tuple"
    );
    Ok(())
}

fn s19k_normalize_mtd_map(raw: &str) -> Result<Vec<String>> {
    let mut lines = raw.lines();
    let header = lines
        .next()
        .context("S19k live /proc/mtd is missing its header")?;
    anyhow::ensure!(
        header.split_whitespace().collect::<Vec<_>>() == ["dev:", "size", "erasesize", "name"],
        "S19k live /proc/mtd header is not exact"
    );
    let observed = lines.collect::<Vec<_>>();
    anyhow::ensure!(
        observed.len() == S19K_LIVE_MTD_ROWS.len(),
        "S19k live /proc/mtd must contain exactly six partition rows"
    );
    let mut normalized = Vec::with_capacity(S19K_LIVE_MTD_ROWS.len());
    for (index, (line, (size, erase, name))) in
        observed.iter().zip(S19K_LIVE_MTD_ROWS.iter()).enumerate()
    {
        let fields = line.split_whitespace().collect::<Vec<_>>();
        anyhow::ensure!(
            fields.len() == 4
                && fields[0] == format!("mtd{index}:")
                && fields[1] == *size
                && fields[2] == *erase
                && fields[3] == format!("\"{name}\""),
            "S19k live /proc/mtd row {index} is not the held Braiins AM3 layout"
        );
        normalized.push(format!("mtd{index}: {size} {erase} {name}"));
    }
    Ok(normalized)
}

const S19K_ABSENT_BOARD_NOTE: &str =
    "HB not detected. Board name unknown. hashrate_ths is calculated.";

fn s19k_hashboard_at(
    observed: &[S19kLiveHashboardDescriptor],
    physical_address: u8,
) -> Option<&S19kLiveHashboardDescriptor> {
    let mut matches = observed
        .iter()
        .filter(|board| board.physical_address == physical_address);
    let board = matches.next()?;
    (matches.next().is_none()).then_some(board)
}

fn s19k_decode_live_model(raw: &[u8]) -> Result<S19kLiveHardwareProfile> {
    anyhow::ensure!(
        raw.len() <= 1024 * 1024,
        "S19k live bosminer model descriptor exceeds the 1 MiB bound"
    );
    let root: S19kLiveModelRoot = serde_json::from_slice(raw)
        .context("S19k live bosminer model descriptor is invalid JSON")?;
    let miner = root.config_descriptor.miner;
    let common = root.config_descriptor.common;
    anyhow::ensure!(
        miner.model == "Antminer S19K Pro NoPic" && miner.vendor_name == "Antminer S19k Pro",
        "Braiins boot-detected model is not exact S19K Pro NoPic"
    );
    anyhow::ensure!(
        common.is_nopic_model
            && common.hashchain_address.start == 1
            && common.hashchain_address.end == 3,
        "Braiins model descriptor lacks the held NoPic 1..3 hashchain domain"
    );
    anyhow::ensure!(
        miner.hashboards.len() == 3,
        "Braiins S19k model descriptor must contain exactly three address records"
    );
    let mut boards = [None; 3];
    for physical_address in 1..=3u8 {
        let board = s19k_hashboard_at(&miner.hashboards, physical_address)
            .with_context(|| format!("missing or duplicate S19k address {physical_address}"))?;
        match (
            board.board_name.as_deref(),
            board.serial_number.as_deref(),
            board.note.as_deref(),
        ) {
            (Some(name), Some(serial), None) if !serial.is_empty() => {
                boards[(physical_address - 1) as usize] = Some(
                    S19kNativeBoardModel::parse(name).with_context(|| {
                        format!(
                            "S19k address {physical_address} board model {name:?} is not BHB56902/BHB56903"
                        )
                    })?,
                );
            }
            (None, None, Some(note)) if note == S19K_ABSENT_BOARD_NOTE => {}
            _ => anyhow::bail!(
                "S19k address {physical_address} is neither an exact populated 902/903 record nor the exact absent placeholder"
            ),
        }
    }
    let profile = S19kLiveHardwareProfile { boards };
    anyhow::ensure!(profile.board_count() > 0, "S19k board population is empty");
    Ok(profile)
}

fn s19k_require_live_eeprom_profile(
    profile: S19kLiveHardwareProfile,
    observed: [bool; 3],
) -> Result<()> {
    anyhow::ensure!(
        observed == profile.eeprom_presence(),
        "direct EEPROM slot population does not match exact S19k profile {}",
        profile.as_str()
    );
    Ok(())
}

fn s19k_linux_machine() -> Result<String> {
    let mut name = std::mem::MaybeUninit::<libc::utsname>::zeroed();
    let status = unsafe { libc::uname(name.as_mut_ptr()) };
    anyhow::ensure!(status == 0, "S19k live identity uname(2) failed");
    let name = unsafe { name.assume_init() };
    let machine = unsafe { CStr::from_ptr(name.machine.as_ptr()) }
        .to_str()
        .context("S19k live identity uname machine is not UTF-8")?;
    Ok(machine.to_string())
}

/// Run one small-output identity probe without allowing a wedged kernel/tool
/// path to retain pre-handoff custody indefinitely. The exact `i2cget` command
/// emits at most one byte literal, so reading its pipe only after exit cannot
/// fill the pipe and deadlock the child.
fn s19k_start_detached_probe_reaper(mut child: std::process::Child, label: &str) -> bool {
    let label_for_thread = label.to_string();
    match std::thread::Builder::new()
        .name("s19k-probe-reap".to_string())
        .spawn(move || match child.wait() {
            Ok(status) => warn!(probe = %label_for_thread, %status, "S19k timed-out identity probe was eventually reaped"),
            Err(error) => warn!(probe = %label_for_thread, %error, "S19k timed-out identity probe reaper failed"),
        })
    {
        Ok(_handle) => true,
        Err(error) => {
            // Failure to create a detached reaper must still fail admission;
            // dropping Child does not wait and therefore cannot hang custody.
            warn!(probe = %label, %error, "S19k timed-out identity probe reaper could not start");
            false
        }
    }
}

fn s19k_small_output_command_bounded(
    command: &mut Command,
    timeout: Duration,
    label: &str,
) -> Result<(ExitStatus, Vec<u8>)> {
    let mut child = command
        .stdout(Stdio::piped())
        .stderr(Stdio::null())
        .spawn()
        .with_context(|| format!("S19k live identity could not execute {label}"))?;
    let deadline = Instant::now() + timeout;
    let status = loop {
        match child.try_wait() {
            Ok(Some(status)) => break status,
            Ok(None) if Instant::now() < deadline => {
                std::thread::sleep(Duration::from_millis(10));
            }
            Ok(None) => {
                let kill_result = child.kill();
                // SIGKILL can remain pending forever while an I2C ioctl is in
                // uninterruptible D-state. Never turn the deadline into an
                // unbounded caller-side wait: poll for a short reap grace,
                // then detach the only wait into a named best-effort reaper.
                let post_kill_deadline = Instant::now() + Duration::from_millis(250);
                loop {
                    match child.try_wait() {
                        Ok(Some(post_kill_status)) => anyhow::bail!(
                            "S19k live identity {label} exceeded {:?}; child was killed and reaped (kill={kill_result:?}, status={post_kill_status})",
                            timeout
                        ),
                        Ok(None) if Instant::now() < post_kill_deadline => {
                            std::thread::sleep(Duration::from_millis(10));
                        }
                        Ok(None) => {
                            let reaper_started =
                                s19k_start_detached_probe_reaper(child, label);
                            anyhow::bail!(
                                "S19k live identity {label} exceeded {:?}; child remained live or in D-state after SIGKILL and admission was aborted (kill={kill_result:?}, detached_reaper_started={reaper_started})",
                                timeout
                            );
                        }
                        Err(error) => {
                            let reaper_started =
                                s19k_start_detached_probe_reaper(child, label);
                            return Err(error).with_context(|| {
                                format!(
                                    "S19k live identity {label} exceeded {timeout:?}; post-kill polling failed and admission was aborted (kill={kill_result:?}, detached_reaper_started={reaper_started})"
                                )
                            });
                        }
                    }
                }
            }
            Err(error) => {
                let kill_result = child.kill();
                let reaper_started = s19k_start_detached_probe_reaper(child, label);
                return Err(error).with_context(|| {
                    format!(
                        "S19k live identity could not poll {label}; admission aborted (kill={kill_result:?}, detached_reaper_started={reaper_started})"
                    )
                });
            }
        }
    };
    let mut stdout = Vec::new();
    child
        .stdout
        .take()
        .context("S19k live identity bounded command lost its stdout pipe")?
        .read_to_end(&mut stdout)
        .with_context(|| format!("S19k live identity could not read {label} output"))?;
    Ok((status, stdout))
}

fn s19k_i2cget_byte(address: u8, offset: u8) -> Result<Option<u8>> {
    let mut command = Command::new("/usr/sbin/i2cget");
    command.args([
        "-y",
        "1",
        &format!("0x{address:02x}"),
        &offset.to_string(),
        "b",
    ]);
    let (status, stdout) = s19k_small_output_command_bounded(
        &mut command,
        Duration::from_secs(2),
        "exact /usr/sbin/i2cget",
    )?;
    if !status.success() {
        return Ok(None);
    }
    let text = std::str::from_utf8(&stdout)
        .context("S19k live EEPROM observation is not UTF-8")?
        .trim();
    anyhow::ensure!(
        text.len() == 4 && text.starts_with("0x"),
        "S19k live EEPROM observation has an invalid byte encoding"
    );
    let value = u8::from_str_radix(&text[2..], 16)
        .context("S19k live EEPROM observation is not hexadecimal")?;
    Ok(Some(value))
}

fn s19k_live_identity_transcript(
    normalized_mtd: &[String],
    model_sha256: &str,
    profile: S19kLiveHardwareProfile,
) -> String {
    let mut lines = vec![
        format!("schema={S19K_LIVE_IDENTITY_SCHEMA}"),
        format!("profile={}", profile.as_str()),
        format!("cpu={S19K_LIVE_CPU_TUPLE}"),
        "bos_platform=am3-aml".to_string(),
        "bos_mode=nand".to_string(),
    ];
    lines.extend(normalized_mtd.iter().cloned());
    lines.extend([
        "model=Antminer S19K Pro NoPic".to_string(),
        "vendor=Antminer S19k Pro".to_string(),
        format!("model_sha256={model_sha256}"),
        format!("board_count={}", profile.board_count()),
        format!("physical_addresses={}", profile.physical_addresses()),
        format!("board_names={}", profile.board_names()),
        format!("eeprom={}", profile.eeprom_slots()),
    ]);
    format!("{}\n", lines.join("\n"))
}

fn s19k_capture_live_identity() -> Result<S19kLiveIdentityReceipt> {
    anyhow::ensure!(
        s19k_linux_machine()? == "aarch64",
        "S19k live identity uname machine is not exact aarch64"
    );
    let cpuinfo = s19k_read_regular_nonsymlink(Path::new("/proc/cpuinfo"), "/proc/cpuinfo")?;
    s19k_validate_cpuinfo(
        std::str::from_utf8(&cpuinfo).context("S19k live /proc/cpuinfo is not UTF-8")?,
    )?;
    s19k_exact_text_file(
        Path::new("/etc/bos_platform"),
        "/etc/bos_platform",
        "am3-aml",
    )?;
    s19k_exact_text_file(Path::new("/etc/bos_mode"), "/etc/bos_mode", "nand")?;
    let mtd = s19k_read_regular_nonsymlink(Path::new("/proc/mtd"), "/proc/mtd")?;
    let normalized_mtd = s19k_normalize_mtd_map(
        std::str::from_utf8(&mtd).context("S19k live /proc/mtd is not UTF-8")?,
    )?;
    let model_path = Path::new("/etc/bosminer_model.json");
    let model = s19k_read_regular_nonsymlink(model_path, "/etc/bosminer_model.json")?;
    let profile = s19k_decode_live_model(&model)?;
    let model_sha256 = format!("{:x}", Sha256::digest(&model));

    let mut eeprom_observed = [false; 3];
    let mut eeprom_fields = Vec::with_capacity(3);
    for (slot, address) in (0x50u8..=0x52).enumerate() {
        match s19k_i2cget_byte(address, 0)? {
            None => eeprom_fields.push(format!("0x{address:02x}=absent")),
            Some(first) => {
                let second = s19k_i2cget_byte(address, 1)?.with_context(|| {
                    format!("partial S19k EEPROM identity read at 0x{address:02x}")
                })?;
                anyhow::ensure!(
                    first == 0x05 && second == 0x11,
                    "live EEPROM at 0x{address:02x} is not held S19K preamble 05:11"
                );
                eeprom_observed[slot] = true;
                eeprom_fields.push(format!("0x{address:02x}=05:11"));
            }
        }
    }
    s19k_require_live_eeprom_profile(profile, eeprom_observed)?;
    let eeprom_slots = eeprom_fields.join(",");
    anyhow::ensure!(
        eeprom_slots == profile.eeprom_slots(),
        "canonical EEPROM transcript does not match exact S19k profile {}",
        profile.as_str()
    );
    let transcript = s19k_live_identity_transcript(&normalized_mtd, &model_sha256, profile);
    let sha256 = format!("{:x}", Sha256::digest(transcript.as_bytes()));
    Ok(S19kLiveIdentityReceipt {
        sha256,
        model_sha256,
        profile,
        board_count: profile.board_count(),
        physical_addresses: profile.physical_addresses().to_string(),
        board_names: profile.board_names().to_string(),
        eeprom_slots,
    })
}

fn s19k_capture_and_require_bound_live_identity() -> Result<S19kLiveIdentityReceipt> {
    let expected = std::env::var(S19K_LIVE_IDENTITY_ENV)
        .context("S19k live identity receipt digest is missing")?;
    s19k_require_lower_hex_sha256(&expected, S19K_LIVE_IDENTITY_ENV)?;
    let observed = s19k_capture_live_identity()?;
    anyhow::ensure!(
        observed.sha256 == expected,
        "fresh S19k live identity digest does not match the runner receipt"
    );
    Ok(observed)
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct S19kTrack1ReceiptAuthority {
    active: PathBuf,
    retained: PathBuf,
    terminal: PathBuf,
    startup_j0: PathBuf,
    startup_c1: PathBuf,
    startup_j1: PathBuf,
    startup_j2: PathBuf,
    startup_release: PathBuf,
    startup_parent_lost: PathBuf,
}

impl S19kTrack1ReceiptAuthority {
    pub(crate) fn from_cli(active: &str, retained: &str) -> Result<Self> {
        let active = PathBuf::from(active);
        let retained = PathBuf::from(retained);
        anyhow::ensure!(
            active.is_absolute() && retained.is_absolute(),
            "S19k Track-1 receipt paths must be absolute"
        );
        anyhow::ensure!(
            active.file_name().and_then(|name| name.to_str()) == Some("runtime_active")
                && retained.file_name().and_then(|name| name.to_str())
                    == Some("runtime_stock_owner_retained_closed"),
            "S19k Track-1 receipt paths have unexpected basenames"
        );
        let active_parent = active
            .parent()
            .context("S19k Track-1 runtime_active has no parent")?;
        anyhow::ensure!(
            retained.parent() == Some(active_parent),
            "S19k Track-1 retained receipt must share runtime_active trial directory"
        );
        let trial = active_parent
            .to_str()
            .context("S19k Track-1 trial directory is not UTF-8")?;
        let suffix = trial
            .strip_prefix("/tmp/dcentrald_bench_t1_")
            .context("S19k Track-1 receipt authority is outside the exact /tmp namespace")?;
        anyhow::ensure!(
            !suffix.is_empty()
                && !suffix.contains('/')
                && suffix
                    .bytes()
                    .all(|byte| byte.is_ascii_alphanumeric() || b"._-".contains(&byte)),
            "S19k Track-1 receipt authority has an unsafe trial suffix"
        );
        let trial_metadata = std::fs::symlink_metadata(active_parent)
            .context("S19k Track-1 cannot inspect trial directory authority")?;
        anyhow::ensure!(
            trial_metadata.file_type().is_dir()
                && !trial_metadata.file_type().is_symlink()
                && trial_metadata.uid() == 0
                && trial_metadata.permissions().mode() & 0o777 == 0o700,
            "S19k Track-1 trial directory must be a real root-owned mode-0700 directory"
        );
        let terminal = active_parent.join("runtime_terminal_safeoff");
        // J0 is also the sole canonical global owner. Keeping one inode avoids
        // an owner-link -> trial-link crash suffix with two apparent sources
        // of authority.
        let startup_j0 = PathBuf::from("/tmp/dcent-s19k-track1-runtime-lock/owner");
        let startup_c1 = active_parent.join("runtime_startup_c1_child_identity");
        let startup_j1 = active_parent.join("runtime_startup_j1_daemon_blocked");
        let startup_j2 = active_parent.join("runtime_startup_j2_child_bound");
        let startup_release = active_parent.join("runtime_startup_release");
        let startup_parent_lost = active_parent.join("runtime_startup_parent_lost");
        Ok(Self {
            active,
            retained,
            terminal,
            startup_j0,
            startup_c1,
            startup_j1,
            startup_j2,
            startup_release,
            startup_parent_lost,
        })
    }
}

fn s19k_ephemeral_trial_parent(path: &Path) -> Result<&Path> {
    let parent = path
        .parent()
        .context("S19k ephemeral publication path has no parent")?;
    let trial = parent
        .to_str()
        .context("S19k ephemeral publication parent is not UTF-8")?;
    let suffix = trial
        .strip_prefix("/tmp/dcentrald_bench_t1_")
        .context("S19k ephemeral publication is outside the trial namespace")?;
    anyhow::ensure!(
        !suffix.is_empty()
            && !suffix.contains('/')
            && suffix
                .bytes()
                .all(|byte| byte.is_ascii_alphanumeric() || b"._-".contains(&byte)),
        "S19k ephemeral publication trial suffix is unsafe"
    );
    let metadata = std::fs::symlink_metadata(parent)
        .context("S19k cannot inspect ephemeral publication parent")?;
    anyhow::ensure!(
        metadata.file_type().is_dir()
            && !metadata.file_type().is_symlink()
            && metadata.uid() == 0
            && metadata.permissions().mode() & 0o777 == 0o700,
        "S19k ephemeral publication parent must be root-owned mode-0700"
    );
    Ok(parent)
}

/// Parent of an endurance acknowledgement publication: the trial's
/// `endurance_evidence/acks` directory. The trial root is validated by
/// `s19k_ephemeral_trial_parent`; both intermediate directories must be the
/// root-owned mode-0700 real directories the daemon created.
fn s19k_ephemeral_ack_parent(path: &Path) -> Result<&Path> {
    let acks = path
        .parent()
        .context("S19k acknowledgement publication path has no parent")?;
    let evidence = acks
        .parent()
        .context("S19k acknowledgement directory has no parent")?;
    anyhow::ensure!(
        acks.file_name().and_then(|name| name.to_str()) == Some("acks")
            && evidence.file_name().and_then(|name| name.to_str()) == Some("endurance_evidence"),
        "S19k acknowledgement publication is outside endurance_evidence/acks"
    );
    s19k_ephemeral_trial_parent(evidence)?;
    for (directory, label) in [
        (evidence, "endurance evidence"),
        (acks, "endurance acknowledgement"),
    ] {
        let metadata = std::fs::symlink_metadata(directory)
            .with_context(|| format!("S19k cannot inspect {label} directory"))?;
        anyhow::ensure!(
            metadata.file_type().is_dir()
                && !metadata.file_type().is_symlink()
                && metadata.uid() == 0
                && metadata.permissions().mode() & 0o777 == 0o700,
            "S19k {label} directory must be root-owned mode-0700"
        );
    }
    Ok(acks)
}

/// No-clobber publication primitive used by the shell-owned J0/J2/release
/// records. The source is a private trial-local scratch file. We fsync its
/// bytes, hard-link it to the admitted destination, fsync the destination
/// directory, and compare the two path-bound digests before returning.
pub(crate) fn s19k_publish_ephemeral_journal_from_cli(
    source: &str,
    destination: &str,
) -> Result<()> {
    // Name-level admission is the single shared set in dcentrald-common; the
    // runner contract resolves every publisher call against the same set, so
    // a receipt the runner publishes but this binary refuses fails at host
    // test time (2026-09-01: five post-SafeOff receipts were refused live).
    let publication = classify_s19k_ephemeral_journal_destination(source, destination)
        .map_err(|reason| anyhow::anyhow!("{reason}"))?;
    let source = PathBuf::from(source);
    let destination = PathBuf::from(destination);
    anyhow::ensure!(
        source.is_absolute() && destination.is_absolute(),
        "S19k journal source/destination must be absolute"
    );
    let source_parent = match publication {
        S19kEphemeralJournalDestination::EnduranceAck => s19k_ephemeral_ack_parent(&source)?,
        S19kEphemeralJournalDestination::TrialJournal
        | S19kEphemeralJournalDestination::GlobalOwner => s19k_ephemeral_trial_parent(&source)?,
    };
    let destination_parent = destination
        .parent()
        .context("S19k journal destination has no parent")?;
    match publication {
        S19kEphemeralJournalDestination::GlobalOwner => {
            let lock_metadata = std::fs::symlink_metadata(destination_parent)
                .context("S19k global startup lock directory is absent")?;
            anyhow::ensure!(
                lock_metadata.file_type().is_dir()
                    && !lock_metadata.file_type().is_symlink()
                    && lock_metadata.uid() == 0
                    && lock_metadata.permissions().mode() & 0o777 == 0o700,
                "S19k global startup lock must be root-owned mode-0700"
            );
        }
        S19kEphemeralJournalDestination::TrialJournal
        | S19kEphemeralJournalDestination::EnduranceAck => {
            anyhow::ensure!(
                destination_parent == source_parent,
                "S19k journal destination must share the admitted source directory"
            );
        }
    }
    s19k_require_path_absent(&destination, "startup journal destination")?;
    let source_metadata =
        std::fs::symlink_metadata(&source).context("S19k startup journal scratch is absent")?;
    anyhow::ensure!(
        source_metadata.file_type().is_file()
            && !source_metadata.file_type().is_symlink()
            && source_metadata.uid() == 0
            && source_metadata.permissions().mode() & 0o777 == 0o600,
        "S19k startup journal scratch must be root-owned mode-0600"
    );
    let source_file = OpenOptions::new()
        .read(true)
        .write(true)
        .custom_flags(libc::O_CLOEXEC | libc::O_NOFOLLOW)
        .open(&source)
        .context("S19k cannot open startup journal scratch")?;
    source_file
        .sync_all()
        .context("S19k cannot fsync startup journal scratch")?;
    let source_digest = s19k_hash_regular_nonsymlink(&source, "startup journal scratch")?;
    let source_inode = source_file
        .metadata()
        .context("S19k cannot re-fstat startup journal scratch before publication")?
        .ino();
    std::fs::hard_link(&source, &destination)
        .context("S19k cannot no-clobber publish startup journal")?;
    let directory = OpenOptions::new()
        .read(true)
        .custom_flags(libc::O_CLOEXEC | libc::O_DIRECTORY)
        .open(destination_parent)
        .context("S19k cannot open startup journal directory for fsync")?;
    directory
        .sync_all()
        .context("S19k cannot fsync startup journal directory")?;
    let destination_metadata = std::fs::symlink_metadata(&destination)
        .context("S19k cannot lstat published startup journal")?;
    anyhow::ensure!(
        destination_metadata.file_type().is_file()
            && !destination_metadata.file_type().is_symlink()
            && destination_metadata.ino() == source_inode
            && destination_metadata.nlink() >= 2
            && source_digest
                == s19k_hash_regular_nonsymlink(&destination, "published startup journal")?,
        "S19k startup journal did not preserve the exact hard-linked inode/content"
    );
    Ok(())
}

const S19K_GUARDED_UNLINK_MAX_BYTES: u64 = 1024 * 1024;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum S19kGuardedUnlinkPhase {
    AfterInitialAdmission,
    AfterClaimRename,
    BeforeCompletionRename,
    AfterCompletionRenameBeforeFsync,
    AfterCompletionFsync,
    BeforePostcondition,
    AfterPostcondition,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum S19kGuardedConsumePhase {
    BeforeUnlink,
    AfterUnlinkBeforeFsync,
    AfterUnlinkFsync,
    BeforePostcondition,
    AfterPostcondition,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct S19kGuardedFileState {
    dev: u64,
    inode: u64,
    mode: u32,
    uid: u32,
    gid: u32,
    nlink: u64,
    bytes: u64,
    mnt_id: u64,
    sha256: [u8; 32],
}

fn s19k_guarded_unlink_mnt_id(file: &File, label: &str) -> Result<u64> {
    let text = std::fs::read_to_string(format!("/proc/self/fdinfo/{}", file.as_raw_fd()))
        .with_context(|| format!("S19k cannot read {label} fdinfo"))?;
    let values = text
        .lines()
        .filter_map(|line| line.strip_prefix("mnt_id:"))
        .map(str::trim)
        .collect::<Vec<_>>();
    anyhow::ensure!(
        values.len() == 1,
        "S19k {label} fdinfo has no unique mount identity"
    );
    values[0]
        .parse::<u64>()
        .with_context(|| format!("S19k {label} mount identity is invalid"))
}

fn s19k_capture_guarded_file(file: &mut File, label: &str) -> Result<S19kGuardedFileState> {
    let before = file
        .metadata()
        .with_context(|| format!("S19k cannot fstat {label}"))?;
    anyhow::ensure!(
        before.file_type().is_file()
            && before.uid() == 0
            && before.gid() == 0
            && before.mode() & 0o7777 == 0o600
            && before.len() <= S19K_GUARDED_UNLINK_MAX_BYTES,
        "S19k {label} is not an exact root-owned mode-0600 bounded regular file"
    );
    let mnt_id = s19k_guarded_unlink_mnt_id(file, label)?;
    file.seek(SeekFrom::Start(0))
        .with_context(|| format!("S19k cannot rewind {label}"))?;
    let mut hasher = Sha256::new();
    let mut bytes = 0u64;
    let mut buffer = [0u8; 8192];
    loop {
        let read = file
            .read(&mut buffer)
            .with_context(|| format!("S19k cannot read held {label}"))?;
        if read == 0 {
            break;
        }
        bytes = bytes
            .checked_add(read as u64)
            .context("S19k guarded-unlink byte count overflow")?;
        anyhow::ensure!(
            bytes <= S19K_GUARDED_UNLINK_MAX_BYTES,
            "S19k held {label} exceeds guarded-unlink bound"
        );
        hasher.update(&buffer[..read]);
    }
    let after = file
        .metadata()
        .with_context(|| format!("S19k cannot re-fstat {label}"))?;
    anyhow::ensure!(
        before.dev() == after.dev()
            && before.ino() == after.ino()
            && before.mode() == after.mode()
            && before.uid() == after.uid()
            && before.gid() == after.gid()
            && before.nlink() == after.nlink()
            && before.len() == after.len()
            && before.len() == bytes
            && mnt_id == s19k_guarded_unlink_mnt_id(file, label)?,
        "S19k held {label} changed during guarded capture"
    );
    file.seek(SeekFrom::Start(0))
        .with_context(|| format!("S19k cannot restore {label} offset"))?;
    Ok(S19kGuardedFileState {
        dev: before.dev(),
        inode: before.ino(),
        mode: before.mode(),
        uid: before.uid(),
        gid: before.gid(),
        nlink: before.nlink(),
        bytes,
        mnt_id,
        sha256: hasher.finalize().into(),
    })
}

fn s19k_openat_guarded_optional(
    directory: &File,
    name: &CString,
    label: &str,
) -> Result<Option<File>> {
    // SAFETY: directory is a held O_DIRECTORY file descriptor and name is a
    // validated single-component CString. The returned descriptor is uniquely
    // owned by File on success.
    let fd = unsafe {
        libc::openat(
            directory.as_raw_fd(),
            name.as_ptr(),
            libc::O_RDONLY | libc::O_CLOEXEC | libc::O_NOFOLLOW | libc::O_NONBLOCK,
        )
    };
    if fd >= 0 {
        // SAFETY: fd is a newly opened descriptor owned by this call.
        return Ok(Some(unsafe { File::from_raw_fd(fd) }));
    }
    let error = std::io::Error::last_os_error();
    if error.kind() == std::io::ErrorKind::NotFound {
        return Ok(None);
    }
    Err(error).with_context(|| format!("S19k cannot open guarded {label}"))
}

fn s19k_guarded_unlink_names_are_exact(
    scratch_name: &str,
    canonical_name: &str,
    claim_name: &str,
    completion_name: &str,
) -> bool {
    let contracts = [
        (
            ".runtime_startup_prefix_pre_safeoff.tmp.",
            ".runtime_startup_prefix_pre_safeoff.claim.",
            ".runtime_startup_prefix_pre_safeoff.completed.",
            "runtime_startup_prefix_pre_safeoff",
        ),
        (
            ".runtime_safeoff_terminal_receipt.tmp.",
            ".runtime_safeoff_terminal_receipt.claim.",
            ".runtime_safeoff_terminal_receipt.completed.",
            "runtime_safeoff_terminal_receipt",
        ),
        (
            ".runtime_safeoff_terminal_receipt_receiptless.tmp.",
            ".runtime_safeoff_terminal_receipt_receiptless.claim.",
            ".runtime_safeoff_terminal_receipt_receiptless.completed.",
            "runtime_safeoff_terminal_receipt",
        ),
        (
            ".runtime_safeoff_terminal_receipt_startup_prefix.tmp.",
            ".runtime_safeoff_terminal_receipt_startup_prefix.claim.",
            ".runtime_safeoff_terminal_receipt_startup_prefix.completed.",
            "runtime_safeoff_terminal_receipt",
        ),
    ];
    contracts.iter().any(
        |(scratch_prefix, claim_prefix, completion_prefix, canonical)| {
            if canonical_name != *canonical {
                return false;
            }
            let Some(scratch_suffix) = scratch_name.strip_prefix(scratch_prefix) else {
                return false;
            };
            let Some(claim_suffix) = claim_name.strip_prefix(claim_prefix) else {
                return false;
            };
            let Some(completion_suffix) = completion_name.strip_prefix(completion_prefix) else {
                return false;
            };
            let mut fields = scratch_suffix.split('.');
            let (Some(pid), Some(start), None) = (fields.next(), fields.next(), fields.next())
            else {
                return false;
            };
            scratch_suffix == claim_suffix
                && scratch_suffix == completion_suffix
                && pid.parse::<u32>().is_ok_and(|value| value > 1)
                && start.parse::<u64>().is_ok_and(|value| value > 0)
        },
    )
}

fn s19k_guarded_unlink_ephemeral_hardlink_with_hook<F>(
    scratch: &Path,
    canonical: &Path,
    claim: &Path,
    completion: &Path,
    mut hook: F,
) -> Result<()>
where
    F: FnMut(S19kGuardedUnlinkPhase, &Path, &Path, &Path, &Path) -> Result<()>,
{
    anyhow::ensure!(
        scratch.is_absolute()
            && canonical.is_absolute()
            && claim.is_absolute()
            && completion.is_absolute(),
        "S19k guarded-unlink paths must be absolute"
    );
    let trial = s19k_ephemeral_trial_parent(scratch)?;
    anyhow::ensure!(
        canonical.parent() == Some(trial)
            && claim.parent() == Some(trial)
            && completion.parent() == Some(trial),
        "S19k guarded-unlink paths do not share the exact trial directory"
    );
    let scratch_name = scratch
        .file_name()
        .and_then(|value| value.to_str())
        .context("S19k guarded-unlink scratch basename is invalid")?;
    let canonical_name = canonical
        .file_name()
        .and_then(|value| value.to_str())
        .context("S19k guarded-unlink canonical basename is invalid")?;
    let claim_name = claim
        .file_name()
        .and_then(|value| value.to_str())
        .context("S19k guarded-unlink claim basename is invalid")?;
    let completion_name = completion
        .file_name()
        .and_then(|value| value.to_str())
        .context("S19k guarded-unlink completion basename is invalid")?;
    anyhow::ensure!(
        s19k_guarded_unlink_names_are_exact(
            scratch_name,
            canonical_name,
            claim_name,
            completion_name,
        ),
        "S19k guarded-unlink basename contract is invalid"
    );
    let scratch_name = CString::new(scratch_name)?;
    let canonical_name = CString::new(canonical_name)?;
    let claim_name = CString::new(claim_name)?;
    let completion_name = CString::new(completion_name)?;
    let directory = OpenOptions::new()
        .read(true)
        .custom_flags(libc::O_CLOEXEC | libc::O_DIRECTORY | libc::O_NOFOLLOW)
        .open(trial)
        .context("S19k cannot open guarded-unlink trial directory")?;
    let directory_metadata = directory
        .metadata()
        .context("S19k cannot fstat guarded-unlink trial directory")?;
    anyhow::ensure!(
        directory_metadata.file_type().is_dir()
            && directory_metadata.uid() == 0
            && directory_metadata.gid() == 0
            && directory_metadata.mode() & 0o7777 == 0o700,
        "S19k guarded-unlink trial directory is not exact root-owned mode-0700"
    );
    let mut canonical_file =
        s19k_openat_guarded_optional(&directory, &canonical_name, "canonical authority")?
            .context("S19k guarded-unlink canonical authority is absent")?;
    let scratch_file = s19k_openat_guarded_optional(&directory, &scratch_name, "scratch hardlink")?;
    let claim_file = s19k_openat_guarded_optional(&directory, &claim_name, "typed claim")?;
    let completion_file =
        s19k_openat_guarded_optional(&directory, &completion_name, "typed completion")?;
    let (mut candidate_file, phase) = match (scratch_file, claim_file, completion_file) {
        (Some(file), None, None) => (file, 0u8),
        (None, Some(file), None) => (file, 1u8),
        (None, None, Some(file)) => (file, 2u8),
        _ => anyhow::bail!(
            "S19k guarded-unlink requires exactly one scratch, claim, or completion path"
        ),
    };
    let initial_candidate = s19k_capture_guarded_file(&mut candidate_file, "scratch-or-claim")?;
    let initial_canonical = s19k_capture_guarded_file(&mut canonical_file, "canonical authority")?;
    anyhow::ensure!(
        initial_candidate == initial_canonical && initial_candidate.nlink >= 2,
        "S19k guarded-unlink candidate is not the exact canonical hardlink"
    );
    hook(
        S19kGuardedUnlinkPhase::AfterInitialAdmission,
        scratch,
        canonical,
        claim,
        completion,
    )?;

    if phase == 0 {
        // SAFETY: both names are validated single components beneath the held
        // exact trial dirfd. RENAME_NOREPLACE makes a pre-existing claim a hard
        // refusal rather than overwriting recovery evidence.
        let renamed = unsafe {
            libc::syscall(
                libc::SYS_renameat2,
                directory.as_raw_fd(),
                scratch_name.as_ptr(),
                directory.as_raw_fd(),
                claim_name.as_ptr(),
                libc::RENAME_NOREPLACE,
            )
        };
        anyhow::ensure!(
            renamed == 0,
            "S19k cannot atomically claim guarded-unlink scratch: {}",
            std::io::Error::last_os_error()
        );
        directory
            .sync_all()
            .context("S19k cannot fsync guarded-unlink claim rename")?;
        hook(
            S19kGuardedUnlinkPhase::AfterClaimRename,
            scratch,
            canonical,
            claim,
            completion,
        )?;
        anyhow::ensure!(
            s19k_openat_guarded_optional(&directory, &scratch_name, "retired scratch")?.is_none(),
            "S19k guarded-unlink scratch still exists after claim rename"
        );
    } else if phase == 1 {
        anyhow::ensure!(
            s19k_openat_guarded_optional(&directory, &scratch_name, "resumed scratch")?.is_none(),
            "S19k crash-left guarded claim conflicts with a scratch path"
        );
    }

    if phase < 2 {
        let mut claimed_file =
            s19k_openat_guarded_optional(&directory, &claim_name, "claimed hardlink")?
                .context("S19k guarded-unlink typed claim is absent after rename/resume")?;
        let claimed_state = s19k_capture_guarded_file(&mut claimed_file, "typed claim")?;
        let canonical_before_completion = s19k_capture_guarded_file(
            &mut canonical_file,
            "canonical authority before completion",
        )?;
        anyhow::ensure!(
            claimed_state == initial_candidate
                && canonical_before_completion == initial_canonical
                && claimed_state == canonical_before_completion,
            "S19k guarded-unlink claim/canonical relation changed before completion"
        );
        hook(
            S19kGuardedUnlinkPhase::BeforeCompletionRename,
            scratch,
            canonical,
            claim,
            completion,
        )?;
        // SAFETY: claim/completion are validated single components beneath the
        // held exact trial dirfd. NOREPLACE preserves any prior completion.
        let completed = unsafe {
            libc::syscall(
                libc::SYS_renameat2,
                directory.as_raw_fd(),
                claim_name.as_ptr(),
                directory.as_raw_fd(),
                completion_name.as_ptr(),
                libc::RENAME_NOREPLACE,
            )
        };
        anyhow::ensure!(
            completed == 0,
            "S19k cannot atomically publish guarded-unlink completion: {}",
            std::io::Error::last_os_error()
        );
        hook(
            S19kGuardedUnlinkPhase::AfterCompletionRenameBeforeFsync,
            scratch,
            canonical,
            claim,
            completion,
        )?;
    }
    directory
        .sync_all()
        .context("S19k cannot fsync guarded-unlink completion authority")?;
    hook(
        S19kGuardedUnlinkPhase::AfterCompletionFsync,
        scratch,
        canonical,
        claim,
        completion,
    )?;
    anyhow::ensure!(
        s19k_openat_guarded_optional(&directory, &scratch_name, "completed scratch")?.is_none()
            && s19k_openat_guarded_optional(&directory, &claim_name, "completed claim")?.is_none(),
        "S19k guarded-unlink scratch or claim survived completion"
    );
    hook(
        S19kGuardedUnlinkPhase::BeforePostcondition,
        scratch,
        canonical,
        claim,
        completion,
    )?;
    let mut completed_file =
        s19k_openat_guarded_optional(&directory, &completion_name, "completion authority")?
            .context("S19k guarded-unlink completion authority is absent")?;
    let completed_state = s19k_capture_guarded_file(&mut completed_file, "completion authority")?;
    let canonical_after =
        s19k_capture_guarded_file(&mut canonical_file, "canonical after completion")?;
    let held_after = s19k_capture_guarded_file(&mut candidate_file, "held completion inode")?;
    anyhow::ensure!(
        completed_state == initial_candidate
            && canonical_after == initial_canonical
            && held_after == initial_candidate
            && completed_state == canonical_after,
        "S19k guarded-unlink durable completion postcondition failed"
    );
    hook(
        S19kGuardedUnlinkPhase::AfterPostcondition,
        scratch,
        canonical,
        claim,
        completion,
    )?;
    Ok(())
}

pub(crate) fn s19k_guarded_unlink_ephemeral_hardlink_from_cli(
    scratch: &str,
    canonical: &str,
    claim: &str,
    completion: &str,
) -> Result<()> {
    s19k_guarded_unlink_ephemeral_hardlink_with_hook(
        Path::new(scratch),
        Path::new(canonical),
        Path::new(claim),
        Path::new(completion),
        |_, _, _, _, _| Ok(()),
    )
}

fn s19k_guarded_completion_name_is_exact(completion_name: &str, canonical_name: &str) -> bool {
    let contracts = [
        (
            ".runtime_startup_prefix_pre_safeoff.completed.",
            "runtime_startup_prefix_pre_safeoff",
        ),
        (
            ".runtime_safeoff_terminal_receipt.completed.",
            "runtime_safeoff_terminal_receipt",
        ),
        (
            ".runtime_safeoff_terminal_receipt_receiptless.completed.",
            "runtime_safeoff_terminal_receipt",
        ),
        (
            ".runtime_safeoff_terminal_receipt_startup_prefix.completed.",
            "runtime_safeoff_terminal_receipt",
        ),
    ];
    contracts.iter().any(|(prefix, canonical)| {
        if canonical_name != *canonical {
            return false;
        }
        let Some(suffix) = completion_name.strip_prefix(prefix) else {
            return false;
        };
        let mut fields = suffix.split('.');
        let (Some(pid), Some(start), None) = (fields.next(), fields.next(), fields.next()) else {
            return false;
        };
        pid.parse::<u32>().is_ok_and(|value| value > 1)
            && start.parse::<u64>().is_ok_and(|value| value > 0)
    })
}

fn s19k_consume_guarded_completion_with_hook<F>(
    completion: &Path,
    canonical: &Path,
    mut hook: F,
) -> Result<()>
where
    F: FnMut(S19kGuardedConsumePhase, &Path, &Path) -> Result<()>,
{
    anyhow::ensure!(
        completion.is_absolute() && canonical.is_absolute(),
        "S19k guarded completion paths must be absolute"
    );
    let trial = s19k_ephemeral_trial_parent(completion)?;
    anyhow::ensure!(
        canonical.parent() == Some(trial),
        "S19k guarded completion/canonical paths do not share the exact trial directory"
    );
    let completion_name = completion
        .file_name()
        .and_then(|value| value.to_str())
        .context("S19k guarded completion basename is invalid")?;
    let canonical_name = canonical
        .file_name()
        .and_then(|value| value.to_str())
        .context("S19k guarded completion canonical basename is invalid")?;
    anyhow::ensure!(
        s19k_guarded_completion_name_is_exact(completion_name, canonical_name),
        "S19k guarded completion basename contract is invalid"
    );
    let completion_name = CString::new(completion_name)?;
    let canonical_name = CString::new(canonical_name)?;
    let directory = OpenOptions::new()
        .read(true)
        .custom_flags(libc::O_CLOEXEC | libc::O_DIRECTORY | libc::O_NOFOLLOW)
        .open(trial)
        .context("S19k cannot open guarded completion trial directory")?;
    let directory_metadata = directory
        .metadata()
        .context("S19k cannot fstat guarded completion trial directory")?;
    anyhow::ensure!(
        directory_metadata.file_type().is_dir()
            && directory_metadata.uid() == 0
            && directory_metadata.gid() == 0
            && directory_metadata.mode() & 0o7777 == 0o700,
        "S19k guarded completion trial directory is not exact root-owned mode-0700"
    );
    let mut completion_file =
        s19k_openat_guarded_optional(&directory, &completion_name, "completion authority")?
            .context("S19k guarded completion authority is absent")?;
    let mut canonical_file = s19k_openat_guarded_optional(
        &directory,
        &canonical_name,
        "completion canonical authority",
    )?
    .context("S19k guarded completion canonical authority is absent")?;
    let initial_completion =
        s19k_capture_guarded_file(&mut completion_file, "completion authority")?;
    let initial_canonical =
        s19k_capture_guarded_file(&mut canonical_file, "completion canonical authority")?;
    anyhow::ensure!(
        initial_completion == initial_canonical && initial_completion.nlink >= 2,
        "S19k completion authority is not the exact canonical hardlink"
    );
    hook(S19kGuardedConsumePhase::BeforeUnlink, completion, canonical)?;
    // SAFETY: completion_name is a validated component beneath the held exact
    // trial dirfd and was just re-opened/fstat'd as the canonical hardlink.
    let unlinked = unsafe { libc::unlinkat(directory.as_raw_fd(), completion_name.as_ptr(), 0) };
    anyhow::ensure!(
        unlinked == 0,
        "S19k cannot consume exact guarded completion: {}",
        std::io::Error::last_os_error()
    );
    hook(
        S19kGuardedConsumePhase::AfterUnlinkBeforeFsync,
        completion,
        canonical,
    )?;
    directory
        .sync_all()
        .context("S19k cannot fsync guarded completion consumption")?;
    hook(
        S19kGuardedConsumePhase::AfterUnlinkFsync,
        completion,
        canonical,
    )?;
    hook(
        S19kGuardedConsumePhase::BeforePostcondition,
        completion,
        canonical,
    )?;
    anyhow::ensure!(
        s19k_openat_guarded_optional(&directory, &completion_name, "consumed completion")?
            .is_none(),
        "S19k guarded completion survived unlink"
    );
    let mut canonical_reopened =
        s19k_openat_guarded_optional(&directory, &canonical_name, "reopened completion canonical")?
            .context("S19k canonical authority vanished after completion consumption")?;
    let held_after = s19k_capture_guarded_file(&mut completion_file, "held consumed completion")?;
    let canonical_after = s19k_capture_guarded_file(
        &mut canonical_file,
        "held completion canonical after unlink",
    )?;
    let reopened_after = s19k_capture_guarded_file(
        &mut canonical_reopened,
        "reopened completion canonical after unlink",
    )?;
    let mut expected_after = initial_completion.clone();
    expected_after.nlink = expected_after
        .nlink
        .checked_sub(1)
        .context("S19k guarded completion link count underflow")?;
    anyhow::ensure!(
        held_after == expected_after
            && canonical_after == expected_after
            && reopened_after == expected_after,
        "S19k guarded completion consumption postcondition failed"
    );
    hook(
        S19kGuardedConsumePhase::AfterPostcondition,
        completion,
        canonical,
    )?;
    Ok(())
}

pub(crate) fn s19k_consume_guarded_completion_from_cli(
    completion: &str,
    canonical: &str,
) -> Result<()> {
    s19k_consume_guarded_completion_with_hook(
        Path::new(completion),
        Path::new(canonical),
        |_, _, _| Ok(()),
    )
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum S19kDurableReplacePhase {
    AfterInitialAdmission,
    AfterNewFileFsync,
    AfterRenameBeforeDirectoryFsync,
    AfterSourceDirectoryFsync,
    AfterDestinationDirectoryFsync,
    BeforePostcondition,
    AfterPostcondition,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum S19kDurableReplaceRole {
    Active,
    Owner,
}

fn s19k_parse_exact_sha256(value: &str, label: &str) -> Result<[u8; 32]> {
    anyhow::ensure!(value.len() == 64, "S19k {label} SHA256 length is invalid");
    let mut result = [0u8; 32];
    for (index, pair) in value.as_bytes().chunks_exact(2).enumerate() {
        let nibble = |byte: u8| -> Option<u8> {
            match byte {
                b'0'..=b'9' => Some(byte - b'0'),
                b'a'..=b'f' => Some(byte - b'a' + 10),
                _ => None,
            }
        };
        let high = nibble(pair[0]).with_context(|| format!("S19k {label} SHA256 is invalid"))?;
        let low = nibble(pair[1]).with_context(|| format!("S19k {label} SHA256 is invalid"))?;
        result[index] = (high << 4) | low;
    }
    Ok(result)
}

fn s19k_durable_replace_directory_state(directory: &File, label: &str) -> Result<(u64, u64)> {
    let metadata = directory
        .metadata()
        .with_context(|| format!("S19k cannot fstat durable-replace {label} directory"))?;
    anyhow::ensure!(
        metadata.file_type().is_dir()
            && metadata.uid() == 0
            && metadata.gid() == 0
            && metadata.mode() & 0o7777 == 0o700,
        "S19k durable-replace {label} directory is not exact root-owned mode-0700"
    );
    Ok((metadata.dev(), metadata.ino()))
}

fn s19k_durable_replace_names_are_exact(
    source_name: &str,
    destination_name: &str,
    expected_suffix: &str,
) -> Option<S19kDurableReplaceRole> {
    let active_source =
        format!(".runtime_active_startup_prefix_stock_restart_pending.tmp.{expected_suffix}");
    let owner_source =
        format!(".runtime_owner_startup_prefix_stock_restart_pending.tmp.{expected_suffix}");
    match (source_name, destination_name) {
        (source, "runtime_active") if source == active_source => {
            Some(S19kDurableReplaceRole::Active)
        }
        (source, "owner") if source == owner_source => Some(S19kDurableReplaceRole::Owner),
        _ => None,
    }
}

fn s19k_durable_replace_with_hook<F>(
    source: &Path,
    destination: &Path,
    expected_suffix: &str,
    expected_old: Option<([u8; 32], u64)>,
    expected_new: ([u8; 32], u64),
    mut hook: F,
) -> Result<()>
where
    F: FnMut(S19kDurableReplacePhase, &Path, &Path) -> Result<()>,
{
    anyhow::ensure!(
        source.is_absolute() && destination.is_absolute(),
        "S19k durable-replace paths must be absolute"
    );
    anyhow::ensure!(
        expected_new.1 > 0 && expected_new.1 <= S19K_GUARDED_UNLINK_MAX_BYTES,
        "S19k durable-replace new byte count is invalid"
    );
    if let Some((_, bytes)) = expected_old {
        anyhow::ensure!(
            bytes > 0 && bytes <= S19K_GUARDED_UNLINK_MAX_BYTES,
            "S19k durable-replace old byte count is invalid"
        );
    }
    let source_parent = s19k_ephemeral_trial_parent(source)?;
    let destination_parent = destination
        .parent()
        .context("S19k durable-replace destination has no parent")?;
    let source_name = source
        .file_name()
        .and_then(|value| value.to_str())
        .context("S19k durable-replace source basename is invalid")?;
    let destination_name = destination
        .file_name()
        .and_then(|value| value.to_str())
        .context("S19k durable-replace destination basename is invalid")?;
    let role = s19k_durable_replace_names_are_exact(source_name, destination_name, expected_suffix)
        .context("S19k durable-replace basename contract is invalid")?;
    anyhow::ensure!(
        role != S19kDurableReplaceRole::Active || destination_parent == source_parent,
        "S19k durable ACTIVE replacement must remain in the exact trial directory"
    );
    let source_name = CString::new(source_name)?;
    let destination_name = CString::new(destination_name)?;
    let source_directory = OpenOptions::new()
        .read(true)
        .custom_flags(libc::O_CLOEXEC | libc::O_DIRECTORY | libc::O_NOFOLLOW)
        .open(source_parent)
        .context("S19k cannot open durable-replace source directory")?;
    let destination_directory = OpenOptions::new()
        .read(true)
        .custom_flags(libc::O_CLOEXEC | libc::O_DIRECTORY | libc::O_NOFOLLOW)
        .open(destination_parent)
        .context("S19k cannot open durable-replace destination directory")?;
    let source_directory_state = s19k_durable_replace_directory_state(&source_directory, "source")?;
    let destination_directory_state =
        s19k_durable_replace_directory_state(&destination_directory, "destination")?;
    anyhow::ensure!(
        source_directory_state.0 == destination_directory_state.0,
        "S19k durable-replace directories are not on the same filesystem"
    );
    let same_directory = source_directory_state == destination_directory_state;

    let source_file =
        s19k_openat_guarded_optional(&source_directory, &source_name, "durable source")?;
    let destination_file = s19k_openat_guarded_optional(
        &destination_directory,
        &destination_name,
        "durable destination",
    )?;
    let mut held_new = match (source_file, destination_file) {
        (Some(mut source_file), destination_file) => {
            let source_state = s19k_capture_guarded_file(&mut source_file, "durable source")?;
            anyhow::ensure!(
                source_state.sha256 == expected_new.0
                    && source_state.bytes == expected_new.1
                    && source_state.nlink == 1
                    && source_state.dev == source_directory_state.0,
                "S19k durable-replace source does not match the exact new record"
            );
            if let Some(mut destination_file) = destination_file {
                let destination_state =
                    s19k_capture_guarded_file(&mut destination_file, "old destination")?;
                anyhow::ensure!(
                    destination_state.dev == destination_directory_state.0,
                    "S19k durable-replace old destination is on the wrong filesystem"
                );
                anyhow::ensure!(
                    destination_state.sha256 != expected_new.0
                        || destination_state.bytes != expected_new.1,
                    "S19k durable-replace refuses simultaneous source and new destination"
                );
                let (old_sha256, old_bytes) = expected_old.context(
                    "S19k durable-replace destination exists but canonical old state is absent",
                )?;
                anyhow::ensure!(
                    destination_state.sha256 == old_sha256 && destination_state.bytes == old_bytes,
                    "S19k durable-replace destination does not match the exact old record"
                );
            } else {
                anyhow::ensure!(
                    expected_old.is_none(),
                    "S19k durable-replace old destination is unexpectedly absent"
                );
            }
            hook(
                S19kDurableReplacePhase::AfterInitialAdmission,
                source,
                destination,
            )?;
            source_file
                .sync_all()
                .context("S19k cannot fsync durable-replace source record")?;
            let source_after_fsync =
                s19k_capture_guarded_file(&mut source_file, "durable source after fsync")?;
            anyhow::ensure!(
                source_after_fsync == source_state,
                "S19k durable-replace source changed during fsync"
            );
            hook(
                S19kDurableReplacePhase::AfterNewFileFsync,
                source,
                destination,
            )?;
            let mut source_reopened =
                s19k_openat_guarded_optional(&source_directory, &source_name, "reopened source")?
                    .context("S19k durable-replace source vanished before rename")?;
            anyhow::ensure!(
                s19k_capture_guarded_file(&mut source_reopened, "reopened source")? == source_state,
                "S19k durable-replace source pathname changed before rename"
            );
            match (
                expected_old,
                s19k_openat_guarded_optional(
                    &destination_directory,
                    &destination_name,
                    "reopened old destination",
                )?,
            ) {
                (None, None) => {}
                (Some((old_sha256, old_bytes)), Some(mut old_file)) => {
                    let old_state =
                        s19k_capture_guarded_file(&mut old_file, "reopened old destination")?;
                    anyhow::ensure!(
                        old_state.sha256 == old_sha256 && old_state.bytes == old_bytes,
                        "S19k durable-replace old destination changed before rename"
                    );
                }
                _ => anyhow::bail!("S19k durable-replace destination state changed before rename"),
            }
            anyhow::ensure!(
                s19k_durable_replace_directory_state(&source_directory, "source before rename")?
                    == source_directory_state
                    && s19k_durable_replace_directory_state(
                        &destination_directory,
                        "destination before rename",
                    )? == destination_directory_state,
                "S19k durable-replace directory identity changed before rename"
            );
            // SAFETY: both names are validated single components under held,
            // exact root-owned dirfds on the same filesystem. flags=0 performs
            // one atomic replacement of the exact old/absent destination.
            let renamed = unsafe {
                libc::syscall(
                    libc::SYS_renameat2,
                    source_directory.as_raw_fd(),
                    source_name.as_ptr(),
                    destination_directory.as_raw_fd(),
                    destination_name.as_ptr(),
                    0,
                )
            };
            anyhow::ensure!(
                renamed == 0,
                "S19k cannot atomically replace durable destination: {}",
                std::io::Error::last_os_error()
            );
            hook(
                S19kDurableReplacePhase::AfterRenameBeforeDirectoryFsync,
                source,
                destination,
            )?;
            source_file
        }
        (None, Some(mut destination_file)) => {
            let destination_state =
                s19k_capture_guarded_file(&mut destination_file, "resumed new destination")?;
            anyhow::ensure!(
                destination_state.sha256 == expected_new.0
                    && destination_state.bytes == expected_new.1
                    && destination_state.nlink == 1
                    && destination_state.dev == destination_directory_state.0,
                "S19k durable-replace source is absent without the exact new destination"
            );
            hook(
                S19kDurableReplacePhase::AfterInitialAdmission,
                source,
                destination,
            )?;
            destination_file
                .sync_all()
                .context("S19k cannot re-fsync resumed durable destination")?;
            anyhow::ensure!(
                s19k_capture_guarded_file(
                    &mut destination_file,
                    "resumed destination after fsync",
                )? == destination_state,
                "S19k resumed durable destination changed during fsync"
            );
            hook(
                S19kDurableReplacePhase::AfterNewFileFsync,
                source,
                destination,
            )?;
            destination_file
        }
        (None, None) => {
            anyhow::bail!("S19k durable-replace has neither a source nor an exact new destination")
        }
    };

    source_directory
        .sync_all()
        .context("S19k cannot fsync durable-replace source directory")?;
    hook(
        S19kDurableReplacePhase::AfterSourceDirectoryFsync,
        source,
        destination,
    )?;
    if !same_directory {
        destination_directory
            .sync_all()
            .context("S19k cannot fsync durable-replace destination directory")?;
    }
    hook(
        S19kDurableReplacePhase::AfterDestinationDirectoryFsync,
        source,
        destination,
    )?;
    hook(
        S19kDurableReplacePhase::BeforePostcondition,
        source,
        destination,
    )?;
    anyhow::ensure!(
        s19k_openat_guarded_optional(&source_directory, &source_name, "retired durable source")?
            .is_none(),
        "S19k durable-replace source survived atomic rename"
    );
    let mut destination_reopened = s19k_openat_guarded_optional(
        &destination_directory,
        &destination_name,
        "reopened durable destination",
    )?
    .context("S19k durable-replace destination is absent after publication")?;
    let destination_after = s19k_capture_guarded_file(
        &mut destination_reopened,
        "durable destination after publish",
    )?;
    let held_after = s19k_capture_guarded_file(&mut held_new, "held durable new record")?;
    anyhow::ensure!(
        destination_after == held_after
            && destination_after.sha256 == expected_new.0
            && destination_after.bytes == expected_new.1
            && destination_after.nlink == 1
            && s19k_durable_replace_directory_state(&source_directory, "source after publish")?
                == source_directory_state
            && s19k_durable_replace_directory_state(
                &destination_directory,
                "destination after publish",
            )? == destination_directory_state,
        "S19k durable-replace postcondition failed"
    );
    hook(
        S19kDurableReplacePhase::AfterPostcondition,
        source,
        destination,
    )?;
    Ok(())
}

pub(crate) fn s19k_durable_replace_from_cli(
    source: &str,
    destination: &str,
    old_sha256: &str,
    old_bytes: &str,
    new_sha256: &str,
    new_bytes: &str,
) -> Result<()> {
    let wrapper_pid = std::env::var("DCENT_S19K_STARTUP_WRAPPER_PID")
        .context("S19k durable-replace wrapper PID is absent")?;
    let wrapper_start = std::env::var("DCENT_S19K_STARTUP_WRAPPER_START")
        .context("S19k durable-replace wrapper start is absent")?;
    anyhow::ensure!(
        wrapper_pid.parse::<u32>().is_ok_and(|value| value > 1)
            && wrapper_start.parse::<u64>().is_ok_and(|value| value > 0),
        "S19k durable-replace wrapper lifetime is invalid"
    );
    let source = Path::new(source);
    let destination = Path::new(destination);
    let suffix = format!("{wrapper_pid}.{wrapper_start}");
    let source_name = source.file_name().and_then(|value| value.to_str());
    let destination_name = destination.file_name().and_then(|value| value.to_str());
    let role = s19k_durable_replace_names_are_exact(
        source_name.context("S19k durable-replace source basename is invalid")?,
        destination_name.context("S19k durable-replace destination basename is invalid")?,
        &suffix,
    )
    .context("S19k durable-replace CLI basename contract is invalid")?;
    if role == S19kDurableReplaceRole::Owner {
        anyhow::ensure!(
            destination == Path::new("/tmp/dcent-s19k-track1-runtime-lock/owner"),
            "S19k durable OWNER replacement destination is not canonical"
        );
    } else {
        anyhow::ensure!(
            destination.parent() == source.parent(),
            "S19k durable ACTIVE replacement escaped the exact trial"
        );
    }
    let expected_old = if old_sha256 == "none" && old_bytes == "0" {
        None
    } else {
        let bytes = old_bytes
            .parse::<u64>()
            .context("S19k durable-replace old byte count is invalid")?;
        Some((s19k_parse_exact_sha256(old_sha256, "old record")?, bytes))
    };
    let expected_new = (
        s19k_parse_exact_sha256(new_sha256, "new record")?,
        new_bytes
            .parse::<u64>()
            .context("S19k durable-replace new byte count is invalid")?,
    );
    s19k_durable_replace_with_hook(
        source,
        destination,
        &suffix,
        expected_old,
        expected_new,
        |_, _, _| Ok(()),
    )
}

fn s19k_read_exact_key_value_file(
    path: &Path,
    label: &str,
    exact_keys: &[&str],
) -> Result<BTreeMap<String, String>> {
    let bytes = s19k_read_regular_nonsymlink(path, label)?;
    anyhow::ensure!(
        bytes.ends_with(b"\n"),
        "S19k {label} lacks terminal newline"
    );
    let text = std::str::from_utf8(&bytes).with_context(|| format!("S19k {label} is not UTF-8"))?;
    let mut fields = BTreeMap::new();
    let mut observed_keys = Vec::new();
    for line in text.lines() {
        let (key, value) = line
            .split_once('=')
            .with_context(|| format!("S19k {label} contains a malformed field"))?;
        anyhow::ensure!(
            !key.is_empty() && fields.insert(key.to_string(), value.to_string()).is_none(),
            "S19k {label} contains an empty or duplicate field"
        );
        observed_keys.push(key);
    }
    anyhow::ensure!(
        observed_keys == exact_keys,
        "S19k {label} has an inexact ordered key set"
    );
    Ok(fields)
}

fn s19k_journal_field<'a>(fields: &'a BTreeMap<String, String>, key: &str) -> Result<&'a str> {
    fields
        .get(key)
        .map(String::as_str)
        .with_context(|| format!("S19k startup journal lacks {key}"))
}

