fn s19k_require_journal_no_effects(fields: &BTreeMap<String, String>) -> Result<()> {
    for key in [
        "watchdog_start_intent",
        "watchdog_armed",
        "signal_attempted",
        "inherited_rails",
        "route_or_uart_opened",
        "hardware_opened",
        "parent_release",
        "persistent_mutation",
    ] {
        anyhow::ensure!(
            s19k_journal_field(fields, key)? == "false",
            "S19k startup journal {key} is not false"
        );
    }
    anyhow::ensure!(
        s19k_journal_field(fields, "publication")? == "no-clobber-hard-link-after-fsync",
        "S19k startup journal publication contract is invalid"
    );
    Ok(())
}

fn s19k_require_recovered_stock_gpio_baseline() -> Result<()> {
    for (gpio, expected_value) in [(437u32, "0"), (454, "0"), (455, "1"), (456, "1")] {
        let root = PathBuf::from(format!("/sys/class/gpio/gpio{gpio}"));
        let direction = std::fs::read_to_string(root.join("direction"))
            .with_context(|| format!("S19k cannot read GPIO{gpio} direction"))?;
        let active_low = std::fs::read_to_string(root.join("active_low"))
            .with_context(|| format!("S19k cannot read GPIO{gpio} active_low"))?;
        let value = std::fs::read_to_string(root.join("value"))
            .with_context(|| format!("S19k cannot read GPIO{gpio} value"))?;
        anyhow::ensure!(
            direction.trim() == "out"
                && active_low.trim() == "0"
                && value.trim() == expected_value,
            "S19k recovered-stock GPIO{gpio} baseline is not out/active_low=0/value={expected_value}"
        );
    }
    Ok(())
}

fn s19k_require_journal_tree_and_artifacts(
    fields: &BTreeMap<String, String>,
    authority: &S19kTrack1ReceiptAuthority,
    expected: &S19kStockHandoffIdentity,
) -> Result<()> {
    let exact = [
        ("supervisor_pid", expected.supervisor.pid.to_string()),
        (
            "supervisor_start",
            expected.supervisor.start_ticks.to_string(),
        ),
        ("supervisor_ppid", expected.supervisor.ppid.to_string()),
        ("supervisor_pgrp", expected.supervisor.pgrp.to_string()),
        (
            "supervisor_session",
            expected.supervisor.session.to_string(),
        ),
        (
            "supervisor_exe",
            expected.supervisor.executable.display().to_string(),
        ),
        (
            "supervisor_cmdline_sha256",
            expected.supervisor.cmdline_sha256.clone(),
        ),
        (
            "supervisor_cmdline_bytes",
            expected.supervisor.cmdline_bytes.to_string(),
        ),
        ("bosminer_pid", expected.bosminer.pid.to_string()),
        ("bosminer_start", expected.bosminer.start_ticks.to_string()),
        ("bosminer_ppid", expected.bosminer.ppid.to_string()),
        ("bosminer_pgrp", expected.bosminer.pgrp.to_string()),
        ("bosminer_session", expected.bosminer.session.to_string()),
        (
            "bosminer_exe",
            expected.bosminer.executable.display().to_string(),
        ),
        (
            "bosminer_cmdline_sha256",
            expected.bosminer.cmdline_sha256.clone(),
        ),
        (
            "bosminer_cmdline_bytes",
            expected.bosminer.cmdline_bytes.to_string(),
        ),
    ];
    for (key, value) in exact {
        anyhow::ensure!(
            s19k_journal_field(fields, key)? == value,
            "S19k startup journal {key} mismatch"
        );
    }
    let pidfile_path = Path::new("/var/run/bosminer.pid");
    let (pidfile_sha256, pidfile_bytes) =
        s19k_hash_regular_nonsymlink(pidfile_path, "stock bosminer pidfile")?;
    let pidfile_content = s19k_read_regular_nonsymlink(pidfile_path, "stock bosminer pidfile")?;
    let expected_pidfile = format!("{}\n", expected.supervisor.pid);
    anyhow::ensure!(
        s19k_journal_field(fields, "stock_pidfile_path")? == "/var/run/bosminer.pid"
            && s19k_journal_field(fields, "stock_pidfile_sha256")? == pidfile_sha256
            && s19k_journal_field(fields, "stock_pidfile_bytes")?.parse::<u64>()? == pidfile_bytes
            && pidfile_content == expected_pidfile.as_bytes(),
        "S19k startup journal stock pidfile does not bind the exact supervisor"
    );
    let parent = authority
        .active
        .parent()
        .context("S19k startup trial parent disappeared")?;
    for (name, sha_key, bytes_key) in [
        ("dcentrald", "binary_sha256", "binary_bytes"),
        ("dcentrald_s19k.toml", "config_sha256", "config_bytes"),
        ("run_trial", "runner_sha256", "runner_bytes"),
        (
            "supervisor_custody_observer",
            "custody_observer_sha256",
            "custody_observer_bytes",
        ),
        (
            "stock_restart_helper",
            "stock_restart_helper_sha256",
            "stock_restart_helper_bytes",
        ),
    ] {
        let (sha, bytes) = s19k_hash_regular_nonsymlink(&parent.join(name), name)?;
        anyhow::ensure!(
            s19k_journal_field(fields, sha_key)? == sha
                && s19k_journal_field(fields, bytes_key)?.parse::<u64>()? == bytes,
            "S19k startup journal artifact {name} mismatch"
        );
    }
    anyhow::ensure!(
        s19k_journal_field(fields, "live_identity_schema")? == S19K_LIVE_IDENTITY_SCHEMA
            && s19k_journal_field(fields, "live_identity_sha256")?
                == std::env::var(S19K_LIVE_IDENTITY_ENV)?,
        "S19k startup journal live identity mismatch"
    );
    anyhow::ensure!(
        s19k_journal_field(fields, "gpio_raw")? == "437:0,454:0,455:1,456:1",
        "S19k startup journal recovered-stock GPIO tuple mismatch"
    );
    s19k_require_recovered_stock_gpio_baseline()?;
    expected.require_exact_tree_at(Path::new("/proc"))?;
    Ok(())
}

fn s19k_read_and_require_j0_static(
    authority: &S19kTrack1ReceiptAuthority,
    expected: &S19kStockHandoffIdentity,
) -> Result<BTreeMap<String, String>> {
    let fields =
        s19k_read_exact_key_value_file(&authority.startup_j0, "startup J0", &S19K_J0_KEYS)?;
    anyhow::ensure!(
        s19k_journal_field(&fields, "schema")? == "dcentos.s19k-startup-j0-prefork/v1"
            && s19k_journal_field(&fields, "ordinal")? == "0"
            && s19k_journal_field(&fields, "predecessor_schema")? == "none"
            && s19k_journal_field(&fields, "predecessor_sha256")? == "none"
            && s19k_journal_field(&fields, "predecessor_bytes")? == "0"
            && s19k_journal_field(&fields, "runtime_active_path")? == "not-published"
            && s19k_journal_field(&fields, "runtime_active_sha256")? == "none"
            && s19k_journal_field(&fields, "runtime_active_bytes")? == "0"
            && s19k_journal_field(&fields, "runtime_active_phase")? == "not-published"
            && s19k_journal_field(&fields, "runtime_owner_path")?
                == "/tmp/dcent-s19k-track1-runtime-lock/owner"
            && s19k_journal_field(&fields, "runtime_owner_binding")? == "self-hardlink"
            && s19k_journal_field(&fields, "fifo_mode")? == "prw-------"
            && s19k_journal_field(&fields, "fifo_uid")? == "0"
            && s19k_journal_field(&fields, "fifo_gid")? == "0"
            && s19k_journal_field(&fields, "writer_role")? == "wrapper"
            && s19k_journal_field(&fields, "daemon_pid")? == "0"
            && s19k_journal_field(&fields, "daemon_start")? == "0",
        "S19k startup J0 phase/authority relation is invalid"
    );
    s19k_require_lower_hex_sha256(
        s19k_journal_field(&fields, "transaction_id")?,
        "startup transaction id",
    )?;
    let owner = Path::new("/tmp/dcent-s19k-track1-runtime-lock/owner");
    let j0_meta = std::fs::symlink_metadata(&authority.startup_j0)?;
    let owner_meta = std::fs::symlink_metadata(owner)?;
    anyhow::ensure!(
        j0_meta.file_type().is_file()
            && owner_meta.file_type().is_file()
            && !j0_meta.file_type().is_symlink()
            && !owner_meta.file_type().is_symlink()
            && j0_meta.ino() == owner_meta.ino()
            && s19k_hash_regular_nonsymlink(owner, "startup J0 global owner")?
                == s19k_hash_regular_nonsymlink(&authority.startup_j0, "startup J0 trial link")?,
        "S19k startup J0/global owner are not the same immutable inode/content"
    );
    let wrapper_pid = s19k_journal_field(&fields, "wrapper_pid")?.parse::<i32>()?;
    let wrapper_start = s19k_journal_field(&fields, "wrapper_start")?.parse::<u64>()?;
    anyhow::ensure!(
        s19k_journal_field(&fields, "writer_pid")? == wrapper_pid.to_string()
            && s19k_journal_field(&fields, "writer_start")? == wrapper_start.to_string()
            && s19k_journal_field(&fields, "writer_ppid")?
                == s19k_journal_field(&fields, "wrapper_ppid")?
            && !s19k_journal_field(&fields, "wrapper_comm")?.is_empty()
            && Path::new(s19k_journal_field(&fields, "wrapper_exe")?).is_absolute()
            && s19k_journal_field(&fields, "wrapper_cmdline_bytes")?.parse::<u64>()? > 0,
        "S19k startup J0 writer/wrapper lifetime relation is invalid"
    );
    s19k_require_lower_hex_sha256(
        s19k_journal_field(&fields, "wrapper_cmdline_sha256")?,
        "startup J0 wrapper cmdline",
    )?;
    s19k_require_lower_hex_sha256(
        s19k_journal_field(&fields, "expected_daemon_cmdline_sha256")?,
        "startup J0 expected daemon cmdline",
    )?;
    s19k_require_lower_hex_sha256(
        s19k_journal_field(&fields, "daemon_environment_sha256")?,
        "startup J0 daemon environment",
    )?;
    anyhow::ensure!(
        s19k_journal_field(&fields, "expected_daemon_cmdline_bytes")?.parse::<u64>()? > 0
            && s19k_journal_field(&fields, "daemon_environment_bytes")?.parse::<u64>()? > 0
            && s19k_journal_field(&fields, "daemon_environment_count")? == "10",
        "S19k startup J0 expected daemon argv/environment sizes are invalid"
    );
    let fifo_path = PathBuf::from(s19k_journal_field(&fields, "fifo_path")?);
    let trial = authority
        .active
        .parent()
        .context("S19k startup J0 trial parent disappeared")?;
    let expected_fifo_name = format!(".startup_fifo.{wrapper_pid}.{wrapper_start}");
    anyhow::ensure!(
        fifo_path.parent() == Some(trial)
            && fifo_path.file_name().and_then(|name| name.to_str())
                == Some(expected_fifo_name.as_str()),
        "S19k startup J0 FIFO path is not the exact transaction-scoped direct child"
    );
    let fifo_metadata =
        std::fs::symlink_metadata(&fifo_path).context("S19k startup J0 FIFO path is absent")?;
    anyhow::ensure!(
        fifo_metadata.file_type().is_fifo()
            && !fifo_metadata.file_type().is_symlink()
            && fifo_metadata.ino() == s19k_journal_field(&fields, "fifo_inode")?.parse::<u64>()?
            && fifo_metadata.permissions().mode() & 0o777 == 0o600
            && fifo_metadata.uid() == 0
            && fifo_metadata.gid() == 0
            && s19k_journal_field(&fields, "fifo_mnt_id")?.parse::<u64>()? > 0,
        "S19k startup J0 FIFO identity/type/mode/owner is invalid"
    );
    anyhow::ensure!(
        s19k_journal_field(&fields, "gpio_raw")? == "437:0,454:0,455:1,456:1",
        "S19k startup J0 does not bind the exact recovered-stock GPIO baseline"
    );
    s19k_require_recovered_stock_gpio_baseline()?;
    s19k_require_journal_no_effects(&fields)?;
    s19k_require_journal_tree_and_artifacts(&fields, authority, expected)?;
    Ok(fields)
}

fn s19k_read_and_require_j0_pre_active(
    authority: &S19kTrack1ReceiptAuthority,
    expected: &S19kStockHandoffIdentity,
) -> Result<BTreeMap<String, String>> {
    let fields = s19k_read_and_require_j0_static(authority, expected)?;
    s19k_require_path_absent(&authority.active, "startup J0 runtime_active")?;
    Ok(fields)
}

fn s19k_publish_text_no_clobber(path: &Path, scratch_label: &str, content: &str) -> Result<()> {
    s19k_require_path_absent(path, scratch_label)?;
    let parent = path
        .parent()
        .context("S19k journal destination parent disappeared")?;
    let (self_pid, self_start, _) = s19k_self_lifetime()?;
    let scratch = parent.join(format!(".{scratch_label}.tmp.{self_pid}.{self_start}"));
    s19k_require_path_absent(&scratch, "startup journal scratch")?;
    let result = (|| -> Result<()> {
        let mut file = OpenOptions::new()
            .write(true)
            .create_new(true)
            .mode(0o600)
            .custom_flags(libc::O_CLOEXEC | libc::O_NOFOLLOW)
            .open(&scratch)
            .context("S19k cannot create startup journal scratch")?;
        file.write_all(content.as_bytes())?;
        file.sync_all()?;
        std::fs::hard_link(&scratch, path)
            .context("S19k cannot no-clobber publish startup journal phase")?;
        let directory = OpenOptions::new()
            .read(true)
            .custom_flags(libc::O_CLOEXEC | libc::O_DIRECTORY)
            .open(parent)?;
        directory.sync_all()?;
        anyhow::ensure!(
            s19k_read_regular_nonsymlink(path, scratch_label)? == content.as_bytes(),
            "S19k published startup journal phase changed"
        );
        Ok(())
    })();
    let _ = std::fs::remove_file(&scratch);
    result
}

fn s19k_self_lifetime() -> Result<(i32, u64, i32)> {
    let pid = std::process::id() as i32;
    let stat = std::fs::read_to_string("/proc/self/stat")?;
    let (_, after_comm) = stat
        .rsplit_once(") ")
        .context("S19k daemon stat is malformed")?;
    let fields = after_comm.split_whitespace().collect::<Vec<_>>();
    anyhow::ensure!(
        fields.len() >= 20 && !matches!(fields[0], "Z" | "X" | "x"),
        "S19k daemon lifetime is not live"
    );
    Ok((pid, fields[19].parse()?, fields[1].parse()?))
}

fn s19k_require_nonterminal_lifetime(pid: i32, start: u64, label: &str) -> Result<()> {
    let stat = std::fs::read_to_string(format!("/proc/{pid}/stat"))
        .with_context(|| format!("S19k cannot read {label} stat"))?;
    let (_, rest) = stat
        .rsplit_once(") ")
        .with_context(|| format!("S19k {label} stat is malformed"))?;
    let fields = rest.split_whitespace().collect::<Vec<_>>();
    anyhow::ensure!(
        fields.len() >= 20
            && fields[19].parse::<u64>()? == start
            && !matches!(fields[0], "Z" | "X" | "x"),
        "S19k {label} lifetime is not exact and nonterminal"
    );
    Ok(())
}

fn s19k_require_j0_wrapper_live(fields: &BTreeMap<String, String>) -> Result<()> {
    let pid = s19k_journal_field(fields, "wrapper_pid")?.parse::<i32>()?;
    let start = s19k_journal_field(fields, "wrapper_start")?.parse::<u64>()?;
    s19k_require_nonterminal_lifetime(pid, start, "startup wrapper")?;
    let root = Path::new("/proc").join(pid.to_string());
    let comm = std::fs::read_to_string(root.join("comm"))?;
    let executable = std::fs::read_link(root.join("exe"))?;
    let cmdline = std::fs::read(root.join("cmdline"))?;
    anyhow::ensure!(
        comm.trim_end() == s19k_journal_field(fields, "wrapper_comm")?
            && executable == PathBuf::from(s19k_journal_field(fields, "wrapper_exe")?)
            && format!("{:x}", Sha256::digest(&cmdline))
                == s19k_journal_field(fields, "wrapper_cmdline_sha256")?
            && cmdline.len().to_string() == s19k_journal_field(fields, "wrapper_cmdline_bytes")?,
        "S19k startup wrapper image/argv changed"
    );
    Ok(())
}

fn s19k_require_exact_daemon_environment(
    j0: &BTreeMap<String, String>,
) -> Result<(String, u64, usize)> {
    let mut expected = BTreeMap::<Vec<u8>, Vec<u8>>::new();
    for (key, value) in [
        ("DCENTOS_EPHEMERAL_RUNTIME", "1".to_string()),
        ("DCENTOS_LOG_RING_DIR", "/tmp/dcent/log".to_string()),
        (
            "DCENT_S19K_LIVE_IDENTITY_SHA256",
            s19k_journal_field(j0, "live_identity_sha256")?.to_string(),
        ),
        ("DCENT_S19K_STARTUP_BOOTSTRAP", "daemon-v1".to_string()),
        (
            "DCENT_S19K_STARTUP_FIFO",
            s19k_journal_field(j0, "fifo_path")?.to_string(),
        ),
        (
            "DCENT_S19K_STARTUP_LOG",
            Path::new(s19k_journal_field(j0, "trial_dir")?)
                .join(format!(
                    ".startup_daemon_transcript.{}.{}",
                    s19k_journal_field(j0, "wrapper_pid")?,
                    s19k_journal_field(j0, "wrapper_start")?
                ))
                .display()
                .to_string(),
        ),
        (
            "DCENT_S19K_STARTUP_WRAPPER_PID",
            s19k_journal_field(j0, "wrapper_pid")?.to_string(),
        ),
        (
            "DCENT_S19K_STARTUP_WRAPPER_START",
            s19k_journal_field(j0, "wrapper_start")?.to_string(),
        ),
        ("DCENT_S19K_TRACK1_STOP_SAFEOFF", "1".to_string()),
        ("PATH", "/usr/bin:/bin:/usr/sbin:/sbin".to_string()),
    ] {
        expected.insert(key.as_bytes().to_vec(), value.into_bytes());
    }
    let actual = std::env::vars_os()
        .map(|(key, value)| {
            (
                key.as_os_str().as_bytes().to_vec(),
                value.as_os_str().as_bytes().to_vec(),
            )
        })
        .collect::<BTreeMap<_, _>>();
    anyhow::ensure!(
        actual == expected,
        "S19k daemon environment is not the exact env-i startup allowlist"
    );
    let mut canonical = Vec::new();
    for (key, value) in &actual {
        canonical.extend_from_slice(key);
        canonical.push(b'=');
        canonical.extend_from_slice(value);
        canonical.push(0);
    }
    let sha256 = format!("{:x}", Sha256::digest(&canonical));
    let bytes = canonical.len() as u64;
    anyhow::ensure!(
        sha256 == s19k_journal_field(j0, "daemon_environment_sha256")?
            && bytes.to_string() == s19k_journal_field(j0, "daemon_environment_bytes")?
            && actual.len().to_string() == s19k_journal_field(j0, "daemon_environment_count")?,
        "S19k daemon environment digest/count does not match immutable J0"
    );
    Ok((sha256, bytes, actual.len()))
}

fn s19k_push_journal_line(content: &mut String, key: &str, value: impl std::fmt::Display) {
    content.push_str(key);
    content.push('=');
    content.push_str(&value.to_string());
    content.push('\n');
}

const S19K_C1_KEYS: [&str; 47] = [
    "schema",
    "transaction_id",
    "ordinal",
    "predecessor_schema",
    "predecessor_sha256",
    "predecessor_bytes",
    "runtime_owner_path",
    "runtime_owner_sha256",
    "runtime_owner_bytes",
    "child_pid",
    "child_start",
    "child_ppid",
    "child_comm",
    "child_exe",
    "child_cmdline_sha256",
    "child_cmdline_bytes",
    "child_environment_sha256",
    "child_environment_bytes",
    "child_environment_count",
    "bootstrap_fd_set",
    "stdin_path",
    "transcript_path",
    "transcript_mnt_id",
    "transcript_inode",
    "transcript_mode",
    "transcript_uid",
    "transcript_gid",
    "wrapper_pid",
    "wrapper_start",
    "wrapper_ppid",
    "wrapper_comm",
    "wrapper_exe",
    "wrapper_cmdline_sha256",
    "wrapper_cmdline_bytes",
    "binary_sha256",
    "binary_bytes",
    "pdeathsig",
    "pdeathsig_scope",
    "watchdog_start_intent",
    "watchdog_armed",
    "signal_attempted",
    "inherited_rails",
    "route_or_uart_opened",
    "hardware_opened",
    "parent_release",
    "persistent_mutation",
    "publication",
];

fn s19k_publish_startup_c1(
    authority: &S19kTrack1ReceiptAuthority,
    j0: &BTreeMap<String, String>,
) -> Result<BTreeMap<String, String>> {
    s19k_require_no_self_watchdog_fd()
        .context("S19k startup C1 inherited a watchdog descriptor")?;
    s19k_require_j0_wrapper_live(j0)?;
    let mut pdeathsig = 0i32;
    let pdeathsig_result =
        unsafe { libc::prctl(libc::PR_GET_PDEATHSIG, &mut pdeathsig as *mut i32, 0, 0, 0) };
    anyhow::ensure!(
        pdeathsig_result == 0 && pdeathsig == libc::SIGKILL,
        "S19k C1 cannot prove permanent PDEATHSIG=SIGKILL"
    );
    let (pid, start, ppid) = s19k_self_lifetime()?;
    let fd_proof = s19k_require_exact_daemon_fd_set(None)?;
    anyhow::ensure!(
        ppid.to_string() == s19k_journal_field(j0, "wrapper_pid")?,
        "S19k C1 child parent does not match J0 wrapper"
    );
    let self_root = Path::new("/proc").join(pid.to_string());
    let comm = std::fs::read_to_string(self_root.join("comm"))?;
    let executable = std::fs::read_link(self_root.join("exe"))?;
    let cmdline = std::fs::read(self_root.join("cmdline"))?;
    let cmdline_sha256 = format!("{:x}", Sha256::digest(&cmdline));
    let (environment_sha256, environment_bytes, environment_count) =
        s19k_require_exact_daemon_environment(j0)?;
    let expected_transcript = Path::new(s19k_journal_field(j0, "trial_dir")?).join(format!(
        ".startup_daemon_transcript.{}.{}",
        s19k_journal_field(j0, "wrapper_pid")?,
        s19k_journal_field(j0, "wrapper_start")?
    ));
    let trial = authority
        .active
        .parent()
        .context("S19k C1 trial parent disappeared")?;
    anyhow::ensure!(
        comm.trim_end() == "dcentrald"
            && executable == trial.join("dcentrald")
            && cmdline_sha256 == s19k_journal_field(j0, "expected_daemon_cmdline_sha256")?
            && cmdline.len().to_string()
                == s19k_journal_field(j0, "expected_daemon_cmdline_bytes")?,
        "S19k C1 daemon image/argv is not the exact J0-bound staged command"
    );
    let owner = s19k_hash_regular_nonsymlink(&authority.startup_j0, "startup C1 owner")?;
    let mut content = String::new();
    for (key, value) in [
        (
            "schema",
            "dcentos.s19k-startup-c1-child-identity/v1".to_string(),
        ),
        (
            "transaction_id",
            s19k_journal_field(j0, "transaction_id")?.to_string(),
        ),
        ("ordinal", "1".to_string()),
        (
            "predecessor_schema",
            s19k_journal_field(j0, "schema")?.to_string(),
        ),
        ("predecessor_sha256", owner.0.clone()),
        ("predecessor_bytes", owner.1.to_string()),
        (
            "runtime_owner_path",
            authority.startup_j0.display().to_string(),
        ),
        ("runtime_owner_sha256", owner.0),
        ("runtime_owner_bytes", owner.1.to_string()),
        ("child_pid", pid.to_string()),
        ("child_start", start.to_string()),
        ("child_ppid", ppid.to_string()),
        ("child_comm", comm.trim_end().to_string()),
        ("child_exe", executable.display().to_string()),
        ("child_cmdline_sha256", cmdline_sha256),
        ("child_cmdline_bytes", cmdline.len().to_string()),
        ("child_environment_sha256", environment_sha256),
        ("child_environment_bytes", environment_bytes.to_string()),
        ("child_environment_count", environment_count.to_string()),
        ("bootstrap_fd_set", "stdio-only".to_string()),
        ("stdin_path", "/dev/null".to_string()),
        ("transcript_path", fd_proof.log_path.display().to_string()),
        ("transcript_mnt_id", fd_proof.log_mnt_id.to_string()),
        ("transcript_inode", fd_proof.log_inode.to_string()),
        ("transcript_mode", format!("{:04o}", fd_proof.log_mode)),
        ("transcript_uid", fd_proof.log_uid.to_string()),
        ("transcript_gid", fd_proof.log_gid.to_string()),
    ] {
        s19k_push_journal_line(&mut content, key, value);
    }
    for key in [
        "wrapper_pid",
        "wrapper_start",
        "wrapper_ppid",
        "wrapper_comm",
        "wrapper_exe",
        "wrapper_cmdline_sha256",
        "wrapper_cmdline_bytes",
        "binary_sha256",
        "binary_bytes",
    ] {
        s19k_push_journal_line(&mut content, key, s19k_journal_field(j0, key)?);
    }
    s19k_push_journal_line(&mut content, "pdeathsig", libc::SIGKILL);
    s19k_push_journal_line(&mut content, "pdeathsig_scope", "process-lifetime");
    for key in [
        "watchdog_start_intent",
        "watchdog_armed",
        "signal_attempted",
        "inherited_rails",
        "route_or_uart_opened",
        "hardware_opened",
        "parent_release",
        "persistent_mutation",
    ] {
        s19k_push_journal_line(&mut content, key, false);
    }
    s19k_push_journal_line(
        &mut content,
        "publication",
        "no-clobber-hard-link-after-fsync",
    );
    s19k_publish_text_no_clobber(&authority.startup_c1, "runtime_startup_c1", &content)?;
    s19k_read_exact_key_value_file(&authority.startup_c1, "startup C1", &S19K_C1_KEYS)
}

fn s19k_require_startup_c1(
    authority: &S19kTrack1ReceiptAuthority,
    j0: &BTreeMap<String, String>,
) -> Result<BTreeMap<String, String>> {
    let c1 = s19k_read_exact_key_value_file(&authority.startup_c1, "startup C1", &S19K_C1_KEYS)?;
    let owner = s19k_hash_regular_nonsymlink(&authority.startup_j0, "startup C1 owner")?;
    let (pid, start, ppid) = s19k_self_lifetime()?;
    let self_root = Path::new("/proc").join(pid.to_string());
    let comm = std::fs::read_to_string(self_root.join("comm"))?;
    let executable = std::fs::read_link(self_root.join("exe"))?;
    let cmdline = std::fs::read(self_root.join("cmdline"))?;
    let (environment_sha256, environment_bytes, environment_count) =
        s19k_require_exact_daemon_environment(j0)?;
    let expected_transcript = Path::new(s19k_journal_field(j0, "trial_dir")?).join(format!(
        ".startup_daemon_transcript.{}.{}",
        s19k_journal_field(j0, "wrapper_pid")?,
        s19k_journal_field(j0, "wrapper_start")?
    ));
    anyhow::ensure!(
        s19k_journal_field(&c1, "schema")? == "dcentos.s19k-startup-c1-child-identity/v1"
            && s19k_journal_field(&c1, "transaction_id")?
                == s19k_journal_field(j0, "transaction_id")?
            && s19k_journal_field(&c1, "ordinal")? == "1"
            && s19k_journal_field(&c1, "predecessor_schema")? == s19k_journal_field(j0, "schema")?
            && s19k_journal_field(&c1, "predecessor_sha256")? == owner.0
            && s19k_journal_field(&c1, "predecessor_bytes")?.parse::<u64>()? == owner.1
            && s19k_journal_field(&c1, "runtime_owner_path")?
                == authority.startup_j0.display().to_string()
            && s19k_journal_field(&c1, "runtime_owner_sha256")? == owner.0
            && s19k_journal_field(&c1, "runtime_owner_bytes")?.parse::<u64>()? == owner.1
            && s19k_journal_field(&c1, "child_pid")? == pid.to_string()
            && s19k_journal_field(&c1, "child_start")? == start.to_string()
            && s19k_journal_field(&c1, "child_ppid")? == ppid.to_string()
            && s19k_journal_field(&c1, "child_comm")? == comm.trim_end()
            && s19k_journal_field(&c1, "child_exe")? == executable.display().to_string()
            && s19k_journal_field(&c1, "child_cmdline_sha256")?
                == format!("{:x}", Sha256::digest(&cmdline))
            && s19k_journal_field(&c1, "child_cmdline_bytes")? == cmdline.len().to_string()
            && s19k_journal_field(&c1, "child_environment_sha256")? == environment_sha256
            && s19k_journal_field(&c1, "child_environment_bytes")? == environment_bytes.to_string()
            && s19k_journal_field(&c1, "child_environment_count")? == environment_count.to_string()
            && s19k_journal_field(&c1, "bootstrap_fd_set")? == "stdio-only"
            && s19k_journal_field(&c1, "stdin_path")? == "/dev/null"
            && s19k_journal_field(&c1, "transcript_path")?
                == expected_transcript.display().to_string()
            && s19k_journal_field(&c1, "transcript_mnt_id")?.parse::<u64>()? > 0
            && s19k_journal_field(&c1, "transcript_inode")?.parse::<u64>()? > 0
            && s19k_journal_field(&c1, "transcript_mode")? == "0600"
            && s19k_journal_field(&c1, "transcript_uid")? == "0"
            && s19k_journal_field(&c1, "transcript_gid")? == "0"
            && s19k_journal_field(&c1, "wrapper_pid")? == s19k_journal_field(j0, "wrapper_pid")?
            && s19k_journal_field(&c1, "wrapper_start")?
                == s19k_journal_field(j0, "wrapper_start")?
            && s19k_journal_field(&c1, "wrapper_ppid")? == s19k_journal_field(j0, "wrapper_ppid")?
            && s19k_journal_field(&c1, "wrapper_comm")? == s19k_journal_field(j0, "wrapper_comm")?
            && s19k_journal_field(&c1, "wrapper_exe")? == s19k_journal_field(j0, "wrapper_exe")?
            && s19k_journal_field(&c1, "wrapper_cmdline_sha256")?
                == s19k_journal_field(j0, "wrapper_cmdline_sha256")?
            && s19k_journal_field(&c1, "wrapper_cmdline_bytes")?
                == s19k_journal_field(j0, "wrapper_cmdline_bytes")?
            && s19k_journal_field(&c1, "binary_sha256")?
                == s19k_journal_field(j0, "binary_sha256")?
            && s19k_journal_field(&c1, "binary_bytes")? == s19k_journal_field(j0, "binary_bytes")?
            && s19k_journal_field(&c1, "pdeathsig")? == "9"
            && s19k_journal_field(&c1, "pdeathsig_scope")? == "process-lifetime",
        "S19k startup C1 relation is invalid"
    );
    s19k_require_journal_no_effects(&c1)?;
    s19k_require_j0_wrapper_live(j0)?;
    Ok(c1)
}

struct S19kStartupFifoReader {
    file: std::fs::File,
    path: PathBuf,
    mnt_id: u64,
    inode: u64,
    mode: u32,
    uid: u32,
    gid: u32,
}

impl S19kStartupFifoReader {
    fn open_and_require_j0(j0: &BTreeMap<String, String>) -> Result<Self> {
        let path = PathBuf::from(s19k_journal_field(j0, "fifo_path")?);
        anyhow::ensure!(
            std::env::var("DCENT_S19K_STARTUP_FIFO")? == path.display().to_string(),
            "S19k startup FIFO environment does not match J0"
        );
        let file = OpenOptions::new()
            .read(true)
            .custom_flags(libc::O_CLOEXEC | libc::O_NOFOLLOW | libc::O_NONBLOCK)
            .open(&path)
            .context("S19k cannot open the J0-bound FIFO reader")?;
        let fd = file.as_raw_fd();
        let metadata = file
            .metadata()
            .context("S19k cannot fstat the held startup FIFO reader")?;
        let fd_target = std::fs::read_link(format!("/proc/self/fd/{fd}"))
            .context("S19k cannot resolve the held startup FIFO descriptor")?;
        let fdinfo = std::fs::read_to_string(format!("/proc/self/fdinfo/{fd}"))
            .context("S19k cannot read held startup FIFO fdinfo")?;
        let mnt_id = fdinfo
            .lines()
            .find_map(|line| line.strip_prefix("mnt_id:").map(str::trim))
            .context("S19k held startup FIFO fdinfo lacks mnt_id")?
            .parse::<u64>()?;
        anyhow::ensure!(
            metadata.file_type().is_fifo()
                && fd_target == path
                && metadata.ino() == s19k_journal_field(j0, "fifo_inode")?.parse::<u64>()?
                && mnt_id == s19k_journal_field(j0, "fifo_mnt_id")?.parse::<u64>()?
                && metadata.permissions().mode() & 0o777 == 0o600
                && metadata.uid() == 0
                && metadata.gid() == 0,
            "S19k held startup FIFO descriptor does not match immutable J0"
        );
        Ok(Self {
            file,
            path,
            mnt_id,
            inode: metadata.ino(),
            mode: metadata.permissions().mode() & 0o777,
            uid: metadata.uid(),
            gid: metadata.gid(),
        })
    }

    fn require_unchanged(&self) -> Result<()> {
        let metadata = self
            .file
            .metadata()
            .context("S19k cannot re-fstat held startup FIFO reader")?;
        let fd = self.file.as_raw_fd();
        let fd_target = std::fs::read_link(format!("/proc/self/fd/{fd}"))?;
        let fdinfo = std::fs::read_to_string(format!("/proc/self/fdinfo/{fd}"))?;
        let mnt_id = fdinfo
            .lines()
            .find_map(|line| line.strip_prefix("mnt_id:").map(str::trim))
            .context("S19k held startup FIFO fdinfo lost mnt_id")?
            .parse::<u64>()?;
        anyhow::ensure!(
            metadata.file_type().is_fifo()
                && fd_target == self.path
                && metadata.ino() == self.inode
                && mnt_id == self.mnt_id
                && metadata.permissions().mode() & 0o777 == self.mode
                && metadata.uid() == self.uid
                && metadata.gid() == self.gid,
            "S19k held startup FIFO identity changed"
        );
        Ok(())
    }

    fn read_exact_token_and_require_eof(&mut self) -> Result<[u8; 64]> {
        self.require_unchanged()?;
        let fd = self.file.as_raw_fd();
        // The release journal is durable before the wrapper opens its sole
        // short-lived writer. A reader with no current writer observes HUP/EOF,
        // so wait boundedly for actual data while retaining O_NONBLOCK instead
        // of racing the journal publication and treating that transient gap as
        // a terminal short read.
        let data_deadline = Instant::now() + Duration::from_secs(2);
        let mut token = [0u8; 64];
        let mut received = 0usize;
        while received < token.len() {
            let mut poll_fd = libc::pollfd {
                fd,
                events: libc::POLLIN | libc::POLLHUP,
                revents: 0,
            };
            let poll_result = unsafe { libc::poll(&mut poll_fd, 1, 20) };
            anyhow::ensure!(poll_result >= 0, "S19k startup FIFO data poll failed");
            anyhow::ensure!(
                poll_fd.revents & (libc::POLLERR | libc::POLLNVAL) == 0,
                "S19k startup FIFO data poll reported an invalid descriptor"
            );
            anyhow::ensure!(
                Instant::now() < data_deadline,
                "S19k startup FIFO release data did not arrive before the bounded deadline"
            );
            if poll_fd.revents & libc::POLLIN != 0 {
                match self.file.read(&mut token[received..]) {
                    Ok(0) if received == 0 => std::thread::sleep(Duration::from_millis(1)),
                    Ok(0) => anyhow::bail!(
                        "S19k startup FIFO closed after only {received} of 64 release bytes"
                    ),
                    Ok(count) => received += count,
                    Err(error) if error.kind() == std::io::ErrorKind::WouldBlock => {}
                    Err(error) => {
                        return Err(error).context("S19k startup FIFO release read failed")
                    }
                }
            } else if poll_fd.revents & libc::POLLHUP != 0 && received > 0 {
                anyhow::bail!(
                    "S19k startup FIFO reached HUP after only {received} of 64 release bytes"
                );
            } else if poll_fd.revents & libc::POLLHUP != 0 {
                // With no writer yet, a FIFO reader legitimately observes
                // HUP/EOF. The wrapper publishes RELEASE before opening its
                // sole short-lived writer, so tolerate this state only until
                // the first byte or the overall data deadline.
                std::thread::sleep(Duration::from_millis(1));
            }
        }

        let eof_deadline = Instant::now() + Duration::from_millis(250);
        loop {
            let mut poll_fd = libc::pollfd {
                fd,
                events: libc::POLLIN | libc::POLLHUP,
                revents: 0,
            };
            let poll_result = unsafe { libc::poll(&mut poll_fd, 1, 20) };
            anyhow::ensure!(poll_result >= 0, "S19k startup FIFO EOF poll failed");
            anyhow::ensure!(
                poll_fd.revents & (libc::POLLERR | libc::POLLNVAL) == 0,
                "S19k startup FIFO EOF poll reported an invalid descriptor"
            );
            if poll_fd.revents & (libc::POLLIN | libc::POLLHUP) != 0 {
                let mut extra = [0u8; 1];
                match self.file.read(&mut extra) {
                    Ok(0) if poll_fd.revents & libc::POLLHUP != 0 => break,
                    Ok(0) => {}
                    Ok(_) => anyhow::bail!("S19k startup FIFO contains extra release bytes"),
                    Err(error) if error.kind() == std::io::ErrorKind::WouldBlock => {}
                    Err(error) => return Err(error).context("S19k cannot prove startup FIFO EOF"),
                }
            }
            anyhow::ensure!(
                Instant::now() < eof_deadline,
                "S19k startup FIFO did not reach bounded writer-closed EOF"
            );
        }
        self.require_unchanged()?;
        Ok(token)
    }
}

#[cfg(test)]
mod s19k_startup_fifo_tests {
    use super::*;
    use std::ffi::CString;
    use std::io::Write;
    use std::time::{SystemTime, UNIX_EPOCH};

    struct FifoFixture {
        path: PathBuf,
    }

    impl Drop for FifoFixture {
        fn drop(&mut self) {
            let _ = std::fs::remove_file(&self.path);
        }
    }

    fn fifo_reader(label: &str) -> (FifoFixture, S19kStartupFifoReader) {
        let nonce = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .expect("clock after epoch")
            .as_nanos();
        let path = PathBuf::from(format!(
            "/tmp/dcent-s19k-startup-fifo-kat-{}-{nonce}-{label}",
            std::process::id()
        ));
        let c_path = CString::new(path.as_os_str().as_bytes()).expect("FIFO path has no NUL");
        assert_eq!(unsafe { libc::mkfifo(c_path.as_ptr(), 0o600) }, 0);
        let file = OpenOptions::new()
            .read(true)
            .custom_flags(libc::O_CLOEXEC | libc::O_NOFOLLOW | libc::O_NONBLOCK)
            .open(&path)
            .expect("open FIFO reader");
        let metadata = file.metadata().expect("FIFO metadata");
        let fd = file.as_raw_fd();
        let fdinfo =
            std::fs::read_to_string(format!("/proc/self/fdinfo/{fd}")).expect("FIFO fdinfo");
        let mnt_id = fdinfo
            .lines()
            .find_map(|line| line.strip_prefix("mnt_id:").map(str::trim))
            .expect("mnt_id")
            .parse::<u64>()
            .expect("numeric mnt_id");
        let reader = S19kStartupFifoReader {
            file,
            path: path.clone(),
            mnt_id,
            inode: metadata.ino(),
            mode: metadata.permissions().mode() & 0o777,
            uid: metadata.uid(),
            gid: metadata.gid(),
        };
        (FifoFixture { path }, reader)
    }

    #[test]
    fn startup_fifo_accepts_delayed_exact_writer_then_eof() {
        let (fixture, mut reader) = fifo_reader("delayed");
        let writer_path = fixture.path.clone();
        let token = [b'a'; 64];
        let writer = std::thread::spawn(move || {
            std::thread::sleep(Duration::from_millis(100));
            let mut file = OpenOptions::new()
                .write(true)
                .open(writer_path)
                .expect("open delayed FIFO writer");
            file.write_all(&token).expect("write exact token");
        });
        assert_eq!(
            reader
                .read_exact_token_and_require_eof()
                .expect("exact delayed token"),
            token
        );
        writer.join().expect("writer thread");
    }

    #[test]
    fn startup_fifo_rejects_partial_token_followed_by_hup() {
        let (fixture, mut reader) = fifo_reader("partial");
        let writer_path = fixture.path.clone();
        let writer = std::thread::spawn(move || {
            std::thread::sleep(Duration::from_millis(50));
            let mut file = OpenOptions::new()
                .write(true)
                .open(writer_path)
                .expect("open partial FIFO writer");
            file.write_all(b"partial").expect("write partial token");
        });
        let started = Instant::now();
        let error = reader
            .read_exact_token_and_require_eof()
            .expect_err("partial token must refuse");
        assert!(error.to_string().contains("only 7 of 64"));
        assert!(started.elapsed() < Duration::from_secs(1));
        writer.join().expect("writer thread");
    }
}

fn s19k_publish_startup_j1(
    authority: &S19kTrack1ReceiptAuthority,
    expected: &S19kStockHandoffIdentity,
    j0: &BTreeMap<String, String>,
    c1: &BTreeMap<String, String>,
    fifo: &S19kStartupFifoReader,
) -> Result<BTreeMap<String, String>> {
    s19k_require_no_self_watchdog_fd()
        .context("S19k startup J1 inherited a watchdog descriptor")?;
    let (daemon_pid, daemon_start, daemon_ppid) = s19k_self_lifetime()?;
    let fd_proof = s19k_require_exact_daemon_fd_set(Some(fifo.file.as_raw_fd()))?;
    let wrapper_pid = s19k_journal_field(j0, "wrapper_pid")?.parse::<i32>()?;
    anyhow::ensure!(
        daemon_ppid == wrapper_pid,
        "S19k daemon parent is neither the exact wrapper nor init"
    );
    let admitted_c1 = s19k_require_startup_c1(authority, j0)?;
    anyhow::ensure!(
        &admitted_c1 == c1,
        "S19k in-memory C1 changed before J1 publication"
    );
    anyhow::ensure!(
        s19k_journal_field(c1, "bootstrap_fd_set")? == "stdio-only"
            && s19k_journal_field(c1, "stdin_path")? == "/dev/null"
            && s19k_journal_field(c1, "transcript_path")?
                == fd_proof.log_path.display().to_string()
            && s19k_journal_field(c1, "transcript_mnt_id")? == fd_proof.log_mnt_id.to_string()
            && s19k_journal_field(c1, "transcript_inode")? == fd_proof.log_inode.to_string()
            && s19k_journal_field(c1, "transcript_mode")? == format!("{:04o}", fd_proof.log_mode)
            && s19k_journal_field(c1, "transcript_uid")? == fd_proof.log_uid.to_string()
            && s19k_journal_field(c1, "transcript_gid")? == fd_proof.log_gid.to_string(),
        "S19k C1 stdio/transcript proof changed before J1"
    );
    let (c1_sha, c1_bytes) = s19k_hash_regular_nonsymlink(&authority.startup_c1, "startup C1")?;
    s19k_require_path_absent(&authority.active, "startup J1 runtime_active")?;
    fifo.require_unchanged()?;
    let owner_path = Path::new("/tmp/dcent-s19k-track1-runtime-lock/owner");
    let (owner_sha, owner_bytes) = s19k_hash_regular_nonsymlink(owner_path, "startup J1 owner")?;
    let mut content = String::new();
    for (key, value) in [
        (
            "schema",
            "dcentos.s19k-startup-j1-daemon-blocked/v1".to_string(),
        ),
        (
            "transaction_id",
            s19k_journal_field(&j0, "transaction_id")?.to_string(),
        ),
        ("ordinal", "2".to_string()),
        (
            "predecessor_schema",
            s19k_journal_field(c1, "schema")?.to_string(),
        ),
        ("predecessor_sha256", c1_sha),
        ("predecessor_bytes", c1_bytes.to_string()),
        (
            "trial_dir",
            s19k_journal_field(j0, "trial_dir")?.to_string(),
        ),
        ("runtime_active_path", "not-published".to_string()),
        ("runtime_active_sha256", "none".to_string()),
        ("runtime_active_bytes", "0".to_string()),
        ("runtime_active_phase", "not-published".to_string()),
        ("runtime_owner_path", owner_path.display().to_string()),
        ("runtime_owner_sha256", owner_sha),
        ("runtime_owner_bytes", owner_bytes.to_string()),
        ("writer_role", "daemon-blocked".to_string()),
        ("writer_pid", daemon_pid.to_string()),
        ("writer_start", daemon_start.to_string()),
        ("writer_ppid", daemon_ppid.to_string()),
        ("daemon_pid", daemon_pid.to_string()),
        ("daemon_start", daemon_start.to_string()),
    ] {
        s19k_push_journal_line(&mut content, key, value);
    }
    for key in [
        "wrapper_pid",
        "wrapper_start",
        "wrapper_ppid",
        "wrapper_comm",
        "wrapper_exe",
        "wrapper_cmdline_sha256",
        "wrapper_cmdline_bytes",
    ] {
        s19k_push_journal_line(&mut content, key, s19k_journal_field(j0, key)?);
    }
    s19k_push_journal_line(&mut content, "pdeathsig", "9");
    s19k_push_journal_line(&mut content, "pdeathsig_scope", "process-lifetime");
    for key in [
        "fifo_path",
        "fifo_mnt_id",
        "fifo_inode",
        "fifo_mode",
        "fifo_uid",
        "fifo_gid",
    ] {
        s19k_push_journal_line(&mut content, key, s19k_journal_field(j0, key)?);
    }
    s19k_push_journal_line(&mut content, "fifo_reader_held", true);
    s19k_push_journal_line(&mut content, "bootstrap_fd_set", "stdio-plus-single-fifo");
    s19k_push_journal_line(
        &mut content,
        "fifo_reader_fd",
        fd_proof
            .fifo_fd
            .context("S19k J1 fd proof lost its FIFO descriptor")?,
    );
    for (key, value) in [
        ("stdin_path", "/dev/null".to_string()),
        ("transcript_path", fd_proof.log_path.display().to_string()),
        ("transcript_mnt_id", fd_proof.log_mnt_id.to_string()),
        ("transcript_inode", fd_proof.log_inode.to_string()),
        ("transcript_mode", format!("{:04o}", fd_proof.log_mode)),
        ("transcript_uid", fd_proof.log_uid.to_string()),
        ("transcript_gid", fd_proof.log_gid.to_string()),
    ] {
        s19k_push_journal_line(&mut content, key, value);
    }
    for key in [
        "supervisor_pid",
        "supervisor_start",
        "supervisor_ppid",
        "supervisor_pgrp",
        "supervisor_session",
        "supervisor_exe",
        "supervisor_cmdline_sha256",
        "supervisor_cmdline_bytes",
        "bosminer_pid",
        "bosminer_start",
        "bosminer_ppid",
        "bosminer_pgrp",
        "bosminer_session",
        "bosminer_exe",
        "bosminer_cmdline_sha256",
        "bosminer_cmdline_bytes",
        "stock_pidfile_path",
        "stock_pidfile_sha256",
        "stock_pidfile_bytes",
        "binary_sha256",
        "binary_bytes",
        "config_sha256",
        "config_bytes",
        "runner_sha256",
        "runner_bytes",
        "custody_observer_sha256",
        "custody_observer_bytes",
        "stock_restart_helper_sha256",
        "stock_restart_helper_bytes",
        "live_identity_schema",
        "live_identity_profile",
        "live_identity_sha256",
        "gpio_raw",
    ] {
        s19k_push_journal_line(&mut content, key, s19k_journal_field(j0, key)?);
    }
    for key in [
        "watchdog_start_intent",
        "watchdog_armed",
        "signal_attempted",
        "inherited_rails",
        "route_or_uart_opened",
        "hardware_opened",
        "parent_release",
        "persistent_mutation",
    ] {
        s19k_push_journal_line(&mut content, key, false);
    }
    s19k_push_journal_line(
        &mut content,
        "publication",
        "no-clobber-hard-link-after-fsync",
    );
    s19k_publish_text_no_clobber(&authority.startup_j1, "runtime_startup_j1", &content)?;
    let j1 = s19k_read_exact_key_value_file(&authority.startup_j1, "startup J1", &S19K_J1_J2_KEYS)?;
    s19k_require_journal_no_effects(&j1)?;
    s19k_require_journal_tree_and_artifacts(&j1, authority, expected)?;
    Ok(j1)
}

const S19K_RELEASE_KEYS: [&str; 30] = [
    "schema",
    "transaction_id",
    "ordinal",
    "predecessor_schema",
    "predecessor_sha256",
    "predecessor_bytes",
    "runtime_active_sha256",
    "runtime_active_bytes",
    "runtime_owner_sha256",
    "runtime_owner_bytes",
    "daemon_pid",
    "daemon_start",
    "wrapper_pid",
    "wrapper_start",
    "wrapper_ppid",
    "wrapper_comm",
    "wrapper_exe",
    "wrapper_cmdline_sha256",
    "wrapper_cmdline_bytes",
    "pdeathsig",
    "pdeathsig_scope",
    "gpio_raw",
    "watchdog_start_intent",
    "watchdog_armed",
    "signal_attempted",
    "inherited_rails",
    "route_or_uart_opened",
    "hardware_opened",
    "parent_release",
    "publication",
];

fn s19k_require_startup_j1(
    authority: &S19kTrack1ReceiptAuthority,
    expected: &S19kStockHandoffIdentity,
    j0: &BTreeMap<String, String>,
    c1: &BTreeMap<String, String>,
) -> Result<BTreeMap<String, String>> {
    let j1 = s19k_read_exact_key_value_file(&authority.startup_j1, "startup J1", &S19K_J1_J2_KEYS)?;
    let predecessor =
        s19k_hash_regular_nonsymlink(&authority.startup_c1, "startup C1 predecessor")?;
    let owner = s19k_hash_regular_nonsymlink(&authority.startup_j0, "startup J0 owner")?;
    let (self_pid, self_start, self_ppid) = s19k_self_lifetime()?;
    anyhow::ensure!(
        s19k_journal_field(&j1, "schema")? == "dcentos.s19k-startup-j1-daemon-blocked/v1"
            && s19k_journal_field(&j1, "transaction_id")?
                == s19k_journal_field(j0, "transaction_id")?
            && s19k_journal_field(&j1, "ordinal")? == "2"
            && s19k_journal_field(&j1, "predecessor_schema")? == s19k_journal_field(c1, "schema")?
            && s19k_journal_field(&j1, "predecessor_sha256")? == predecessor.0
            && s19k_journal_field(&j1, "predecessor_bytes")?.parse::<u64>()? == predecessor.1
            && s19k_journal_field(&j1, "runtime_active_path")? == "not-published"
            && s19k_journal_field(&j1, "runtime_active_sha256")? == "none"
            && s19k_journal_field(&j1, "runtime_active_bytes")? == "0"
            && s19k_journal_field(&j1, "runtime_active_phase")? == "not-published"
            && s19k_journal_field(&j1, "runtime_owner_sha256")? == owner.0
            && s19k_journal_field(&j1, "runtime_owner_bytes")?.parse::<u64>()? == owner.1
            && s19k_journal_field(&j1, "writer_role")? == "daemon-blocked"
            && s19k_journal_field(&j1, "writer_pid")? == self_pid.to_string()
            && s19k_journal_field(&j1, "writer_start")? == self_start.to_string()
            && s19k_journal_field(&j1, "writer_ppid")? == self_ppid.to_string()
            && s19k_journal_field(&j1, "daemon_pid")? == self_pid.to_string()
            && s19k_journal_field(&j1, "daemon_start")? == self_start.to_string()
            && s19k_journal_field(&j1, "wrapper_pid")? == s19k_journal_field(j0, "wrapper_pid")?
            && s19k_journal_field(&j1, "wrapper_start")?
                == s19k_journal_field(j0, "wrapper_start")?
            && s19k_journal_field(&j1, "wrapper_ppid")? == s19k_journal_field(j0, "wrapper_ppid")?
            && s19k_journal_field(&j1, "wrapper_comm")? == s19k_journal_field(j0, "wrapper_comm")?
            && s19k_journal_field(&j1, "wrapper_exe")? == s19k_journal_field(j0, "wrapper_exe")?
            && s19k_journal_field(&j1, "wrapper_cmdline_sha256")?
                == s19k_journal_field(j0, "wrapper_cmdline_sha256")?
            && s19k_journal_field(&j1, "wrapper_cmdline_bytes")?
                == s19k_journal_field(j0, "wrapper_cmdline_bytes")?
            && s19k_journal_field(&j1, "pdeathsig")? == "9"
            && s19k_journal_field(&j1, "pdeathsig_scope")? == "process-lifetime"
            && s19k_journal_field(&j1, "fifo_path")? == s19k_journal_field(j0, "fifo_path")?
            && s19k_journal_field(&j1, "fifo_mnt_id")? == s19k_journal_field(j0, "fifo_mnt_id")?
            && s19k_journal_field(&j1, "fifo_inode")? == s19k_journal_field(j0, "fifo_inode")?
            && s19k_journal_field(&j1, "fifo_mode")? == s19k_journal_field(j0, "fifo_mode")?
            && s19k_journal_field(&j1, "fifo_uid")? == s19k_journal_field(j0, "fifo_uid")?
            && s19k_journal_field(&j1, "fifo_gid")? == s19k_journal_field(j0, "fifo_gid")?
            && s19k_journal_field(&j1, "fifo_reader_held")? == "true"
            && s19k_journal_field(&j1, "bootstrap_fd_set")? == "stdio-plus-single-fifo"
            && s19k_journal_field(&j1, "fifo_reader_fd")?.parse::<i32>()? > 2
            && s19k_journal_field(&j1, "stdin_path")? == s19k_journal_field(c1, "stdin_path")?
            && s19k_journal_field(&j1, "transcript_path")?
                == s19k_journal_field(c1, "transcript_path")?
            && s19k_journal_field(&j1, "transcript_mnt_id")?
                == s19k_journal_field(c1, "transcript_mnt_id")?
            && s19k_journal_field(&j1, "transcript_inode")?
                == s19k_journal_field(c1, "transcript_inode")?
            && s19k_journal_field(&j1, "transcript_mode")?
                == s19k_journal_field(c1, "transcript_mode")?
            && s19k_journal_field(&j1, "transcript_uid")?
                == s19k_journal_field(c1, "transcript_uid")?
            && s19k_journal_field(&j1, "transcript_gid")?
                == s19k_journal_field(c1, "transcript_gid")?,
        "S19k startup J1 relation is invalid"
    );
    s19k_require_journal_no_effects(&j1)?;
    s19k_require_journal_tree_and_artifacts(&j1, authority, expected)?;
    s19k_require_j0_wrapper_live(j0)?;
    Ok(j1)
}

fn s19k_require_startup_j2_and_release(
    authority: &S19kTrack1ReceiptAuthority,
    expected: &S19kStockHandoffIdentity,
    j0: &BTreeMap<String, String>,
    j1: &BTreeMap<String, String>,
) -> Result<S19kTrack1RuntimeBinding> {
    let j2 = s19k_read_exact_key_value_file(&authority.startup_j2, "startup J2", &S19K_J1_J2_KEYS)?;
    let j1_digest = s19k_hash_regular_nonsymlink(&authority.startup_j1, "startup J1 predecessor")?;
    let owner = s19k_hash_regular_nonsymlink(&authority.startup_j0, "startup J0 owner")?;
    let binding = s19k_parse_runtime_binding_once(authority, expected)?
        .context("S19k startup J2 was published without child-bound runtime_active")?;
    let (self_pid, self_start, _) = s19k_self_lifetime()?;
    let wrapper_pid = s19k_journal_field(j0, "wrapper_pid")?.parse::<i32>()?;
    let wrapper_start = s19k_journal_field(j0, "wrapper_start")?.parse::<u64>()?;
    let wrapper_ppid = s19k_journal_field(j0, "writer_ppid")?.parse::<i32>()?;
    anyhow::ensure!(
        s19k_journal_field(&j2, "schema")? == "dcentos.s19k-startup-j2-child-bound/v1"
            && s19k_journal_field(&j2, "transaction_id")?
                == s19k_journal_field(j0, "transaction_id")?
            && s19k_journal_field(&j2, "ordinal")? == "3"
            && s19k_journal_field(&j2, "predecessor_schema")? == s19k_journal_field(j1, "schema")?
            && s19k_journal_field(&j2, "predecessor_sha256")? == j1_digest.0
            && s19k_journal_field(&j2, "predecessor_bytes")?.parse::<u64>()? == j1_digest.1
            && s19k_journal_field(&j2, "runtime_active_path")?
                == authority.active.display().to_string()
            && s19k_journal_field(&j2, "runtime_active_sha256")? == binding.active_sha256
            && s19k_journal_field(&j2, "runtime_active_bytes")?.parse::<u64>()?
                == binding.active_bytes
            && s19k_journal_field(&j2, "runtime_active_phase")?
                == "child-live-or-recovery-required"
            && s19k_journal_field(&j2, "runtime_owner_sha256")? == owner.0
            && s19k_journal_field(&j2, "runtime_owner_bytes")?.parse::<u64>()? == owner.1
            && s19k_journal_field(&j2, "writer_role")? == "wrapper"
            && s19k_journal_field(&j2, "writer_pid")? == wrapper_pid.to_string()
            && s19k_journal_field(&j2, "writer_start")? == wrapper_start.to_string()
            && s19k_journal_field(&j2, "writer_ppid")? == wrapper_ppid.to_string()
            && s19k_journal_field(&j2, "daemon_pid")? == self_pid.to_string()
            && s19k_journal_field(&j2, "daemon_start")? == self_start.to_string()
            && s19k_journal_field(&j2, "wrapper_pid")? == s19k_journal_field(j0, "wrapper_pid")?
            && s19k_journal_field(&j2, "wrapper_start")?
                == s19k_journal_field(j0, "wrapper_start")?
            && s19k_journal_field(&j2, "wrapper_ppid")? == s19k_journal_field(j0, "wrapper_ppid")?
            && s19k_journal_field(&j2, "wrapper_comm")? == s19k_journal_field(j0, "wrapper_comm")?
            && s19k_journal_field(&j2, "wrapper_exe")? == s19k_journal_field(j0, "wrapper_exe")?
            && s19k_journal_field(&j2, "wrapper_cmdline_sha256")?
                == s19k_journal_field(j0, "wrapper_cmdline_sha256")?
            && s19k_journal_field(&j2, "wrapper_cmdline_bytes")?
                == s19k_journal_field(j0, "wrapper_cmdline_bytes")?
            && s19k_journal_field(&j2, "pdeathsig")? == "9"
            && s19k_journal_field(&j2, "pdeathsig_scope")? == "process-lifetime"
            && s19k_journal_field(&j2, "fifo_path")? == s19k_journal_field(j0, "fifo_path")?
            && s19k_journal_field(&j2, "fifo_mnt_id")? == s19k_journal_field(j0, "fifo_mnt_id")?
            && s19k_journal_field(&j2, "fifo_inode")? == s19k_journal_field(j0, "fifo_inode")?
            && s19k_journal_field(&j2, "fifo_mode")? == s19k_journal_field(j0, "fifo_mode")?
            && s19k_journal_field(&j2, "fifo_uid")? == s19k_journal_field(j0, "fifo_uid")?
            && s19k_journal_field(&j2, "fifo_gid")? == s19k_journal_field(j0, "fifo_gid")?
            && s19k_journal_field(&j2, "fifo_reader_held")? == "true",
        "S19k startup J2 relation is invalid"
    );
    for key in [
        "bootstrap_fd_set",
        "fifo_reader_fd",
        "stdin_path",
        "transcript_path",
        "transcript_mnt_id",
        "transcript_inode",
        "transcript_mode",
        "transcript_uid",
        "transcript_gid",
    ] {
        anyhow::ensure!(
            s19k_journal_field(&j2, key)? == s19k_journal_field(j1, key)?,
            "S19k startup J2 changed J1 descriptor proof field {key}"
        );
    }
    s19k_require_journal_no_effects(&j2)?;
    s19k_require_journal_tree_and_artifacts(&j2, authority, expected)?;
    s19k_require_nonterminal_lifetime(wrapper_pid, wrapper_start, "startup J2 wrapper")?;
    let release = s19k_read_exact_key_value_file(
        &authority.startup_release,
        "startup release",
        &S19K_RELEASE_KEYS,
    )?;
    let j2_digest = s19k_hash_regular_nonsymlink(&authority.startup_j2, "startup J2 predecessor")?;
    anyhow::ensure!(
        s19k_journal_field(&release, "schema")? == "dcentos.s19k-startup-release/v1"
            && s19k_journal_field(&release, "transaction_id")?
                == s19k_journal_field(j0, "transaction_id")?
            && s19k_journal_field(&release, "ordinal")? == "3-release"
            && s19k_journal_field(&release, "predecessor_schema")?
                == s19k_journal_field(&j2, "schema")?
            && s19k_journal_field(&release, "predecessor_sha256")? == j2_digest.0
            && s19k_journal_field(&release, "predecessor_bytes")?.parse::<u64>()? == j2_digest.1
            && s19k_journal_field(&release, "runtime_active_sha256")? == binding.active_sha256
            && s19k_journal_field(&release, "runtime_active_bytes")?.parse::<u64>()?
                == binding.active_bytes
            && s19k_journal_field(&release, "runtime_owner_sha256")? == owner.0
            && s19k_journal_field(&release, "runtime_owner_bytes")?.parse::<u64>()? == owner.1
            && s19k_journal_field(&release, "daemon_pid")? == self_pid.to_string()
            && s19k_journal_field(&release, "daemon_start")? == self_start.to_string()
            && s19k_journal_field(&release, "wrapper_pid")? == wrapper_pid.to_string()
            && s19k_journal_field(&release, "wrapper_start")? == wrapper_start.to_string()
            && s19k_journal_field(&release, "wrapper_ppid")? == wrapper_ppid.to_string()
            && s19k_journal_field(&release, "wrapper_comm")?
                == s19k_journal_field(j0, "wrapper_comm")?
            && s19k_journal_field(&release, "wrapper_exe")?
                == s19k_journal_field(j0, "wrapper_exe")?
            && s19k_journal_field(&release, "wrapper_cmdline_sha256")?
                == s19k_journal_field(j0, "wrapper_cmdline_sha256")?
            && s19k_journal_field(&release, "wrapper_cmdline_bytes")?
                == s19k_journal_field(j0, "wrapper_cmdline_bytes")?
            && s19k_journal_field(&release, "pdeathsig")? == "9"
            && s19k_journal_field(&release, "pdeathsig_scope")? == "process-lifetime"
            && s19k_journal_field(&release, "gpio_raw")? == "437:0,454:0,455:1,456:1"
            && s19k_journal_field(&release, "parent_release")? == "true"
            && s19k_journal_field(&release, "publication")? == "no-clobber-hard-link-after-fsync",
        "S19k startup release relation is invalid"
    );
    for key in [
        "watchdog_start_intent",
        "watchdog_armed",
        "signal_attempted",
        "inherited_rails",
        "route_or_uart_opened",
        "hardware_opened",
    ] {
        anyhow::ensure!(
            s19k_journal_field(&release, key)? == "false",
            "S19k startup release {key} is not false"
        );
    }
    s19k_require_nonterminal_lifetime(wrapper_pid, wrapper_start, "startup release wrapper")?;
    s19k_require_recovered_stock_gpio_baseline()?;
    Ok(binding)
}

fn s19k_publish_parent_lost_at_j0(
    authority: &S19kTrack1ReceiptAuthority,
    expected: &S19kStockHandoffIdentity,
    j0: &BTreeMap<String, String>,
) -> Result<()> {
    let (daemon_pid, daemon_start, daemon_ppid) = s19k_self_lifetime()?;
    anyhow::ensure!(
        daemon_ppid == 1,
        "S19k J0 parent-lost receipt requires PPID 1"
    );
    let wrapper_pid = s19k_journal_field(j0, "wrapper_pid")?.parse::<i32>()?;
    let wrapper_start = s19k_journal_field(j0, "wrapper_start")?.parse::<u64>()?;
    let exact_wrapper_nonterminal = std::fs::read_to_string(format!("/proc/{wrapper_pid}/stat"))
        .ok()
        .and_then(|stat| stat.rsplit_once(") ").map(|(_, rest)| rest.to_string()))
        .and_then(|rest| {
            let fields = rest.split_whitespace().collect::<Vec<_>>();
            (fields.len() >= 20).then(|| (fields[0].to_string(), fields[19].parse::<u64>().ok()))
        })
        .is_some_and(|(state, start)| {
            start == Some(wrapper_start) && !matches!(state.as_str(), "Z" | "X" | "x")
        });
    anyhow::ensure!(
        !exact_wrapper_nonterminal,
        "S19k exact wrapper remains nonterminal after J0 reparenting"
    );
    s19k_require_path_absent(&authority.active, "startup J0 parent-lost runtime_active")?;
    s19k_require_path_absent(&authority.startup_c1, "startup J0 parent-lost C1")?;
    s19k_require_path_absent(&authority.startup_j1, "startup J0 parent-lost J1")?;
    expected.require_exact_tree_at(Path::new("/proc"))?;
    s19k_require_recovered_stock_gpio_baseline()
        .context("S19k J0 parent-lost refusal lost recovered-stock GPIO baseline")?;
    s19k_require_no_self_watchdog_fd()?;
    let predecessor =
        s19k_hash_regular_nonsymlink(&authority.startup_j0, "startup J0 parent-lost predecessor")?;
    let mut receipt = String::new();
    for (key, value) in [
        ("schema", "dcentos.s19k-startup-parent-lost/v2".to_string()),
        (
            "transaction_id",
            s19k_journal_field(j0, "transaction_id")?.to_string(),
        ),
        ("highest_phase", "j0".to_string()),
        (
            "predecessor_schema",
            s19k_journal_field(j0, "schema")?.to_string(),
        ),
        ("predecessor_sha256", predecessor.0.clone()),
        ("predecessor_bytes", predecessor.1.to_string()),
        ("runtime_owner_sha256", predecessor.0),
        ("runtime_owner_bytes", predecessor.1.to_string()),
        ("daemon_pid", daemon_pid.to_string()),
        ("daemon_start", daemon_start.to_string()),
        ("daemon_ppid", daemon_ppid.to_string()),
        ("wrapper_pid", wrapper_pid.to_string()),
        ("wrapper_start", wrapper_start.to_string()),
        ("pdeathsig", "9".to_string()),
        ("pdeathsig_scope", "process-lifetime".to_string()),
        ("runtime_active", "not-published".to_string()),
        ("watchdog_start_intent", "false".to_string()),
        ("watchdog_armed", "false".to_string()),
        ("signal_attempted", "false".to_string()),
        ("inherited_rails", "false".to_string()),
        ("route_or_uart_opened", "false".to_string()),
        ("hardware_opened", "false".to_string()),
        ("stock_tree_revalidated", "true".to_string()),
        ("gpio_raw", "437:0,454:0,455:1,456:1".to_string()),
        ("gpio_stock_baseline_revalidated", "true".to_string()),
        ("gpio437_engaged", "true".to_string()),
        (
            "publication",
            "no-clobber-hard-link-after-fsync".to_string(),
        ),
    ] {
        s19k_push_journal_line(&mut receipt, key, value);
    }
    s19k_publish_text_no_clobber(
        &authority.startup_parent_lost,
        "runtime_startup_parent_lost_j0",
        &receipt,
    )
}

pub(crate) fn s19k_complete_daemon_pre_runtime_bootstrap(
    authority: &S19kTrack1ReceiptAuthority,
    expected: &S19kStockHandoffIdentity,
    state: S19kPreRuntimeBootstrapState,
) -> Result<()> {
    anyhow::ensure!(
        state.role() == S19kPreRuntimeBootstrapRole::Daemon,
        "S19k daemon bootstrap received the publisher role"
    );
    let j0 = s19k_read_and_require_j0_pre_active(authority, expected)?;
    anyhow::ensure!(
        std::env::var("DCENT_S19K_STARTUP_WRAPPER_PID")? == s19k_journal_field(&j0, "wrapper_pid")?
            && std::env::var("DCENT_S19K_STARTUP_WRAPPER_START")?
                == s19k_journal_field(&j0, "wrapper_start")?,
        "S19k bootstrap wrapper environment does not match immutable J0"
    );
    s19k_require_exact_daemon_environment(&j0)?;
    if !state.parent_is_live() {
        s19k_publish_parent_lost_at_j0(authority, expected, &j0)?;
        anyhow::bail!("S19k wrapper was lost before C1; typed J0 no-effect receipt published");
    }
    s19k_require_j0_wrapper_live(&j0)?;
    let c1 = s19k_publish_startup_c1(authority, &j0)?;
    let mut fifo = S19kStartupFifoReader::open_and_require_j0(&j0)?;
    let j1 = s19k_publish_startup_j1(authority, expected, &j0, &c1, &fifo)?;
    loop {
        if authority.startup_release.exists() {
            break;
        }
        s19k_require_j0_wrapper_live(&j0)?;
        fifo.require_unchanged()?;
        std::thread::sleep(Duration::from_millis(20));
    }
    let binding = s19k_require_startup_j2_and_release(authority, expected, &j0, &j1)?;
    let token = fifo.read_exact_token_and_require_eof()?;
    anyhow::ensure!(
        token
            .iter()
            .all(|byte| byte.is_ascii_hexdigit() && !byte.is_ascii_uppercase()),
        "S19k startup release token is not 64 lowercase hexadecimal bytes"
    );
    let j2_sha = s19k_hash_regular_nonsymlink(&authority.startup_j2, "startup J2 token")?.0;
    let release_sha =
        s19k_hash_regular_nonsymlink(&authority.startup_release, "startup release token")?.0;
    let expected_token = format!(
        "{:x}",
        Sha256::digest(
            format!(
                "{}:{j2_sha}:{release_sha}",
                s19k_journal_field(&j0, "transaction_id")?
            )
            .as_bytes()
        )
    );
    anyhow::ensure!(
        token == expected_token.as_bytes(),
        "S19k startup release token mismatch"
    );
    let j0_after = s19k_read_and_require_j0_static(authority, expected)?;
    anyhow::ensure!(j0_after == j0, "S19k J0 changed after startup release");
    let c1_after = s19k_require_startup_c1(authority, &j0)?;
    anyhow::ensure!(c1_after == c1, "S19k C1 changed after startup release");
    let j1_after = s19k_require_startup_j1(authority, expected, &j0, &c1)?;
    anyhow::ensure!(j1_after == j1, "S19k J1 changed after startup release");
    let binding_after = s19k_require_startup_j2_and_release(authority, expected, &j0, &j1)?;
    anyhow::ensure!(
        binding_after.active_sha256 == binding.active_sha256
            && binding_after.active_bytes == binding.active_bytes,
        "S19k runtime binding changed after startup release"
    );
    fifo.require_unchanged()?;
    s19k_require_j0_wrapper_live(&j0)?;
    S19K_STARTUP_TOKEN_ADMITTED.store(true, Ordering::SeqCst);
    Ok(())
}

/// Complete the frozen J0/C1/J1/J2/release transaction and acquire J3 over
/// every thread in the exact stock supervisor+child tree. This runs before
/// Tokio construction, config load, logging, watchdog, signal, route, GPIO,
/// or UART access. A refusal publishes the same typed retained-stock evidence
/// used by every other pre-watchdog failure.
pub(crate) fn s19k_track1_startup_barrier_and_acquire_j3(
    authority: &S19kTrack1ReceiptAuthority,
    expected: &S19kStockHandoffIdentity,
) -> Result<S19kTrack1J3Lease> {
    anyhow::ensure!(
        S19K_STARTUP_TOKEN_ADMITTED.load(Ordering::SeqCst),
        "S19k pre-runtime FIFO release token was not admitted before Tokio/runtime construction"
    );
    let j0 = s19k_read_and_require_j0_static(authority, expected)?;
    let c1 = s19k_require_startup_c1(authority, &j0)?;
    let j1 = s19k_require_startup_j1(authority, expected, &j0, &c1)?;
    let binding = s19k_require_startup_j2_and_release(authority, expected, &j0, &j1)?;
    let live_identity = s19k_capture_and_require_bound_live_identity()?;
    binding.require_fresh_live_identity(&live_identity)?;
    match S19kTrack1J3Lease::acquire(expected, binding.clone(), live_identity.clone()) {
        Ok(lease) => Ok(lease),
        Err(primary) => {
            s19k_publish_stock_owner_retained_prewatchdog_receipt(
                authority,
                &binding,
                expected,
                &live_identity,
            )?;
            Err(primary.context(
                "S19k J0/C1/J1/J2 startup barrier completed but J3 all-thread lease refused",
            ))
        }
    }
}

#[derive(Debug, Clone)]
struct S19kTrack1RuntimeBinding {
    active_sha256: String,
    active_bytes: u64,
    fields: BTreeMap<String, String>,
}

impl S19kTrack1RuntimeBinding {
    fn field(&self, key: &str) -> Result<&str> {
        self.fields
            .get(key)
            .map(String::as_str)
            .with_context(|| format!("S19k runtime binding lacks {key}"))
    }

    fn require_active_unchanged(&self, authority: &S19kTrack1ReceiptAuthority) -> Result<()> {
        let (sha256, bytes) = s19k_hash_regular_nonsymlink(&authority.active, "runtime_active")?;
        anyhow::ensure!(
            sha256 == self.active_sha256 && bytes == self.active_bytes,
            "S19k runtime_active changed after daemon admission"
        );
        Ok(())
    }

    fn require_fresh_live_identity(&self, live_identity: &S19kLiveIdentityReceipt) -> Result<()> {
        let expected_live_sha = std::env::var(S19K_LIVE_IDENTITY_ENV)
            .context("S19k runtime binding lacks live identity environment")?;
        anyhow::ensure!(
            self.field("live_identity_sha256")? == expected_live_sha
                && live_identity.sha256 == expected_live_sha
                && self.field("live_identity_profile")? == live_identity.profile.as_str(),
            "S19k runtime_active live identity/profile does not match the fresh observation"
        );
        Ok(())
    }

    fn no_work(&self) -> Result<bool> {
        match self.field("deploy_mode")? {
            "mining-on-passthrough"
            | "install-custody-safeoff"
            | "bounded-work-proof"
            | "endurance-work-proof" => Ok(false),
            "handoff-no-work" => Ok(true),
            mode => anyhow::bail!("S19k runtime binding has unsupported deploy mode {mode}"),
        }
    }

    fn install_custody_safeoff(&self) -> Result<bool> {
        match self.field("deploy_mode")? {
            "install-custody-safeoff" => Ok(true),
            "mining-on-passthrough"
            | "handoff-no-work"
            | "bounded-work-proof"
            | "endurance-work-proof" => Ok(false),
            mode => anyhow::bail!("S19k runtime binding has unsupported deploy mode {mode}"),
        }
    }

    fn require_install_custody_safeoff_policy(
        &self,
        cli_install_custody_safeoff: bool,
    ) -> Result<()> {
        anyhow::ensure!(
            self.install_custody_safeoff()? == cli_install_custody_safeoff,
            "S19k install-custody-safeoff CLI authority does not match immutable runtime_active deploy_mode"
        );
        Ok(())
    }

    fn bounded_work_proof(&self) -> Result<bool> {
        match self.field("deploy_mode")? {
            "mining-on-passthrough"
            | "install-custody-safeoff"
            | "handoff-no-work"
            | "endurance-work-proof" => Ok(false),
            "bounded-work-proof" => Ok(true),
            mode => anyhow::bail!("S19k runtime binding has unsupported deploy mode {mode}"),
        }
    }

    fn require_no_work_policy(&self, cli_no_work: bool) -> Result<()> {
        anyhow::ensure!(
            self.no_work()? == cli_no_work,
            "S19k no-work CLI authority does not match immutable runtime_active deploy_mode"
        );
        Ok(())
    }

    fn require_bounded_work_proof_policy(&self, cli_bounded_work_proof: bool) -> Result<()> {
        anyhow::ensure!(
            self.bounded_work_proof()? == cli_bounded_work_proof,
            "S19k bounded-work-proof CLI authority does not match immutable runtime_active deploy_mode"
        );
        Ok(())
    }

    fn endurance_work_proof(&self) -> Result<bool> {
        match self.field("deploy_mode")? {
            "mining-on-passthrough"
            | "install-custody-safeoff"
            | "handoff-no-work"
            | "bounded-work-proof" => Ok(false),
            "endurance-work-proof" => Ok(true),
            mode => anyhow::bail!("S19k runtime binding has unsupported deploy mode {mode}"),
        }
    }

    fn require_endurance_work_proof_policy(&self, cli_endurance_work_proof: bool) -> Result<()> {
        anyhow::ensure!(
            self.endurance_work_proof()? == cli_endurance_work_proof,
            "S19k endurance-work-proof CLI authority does not match immutable runtime_active deploy_mode"
        );
        Ok(())
    }
}

fn s19k_hash_regular_nonsymlink(path: &Path, label: &str) -> Result<(String, u64)> {
    let mut file = OpenOptions::new()
        .read(true)
        .custom_flags(libc::O_CLOEXEC | libc::O_NOFOLLOW)
        .open(path)
        .with_context(|| {
            format!(
                "S19k cannot open content-bound {label} at {}",
                path.display()
            )
        })?;
    let metadata = file
        .metadata()
        .with_context(|| format!("S19k cannot fstat content-bound {label}"))?;
    anyhow::ensure!(
        metadata.file_type().is_file(),
        "S19k {label} is not regular"
    );
    let mut digest = Sha256::new();
    let mut bytes = 0u64;
    let mut chunk = [0u8; 16 * 1024];
    loop {
        let read = file
            .read(&mut chunk)
            .with_context(|| format!("S19k cannot read content-bound {label}"))?;
        if read == 0 {
            break;
        }
        bytes = bytes
            .checked_add(read as u64)
            .context("S19k content-bound file byte count overflow")?;
        digest.update(&chunk[..read]);
    }
    Ok((format!("{:x}", digest.finalize()), bytes))
}

fn s19k_runtime_process_matches(
    pid: i32,
    start_ticks: u64,
    expected_ppid: i32,
    comm: &str,
    executable: &Path,
) -> Result<()> {
    let root = Path::new("/proc").join(pid.to_string());
    let stat = std::fs::read_to_string(root.join("stat"))
        .with_context(|| format!("S19k runtime binding cannot read PID {pid} stat"))?;
    let (_, after_comm) = stat
        .rsplit_once(") ")
        .context("S19k runtime binding process stat is malformed")?;
    let fields = after_comm.split_whitespace().collect::<Vec<_>>();
    anyhow::ensure!(
        fields.len() >= 20,
        "S19k runtime binding process stat is truncated"
    );
    let state = fields[0]
        .chars()
        .next()
        .context("S19k runtime binding process state missing")?;
    let observed_start = fields[19]
        .parse::<u64>()
        .context("S19k runtime binding process start is invalid")?;
    let observed_ppid = fields[1]
        .parse::<i32>()
        .context("S19k runtime binding process PPID is invalid")?;
    anyhow::ensure!(
        observed_start == start_ticks
            && observed_ppid == expected_ppid
            && !matches!(state, 'Z' | 'X' | 'x'),
        "S19k runtime binding process lifetime/parent is not live/exact"
    );
    let observed_comm = std::fs::read_to_string(root.join("comm"))?;
    let observed_exe = std::fs::read_link(root.join("exe"))?;
    anyhow::ensure!(
        observed_comm.trim() == comm && observed_exe == executable,
        "S19k runtime binding process comm/executable changed"
    );
    Ok(())
}

fn s19k_parse_runtime_binding_once(
    authority: &S19kTrack1ReceiptAuthority,
    expected: &S19kStockHandoffIdentity,
) -> Result<Option<S19kTrack1RuntimeBinding>> {
    let bytes = s19k_read_regular_nonsymlink(&authority.active, "Track-1 runtime_active")?;
    anyhow::ensure!(
        bytes.ends_with(b"\n"),
        "S19k runtime_active lacks terminal newline"
    );
    let text = std::str::from_utf8(&bytes).context("S19k runtime_active is not UTF-8")?;
    let mut fields = BTreeMap::new();
    for line in text.lines() {
        let (key, value) = line
            .split_once('=')
            .context("S19k runtime_active contains a malformed field")?;
        anyhow::ensure!(
            !key.is_empty() && fields.insert(key.to_string(), value.to_string()).is_none(),
            "S19k runtime_active contains an empty or duplicate field"
        );
    }
    const EXACT_RUNTIME_KEYS: [&str; 40] = [
        "schema",
        "phase",
        "wrapper_pid",
        "wrapper_start",
        "child_pid",
        "child_start",
        "supervisor_pid",
        "supervisor_start",
        "supervisor_ppid",
        "supervisor_pgrp",
        "supervisor_session",
        "supervisor_exe",
        "supervisor_cmdline_sha256",
        "supervisor_cmdline_bytes",
        "bosminer_pid",
        "bosminer_start",
        "bosminer_ppid",
        "bosminer_pgrp",
        "bosminer_session",
        "bosminer_exe",
        "bosminer_cmdline_sha256",
        "bosminer_cmdline_bytes",
        "stock_pidfile_path",
        "stock_pidfile_sha256",
        "stock_pidfile_bytes",
        "binary_sha256",
        "binary_bytes",
        "config_sha256",
        "config_bytes",
        "runner_sha256",
        "runner_bytes",
        "custody_observer_sha256",
        "custody_observer_bytes",
        "stock_restart_helper_sha256",
        "stock_restart_helper_bytes",
        "live_identity_schema",
        "live_identity_profile",
        "live_identity_sha256",
        "deploy_mode",
        "persistent_mutation",
    ];
    anyhow::ensure!(
        fields.len() == EXACT_RUNTIME_KEYS.len()
            && EXACT_RUNTIME_KEYS
                .iter()
                .all(|key| fields.contains_key(*key)),
        "S19k runtime_active has an inexact key set"
    );
    let field = |key: &str| -> Result<&str> {
        fields
            .get(key)
            .map(String::as_str)
            .with_context(|| format!("S19k runtime_active lacks {key}"))
    };
    anyhow::ensure!(
        field("schema")? == "dcentos.s19k-tmp-runtime/v5"
            && field("persistent_mutation")? == "false"
            && matches!(
                field("deploy_mode")?,
                "mining-on-passthrough"
                    | "install-custody-safeoff"
                    | "handoff-no-work"
                    | "bounded-work-proof"
                    | "endurance-work-proof"
            )
            && field("live_identity_schema")? == S19K_LIVE_IDENTITY_SCHEMA,
        "S19k runtime_active has an invalid schema/policy"
    );
    let exact_pairs = [
        ("supervisor_pid", expected.supervisor.pid.to_string()),
        (
            "supervisor_start",
            expected.supervisor.start_ticks.to_string(),
        ),
        ("supervisor_ppid", expected.supervisor.ppid.to_string()),
        ("supervisor_pgrp", expected.supervisor.pgrp.to_string()),
        (
            "supervisor_session",
            expected.supervisor.session.to_string(),
        ),
        (
            "supervisor_exe",
            expected.supervisor.executable.display().to_string(),
        ),
        (
            "supervisor_cmdline_sha256",
            expected.supervisor.cmdline_sha256.clone(),
        ),
        (
            "supervisor_cmdline_bytes",
            expected.supervisor.cmdline_bytes.to_string(),
        ),
        ("bosminer_pid", expected.bosminer.pid.to_string()),
        ("bosminer_start", expected.bosminer.start_ticks.to_string()),
        ("bosminer_ppid", expected.bosminer.ppid.to_string()),
        ("bosminer_pgrp", expected.bosminer.pgrp.to_string()),
        ("bosminer_session", expected.bosminer.session.to_string()),
        (
            "bosminer_exe",
            expected.bosminer.executable.display().to_string(),
        ),
        (
            "bosminer_cmdline_sha256",
            expected.bosminer.cmdline_sha256.clone(),
        ),
        (
            "bosminer_cmdline_bytes",
            expected.bosminer.cmdline_bytes.to_string(),
        ),
    ];
    for (key, expected_value) in exact_pairs {
        anyhow::ensure!(
            field(key)? == expected_value,
            "S19k runtime_active {key} mismatch"
        );
    }
    let stock_pidfile = Path::new("/var/run/bosminer.pid");
    let (stock_pidfile_sha256, stock_pidfile_bytes) =
        s19k_hash_regular_nonsymlink(stock_pidfile, "stock bosminer supervisor pidfile")?;
    let stock_pidfile_content =
        s19k_read_regular_nonsymlink(stock_pidfile, "stock bosminer supervisor pidfile content")?;
    anyhow::ensure!(
        field("stock_pidfile_path")? == "/var/run/bosminer.pid"
            && field("stock_pidfile_sha256")? == stock_pidfile_sha256
            && field("stock_pidfile_bytes")?.parse::<u64>()? == stock_pidfile_bytes
            && stock_pidfile_content == format!("{}\n", expected.supervisor.pid).as_bytes(),
        "S19k runtime_active stock supervisor pidfile binding changed"
    );
    let parent = authority
        .active
        .parent()
        .context("S19k trial parent disappeared")?;
    for (name, sha_field, bytes_field) in [
        ("dcentrald", "binary_sha256", "binary_bytes"),
        ("dcentrald_s19k.toml", "config_sha256", "config_bytes"),
        ("run_trial", "runner_sha256", "runner_bytes"),
        (
            "supervisor_custody_observer",
            "custody_observer_sha256",
            "custody_observer_bytes",
        ),
        (
            "stock_restart_helper",
            "stock_restart_helper_sha256",
            "stock_restart_helper_bytes",
        ),
    ] {
        let (sha256, observed_bytes) = s19k_hash_regular_nonsymlink(&parent.join(name), name)?;
        let expected_bytes = field(bytes_field)?
            .parse::<u64>()
            .with_context(|| format!("S19k runtime_active {bytes_field} is invalid"))?;
        anyhow::ensure!(
            field(sha_field)? == sha256 && expected_bytes == observed_bytes,
            "S19k runtime_active does not bind exact {name} bytes"
        );
    }
    let expected_live_sha = std::env::var(S19K_LIVE_IDENTITY_ENV)
        .context("S19k runtime binding lacks live identity environment")?;
    anyhow::ensure!(
        field("live_identity_sha256")? == expected_live_sha,
        "S19k runtime_active live identity digest mismatch"
    );
    anyhow::ensure!(
        s19k_profile_label_supported(field("live_identity_profile")?),
        "S19k runtime_active live identity profile is not admitted"
    );
    let wrapper_pid = field("wrapper_pid")?.parse::<i32>()?;
    let wrapper_start = field("wrapper_start")?.parse::<u64>()?;
    anyhow::ensure!(
        wrapper_pid > 1 && wrapper_start > 0,
        "S19k wrapper lifetime is invalid"
    );
    let wrapper_root = Path::new("/proc").join(wrapper_pid.to_string());
    let wrapper_stat = std::fs::read_to_string(wrapper_root.join("stat"))?;
    let (_, wrapper_after_comm) = wrapper_stat
        .rsplit_once(") ")
        .context("S19k wrapper stat is malformed")?;
    let wrapper_fields = wrapper_after_comm.split_whitespace().collect::<Vec<_>>();
    anyhow::ensure!(
        wrapper_fields.len() >= 20
            && wrapper_fields[19].parse::<u64>()? == wrapper_start
            && !matches!(wrapper_fields[0], "Z" | "X" | "x"),
        "S19k wrapper lifetime changed before daemon admission"
    );
    match field("phase")? {
        "launch-pending-or-recovery-required" => return Ok(None),
        "child-live-or-recovery-required" => {}
        _ => anyhow::bail!("S19k runtime_active phase is invalid"),
    }
    let child_pid = field("child_pid")?.parse::<i32>()?;
    let child_start = field("child_start")?.parse::<u64>()?;
    anyhow::ensure!(
        child_pid == std::process::id() as i32,
        "S19k runtime_active child PID is not this daemon"
    );
    s19k_runtime_process_matches(
        child_pid,
        child_start,
        wrapper_pid,
        "dcentrald",
        &parent.join("dcentrald"),
    )?;
    let active_sha256 = format!("{:x}", Sha256::digest(&bytes));
    Ok(Some(S19kTrack1RuntimeBinding {
        active_sha256,
        active_bytes: bytes.len() as u64,
        fields,
    }))
}

fn s19k_wait_for_runtime_binding(
    authority: &S19kTrack1ReceiptAuthority,
    expected: &S19kStockHandoffIdentity,
) -> Result<S19kTrack1RuntimeBinding> {
    loop {
        match s19k_parse_runtime_binding_once(authority, expected) {
            Ok(Some(binding)) => return Ok(binding),
            Ok(None) => {}
            Err(error) => {
                let self_stat = std::fs::read_to_string("/proc/self/stat").context(
                    "S19k cannot inspect daemon parent while waiting for runtime binding",
                )?;
                let (_, after_comm) = self_stat
                    .rsplit_once(") ")
                    .context("S19k daemon stat is malformed while waiting for runtime binding")?;
                let ppid = after_comm
                    .split_whitespace()
                    .nth(1)
                    .context("S19k daemon stat lacks PPID while waiting for runtime binding")?
                    .parse::<i32>()?;
                if ppid == 1 {
                    return Err(error).context(
                        "S19k original wrapper is gone; runtime_active can no longer be renamed by it",
                    );
                }
            }
        }
        // Never publish a phase-zero receipt while the original wrapper may
        // still perform its single pending->child-live rename. A delayed or
        // stuck live wrapper retains custody; only PPID==1 makes the pending
        // bytes immutable enough for the early receipt path.
        std::thread::sleep(Duration::from_millis(20));
    }
}

/// Exact two-process Braiins custody tree admitted by the content-bound /tmp
/// runner.  S99bosminer records the long-lived `bos-tools run-and-watch`
/// supervisor in its pidfile; the hardware-owning bosminer is its child.
/// Killing only the child lets the unchanged supervisor restart it, so both
/// lifetimes and their argv/parent/group/session relationship are authority.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum S19kStockProcessRole {
    Supervisor,
    Bosminer,
}

impl S19kStockProcessRole {
    fn label(self) -> &'static str {
        match self {
            Self::Supervisor => "bos-tools supervisor",
            Self::Bosminer => "bosminer child",
        }
    }

    fn comm(self) -> &'static str {
        match self {
            Self::Supervisor => "bos-tools",
            Self::Bosminer => "bosminer",
        }
    }

    fn executable(self) -> &'static str {
        match self {
            Self::Supervisor => "/usr/bin/bos-tools",
            Self::Bosminer => "/usr/bin/bosminer",
        }
    }

    fn exact_cmdline(self) -> &'static [u8] {
        match self {
            Self::Supervisor => {
                b"/usr/bin/bos-tools\0run-and-watch\0--\0/usr/bin/bosminer\0--log-to-file\0"
            }
            Self::Bosminer => b"/usr/bin/bosminer\0--log-to-file\0",
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct S19kStockProcessHandoffIdentity {
    role: S19kStockProcessRole,
    pid: i32,
    start_ticks: u64,
    ppid: i32,
    pgrp: i32,
    session: i32,
    executable: PathBuf,
    cmdline_sha256: String,
    cmdline_bytes: u64,
}

impl S19kStockProcessHandoffIdentity {
    #[allow(clippy::too_many_arguments)]
    fn from_cli(
        role: S19kStockProcessRole,
        pid: &str,
        start_ticks: &str,
        ppid: &str,
        pgrp: &str,
        session: &str,
        executable: &str,
        cmdline_sha256: &str,
        cmdline_bytes: &str,
    ) -> Result<Self> {
        let parse_positive_i32 = |value: &str, field: &str| -> Result<i32> {
            let parsed = value
                .parse::<i32>()
                .with_context(|| format!("S19k {} {field} is not an integer", role.label()))?;
            anyhow::ensure!(parsed > 0, "S19k {} {field} must be positive", role.label());
            Ok(parsed)
        };
        let pid = parse_positive_i32(pid, "PID")?;
        anyhow::ensure!(pid > 1, "S19k {} PID must be greater than 1", role.label());
        let start_ticks = start_ticks
            .parse::<u64>()
            .with_context(|| format!("S19k {} start ticks are not an integer", role.label()))?;
        anyhow::ensure!(
            start_ticks > 0,
            "S19k {} start ticks must be nonzero",
            role.label()
        );
        let ppid = parse_positive_i32(ppid, "PPID")?;
        let pgrp = parse_positive_i32(pgrp, "process group")?;
        let session = parse_positive_i32(session, "session")?;
        let executable = PathBuf::from(executable);
        anyhow::ensure!(
            executable == Path::new(role.executable()),
            "S19k {} executable must be exactly {}",
            role.label(),
            role.executable()
        );
        s19k_require_lower_hex_sha256(cmdline_sha256, "S19k stock-process cmdline SHA256")?;
        let cmdline_bytes = cmdline_bytes
            .parse::<u64>()
            .with_context(|| format!("S19k {} cmdline byte count is invalid", role.label()))?;
        anyhow::ensure!(
            cmdline_bytes == role.exact_cmdline().len() as u64,
            "S19k {} cmdline byte count is not the exact stock argv size",
            role.label()
        );
        let exact_sha = format!("{:x}", Sha256::digest(role.exact_cmdline()));
        anyhow::ensure!(
            cmdline_sha256 == exact_sha,
            "S19k {} cmdline digest is not the exact stock argv digest",
            role.label()
        );
        Ok(Self {
            role,
            pid,
            start_ticks,
            ppid,
            pgrp,
            session,
            executable,
            cmdline_sha256: cmdline_sha256.to_string(),
            cmdline_bytes,
        })
    }

    fn observe_at(&self, proc_root: &Path) -> Result<S19kStockProcObservation> {
        let process_root = proc_root.join(self.pid.to_string());
        let stat = std::fs::read_to_string(process_root.join("stat")).with_context(|| {
            format!("S19k {} cannot read expected /proc stat", self.role.label())
        })?;
        let (_, after_comm) = stat.rsplit_once(") ").with_context(|| {
            format!("S19k {} /proc stat has no comm boundary", self.role.label())
        })?;
        let stat_fields = after_comm.split_whitespace().collect::<Vec<_>>();
        anyhow::ensure!(
            stat_fields.len() >= 20,
            "S19k {} /proc stat is truncated",
            self.role.label()
        );
        let state = stat_fields[0]
            .chars()
            .next()
            .with_context(|| format!("S19k {} /proc stat has no state", self.role.label()))?;
        let parse_stat_i32 = |index: usize, name: &str| -> Result<i32> {
            stat_fields[index]
                .parse::<i32>()
                .with_context(|| format!("S19k {} /proc {name} is invalid", self.role.label()))
        };
        let ppid = parse_stat_i32(1, "PPID")?;
        let pgrp = parse_stat_i32(2, "process group")?;
        let session = parse_stat_i32(3, "session")?;
        let start_ticks = stat_fields[19]
            .parse::<u64>()
            .with_context(|| format!("S19k {} /proc start ticks are invalid", self.role.label()))?;
        let comm = std::fs::read_to_string(process_root.join("comm")).with_context(|| {
            format!("S19k {} cannot read expected /proc comm", self.role.label())
        })?;
        let executable = std::fs::read_link(process_root.join("exe")).with_context(|| {
            format!(
                "S19k {} cannot resolve expected /proc exe",
                self.role.label()
            )
        })?;
        let cmdline = std::fs::read(process_root.join("cmdline")).with_context(|| {
            format!(
                "S19k {} cannot read expected /proc cmdline",
                self.role.label()
            )
        })?;
        Ok(S19kStockProcObservation {
            start_ticks,
            state,
            ppid,
            pgrp,
            session,
            comm: comm.trim().to_string(),
            executable,
            cmdline_sha256: format!("{:x}", Sha256::digest(&cmdline)),
            cmdline_bytes: cmdline.len() as u64,
            cmdline,
        })
    }

    fn require_live_match_at(
        &self,
        proc_root: &Path,
        allow_reparent_to_init: bool,
    ) -> Result<S19kStockProcObservation> {
        let observed = self.observe_at(proc_root)?;
        anyhow::ensure!(
            observed.start_ticks == self.start_ticks,
            "S19k {} start ticks changed (expected {}, observed {})",
            self.role.label(),
            self.start_ticks,
            observed.start_ticks
        );
        let ppid_matches = observed.ppid == self.ppid
            || (allow_reparent_to_init
                && self.role == S19kStockProcessRole::Bosminer
                && observed.ppid == 1);
        anyhow::ensure!(
            ppid_matches,
            "S19k {} PPID changed outside the admitted supervisor-to-init transition (expected {}, observed {})",
            self.role.label(),
            self.ppid,
            observed.ppid
        );
        anyhow::ensure!(
            observed.pgrp == self.pgrp && observed.session == self.session,
            "S19k {} process group/session changed",
            self.role.label()
        );
        anyhow::ensure!(
            observed.comm == self.role.comm(),
            "S19k {} comm changed (observed {:?})",
            self.role.label(),
            observed.comm
        );
        anyhow::ensure!(
            observed.executable == self.executable,
            "S19k {} executable changed (expected {:?}, observed {:?})",
            self.role.label(),
            self.executable,
            observed.executable
        );
        anyhow::ensure!(
            observed.cmdline == self.role.exact_cmdline()
                && observed.cmdline_sha256 == self.cmdline_sha256
                && observed.cmdline_bytes == self.cmdline_bytes,
            "S19k {} argv bytes changed",
            self.role.label()
        );
        anyhow::ensure!(
            !matches!(observed.state, 'Z' | 'X' | 'x'),
            "S19k {} process is already terminal ({})",
            self.role.label(),
            observed.state
        );
        Ok(observed)
    }

    fn open_signal_lease_checked(&self) -> Result<S19kStockSignalLease> {
        self.require_live_match_at(Path::new("/proc"), false)?;
        let raw = unsafe { libc::syscall(libc::SYS_pidfd_open, self.pid, 0) };
        if raw < 0 {
            let error = std::io::Error::last_os_error();
            if s19k_pidfd_open_uses_legacy_fallback(error.raw_os_error()) {
                warn!(
                    pid = self.pid,
                    role = self.role.label(),
                    "S19k kernel lacks pidfd_open; using exact process-tree legacy handoff"
                );
                self.require_live_match_at(Path::new("/proc"), false)?;
                return Ok(S19kStockSignalLease::Legacy(self.clone()));
            }
            return Err(error)
                .with_context(|| format!("S19k {} pidfd_open failed", self.role.label()));
        }
        let lease = S19kStockPidFd {
            fd: raw as i32,
            role: self.role,
        };
        self.require_live_match_at(Path::new("/proc"), false)?;
        Ok(S19kStockSignalLease::PidFd(lease))
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct S19kStockHandoffIdentity {
    supervisor: S19kStockProcessHandoffIdentity,
    bosminer: S19kStockProcessHandoffIdentity,
}

impl S19kStockHandoffIdentity {
    #[allow(clippy::too_many_arguments)]
    pub(crate) fn from_cli(
        supervisor_pid: &str,
        supervisor_start: &str,
        supervisor_ppid: &str,
        supervisor_pgrp: &str,
        supervisor_session: &str,
        supervisor_executable: &str,
        supervisor_cmdline_sha256: &str,
        supervisor_cmdline_bytes: &str,
        bosminer_pid: &str,
        bosminer_start: &str,
        bosminer_ppid: &str,
        bosminer_pgrp: &str,
        bosminer_session: &str,
        bosminer_executable: &str,
        bosminer_cmdline_sha256: &str,
        bosminer_cmdline_bytes: &str,
    ) -> Result<Self> {
        let supervisor = S19kStockProcessHandoffIdentity::from_cli(
            S19kStockProcessRole::Supervisor,
            supervisor_pid,
            supervisor_start,
            supervisor_ppid,
            supervisor_pgrp,
            supervisor_session,
            supervisor_executable,
            supervisor_cmdline_sha256,
            supervisor_cmdline_bytes,
        )?;
        let bosminer = S19kStockProcessHandoffIdentity::from_cli(
            S19kStockProcessRole::Bosminer,
            bosminer_pid,
            bosminer_start,
            bosminer_ppid,
            bosminer_pgrp,
            bosminer_session,
            bosminer_executable,
            bosminer_cmdline_sha256,
            bosminer_cmdline_bytes,
        )?;
        anyhow::ensure!(
            supervisor.ppid == 1,
            "S19k stock supervisor must have PPID 1"
        );
        anyhow::ensure!(
            bosminer.ppid == supervisor.pid,
            "S19k bosminer must be the admitted supervisor child"
        );
        anyhow::ensure!(
            bosminer.pgrp == supervisor.pgrp && bosminer.session == supervisor.session,
            "S19k supervisor and bosminer must share process group/session"
        );
        Ok(Self {
            supervisor,
            bosminer,
        })
    }

    fn require_exact_tree_at(&self, proc_root: &Path) -> Result<()> {
        self.supervisor.require_live_match_at(proc_root, false)?;
        self.bosminer.require_live_match_at(proc_root, false)?;
        Ok(())
    }

    fn open_both_signal_leases_checked(
        &self,
    ) -> Result<(S19kStockSignalLease, S19kStockSignalLease)> {
        self.require_exact_tree_at(Path::new("/proc"))?;
        let supervisor = self.supervisor.open_signal_lease_checked()?;
        self.require_exact_tree_at(Path::new("/proc"))?;
        let bosminer = self.bosminer.open_signal_lease_checked()?;
        self.require_exact_tree_at(Path::new("/proc"))?;
        Ok((supervisor, bosminer))
    }

    fn child_after_supervisor_exit_at(
        &self,
        proc_root: &Path,
    ) -> Result<S19kChildAfterSupervisorExit> {
        match self.bosminer.observe_at(proc_root) {
            Ok(observed) if observed.start_ticks != self.bosminer.start_ticks => anyhow::bail!(
                "S19k bosminer PID was reused after supervisor exit (expected start {}, observed {})",
                self.bosminer.start_ticks,
                observed.start_ticks
            ),
            Ok(observed) if matches!(observed.state, 'Z' | 'X' | 'x') => {
                Ok(S19kChildAfterSupervisorExit::Gone)
            }
            Ok(_) => {
                self.bosminer.require_live_match_at(proc_root, true)?;
                Ok(S19kChildAfterSupervisorExit::Live)
            }
            Err(error)
                if error.chain().any(|cause| {
                    cause
                        .downcast_ref::<std::io::Error>()
                        .map(std::io::Error::kind)
                        == Some(std::io::ErrorKind::NotFound)
                }) =>
            {
                Ok(S19kChildAfterSupervisorExit::Gone)
            }
            Err(error) => Err(error),
        }
    }
}

const S19K_TRACK1_PTRACE_OPTIONS: libc::c_int = libc::PTRACE_O_TRACEFORK
    | libc::PTRACE_O_TRACEVFORK
    | libc::PTRACE_O_TRACECLONE
    | libc::PTRACE_O_TRACEEXEC
    | libc::PTRACE_O_TRACEEXIT;
const S19K_TRACK1_PTRACE_TIMEOUT: Duration = Duration::from_secs(5);

#[derive(Debug, Clone)]
struct S19kTrack1PtraceTask {
    tgid: i32,
    start_ticks: u64,
    stopped: bool,
    interrupt_sent: bool,
    terminal: bool,
    pending_signal: Option<i32>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum S19kTrack1PtraceWaitPhase {
    Freeze,
    Commit,
    Release,
}

/// Move-only pre-runtime authority over every thread in the exact stock
/// supervisor+child tree. The lease is acquired on the daemon's initial OS
/// thread before Tokio construction, and every later ptrace operation must run
/// on that same thread. EXITKILL is deliberately absent until the separately
/// committed supervisor-first terminal action.
#[derive(Debug)]
pub(crate) struct S19kTrack1J3Lease {
    expected: S19kStockHandoffIdentity,
    runtime_binding: S19kTrack1RuntimeBinding,
    live_identity: S19kLiveIdentityReceipt,
    tracer_tid: i32,
    tasks: BTreeMap<i32, S19kTrack1PtraceTask>,
    frozen: bool,
    committed: bool,
}

fn s19k_track1_current_tid() -> Result<i32> {
    let tid = unsafe { libc::syscall(libc::SYS_gettid) };
    anyhow::ensure!(
        tid > 0 && tid <= i32::MAX as libc::c_long,
        "S19k J3 gettid failed"
    );
    Ok(tid as i32)
}

fn s19k_track1_ptrace_call(
    request: u32,
    tid: i32,
    addr: *mut libc::c_void,
    data: *mut libc::c_void,
) -> std::io::Result<libc::c_long> {
    #[cfg(target_env = "musl")]
    let result = unsafe { libc::ptrace(request as libc::c_int, tid, addr, data) };
    #[cfg(not(target_env = "musl"))]
    let result = unsafe { libc::ptrace(request as libc::c_uint, tid, addr, data) };
    if result == -1 {
        Err(std::io::Error::last_os_error())
    } else {
        Ok(result)
    }
}

fn s19k_track1_ptrace_seize(tid: i32) -> Result<()> {
    s19k_track1_ptrace_call(
        libc::PTRACE_SEIZE as u32,
        tid,
        std::ptr::null_mut(),
        S19K_TRACK1_PTRACE_OPTIONS as usize as *mut libc::c_void,
    )
    .map(|_| ())
    .with_context(|| format!("S19k J3 PTRACE_SEIZE failed for TID {tid}"))
}

fn s19k_track1_ptrace_interrupt(tid: i32) -> Result<()> {
    s19k_track1_ptrace_call(
        libc::PTRACE_INTERRUPT as u32,
        tid,
        std::ptr::null_mut(),
        std::ptr::null_mut(),
    )
    .map(|_| ())
    .with_context(|| format!("S19k J3 PTRACE_INTERRUPT failed for TID {tid}"))
}

fn s19k_track1_ptrace_continue(tid: i32, signal: i32) -> Result<()> {
    s19k_track1_ptrace_call(
        libc::PTRACE_CONT as u32,
        tid,
        std::ptr::null_mut(),
        signal as usize as *mut libc::c_void,
    )
    .map(|_| ())
    .with_context(|| format!("S19k J3 PTRACE_CONT failed for TID {tid}"))
}

fn s19k_track1_status_i32(tid: i32, key: &str) -> Result<i32> {
    let status = std::fs::read_to_string(format!("/proc/{tid}/status"))
        .with_context(|| format!("S19k J3 cannot read /proc/{tid}/status"))?;
    let prefix = format!("{key}:");
    let value = status
        .lines()
        .find_map(|line| line.strip_prefix(&prefix))
        .with_context(|| format!("S19k J3 /proc/{tid}/status lacks {key}"))?
        .trim()
        .parse::<i32>()
        .with_context(|| format!("S19k J3 /proc/{tid}/status {key} is invalid"))?;
    anyhow::ensure!(value >= 0, "S19k J3 /proc/{tid}/status {key} is negative");
    Ok(value)
}

fn s19k_track1_tid_stat(tid: i32) -> Result<(char, u64)> {
    let stat = std::fs::read_to_string(format!("/proc/{tid}/stat"))
        .with_context(|| format!("S19k J3 cannot read /proc/{tid}/stat"))?;
    let (_, rest) = stat
        .rsplit_once(") ")
        .with_context(|| format!("S19k J3 /proc/{tid}/stat is malformed"))?;
    let fields = rest.split_whitespace().collect::<Vec<_>>();
    anyhow::ensure!(fields.len() >= 20, "S19k J3 /proc/{tid}/stat is truncated");
    let state = fields[0]
        .chars()
        .next()
        .with_context(|| format!("S19k J3 /proc/{tid}/stat lacks state"))?;
    let start_ticks = fields[19]
        .parse::<u64>()
        .with_context(|| format!("S19k J3 /proc/{tid}/stat starttime is invalid"))?;
    anyhow::ensure!(start_ticks > 0, "S19k J3 TID {tid} has zero starttime");
    Ok((state, start_ticks))
}

fn s19k_track1_list_tids(tgid: i32) -> Result<BTreeSet<i32>> {
    let mut tids = BTreeSet::new();
    for entry in std::fs::read_dir(format!("/proc/{tgid}/task"))
        .with_context(|| format!("S19k J3 cannot enumerate TGID {tgid}"))?
    {
        let entry = entry.with_context(|| format!("S19k J3 TGID {tgid} task entry failed"))?;
        let name = entry.file_name();
        let Some(name) = name.to_str() else {
            anyhow::bail!("S19k J3 TGID {tgid} has non-UTF8 task name");
        };
        anyhow::ensure!(
            !name.is_empty() && name.bytes().all(|byte| byte.is_ascii_digit()),
            "S19k J3 TGID {tgid} has non-decimal task name"
        );
        let tid = name
            .parse::<i32>()
            .with_context(|| format!("S19k J3 TGID {tgid} task id is invalid"))?;
        anyhow::ensure!(tid > 0, "S19k J3 TGID {tgid} has non-positive TID");
        tids.insert(tid);
    }
    anyhow::ensure!(
        !tids.is_empty() && tids.contains(&tgid),
        "S19k J3 TGID {tgid} task roster lacks its leader"
    );
    Ok(tids)
}

fn s19k_track1_require_ptrace_kernel_contract() -> Result<i32> {
    anyhow::ensure!(unsafe { libc::geteuid() } == 0, "S19k J3 requires uid 0");
    anyhow::ensure!(
        std::mem::size_of::<libc::c_ulong>() == 4,
        "S19k J3 requires the target-validated ARM32 c_ulong ABI"
    );
    let mut uts = std::mem::MaybeUninit::<libc::utsname>::zeroed();
    anyhow::ensure!(
        unsafe { libc::uname(uts.as_mut_ptr()) } == 0,
        "S19k J3 uname failed"
    );
    let uts = unsafe { uts.assume_init() };
    let release = unsafe { CStr::from_ptr(uts.release.as_ptr()) }.to_str()?;
    let machine = unsafe { CStr::from_ptr(uts.machine.as_ptr()) }.to_str()?;
    anyhow::ensure!(
        release == "4.9.113" && machine == "aarch64",
        "S19k J3 requires target-validated aarch64 Linux 4.9.113 (observed {machine} {release})"
    );
    match std::fs::symlink_metadata("/proc/sys/kernel/yama/ptrace_scope") {
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
        Err(error) => return Err(error).context("S19k J3 cannot inspect Yama ptrace_scope"),
        Ok(_) => anyhow::bail!("S19k J3 refuses an unexpected Yama ptrace_scope surface"),
    }
    let status = std::fs::read_to_string("/proc/self/status")?;
    let cap_eff = status
        .lines()
        .find_map(|line| line.strip_prefix("CapEff:"))
        .context("S19k J3 /proc/self/status lacks CapEff")?
        .trim();
    let cap_eff = u64::from_str_radix(cap_eff, 16).context("S19k J3 CapEff is invalid")?;
    anyhow::ensure!(
        cap_eff & (1u64 << 19) != 0,
        "S19k J3 requires CAP_SYS_PTRACE"
    );
    s19k_track1_current_tid()
}

impl S19kTrack1J3Lease {
    fn acquire(
        expected: &S19kStockHandoffIdentity,
        runtime_binding: S19kTrack1RuntimeBinding,
        live_identity: S19kLiveIdentityReceipt,
    ) -> Result<Self> {
        let tracer_tid = s19k_track1_require_ptrace_kernel_contract()?;
        expected.require_exact_tree_at(Path::new("/proc"))?;
        let mut lease = Self {
            expected: expected.clone(),
            runtime_binding,
            live_identity,
            tracer_tid,
            tasks: BTreeMap::new(),
            frozen: false,
            committed: false,
        };
        lease.acquire_group_fixpoint(S19kStockProcessRole::Supervisor)?;
        lease.acquire_group_fixpoint(S19kStockProcessRole::Bosminer)?;
        lease.require_same_tracer_thread()?;
        lease.expected.require_exact_tree_at(Path::new("/proc"))?;
        anyhow::ensure!(
            lease.drain_known(S19kTrack1PtraceWaitPhase::Freeze)? == 0,
            "S19k J3 stock lifecycle changed during initial all-thread acquisition"
        );
        Ok(lease)
    }

    fn process(&self, role: S19kStockProcessRole) -> &S19kStockProcessHandoffIdentity {
        match role {
            S19kStockProcessRole::Supervisor => &self.expected.supervisor,
            S19kStockProcessRole::Bosminer => &self.expected.bosminer,
        }
    }

    fn require_same_tracer_thread(&self) -> Result<()> {
        anyhow::ensure!(
            s19k_track1_current_tid()? == self.tracer_tid,
            "S19k J3 ptrace authority moved away from its pre-runtime tracer thread"
        );
        Ok(())
    }

    fn observe_tid(&self, role: S19kStockProcessRole, tid: i32) -> Result<(i32, u64, i32)> {
        let expected = self.process(role);
        let tgid = s19k_track1_status_i32(tid, "Tgid")?;
        let tracer_pid = s19k_track1_status_i32(tid, "TracerPid")?;
        let (state, start_ticks) = s19k_track1_tid_stat(tid)?;
        anyhow::ensure!(tgid == expected.pid, "S19k J3 TID {tid} changed TGID");
        anyhow::ensure!(
            !matches!(state, 'Z' | 'X' | 'x'),
            "S19k J3 TID {tid} is terminal during live admission"
        );
        anyhow::ensure!(
            std::fs::read_link(format!("/proc/{tid}/exe"))? == expected.executable,
            "S19k J3 TID {tid} executable changed"
        );
        anyhow::ensure!(
            std::fs::read(format!("/proc/{tid}/cmdline"))? == expected.role.exact_cmdline(),
            "S19k J3 TID {tid} argv changed"
        );
        Ok((tgid, start_ticks, tracer_pid))
    }

    fn acquire_tid(&mut self, role: S19kStockProcessRole, tid: i32) -> Result<()> {
        let (tgid, start_ticks, tracer_pid) = self.observe_tid(role, tid)?;
        if let Some(task) = self.tasks.get(&tid) {
            anyhow::ensure!(
                !task.terminal
                    && task.tgid == tgid
                    && task.start_ticks == start_ticks
                    && tracer_pid == self.tracer_tid,
                "S19k J3 active TID {tid} generation changed"
            );
            return Ok(());
        }
        if tracer_pid == 0 {
            s19k_track1_ptrace_seize(tid)?;
        } else {
            anyhow::ensure!(
                tracer_pid == self.tracer_tid,
                "S19k J3 TID {tid} is traced by unexpected TID {tracer_pid}"
            );
        }
        let (after_tgid, after_start, after_tracer) = self.observe_tid(role, tid)?;
        anyhow::ensure!(
            after_tgid == tgid && after_start == start_ticks && after_tracer == self.tracer_tid,
            "S19k J3 TID {tid} changed during PTRACE_SEIZE"
        );
        self.tasks.insert(
            tid,
            S19kTrack1PtraceTask {
                tgid,
                start_ticks,
                stopped: false,
                interrupt_sent: false,
                terminal: false,
                pending_signal: None,
            },
        );
        Ok(())
    }

    fn acquire_group_fixpoint(&mut self, role: S19kStockProcessRole) -> Result<()> {
        let deadline = Instant::now() + S19K_TRACK1_PTRACE_TIMEOUT;
        let tgid = self.process(role).pid;
        let mut previous = None;
        loop {
            self.process(role)
                .require_live_match_at(Path::new("/proc"), false)?;
            let tids = s19k_track1_list_tids(tgid)?;
            for tid in &tids {
                self.acquire_tid(role, *tid)?;
            }
            anyhow::ensure!(
                self.drain_known(S19kTrack1PtraceWaitPhase::Freeze)? == 0,
                "S19k J3 stock lifecycle changed during all-thread acquisition"
            );
            let second = s19k_track1_list_tids(tgid)?;
            if tids == second && previous.as_ref() == Some(&second) {
                return Ok(());
            }
            previous = Some(second);
            anyhow::ensure!(
                Instant::now() < deadline,
                "S19k J3 {} all-thread acquisition timed out",
                role.label()
            );
            std::thread::sleep(Duration::from_millis(5));
        }
    }

    fn handle_wait(
        &mut self,
        tid: i32,
        status: i32,
        phase: S19kTrack1PtraceWaitPhase,
    ) -> Result<()> {
        let task = self
            .tasks
            .get_mut(&tid)
            .with_context(|| format!("S19k J3 wait returned unknown TID {tid}"))?;
        if libc::WIFEXITED(status) || libc::WIFSIGNALED(status) {
            task.terminal = true;
            task.stopped = false;
            anyhow::ensure!(
                phase != S19kTrack1PtraceWaitPhase::Freeze,
                "S19k J3 stock TID {tid} terminated before commit"
            );
            return Ok(());
        }
        anyhow::ensure!(
            libc::WIFSTOPPED(status),
            "S19k J3 TID {tid} wait status is invalid"
        );
        let signal = libc::WSTOPSIG(status);
        let event = (status >> 16) & 0xffff;
        let was_interrupt_sent = task.interrupt_sent;
        task.interrupt_sent = false;
        task.stopped = true;
        match (phase, event) {
            (S19kTrack1PtraceWaitPhase::Freeze, libc::PTRACE_EVENT_STOP)
                if was_interrupt_sent =>
            {
                Ok(())
            }
            (S19kTrack1PtraceWaitPhase::Freeze, 0) => {
                task.pending_signal = Some(signal);
                Ok(())
            }
            (S19kTrack1PtraceWaitPhase::Commit, libc::PTRACE_EVENT_EXIT)
            | (S19kTrack1PtraceWaitPhase::Commit, libc::PTRACE_EVENT_STOP) => {
                s19k_track1_ptrace_continue(tid, 0)?;
                task.stopped = false;
                Ok(())
            }
            (S19kTrack1PtraceWaitPhase::Release, _) => Ok(()),
            _ => anyhow::bail!(
                "S19k J3 TID {tid} produced unexpected ptrace event {event} signal {signal} in {phase:?}"
            ),
        }
    }

    fn drain_known(&mut self, phase: S19kTrack1PtraceWaitPhase) -> Result<usize> {
        let tids = self.tasks.keys().copied().collect::<Vec<_>>();
        let mut count = 0;
        for tid in tids {
            loop {
                let mut status = 0;
                let waited =
                    unsafe { libc::waitpid(tid, &mut status, libc::__WALL | libc::WNOHANG) };
                if waited == tid {
                    self.handle_wait(tid, status, phase)?;
                    count += 1;
                    continue;
                }
                if waited == 0 {
                    break;
                }
                let error = std::io::Error::last_os_error();
                if error.kind() == std::io::ErrorKind::Interrupted {
                    continue;
                }
                if error.raw_os_error() == Some(libc::ECHILD) {
                    break;
                }
                return Err(error).with_context(|| format!("S19k J3 waitpid failed for TID {tid}"));
            }
        }
        Ok(count)
    }

    pub(crate) fn require_context(
        &self,
        authority: &S19kTrack1ReceiptAuthority,
        expected: &S19kStockHandoffIdentity,
    ) -> Result<()> {
        self.require_same_tracer_thread()?;
        anyhow::ensure!(
            &self.expected == expected,
            "S19k J3 stock identity tuple changed"
        );
        self.runtime_binding.require_active_unchanged(authority)?;
        let live_identity = s19k_capture_and_require_bound_live_identity()?;
        anyhow::ensure!(
            live_identity == self.live_identity,
            "S19k J3 live hardware identity changed after pre-runtime acquisition"
        );
        expected.require_exact_tree_at(Path::new("/proc"))
    }

    pub(crate) fn require_no_work_policy(&self, cli_no_work: bool) -> Result<()> {
        self.runtime_binding.require_no_work_policy(cli_no_work)
    }

    pub(crate) fn require_install_custody_safeoff_policy(
        &self,
        cli_install_custody_safeoff: bool,
    ) -> Result<()> {
        self.runtime_binding
            .require_install_custody_safeoff_policy(cli_install_custody_safeoff)
    }

    pub(crate) fn require_bounded_work_proof_policy(
        &self,
        cli_bounded_work_proof: bool,
    ) -> Result<()> {
        self.runtime_binding
            .require_bounded_work_proof_policy(cli_bounded_work_proof)
    }

    pub(crate) fn require_endurance_work_proof_policy(
        &self,
        cli_endurance_work_proof: bool,
    ) -> Result<()> {
        self.runtime_binding
            .require_endurance_work_proof_policy(cli_endurance_work_proof)
    }

    fn freeze_for_handoff(
        &mut self,
        authority: &S19kTrack1ReceiptAuthority,
        expected: &S19kStockHandoffIdentity,
    ) -> Result<usize> {
        self.require_context(authority, expected)?;
        let deadline = Instant::now() + S19K_TRACK1_PTRACE_TIMEOUT;
        let mut previous = None;
        loop {
            self.acquire_group_fixpoint(S19kStockProcessRole::Supervisor)?;
            self.acquire_group_fixpoint(S19kStockProcessRole::Bosminer)?;
            let interrupt_tids = self
                .tasks
                .iter()
                .filter_map(|(tid, task)| {
                    (!task.terminal && !task.stopped && !task.interrupt_sent).then_some(*tid)
                })
                .collect::<Vec<_>>();
            for tid in interrupt_tids {
                s19k_track1_ptrace_interrupt(tid)?;
                self.tasks
                    .get_mut(&tid)
                    .context("S19k J3 lost task during interrupt")?
                    .interrupt_sent = true;
            }
            self.drain_known(S19kTrack1PtraceWaitPhase::Freeze)?;
            let supervisor = s19k_track1_list_tids(expected.supervisor.pid)?;
            let bosminer = s19k_track1_list_tids(expected.bosminer.pid)?;
            for (role, tids) in [
                (S19kStockProcessRole::Supervisor, &supervisor),
                (S19kStockProcessRole::Bosminer, &bosminer),
            ] {
                for tid in tids {
                    self.acquire_tid(role, *tid)?;
                    let task = self.tasks.get(tid).context("S19k J3 lost frozen task")?;
                    anyhow::ensure!(
                        s19k_track1_status_i32(*tid, "TracerPid")? == self.tracer_tid
                            && !task.terminal,
                        "S19k J3 TID {tid} is outside the frozen lease"
                    );
                }
            }
            let snapshot = (supervisor, bosminer);
            let all_stopped = self
                .tasks
                .values()
                .filter(|task| !task.terminal)
                .all(|task| task.stopped);
            if all_stopped
                && previous.as_ref() == Some(&snapshot)
                && self.drain_known(S19kTrack1PtraceWaitPhase::Freeze)? == 0
            {
                self.require_context(authority, expected)?;
                self.frozen = true;
                return Ok(self.tasks.values().filter(|task| !task.terminal).count());
            }
            previous = Some(snapshot);
            anyhow::ensure!(
                Instant::now() < deadline,
                "S19k J3 all-thread freeze timed out"
            );
            std::thread::sleep(Duration::from_millis(5));
        }
    }

    fn sigkill_and_wait(&mut self, role: S19kStockProcessRole, timeout: Duration) -> Result<()> {
        self.require_same_tracer_thread()?;
        anyhow::ensure!(
            self.frozen,
            "S19k J3 terminal action requires a frozen lease"
        );
        let expected = self.process(role).clone();
        expected
            .require_live_match_at(Path::new("/proc"), role == S19kStockProcessRole::Bosminer)?;
        let mut tids = self
            .tasks
            .iter()
            .filter_map(|(tid, task)| (task.tgid == expected.pid && !task.terminal).then_some(*tid))
            .collect::<Vec<_>>();
        tids.sort_by_key(|tid| (*tid != expected.pid, *tid));
        anyhow::ensure!(
            !tids.is_empty(),
            "S19k J3 {} has no live TIDs",
            role.label()
        );
        anyhow::ensure!(
            tids.iter()
                .all(|tid| self.tasks.get(tid).is_some_and(|task| task.stopped)),
            "S19k J3 {} is not fully frozen at commit",
            role.label()
        );
        self.committed = true;
        anyhow::ensure!(
            unsafe { libc::kill(expected.pid, libc::SIGKILL) } == 0,
            "S19k J3 kill(2) failed for exact {}: {}",
            role.label(),
            std::io::Error::last_os_error()
        );
        for tid in tids {
            match s19k_track1_ptrace_continue(tid, 0) {
                Ok(()) => {
                    if let Some(task) = self.tasks.get_mut(&tid) {
                        task.stopped = false;
                        task.pending_signal = None;
                    }
                }
                Err(error)
                    if error.chain().any(|cause| {
                        cause
                            .downcast_ref::<std::io::Error>()
                            .is_some_and(|io| io.raw_os_error() == Some(libc::ESRCH))
                    }) => {}
                Err(error) => return Err(error),
            }
        }
        let deadline = Instant::now() + timeout;
        loop {
            self.drain_known(S19kTrack1PtraceWaitPhase::Commit)?;
            let active = self
                .tasks
                .values()
                .any(|task| task.tgid == expected.pid && !task.terminal);
            if !active && expected.exact_lifetime_is_gone_or_terminal_at(Path::new("/proc"))? {
                return Ok(());
            }
            anyhow::ensure!(
                Instant::now() < deadline,
                "S19k J3 exact {} did not reach terminal state before deadline",
                role.label()
            );
            std::thread::sleep(Duration::from_millis(5));
        }
    }

    fn best_effort_release(&mut self) {
        if self.committed || s19k_track1_current_tid().ok() != Some(self.tracer_tid) {
            return;
        }
        for (tid, task) in &mut self.tasks {
            if !task.terminal && !task.stopped && !task.interrupt_sent {
                if s19k_track1_ptrace_interrupt(*tid).is_ok() {
                    task.interrupt_sent = true;
                }
            }
        }
        let deadline = Instant::now() + Duration::from_millis(500);
        while self
            .tasks
            .values()
            .any(|task| !task.terminal && !task.stopped)
            && Instant::now() < deadline
        {
            let _ = self.drain_known(S19kTrack1PtraceWaitPhase::Release);
            std::thread::sleep(Duration::from_millis(5));
        }
        for (tid, task) in &self.tasks {
            if !task.terminal && task.stopped {
                let signal = task.pending_signal.unwrap_or(0);
                let _ = s19k_track1_ptrace_call(
                    libc::PTRACE_DETACH as u32,
                    *tid,
                    std::ptr::null_mut(),
                    signal as usize as *mut libc::c_void,
                );
            }
        }
    }
}

impl Drop for S19kTrack1J3Lease {
    fn drop(&mut self) {
        self.best_effort_release();
    }
}

fn s19k_require_no_live_stock_custody_processes_at(proc_root: &Path) -> Result<()> {
    let entries =
        std::fs::read_dir(proc_root).context("S19k cannot scan /proc for stock custody")?;
    for entry in entries {
        let entry = entry.context("S19k /proc scan returned an unreadable entry")?;
        let name = entry.file_name();
        let Some(name) = name.to_str() else {
            continue;
        };
        if name.is_empty() || !name.bytes().all(|byte| byte.is_ascii_digit()) {
            continue;
        }
        let process_root = entry.path();
        let read_text_or_gone = |path: &Path| -> Result<Option<String>> {
            match std::fs::read_to_string(path) {
                Ok(value) => Ok(Some(value)),
                Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(None),
                Err(error) => Err(error.into()),
            }
        };
        let Some(stat) = read_text_or_gone(&process_root.join("stat"))
            .with_context(|| format!("S19k cannot read /proc/{name}/stat during absence scan"))?
        else {
            continue;
        };
        let (_, after_comm) = stat
            .rsplit_once(") ")
            .with_context(|| format!("S19k /proc/{name}/stat is malformed during absence scan"))?;
        let state = after_comm
            .split_whitespace()
            .next()
            .and_then(|field| field.chars().next())
            .with_context(|| format!("S19k /proc/{name}/stat has no state"))?;
        if matches!(state, 'Z' | 'X' | 'x') {
            continue;
        }
        let Some(comm) = read_text_or_gone(&process_root.join("comm"))
            .with_context(|| format!("S19k cannot read /proc/{name}/comm during absence scan"))?
        else {
            continue;
        };
        let executable = match std::fs::read_link(process_root.join("exe")) {
            Ok(value) => Some(value),
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => None,
            Err(error) => {
                return Err(error).with_context(|| {
                    format!("S19k cannot resolve /proc/{name}/exe during absence scan")
                })
            }
        };
        let cmdline = match std::fs::read(process_root.join("cmdline")) {
            Ok(value) => value,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => continue,
            Err(error) => {
                return Err(error).with_context(|| {
                    format!("S19k cannot read /proc/{name}/cmdline during absence scan")
                })
            }
        };
        let argv = cmdline
            .split(|byte| *byte == 0)
            .filter(|arg| !arg.is_empty())
            .collect::<Vec<_>>();
        let argv0 = argv.first().copied().unwrap_or_default();
        let comm = comm.trim();
        let executable = executable.as_deref();
        let bosminer_candidate = comm == "bosminer"
            || executable == Some(Path::new("/usr/bin/bosminer"))
            || argv0 == b"/usr/bin/bosminer";
        let bos_tools_candidate = comm == "bos-tools"
            || executable == Some(Path::new("/usr/bin/bos-tools"))
            || argv0 == b"/usr/bin/bos-tools";
        let mentions_bosminer = argv.iter().any(|arg| *arg == b"/usr/bin/bosminer");
        anyhow::ensure!(
            !bosminer_candidate && !(bos_tools_candidate && mentions_bosminer),
            "S19k stock custody remains globally live or ambiguous at PID {name} (comm={comm:?}, exe={executable:?})"
        );
    }
    Ok(())
}

#[derive(Debug, Clone, Copy)]
enum S19kEarlyRetainedPhase {
    RuntimeBindingNotAdmitted,
    LiveIdentityNotAdmitted,
}

fn s19k_require_no_self_watchdog_fd() -> Result<()> {
    for entry in std::fs::read_dir("/proc/self/fd")
        .context("S19k retained-owner proof cannot inspect daemon descriptors")?
    {
        let entry = entry.context("S19k retained-owner descriptor scan failed")?;
        let target = match std::fs::read_link(entry.path()) {
            Ok(target) => target,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => continue,
            Err(error) => {
                return Err(error).context("S19k retained-owner descriptor readlink failed")
            }
        };
        anyhow::ensure!(
            !target.to_string_lossy().starts_with("/dev/watchdog"),
            "S19k retained-owner proof found a watchdog descriptor"
        );
    }
    Ok(())
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct S19kBootstrapFdProof {
    log_path: PathBuf,
    log_mnt_id: u64,
    log_inode: u64,
    log_mode: u32,
    log_uid: u32,
    log_gid: u32,
    fifo_fd: Option<i32>,
}

fn s19k_snapshot_open_fds() -> Result<BTreeMap<i32, PathBuf>> {
    // Collect the directory entries first and drop read_dir before resolving
    // them. Its own transient descriptor is therefore terminal/absent and is
    // the only candidate ignored below. Bootstrap is synchronous/single-threaded.
    let candidates = {
        let entries = std::fs::read_dir("/proc/self/fd")
            .context("S19k bootstrap cannot enumerate inherited descriptors")?;
        let mut values = Vec::new();
        for entry in entries {
            let entry = entry.context("S19k bootstrap descriptor enumeration raced")?;
            let name = entry.file_name();
            let text = name
                .to_str()
                .context("S19k bootstrap descriptor name is not UTF-8")?;
            values.push(
                text.parse::<i32>()
                    .context("S19k bootstrap descriptor name is not numeric")?,
            );
        }
        values
    };
    let mut observed = BTreeMap::new();
    for fd in candidates {
        match std::fs::read_link(format!("/proc/self/fd/{fd}")) {
            Ok(target) => {
                anyhow::ensure!(
                    observed.insert(fd, target).is_none(),
                    "S19k bootstrap observed a duplicate descriptor"
                );
            }
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
            Err(error) => {
                return Err(error).context("S19k bootstrap cannot resolve inherited descriptor")
            }
        }
    }
    Ok(observed)
}

fn s19k_fd_mnt_id(fd: i32) -> Result<u64> {
    std::fs::read_to_string(format!("/proc/self/fdinfo/{fd}"))?
        .lines()
        .find_map(|line| line.strip_prefix("mnt_id:").map(str::trim))
        .context("S19k bootstrap descriptor lacks mnt_id")?
        .parse::<u64>()
        .context("S19k bootstrap descriptor mnt_id is invalid")
}

fn s19k_require_exact_publisher_fd_set() -> Result<()> {
    let observed = s19k_snapshot_open_fds()?;
    let expected = BTreeSet::from([0, 1, 2]);
    anyhow::ensure!(
        observed.keys().copied().collect::<BTreeSet<_>>() == expected
            && observed
                .values()
                .all(|target| target == Path::new("/dev/null")),
        "S19k journal publisher inherited descriptors outside exact /dev/null stdio"
    );
    Ok(())
}

fn s19k_require_exact_daemon_fd_set(fifo_fd: Option<i32>) -> Result<S19kBootstrapFdProof> {
    let observed = s19k_snapshot_open_fds()?;
    let mut expected = BTreeSet::from([0, 1, 2]);
    if let Some(fd) = fifo_fd {
        anyhow::ensure!(fd > 2, "S19k startup FIFO descriptor overlaps stdio");
        expected.insert(fd);
    }
    anyhow::ensure!(
        observed.keys().copied().collect::<BTreeSet<_>>() == expected,
        "S19k daemon inherited an inexact descriptor set"
    );
    anyhow::ensure!(
        observed.get(&0).map(PathBuf::as_path) == Some(Path::new("/dev/null")),
        "S19k daemon stdin is not exact /dev/null"
    );
    let log_path = PathBuf::from(std::env::var("DCENT_S19K_STARTUP_LOG")?);
    let wrapper_pid = std::env::var("DCENT_S19K_STARTUP_WRAPPER_PID")?.parse::<i32>()?;
    let wrapper_start = std::env::var("DCENT_S19K_STARTUP_WRAPPER_START")?.parse::<u64>()?;
    let expected_name = format!(".startup_daemon_transcript.{wrapper_pid}.{wrapper_start}");
    anyhow::ensure!(
        log_path.is_absolute()
            && log_path.file_name().and_then(|name| name.to_str()) == Some(expected_name.as_str())
            && observed.get(&1) == Some(&log_path)
            && observed.get(&2) == Some(&log_path),
        "S19k daemon stdout/stderr are not the exact transaction transcript"
    );
    let log_metadata = std::fs::metadata("/proc/self/fd/1")?;
    let stderr_metadata = std::fs::metadata("/proc/self/fd/2")?;
    let path_metadata = std::fs::symlink_metadata(&log_path)?;
    anyhow::ensure!(
        path_metadata.file_type().is_file()
            && !path_metadata.file_type().is_symlink()
            && path_metadata.ino() == log_metadata.ino()
            && path_metadata.dev() == log_metadata.dev()
            && stderr_metadata.ino() == log_metadata.ino()
            && stderr_metadata.dev() == log_metadata.dev()
            && path_metadata.permissions().mode() & 0o777 == 0o600
            && path_metadata.uid() == 0
            && path_metadata.gid() == 0,
        "S19k daemon transcript type/inode/mode/owner is not exact"
    );
    if let Some(fd) = fifo_fd {
        anyhow::ensure!(
            observed.get(&fd) == Some(&PathBuf::from(std::env::var("DCENT_S19K_STARTUP_FIFO")?)),
            "S19k daemon FIFO descriptor target changed"
        );
    }
    Ok(S19kBootstrapFdProof {
        log_path,
        log_mnt_id: s19k_fd_mnt_id(1)?,
        log_inode: log_metadata.ino(),
        log_mode: path_metadata.permissions().mode() & 0o777,
        log_uid: path_metadata.uid(),
        log_gid: path_metadata.gid(),
        fifo_fd,
    })
}

fn s19k_publish_early_retained_receipt(
    authority: &S19kTrack1ReceiptAuthority,
    expected: &S19kStockHandoffIdentity,
    phase: S19kEarlyRetainedPhase,
) -> Result<()> {
    s19k_require_path_absent(&authority.retained, "early retained-stock receipt")?;
    let (active_sha256, active_bytes) =
        s19k_hash_regular_nonsymlink(&authority.active, "early runtime_active")?;
    expected
        .require_exact_tree_at(Path::new("/proc"))
        .context("S19k early refusal lost the exact stock tree")?;
    anyhow::ensure!(
        dcentrald_hal::platform::amlogic::read_s19k_track1_psu_engaged_checked()?,
        "S19k early refusal lost checked GPIO437 engagement"
    );
    s19k_require_no_self_watchdog_fd()?;
    let self_pid = std::process::id() as i32;
    let self_root = Path::new("/proc").join(self_pid.to_string());
    let self_stat = std::fs::read_to_string(self_root.join("stat"))?;
    let (_, self_after_comm) = self_stat
        .rsplit_once(") ")
        .context("S19k early retained daemon stat is malformed")?;
    let self_fields = self_after_comm.split_whitespace().collect::<Vec<_>>();
    anyhow::ensure!(
        self_fields.len() >= 20 && !matches!(self_fields[0], "Z" | "X" | "x"),
        "S19k early retained daemon lifetime is not live"
    );
    let self_ppid = self_fields[1].parse::<i32>()?;
    let self_start = self_fields[19].parse::<u64>()?;
    let self_comm = std::fs::read_to_string(self_root.join("comm"))?;
    let self_exe = std::fs::read_link(self_root.join("exe"))?;
    let parent = authority
        .active
        .parent()
        .context("S19k early retained trial parent disappeared")?;
    anyhow::ensure!(
        self_comm.trim() == "dcentrald" && self_exe == parent.join("dcentrald"),
        "S19k early retained daemon comm/executable is not exact"
    );
    let (schema, disposition, runtime_binding, live_identity) = match phase {
        S19kEarlyRetainedPhase::RuntimeBindingNotAdmitted => (
            "dcentos.s19k-stock-owner-retained-runtime-binding-not-admitted/v1",
            "stock-owner-retained-runtime-binding-not-admitted",
            "not-admitted",
            "not-observed",
        ),
        S19kEarlyRetainedPhase::LiveIdentityNotAdmitted => (
            "dcentos.s19k-stock-owner-retained-before-live-identity/v1",
            "stock-owner-retained-before-live-identity",
            "admitted",
            "not-admitted",
        ),
    };

    let mut receipt = String::new();
    macro_rules! line {
        ($key:expr, $value:expr) => {
            receipt.push_str($key);
            receipt.push('=');
            receipt.push_str(&$value.to_string());
            receipt.push('\n');
        };
    }
    line!("schema", schema);
    line!("disposition", disposition);
    line!("runtime_binding", runtime_binding);
    line!("live_identity", live_identity);
    line!("runtime_active_sha256", &active_sha256);
    line!("runtime_active_bytes", active_bytes);
    line!("signal_attempted", false);
    line!("supervisor_signal_attempted", false);
    line!("child_signal_attempted", false);
    line!("inherited_rails", false);
    line!("route_or_uart_opened", false);
    line!("watchdog_started", false);
    line!("watchdog_fd", "absent-checked");
    line!("daemon_pid", self_pid);
    line!("daemon_start", self_start);
    line!("daemon_ppid", self_ppid);
    line!("daemon_exe", self_exe.display());
    line!("stock_tree_revalidated", true);
    line!("gpio437_engaged", true);
    line!("supervisor_pid", expected.supervisor.pid);
    line!("supervisor_start", expected.supervisor.start_ticks);
    line!("supervisor_ppid", expected.supervisor.ppid);
    line!("supervisor_pgrp", expected.supervisor.pgrp);
    line!("supervisor_session", expected.supervisor.session);
    line!("supervisor_exe", expected.supervisor.executable.display());
    line!(
        "supervisor_cmdline_sha256",
        &expected.supervisor.cmdline_sha256
    );
    line!(
        "supervisor_cmdline_bytes",
        expected.supervisor.cmdline_bytes
    );
    line!("bosminer_pid", expected.bosminer.pid);
    line!("bosminer_start", expected.bosminer.start_ticks);
    line!("bosminer_ppid", expected.bosminer.ppid);
    line!("bosminer_pgrp", expected.bosminer.pgrp);
    line!("bosminer_session", expected.bosminer.session);
    line!("bosminer_exe", expected.bosminer.executable.display());
    line!("bosminer_cmdline_sha256", &expected.bosminer.cmdline_sha256);
    line!("bosminer_cmdline_bytes", expected.bosminer.cmdline_bytes);
    for (key, name) in [
        ("binary", "dcentrald"),
        ("config", "dcentrald_s19k.toml"),
        ("runner", "run_trial"),
        ("custody_observer", "supervisor_custody_observer"),
        ("stock_restart_helper", "stock_restart_helper"),
    ] {
        let (sha256, bytes) = s19k_hash_regular_nonsymlink(&parent.join(name), name)?;
        line!(&format!("{key}_sha256"), sha256);
        line!(&format!("{key}_bytes"), bytes);
    }
    line!("persistent_mutation", false);
    line!("publication", "no-clobber-hard-link-after-fsync");

    let temp = parent.join(format!(
        ".runtime_stock_owner_retained_early.tmp.{self_pid}.{self_start}"
    ));
    s19k_require_path_absent(&temp, "early retained-stock receipt scratch")?;
    let write_result = (|| -> Result<()> {
        let mut file = OpenOptions::new()
            .write(true)
            .create_new(true)
            .mode(0o600)
            .custom_flags(libc::O_CLOEXEC | libc::O_NOFOLLOW)
            .open(&temp)
            .context("S19k cannot create private early retained receipt scratch")?;
        file.write_all(receipt.as_bytes())?;
        file.sync_all()?;
        std::fs::hard_link(&temp, &authority.retained)
            .context("S19k cannot no-clobber publish early retained receipt")?;
        Ok(())
    })();
    let _ = std::fs::remove_file(&temp);
    write_result?;
    let published =
        s19k_read_regular_nonsymlink(&authority.retained, "published early retained receipt")?;
    anyhow::ensure!(
        published == receipt.as_bytes(),
        "S19k early retained receipt changed after publication"
    );
    let (after_sha256, after_bytes) =
        s19k_hash_regular_nonsymlink(&authority.active, "early runtime_active recheck")?;
    anyhow::ensure!(
        after_sha256 == active_sha256 && after_bytes == active_bytes,
        "S19k runtime_active changed across early receipt publication"
    );
    Ok(())
}

fn s19k_publish_stock_owner_retained_prewatchdog_receipt(
    authority: &S19kTrack1ReceiptAuthority,
    binding: &S19kTrack1RuntimeBinding,
    expected: &S19kStockHandoffIdentity,
    admitted_live_identity: &S19kLiveIdentityReceipt,
) -> Result<()> {
    binding.require_active_unchanged(authority)?;
    s19k_require_path_absent(&authority.retained, "pre-watchdog retained-stock receipt")?;
    expected
        .require_exact_tree_at(Path::new("/proc"))
        .context("S19k pre-watchdog refusal lost the exact stock tree")?;
    anyhow::ensure!(
        dcentrald_hal::platform::amlogic::read_s19k_track1_psu_engaged_checked()?,
        "S19k pre-watchdog refusal lost checked GPIO437 engagement"
    );
    let retained_live_identity = s19k_capture_and_require_bound_live_identity()
        .context("S19k pre-watchdog refusal could not revalidate live identity")?;
    anyhow::ensure!(
        &retained_live_identity == admitted_live_identity,
        "S19k pre-watchdog refusal observed changed live identity"
    );
    for entry in std::fs::read_dir("/proc/self/fd")
        .context("S19k pre-watchdog refusal cannot inspect daemon descriptors")?
    {
        let entry = entry.context("S19k pre-watchdog descriptor scan failed")?;
        let target = match std::fs::read_link(entry.path()) {
            Ok(target) => target,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => continue,
            Err(error) => {
                return Err(error).context("S19k pre-watchdog descriptor readlink failed")
            }
        };
        anyhow::ensure!(
            !target.to_string_lossy().starts_with("/dev/watchdog"),
            "S19k pre-watchdog retained-owner proof found a watchdog descriptor"
        );
    }

    let mut receipt = String::new();
    macro_rules! line {
        ($key:expr, $value:expr) => {
            receipt.push_str($key);
            receipt.push('=');
            receipt.push_str(&$value.to_string());
            receipt.push('\n');
        };
    }
    line!("schema", "dcentos.s19k-stock-owner-retained-prewatchdog/v1");
    line!("disposition", "stock-owner-retained-before-watchdog");
    line!("runtime_active_sha256", &binding.active_sha256);
    line!("runtime_active_bytes", binding.active_bytes);
    line!("signal_attempted", false);
    line!("supervisor_signal_attempted", false);
    line!("child_signal_attempted", false);
    line!("inherited_rails", false);
    line!("route_or_uart_opened", false);
    line!("watchdog_started", false);
    line!("watchdog_fd", "absent-checked");
    line!("stock_tree_revalidated", true);
    line!("live_identity_revalidated", true);
    line!("gpio437_engaged", true);
    line!("supervisor_pid", expected.supervisor.pid);
    line!("supervisor_start", expected.supervisor.start_ticks);
    line!("supervisor_ppid", expected.supervisor.ppid);
    line!("supervisor_pgrp", expected.supervisor.pgrp);
    line!("supervisor_session", expected.supervisor.session);
    line!("supervisor_exe", expected.supervisor.executable.display());
    line!(
        "supervisor_cmdline_sha256",
        &expected.supervisor.cmdline_sha256
    );
    line!(
        "supervisor_cmdline_bytes",
        expected.supervisor.cmdline_bytes
    );
    line!("bosminer_pid", expected.bosminer.pid);
    line!("bosminer_start", expected.bosminer.start_ticks);
    line!("bosminer_ppid", expected.bosminer.ppid);
    line!("bosminer_pgrp", expected.bosminer.pgrp);
    line!("bosminer_session", expected.bosminer.session);
    line!("bosminer_exe", expected.bosminer.executable.display());
    line!("bosminer_cmdline_sha256", &expected.bosminer.cmdline_sha256);
    line!("bosminer_cmdline_bytes", expected.bosminer.cmdline_bytes);
    for (key, source) in [
        ("binary_sha256", "binary_sha256"),
        ("binary_bytes", "binary_bytes"),
        ("config_sha256", "config_sha256"),
        ("config_bytes", "config_bytes"),
        ("runner_sha256", "runner_sha256"),
        ("runner_bytes", "runner_bytes"),
        ("custody_observer_sha256", "custody_observer_sha256"),
        ("custody_observer_bytes", "custody_observer_bytes"),
        ("stock_restart_helper_sha256", "stock_restart_helper_sha256"),
        ("stock_restart_helper_bytes", "stock_restart_helper_bytes"),
    ] {
        line!(key, binding.field(source)?);
    }
    line!("live_identity_schema", S19K_LIVE_IDENTITY_SCHEMA);
    line!(
        "live_identity_profile",
        admitted_live_identity.profile.as_str()
    );
    line!("live_identity_sha256", &admitted_live_identity.sha256);
    line!(
        "live_identity_model_sha256",
        &admitted_live_identity.model_sha256
    );
    line!("persistent_mutation", false);
    line!("publication", "no-clobber-hard-link-after-fsync");

    let parent = authority
        .retained
        .parent()
        .context("S19k pre-watchdog retained receipt parent disappeared")?;
    let (self_pid, self_start, _) = s19k_self_lifetime()?;
    let temp = parent.join(format!(
        ".runtime_stock_owner_retained_prewatchdog.tmp.{self_pid}.{self_start}"
    ));
    s19k_require_path_absent(&temp, "pre-watchdog retained-stock receipt scratch")?;
    let write_result = (|| -> Result<()> {
        let mut file = OpenOptions::new()
            .write(true)
            .create_new(true)
            .mode(0o600)
            .custom_flags(libc::O_CLOEXEC | libc::O_NOFOLLOW)
            .open(&temp)
            .context("S19k cannot create private pre-watchdog retained receipt scratch")?;
        file.write_all(receipt.as_bytes())?;
        file.sync_all()?;
        std::fs::hard_link(&temp, &authority.retained)
            .context("S19k cannot no-clobber publish pre-watchdog retained receipt")?;
        Ok(())
    })();
    let _ = std::fs::remove_file(&temp);
    write_result?;
    let published = s19k_read_regular_nonsymlink(
        &authority.retained,
        "published Track-1 pre-watchdog retained-stock receipt",
    )?;
    anyhow::ensure!(
        published == receipt.as_bytes(),
        "S19k pre-watchdog retained-stock receipt changed after publication"
    );
    binding.require_active_unchanged(authority)?;
    Ok(())
}

