fn s19k_bounded_work_rx_wire_hex(body: &[u8]) -> String {
    let mut wire = Vec::with_capacity(body.len().saturating_add(2));
    wire.extend_from_slice(&[0xAA, 0x55]);
    wire.extend_from_slice(body);
    s19k_compact_tx_hex(&wire)
}

fn s19k_endurance_snapshot(
    monotonic_ms: u64,
    pool_state: String,
    aggregate_hashrate_ghs: f64,
    hottest_temp_c: f32,
    dangerous_temp_c: u8,
    fan_pwm: u8,
    fan_readings: &[(u8, u32)],
    gpio437: Option<u8>,
    endpoints: &[S19kSerialEndpointRuntime],
) -> Result<S19kEnduranceSnapshot> {
    anyhow::ensure!(
        hottest_temp_c.is_finite(),
        "S19k endurance temperature is not finite"
    );
    anyhow::ensure!(
        aggregate_hashrate_ghs.is_finite() && aggregate_hashrate_ghs >= 0.0,
        "S19k endurance aggregate hashrate is invalid"
    );
    let hottest_temp_millic = (f64::from(hottest_temp_c) * 1000.0).round() as i64;
    let dangerous_temp_millic = i64::from(dangerous_temp_c) * 1000;
    let gpio437 = gpio437.context("S19k endurance GPIO437 state is unavailable")?;
    let mut paths = endpoints
        .iter()
        .filter(|endpoint| endpoint.tx_active)
        .map(|endpoint| S19kEndurancePathSnapshot {
            path: endpoint.logical_path.clone(),
            chips: endpoint.getaddress_responses,
            complete_77_at_work_baud: endpoint.complete_77_at_work_baud,
            tx_frames: endpoint.work_frames_committed,
            rx_wire_bytes: endpoint.rx_wire_bytes,
            rx_frames: endpoint.rx_frames,
            valid_nonces: endpoint.valid_job_nonce_observations,
            shares_submitted: endpoint.shares_submitted,
            shares_accepted: endpoint.shares_accepted,
            shares_rejected: endpoint.shares_rejected,
        })
        .collect::<Vec<_>>();
    paths.sort_by(|left, right| left.path.cmp(&right.path));
    Ok(S19kEnduranceSnapshot {
        monotonic_ms,
        wall_unix_ms: unix_time_ms()?,
        pool_state,
        aggregate_hashrate_millighs: (aggregate_hashrate_ghs * 1000.0).round() as u64,
        hottest_temp_millic,
        dangerous_temp_millic,
        fan_pwm,
        fan_readings: fan_readings.to_vec(),
        gpio437,
        paths,
    })
}

#[derive(Default)]
struct S19kSubmittedShareOriginSidecar {
    entries: Mutex<VecDeque<(S19kSubmittedShareKey, S19kSubmittedShareOrigin)>>,
    evicted: AtomicU64,
    unmatched_results: AtomicU64,
}

fn s19k_record_submitted_share_origin(
    sidecar: &S19kSubmittedShareOriginSidecar,
    key: S19kSubmittedShareKey,
    origin: S19kSubmittedShareOrigin,
) {
    let mut entries = sidecar.entries.lock().unwrap_or_else(|poisoned| {
        warn!("S19k submitted-share origin sidecar mutex poisoned; recovering");
        poisoned.into_inner()
    });
    if entries.len() >= S19K_SUBMITTED_SHARE_ORIGIN_CAPACITY {
        if let Some((evicted_key, evicted_origin)) = entries.pop_front() {
            let evicted = sidecar.evicted.fetch_add(1, Ordering::AcqRel) + 1;
            warn!(
                evicted,
                work_generation = ?evicted_key.work_generation,
                job_id = %evicted_key.job_id,
                nonce = %evicted_key.nonce,
                path = %evicted_origin.path,
                "S19k submitted-share origin evicted from bounded result-correlation history"
            );
        }
    }
    entries.push_back((key, origin));
}

fn s19k_remove_submitted_share_origin(
    sidecar: &S19kSubmittedShareOriginSidecar,
    share: &dcentrald_stratum::types::ValidShare,
) -> Option<S19kSubmittedShareOrigin> {
    let key = S19kSubmittedShareKey::from_share(share);
    let mut entries = sidecar.entries.lock().unwrap_or_else(|poisoned| {
        warn!("S19k submitted-share origin sidecar mutex poisoned; recovering");
        poisoned.into_inner()
    });
    let position = entries
        .iter()
        .position(|(candidate, _)| candidate == &key)?;
    entries.remove(position).map(|(_, origin)| origin)
}

fn s19k_take_submitted_share_origin_for_result(
    sidecar: &S19kSubmittedShareOriginSidecar,
    share: &dcentrald_stratum::types::ValidShare,
) -> Option<S19kSubmittedShareOrigin> {
    let origin = s19k_remove_submitted_share_origin(sidecar, share);
    if origin.is_none() {
        let unmatched_results = sidecar.unmatched_results.fetch_add(1, Ordering::AcqRel) + 1;
        let evicted = sidecar.evicted.load(Ordering::Acquire);
        let classification = if evicted > 0 {
            "missing_or_evicted_bounded_history"
        } else {
            "missing_never_recorded_or_already_consumed"
        };
        warn!(
            unmatched_results,
            evicted,
            classification,
            work_generation = ?share.work_generation,
            job_id = %share.job_id,
            nonce = %share.nonce,
            "S19k pool result has no exact submitted-share serial origin"
        );
    }
    origin
}

fn s19k_note_share_result_missing_meta(sidecar: &S19kSubmittedShareOriginSidecar) {
    let unmatched_results = sidecar.unmatched_results.fetch_add(1, Ordering::AcqRel) + 1;
    let evicted = sidecar.evicted.load(Ordering::Acquire);
    warn!(
        unmatched_results,
        evicted,
        classification = "missing_stratum_share_event_meta",
        "S19k pool result cannot be correlated to a submitted serial share"
    );
}

/// Attempt-8d duplicate-path credit: is this exact share key currently in the
/// bounded submitted-origin history (submitted, pool result still pending)?
/// The sidecar is capacity-bounded and drained on each pool result, so a
/// `true` here is always a live awaitable submission.
fn s19k_submitted_share_origin_known(
    sidecar: &S19kSubmittedShareOriginSidecar,
    key: &S19kSubmittedShareKey,
) -> bool {
    let entries = sidecar.entries.lock().unwrap_or_else(|poisoned| {
        warn!("S19k submitted-share origin sidecar mutex poisoned; recovering");
        poisoned.into_inner()
    });
    entries.iter().any(|(candidate, _)| candidate == key)
}

impl S19kSerialEndpointRuntime {
    fn opened(
        path: &'static str,
        getaddress_responses: u16,
        complete_77_at_work_baud: bool,
        tx_active: bool,
    ) -> Self {
        Self {
            logical_path: path.to_string(),
            open_state: "open".to_string(),
            tx_role: if !tx_active {
                "discover_rx_only"
            } else if path == BRAIINS_TTYS_THIRD {
                "complete77_work_baud_promoted_tx"
            } else {
                "required_pair_work_tx"
            }
            .to_string(),
            tx_active,
            getaddress_responses,
            complete_77_at_work_baud,
            work_frames_committed: 0,
            rx_wire_bytes: 0,
            rx_frames: 0,
            crc_rejected_frames: 0,
            buffered_rx_bytes: 0,
            valid_job_nonce_observations: 0,
            shares_submitted: 0,
            shares_accepted: 0,
            shares_rejected: 0,
            last_frame_rx_at: None,
            last_valid_job_nonce_at: None,
            parser_state: SerialRxIntervalState::Silent.as_str().to_string(),
        }
    }

    fn optional_open_failed(path: &'static str) -> Self {
        let mut endpoint = Self::opened(path, 0, false, false);
        endpoint.open_state = "optional_open_failed".to_string();
        endpoint
    }

    fn to_api(&self, now: Duration) -> dcentrald_api::SerialEndpointState {
        dcentrald_api::SerialEndpointState {
            logical_path: self.logical_path.clone(),
            open_state: self.open_state.clone(),
            tx_role: self.tx_role.clone(),
            tx_active: self.tx_active,
            getaddress_responses: self.getaddress_responses,
            complete_77_at_work_baud: self.complete_77_at_work_baud,
            work_frames_committed: self.work_frames_committed,
            rx_wire_bytes: self.rx_wire_bytes,
            rx_frames: self.rx_frames,
            crc_rejected_frames: self.crc_rejected_frames,
            buffered_rx_bytes: self.buffered_rx_bytes,
            valid_job_nonce_observations: self.valid_job_nonce_observations,
            last_frame_rx_age_s: self
                .last_frame_rx_at
                .map(|observed| now.saturating_sub(observed).as_secs()),
            last_valid_job_nonce_age_s: self
                .last_valid_job_nonce_at
                .map(|observed| now.saturating_sub(observed).as_secs()),
            parser_state: self.parser_state.clone(),
        }
    }
}

fn s19k_all_active_tx_paths_have_recent_valid_nonce(
    endpoints: &[S19kSerialEndpointRuntime],
    now: Duration,
    startup_grace: Duration,
) -> bool {
    let mut active = endpoints.iter().filter(|endpoint| endpoint.tx_active);
    let Some(first) = active.next() else {
        return false;
    };
    if now < startup_grace {
        return true;
    }
    std::iter::once(first).chain(active).all(|endpoint| {
        endpoint
            .last_valid_job_nonce_at
            .is_some_and(|observed| now.saturating_sub(observed) < startup_grace)
    })
}

fn aggregate_serial_rx_parser_state(
    states: impl IntoIterator<Item = SerialRxIntervalState>,
) -> SerialRxIntervalState {
    states
        .into_iter()
        .max_by_key(|state| match state {
            SerialRxIntervalState::Silent => 0,
            SerialRxIntervalState::FramedProgress => 1,
            SerialRxIntervalState::WireOnlyProgress => 2,
            SerialRxIntervalState::CounterReset => 3,
        })
        .unwrap_or(SerialRxIntervalState::Silent)
}

