    #[test]
    fn nopic_panic_fans_coast_only_after_checked_cut() {
        assert_eq!(
            s19k_nopic_panic_fan_action(true, true, false),
            S19kNoPicPanicFanAction::CoastAfterCheckedCut
        );
        assert_eq!(
            s19k_nopic_panic_fan_action(true, false, true),
            S19kNoPicPanicFanAction::RetainTrack1ExplicitPwm100
        );
        assert_eq!(
            s19k_nopic_panic_fan_action(true, false, false),
            S19kNoPicPanicFanAction::HoldTrack1HomeCap
        );
        assert_eq!(
            s19k_nopic_panic_fan_action(false, false, false),
            S19kNoPicPanicFanAction::LeaveUnchanged
        );
    }

    #[test]
    fn track1_watchdog_accepts_only_positive_armed_admission() {
        let armed = WatchdogAdmission::Armed(crate::runtime::safety_watchdog::WatchdogArmReceipt {
            requested_timeout_s: 60,
            effective_timeout_s: 60,
            kick_interval_s: 20,
        });
        assert!(armed.require_armed("S19k Track-1").is_ok());
        assert!(WatchdogAdmission::DisabledByConfiguration
            .require_armed("S19k Track-1")
            .is_err());
        assert!(WatchdogAdmission::UnavailableBeforeOpen {
            reason: "missing watchdog".to_string(),
        }
        .require_armed("S19k Track-1")
        .is_err());
        assert!(WatchdogAdmission::OpenedOrOutcomeUnknown {
            reason: "open outcome unknown".to_string(),
        }
        .require_armed("S19k Track-1")
        .is_err());
    }

    #[test]
    fn track1_watchdog_sla_requires_exact_30_30_5() {
        let exact = WatchdogArmReceipt {
            requested_timeout_s: 30,
            effective_timeout_s: 30,
            kick_interval_s: 5,
        };
        assert!(admit_s19k_track1_watchdog_sla(&exact).is_ok());

        for refused in [
            WatchdogArmReceipt {
                requested_timeout_s: 29,
                ..exact.clone()
            },
            WatchdogArmReceipt {
                effective_timeout_s: 6,
                ..exact.clone()
            },
            WatchdogArmReceipt {
                effective_timeout_s: 31,
                ..exact.clone()
            },
            WatchdogArmReceipt {
                effective_timeout_s: 60,
                ..exact.clone()
            },
            WatchdogArmReceipt {
                kick_interval_s: 4,
                ..exact.clone()
            },
            WatchdogArmReceipt {
                kick_interval_s: 6,
                ..exact
            },
        ] {
            let error = admit_s19k_track1_watchdog_sla(&refused)
                .expect_err("non-exact Track-1 watchdog SLA must be refused");
            assert!(error
                .to_string()
                .contains("required requested/effective/kick=30/30/5s"));
        }
    }

    #[test]
    fn track1_j3_is_exact_kernel_all_thread_authority() {
        let source = include_str!("serial_mining.rs");
        let production = source
            .split("\n#[cfg(test)]\nmod tests {")
            .next()
            .expect("production source");

        let options = production
            .split_once("const S19K_TRACK1_PTRACE_OPTIONS")
            .expect("J3 ptrace options")
            .1
            .split_once("const S19K_TRACK1_PTRACE_TIMEOUT")
            .expect("J3 ptrace option boundary")
            .0;
        for option in [
            "PTRACE_O_TRACEFORK",
            "PTRACE_O_TRACEVFORK",
            "PTRACE_O_TRACECLONE",
            "PTRACE_O_TRACEEXEC",
            "PTRACE_O_TRACEEXIT",
        ] {
            assert!(options.contains(option), "J3 lacks {option}");
        }
        assert!(
            !options.contains("PTRACE_O_EXITKILL"),
            "uncommitted J3 must remain rollback-capable"
        );

        let kernel = production
            .split_once("fn s19k_track1_require_ptrace_kernel_contract()")
            .expect("J3 kernel contract")
            .1
            .split_once("impl S19kTrack1J3Lease")
            .expect("J3 kernel contract boundary")
            .0;
        assert!(kernel.contains("std::mem::size_of::<libc::c_ulong>() == 4"));
        assert!(kernel.contains("release == \"4.9.113\" && machine == \"aarch64\""));
        assert!(kernel.contains("/proc/sys/kernel/yama/ptrace_scope"));
        assert!(kernel.contains("cap_eff & (1u64 << 19) != 0"));
        assert!(production.contains("libc::syscall(libc::SYS_gettid)"));
        assert!(production.contains("s19k_track1_current_tid()? == self.tracer_tid"));

        let freeze = production
            .split_once("fn freeze_for_handoff(")
            .expect("J3 freeze")
            .1
            .split_once("fn sigkill_and_wait(")
            .expect("J3 freeze boundary")
            .0;
        assert!(freeze.contains("acquire_group_fixpoint(S19kStockProcessRole::Supervisor)"));
        assert!(freeze.contains("acquire_group_fixpoint(S19kStockProcessRole::Bosminer)"));
        assert!(freeze.contains("s19k_track1_ptrace_interrupt(tid)?"));
        let all_stopped = freeze
            .find("let all_stopped")
            .expect("all-TID stopped proof");
        let double_stable = freeze
            .find("previous.as_ref() == Some(&snapshot)")
            .expect("double-stable task roster");
        let empty_wait_queue = freeze
            .find("self.drain_known(S19kTrack1PtraceWaitPhase::Freeze)? == 0")
            .expect("empty ptrace wait queue proof");
        let final_context = freeze
            .rfind("self.require_context(authority, expected)?")
            .expect("final content-bound context proof");
        assert!(all_stopped < double_stable);
        assert!(double_stable < empty_wait_queue);
        assert!(empty_wait_queue < final_context);

        let commit = production
            .split_once("fn sigkill_and_wait(")
            .expect("J3 commit")
            .1
            .split_once("fn best_effort_release(")
            .expect("J3 commit boundary")
            .0;
        let committed = commit
            .find("self.committed = true")
            .expect("irreversible-boundary marker");
        let group_kill = commit
            .find("libc::kill(expected.pid, libc::SIGKILL)")
            .expect("real group-directed SIGKILL");
        let every_tid = commit.find("for tid in tids").expect("all-TID resume loop");
        let resume = commit[every_tid..]
            .find("s19k_track1_ptrace_continue(tid, 0)")
            .map(|offset| every_tid + offset)
            .expect("all-TID post-kill resume");
        assert!(committed < group_kill && group_kill < every_tid && every_tid < resume);
        assert!(!commit.contains("s19k_track1_ptrace_continue(tid, libc::SIGKILL)"));

        let release = production
            .split_once("fn best_effort_release(")
            .expect("J3 rollback")
            .1
            .split_once("impl Drop for S19kTrack1J3Lease")
            .expect("J3 rollback boundary")
            .0;
        assert!(release.contains("s19k_track1_ptrace_interrupt(*tid)"));
        assert!(release.contains("libc::PTRACE_DETACH"));
        assert!(release.contains("task.pending_signal.unwrap_or(0)"));
    }

    #[test]
    fn track1_closeout_source_fences_panic_planned_stop_and_question_mark_exits() {
        let source = include_str!("serial_mining.rs");
        let production = source
            .split("\n#[cfg(test)]\nmod tests {")
            .next()
            .expect("production source");

        let safeoff_start = production
            .find("fn s19k_track1_reset_then_cut_checked()")
            .expect("typed Track-1 reset+cut closeout");
        let safeoff_end = production[safeoff_start..]
            .find("pub(crate) fn s19k_track1_recovery_safeoff(")
            .map(|offset| safeoff_start + offset)
            .expect("Track-1 recovery closeout boundary");
        let safeoff = &production[safeoff_start..safeoff_end];
        assert!(
            safeoff.find("set_amlogic_board_reset_checked").unwrap()
                < safeoff.find("disable_s19k_track1_psu_checked").unwrap()
        );
        assert!(safeoff.contains("failures.push"));
        assert!(!safeoff.contains("disable_psu_checked()"));
        let terminal_start = production
            .find("fn s19k_track1_terminal_safeoff() -> Result<()>")
            .expect("typed Track-1 terminal closeout");
        let terminal_end = production[terminal_start..]
            .find("struct S19kTrack1RunCloseoutGuard")
            .map(|offset| terminal_start + offset)
            .expect("Track-1 result-error guard");
        let terminal = &production[terminal_start..terminal_end];
        assert!(terminal.contains("s19k_track1_reset_then_cut_checked"));
        // 2026-08-28 C1 convergence re-pin (2 -> 4): commit 13915439a (S19k
        // native BM1366 population owner) added two further explicit cuts in
        // `impl Drop for NoPicPsuGuard` — the `s19k_native_reset_before_cut`
        // pre-join cut and the post-join raw-1 final cut. Both are drop-time
        // best-effort teardown legs, the same safety family as the terminal
        // closeout and the panic hook; the fence below still proves every
        // explicit marker-independent cut lives inside a teardown context.
        let drop_start = production
            .find("impl Drop for NoPicPsuGuard")
            .expect("NoPic PSU guard drop teardown");
        let drop_end = production[drop_start..]
            .find("if !owner_cut_attempted")
            .map(|offset| drop_start + offset)
            .expect("drop pre-join cut boundary");
        let drop_pre_join = &production[drop_start..drop_end];
        assert!(
            drop_pre_join.contains("latch_terminal_and_disable_psu_checked"),
            "the drop path's owned-lifecycle cut goes through the terminal latch"
        );
        assert_eq!(
            production
                .match_indices("disable_s19k_track1_psu_checked()")
                .count(),
            5,
            "the explicit marker-independent S19k cut is restricted to the \
             reset-capable terminal closeout, install-custody cut-only helper, \
             panic hook, and the NoPicPsuGuard drop teardown (pre-join + \
             post-join legs)"
        );

        let planned_start = production
            .find("fn s19k_track1_maybe_planned_stop_safeoff() -> Result<()>")
            .expect("planned-stop helper");
        let planned_end = production[planned_start..]
            .find("struct Track1HostBaudRestore")
            .map(|offset| planned_start + offset)
            .expect("planned-stop helper end");
        let planned = &production[planned_start..planned_end];
        assert!(planned.contains("Ok(true) => s19k_track1_terminal_safeoff()"));
        assert!(!planned.contains("disable_psu_checked"));

        let panic_start = production
            .find("pub fn nopic_panic_hook_best_effort_teardown()")
            .expect("NoPic panic hook");
        let panic_end = production[panic_start..]
            .find("trait Am2FirstStagePowerCut")
            .map(|offset| panic_start + offset)
            .expect("NoPic panic hook end");
        let panic_hook = &production[panic_start..panic_end];
        // 2026-08-28 C1 convergence: the panic hook's reset leg was renamed
        // with the S19k native owner work (13915439a) from
        // `set_amlogic_board_reset_checked` to the all-resets assertion; the
        // ordering fence (reset assertion strictly before the PSU cut) is
        // unchanged.
        assert!(
            panic_hook
                .find("assert_s19k_native_all_resets_checked")
                .unwrap()
                < panic_hook.find("disable_s19k_track1_psu_checked").unwrap()
        );
        // 2026-08-28 C1 convergence: the Track-1 armed gate is now expressed
        // through the `s19k_reset_and_raw1` conjunction (native OR track1)
        // for the reset+cut legs and the separate `explicit_loud_authority`
        // (track1_armed AND the loud-fan authorization load) for the loud
        // action — the "if track1_armed" single-branch shape was refactored
        // by the S19k native owner work (13915439a) without weakening it.
        assert!(panic_hook.contains("let track1_armed = S19K_TRACK1_TEARDOWN_ARMED.load"));
        assert!(panic_hook.contains("let s19k_reset_and_raw1 = native_armed || track1_armed;"));
        assert!(panic_hook.contains("let explicit_loud_authority = track1_armed"));
        assert!(panic_hook.contains("S19K_TRACK1_LOUD_FAN_AUTHORIZED.load"));
        assert!(panic_hook.contains("S19kNoPicPanicFanAction::RetainTrack1ExplicitPwm100"));
        assert!(panic_hook.contains("S19kNoPicPanicFanAction::HoldTrack1HomeCap"));
        assert!(panic_hook.contains("hold_track1_leftover_fans_pwm100(true)"));
        assert!(!panic_hook.contains("disable_psu();"));

        let run_start = production
            .find("pub async fn run(&mut self) -> Result<()>")
            .expect("production run");
        let run = &production[run_start..];
        let guard_owner = run
            .find("let mut s19k_track1_run_closeout")
            .expect("run-scoped Track-1 guard");
        let guard_prepare = run
            .find("S19kTrack1RunCloseoutGuard::prepare(")
            .expect("Track-1 guard preparation");
        let first_track1_uart_open = run
            .find("SerialChainBackend::open_passthrough_bm1366")
            .expect("first Track-1 UART open");
        let first_track1_fallible_observation = run
            // Re-anchored 2026-09-01 (Lane-F): production drifted to the
            // install-custody branch form in 25ea0e9b1, so the historical
            // `let nopic = is_nopic(&self.config)?;` literal only self-matched
            // test bodies. Same statement, same ordering intent.
            .find("let nopic = if s19k_install_custody_safeoff || is_bm1362_aml || is_bm1366_xp {")
            .expect("first Track-1 fallible hardware observation");
        assert!(guard_owner < guard_prepare && guard_prepare < first_track1_fallible_observation);
        assert!(guard_prepare < first_track1_uart_open);
        assert!(run.contains("requires explicit --allow-loud authority"));
        assert!(run.contains("hold_track1_leftover_fans_pwm100(\n                        self.explicit_loud_fan_authority,"));
        let handoff_start = run
            .find("match s19k_wait_for_runtime_binding(retained_receipt_authority, expected)")
            .expect("receipt-bound runner/self/artifact/tree admission");
        let first_live_identity = run[handoff_start..]
            .find(
                "let admitted_live_identity = match s19k_capture_and_require_bound_live_identity()",
            )
            .map(|offset| handoff_start + offset)
            .expect("receipt-bound process-independent live identity");
        let j3_freeze = run[first_live_identity..]
            .find(".freeze_for_handoff(retained_receipt_authority, expected)?")
            .map(|offset| first_live_identity + offset)
            .expect("J3 all-thread freeze before watchdog open");
        let signal_lease = run[handoff_start..]
            .find("expected.open_both_signal_leases_checked()?")
            .map(|offset| handoff_start + offset)
            .expect("exact supervisor+child signal leases");
        let watchdog_start = run[signal_lease..]
            .find("SafetyWatchdogOwner::start_before_energizing")
            .map(|offset| signal_lease + offset)
            .expect("Track-1 watchdog startup");
        let watchdog_positive = run[watchdog_start..]
            .find("WatchdogAdmission::Armed(receipt) => receipt")
            .map(|offset| watchdog_start + offset)
            .expect("Track-1 positive watchdog admission");
        let watchdog_sla = run[watchdog_positive..]
            .find("admit_s19k_track1_watchdog_sla(&receipt)")
            .map(|offset| watchdog_positive + offset)
            .expect("Track-1 exact watchdog SLA gate");
        let immediate_live_identity = run[watchdog_sla..]
            .find("let immediate_live_identity_result: Result<S19kLiveIdentityReceipt>")
            .map(|offset| watchdog_sla + offset)
            .expect("fresh process-independent identity immediately before route/signal");
        let pre_signal_revalidate = run[immediate_live_identity..]
            .find("expected.require_exact_tree_at(Path::new(\"/proc\"))?")
            .map(|offset| immediate_live_identity + offset)
            .expect("pre-signal exact supervisor+child tree revalidation");
        let pre_signal_gpio = run[pre_signal_revalidate..]
            .find("read_s19k_track1_psu_engaged_checked()?")
            .map(|offset| pre_signal_revalidate + offset)
            .expect("pre-signal checked GPIO437 engagement");
        let route_claim = run[pre_signal_gpio..]
            .find("SerialRouteDomains::claim_s19k_track1(")
            .map(|offset| pre_signal_gpio + offset)
            .expect("S19k Track-1 route claim after watchdog SLA");
        let watchdog_retained = run[route_claim..]
            .find("nopic_watchdog = Some(watchdog_owner);")
            .map(|offset| route_claim + offset)
            .expect("Track-1 retained watchdog owner");
        let inherited = run[watchdog_retained..]
            .find(".assume_inherited_rails()")
            .map(|offset| watchdog_retained + offset)
            .expect("Track-1 inherited-rail closeout arm");
        let supervisor_kill = run[inherited..]
            .find(".sigkill_and_wait(")
            .map(|offset| inherited + offset)
            .expect("J3-bound exact supervisor-first kill+exit wait");
        let child_kill = run[supervisor_kill + 1..]
            .find(".sigkill_and_wait(")
            .map(|offset| supervisor_kill + 1 + offset)
            .expect("J3-bound exact child-second kill+exit wait");
        let stock_absence = run[child_kill..]
            .find("s19k_require_no_live_stock_custody_processes_at")
            .map(|offset| child_kill + offset)
            .expect("global stock-process absence gate");
        let actor_activation = run[stock_absence..]
            .find("runtime_threads.activate_s19k_track1(actor_owner)?")
            .map(|offset| stock_absence + offset)
            .expect("Track-1 actor activation after stock absence");
        assert!(
            handoff_start < first_live_identity
                && first_live_identity < j3_freeze
                && j3_freeze < signal_lease
                && signal_lease < watchdog_start
                && watchdog_start < watchdog_positive
                && watchdog_positive < watchdog_sla
                && watchdog_sla < immediate_live_identity
                && immediate_live_identity < pre_signal_revalidate
                && pre_signal_revalidate < pre_signal_gpio
                && watchdog_sla < route_claim
                && route_claim < watchdog_retained
                && watchdog_retained < inherited
                && inherited < supervisor_kill
                && supervisor_kill < child_kill
                && child_kill < stock_absence
                && stock_absence < actor_activation
                && actor_activation < first_track1_uart_open
        );
        let sla_refusal = &run[watchdog_sla..route_claim];
        assert!(sla_refusal.contains("close_s19k_track1_watchdog_never_handoff"));
        assert!(sla_refusal.contains("expected.require_exact_tree_at(Path::new(\"/proc\"))"));
        assert!(sla_refusal.contains("runner custody MUST remain"));
        assert!(!sla_refusal.contains("sigkill_and_wait"));
        assert!(!sla_refusal.contains("assume_inherited_rails"));
        assert!(run.contains("read_s19k_track1_psu_engaged_checked"));
        assert!(run.contains("lease_kind = bosminer_signal_lease.lease_kind()"));
        assert!(run.contains("supervisor-first/child-second J3-confirmed stock exit"));
        assert!(run.contains("live_identity_sha256 = %immediate_live_identity.sha256"));
        assert!(run.contains("live_identity_profile = immediate_live_identity.profile.as_str()"));
        assert!(run.contains(
            "live_identity_physical_addresses = %immediate_live_identity.physical_addresses"
        ));
        assert!(run.contains("live_identity_board_names = %immediate_live_identity.board_names"));
        assert!(!run.contains("pidfd-confirmed bosminer exit"));
        assert!(production.contains("legacy_exact_identity_experimental"));
        assert!(production.contains("libc::SYS_pidfd_open"));
        assert!(production.contains("libc::SYS_pidfd_send_signal"));
        assert!(production.contains("libc::kill(expected.pid, libc::SIGKILL)"));
        assert!(run.contains("serial_actor_topology == SerialActorTopology::ExactS19kTrack1"));
        assert!(production.contains("impl Drop for S19kTrack1RunCloseoutGuard"));
        assert!(run.contains("if terminal_result.is_ok()"));
        assert!(run.contains("guard.disarm();"));

        // Live 2026-08-20 reached the GPIO437 preflight after the signal
        // boundary. Its ordinary `?` unwound through the Drop guard, which
        // performed reset+cut but left the watchdog command channel without a
        // typed closeout. Pin both post-handoff fallible regions inside an
        // explicit Result funnel whose error arm calls the exact closeout.
        let post_handoff_result = run
            .find("let s19k_track1_post_handoff_result: Result<()> = async {")
            .expect("post-handoff result funnel");
        let post_handoff_error = run[post_handoff_result..]
            .find("if let Err(primary) = s19k_track1_post_handoff_result")
            .map(|offset| post_handoff_result + offset)
            .expect("post-handoff typed error arm");
        let multi_uart_result = run[post_handoff_error..]
            .find("let s19k_track1_multi_uart_result: Result<SerialWorkTransport> = async {")
            .map(|offset| post_handoff_error + offset)
            .expect("Track-1 multi-UART result funnel");
        let multi_uart_error = run[multi_uart_result..]
            .find("match s19k_track1_multi_uart_result")
            .map(|offset| multi_uart_result + offset)
            .expect("Track-1 multi-UART typed error arm");
        let multi_uart_end = run[multi_uart_error..]
            .find("} else if passthrough {")
            .map(|offset| multi_uart_error + offset)
            .expect("end of Track-1 multi-UART error funnel");
        let post_handoff = &run[post_handoff_result..post_handoff_error];
        let post_handoff_closeout = &run[post_handoff_error..multi_uart_result];
        let multi_uart = &run[multi_uart_result..multi_uart_error];
        let multi_uart_closeout = &run[multi_uart_error..multi_uart_end];
        assert!(inherited < post_handoff_result);
        assert!(post_handoff.contains("S19kStockProcessRole::Supervisor"));
        assert!(post_handoff.contains("S19kStockProcessRole::Bosminer"));
        assert_eq!(post_handoff.matches(".sigkill_and_wait(").count(), 2);
        assert!(post_handoff.contains("read_s19k_track1_psu_engaged_checked()?"));
        assert!(post_handoff_closeout.contains("closeout_s19k_track1_failure("));
        assert!(post_handoff_closeout.contains("terminal_safe_off_error(primary, receipt)"));
        assert!(multi_uart.contains("SerialChainBackend::open_passthrough_bm1366"));
        assert!(multi_uart.contains("admit_s19k_passthrough_work_tx(silence_class, gpio437)"));
        assert!(multi_uart.contains("admit_s19k_track1_multi_execution("));
        assert!(multi_uart_closeout.contains("closeout_s19k_track1_failure("));
        assert!(multi_uart_closeout.contains("terminal_safe_off_error(primary, receipt)"));

        let recovery_start = production
            .find("pub(crate) fn s19k_track1_recovery_safeoff(")
            .expect("Track-1 recovery entrypoint");
        let recovery_end = production[recovery_start..]
            .find("fn s19k_track1_terminal_safeoff()")
            .map(|offset| recovery_start + offset)
            .expect("Track-1 recovery boundary");
        let recovery = &production[recovery_start..recovery_end];
        assert!(
            recovery
                .find("s19k_capture_and_require_bound_live_identity()")
                .unwrap()
                < recovery
                    .find("s19k_track1_reset_then_cut_checked()")
                    .unwrap()
        );
        let receipt_fields = [
            "live_identity_sha256={}",
            "live_identity_profile={}",
            "live_identity_model_sha256={}",
            "live_identity_board_count={}",
            "live_identity_physical_addresses={}",
            "live_identity_board_names={}",
            "live_identity_eeprom={}",
            "resets={}:0,{}:0,{}:0",
            "psu={}:1",
        ];
        let mut previous = 0usize;
        for field in receipt_fields {
            assert!(
                recovery.contains(field),
                "missing recovery receipt field {field}"
            );
            let position = recovery.find(field).unwrap();
            assert!(
                position >= previous,
                "misordered recovery receipt field {field}"
            );
            previous = position;
        }
    }

