    #[test]
    fn bm1366_native_post_baud_admission_requires_exact_host_pair_and_fresh_geometry() {
        let body = |address| {
            let frame = dcentrald_common::s19k_bm1366_uart_rx::bm1366_chip_address_uart(address);
            frame[2..].to_vec()
        };
        let bodies = vec![body(0), body(2)];
        let admitted = Bm1366NativePostBaudAdmission::from_response_window(
            115_200,
            BOSMINER_BM1366_AML_HOST_BAUD,
            &bodies,
            2,
            2,
            2,
        )
        .expect("exact stock host pair plus fresh CRC-valid geometry must admit");
        assert_eq!(admitted.host_baud, BOSMINER_BM1366_AML_HOST_BAUD);
        assert_eq!(admitted.coverage.addresses, vec![0, 2]);

        assert!(Bm1366NativePostBaudAdmission::from_response_window(
            115_200,
            BOSMINER_BM1366_AML_HOST_BAUD,
            &[],
            2,
            2,
            2,
        )
        .is_err());
        assert!(Bm1366NativePostBaudAdmission::from_response_window(
            115_200, 115_200, &bodies, 2, 2, 2,
        )
        .is_err());
        assert!(Bm1366NativePostBaudAdmission::from_response_window(
            1_000_000,
            BOSMINER_BM1366_AML_HOST_BAUD,
            &bodies,
            2,
            2,
            2,
        )
        .is_err());
    }

