    #[tokio::test]
    async fn s19k_track1_route_is_distinct_fenced_and_api_denied() {
        let mut watchdog = SafetyWatchdogOwner::inert_for_pre_hardware_test();
        let mut domains = SerialRouteDomains::claim_s19k_track1(
            &mut watchdog,
            admit_s19k_track1_watchdog_sla(&WatchdogArmReceipt {
                requested_timeout_s: 30,
                effective_timeout_s: 30,
                kick_interval_s: 5,
            })
            .unwrap(),
        )
        .unwrap();
        let api_gate = domains.management_api_gate().unwrap();
        assert!(
            api_gate.try_acquire().is_err(),
            "Track-1 has no typed voltage/GPIO API owner and must expose a pending denial gate"
        );
        let execution = domains
            .admit_s19k_track1_multi_execution(
                &["/dev/ttyS1", "/dev/ttyS2", "/dev/ttyS3"],
                &[true, true, false],
                &[false, false, false],
            )
            .unwrap();
        drop(execution);
        let (serial, api) = domains.begin_closeout().unwrap().split_for_closeout();
        let serial = serial
            .complete(Duration::from_millis(100), "Track-1 route test")
            .await
            .unwrap();
        let api = api
            .complete(Duration::from_millis(100), "Track-1 API test")
            .await
            .unwrap();
        assert!(serial.is_s19k_track1());
        assert!(api.is_s19k_track1());
        assert!(serial.was_promoted_to_execution());
        assert!(api.was_never_opened());

        let mut invalid_watchdog = SafetyWatchdogOwner::inert_for_pre_hardware_test();
        let mut invalid = SerialRouteDomains::claim_s19k_track1(
            &mut invalid_watchdog,
            admit_s19k_track1_watchdog_sla(&WatchdogArmReceipt {
                requested_timeout_s: 30,
                effective_timeout_s: 30,
                kick_interval_s: 5,
            })
            .unwrap(),
        )
        .unwrap();
        assert!(invalid
            .admit_s19k_track1_multi_execution(
                &["/dev/ttyS1", "/dev/ttyS2", "/dev/ttyS3"],
                &[true, true, true],
                &[false, false, false],
            )
            .is_err());
    }

    #[test]
    fn s19k_share_result_sidecar_consumes_exact_payload_once() {
        let sidecar = Arc::new(S19kSubmittedShareOriginSidecar::default());
        let share = dcentrald_stratum::types::ValidShare {
            work_generation: dcentrald_stratum::WorkGeneration { session: 4, job: 9 },
            worker_name: "worker".to_string(),
            job_id: "pool-job".to_string(),
            extranonce2: "00000001".to_string(),
            ntime: "68a40000".to_string(),
            nonce: "12345678".to_string(),
            version_bits: Some("00002000".to_string()),
            version: 0x2000_0000,
            achieved_difficulty: Some(8192.0),
        };
        s19k_record_submitted_share_origin(
            &sidecar,
            S19kSubmittedShareKey::from_share(&share),
            S19kSubmittedShareOrigin {
                path: "/dev/ttyS2".to_string(),
                attribution: "Raw".to_string(),
                physical_chip_core: Some((2, 1, 7)),
            },
        );
        let mut wrong = share.clone();
        wrong.nonce = "12345679".to_string();
        assert!(s19k_take_submitted_share_origin_for_result(&sidecar, &wrong).is_none());
        let origin = s19k_take_submitted_share_origin_for_result(&sidecar, &share).unwrap();
        assert_eq!(origin.path, "/dev/ttyS2");
        assert_eq!(origin.physical_chip_core, Some((2, 1, 7)));
        assert!(s19k_take_submitted_share_origin_for_result(&sidecar, &share).is_none());
        assert_eq!(sidecar.evicted.load(Ordering::Acquire), 0);
        assert_eq!(sidecar.unmatched_results.load(Ordering::Acquire), 2);

        // Submission-channel failure cleanup is not a pool result and must
        // not increment the unmatched-result fact.
        s19k_record_submitted_share_origin(
            &sidecar,
            S19kSubmittedShareKey::from_share(&share),
            S19kSubmittedShareOrigin {
                path: "/dev/ttyS2".to_string(),
                attribution: "Raw".to_string(),
                physical_chip_core: None,
            },
        );
        assert!(s19k_remove_submitted_share_origin(&sidecar, &share).is_some());
        assert_eq!(sidecar.unmatched_results.load(Ordering::Acquire), 2);
        s19k_note_share_result_missing_meta(&sidecar);
        assert_eq!(sidecar.unmatched_results.load(Ordering::Acquire), 3);
    }

    #[test]
    fn s19k_share_result_sidecar_bounds_history_and_counts_eviction() {
        let sidecar = S19kSubmittedShareOriginSidecar::default();
        let template = dcentrald_stratum::types::ValidShare {
            work_generation: dcentrald_stratum::WorkGeneration { session: 8, job: 1 },
            worker_name: "worker".to_string(),
            job_id: "bounded-job".to_string(),
            extranonce2: "00000001".to_string(),
            ntime: "68a40000".to_string(),
            nonce: "00000000".to_string(),
            version_bits: None,
            version: 0x2000_0000,
            achieved_difficulty: Some(1.0),
        };
        for nonce in 0..=S19K_SUBMITTED_SHARE_ORIGIN_CAPACITY {
            let mut share = template.clone();
            share.nonce = format!("{nonce:08x}");
            s19k_record_submitted_share_origin(
                &sidecar,
                S19kSubmittedShareKey::from_share(&share),
                S19kSubmittedShareOrigin {
                    path: "/dev/ttyS1".to_string(),
                    attribution: "Shift3".to_string(),
                    physical_chip_core: None,
                },
            );
        }
        assert_eq!(
            sidecar.entries.lock().unwrap().len(),
            S19K_SUBMITTED_SHARE_ORIGIN_CAPACITY
        );
        assert_eq!(sidecar.evicted.load(Ordering::Acquire), 1);

        assert!(s19k_take_submitted_share_origin_for_result(&sidecar, &template).is_none());
        assert_eq!(sidecar.unmatched_results.load(Ordering::Acquire), 1);
        let mut newest = template;
        newest.nonce = format!("{:08x}", S19K_SUBMITTED_SHARE_ORIGIN_CAPACITY);
        assert!(s19k_take_submitted_share_origin_for_result(&sidecar, &newest).is_some());
    }

    fn run_fake_serial_actor(
        backend: FakeSerialActorBackend,
        work: Vec<Vec<u8>>,
        event_tx: mpsc::Sender<SerialActorEvent>,
        shutdown: CancellationToken,
        exact_am2_bm1362: bool,
    ) -> (SerialActorExit, u64, u64) {
        run_fake_serial_actor_queued(
            backend,
            work.into_iter().map(SerialQueuedTx::control).collect(),
            event_tx,
            shutdown,
            exact_am2_bm1362,
        )
    }

    fn run_fake_serial_actor_queued(
        backend: FakeSerialActorBackend,
        work: Vec<SerialQueuedTx>,
        event_tx: mpsc::Sender<SerialActorEvent>,
        shutdown: CancellationToken,
        exact_am2_bm1362: bool,
    ) -> (SerialActorExit, u64, u64) {
        let progress = Arc::new(AtomicU64::new(0));
        let committed = Arc::new(AtomicU64::new(0));
        let exit = run_serial_io_actor(
            backend,
            Arc::new(Mutex::new(work.into())),
            event_tx,
            shutdown,
            Arc::clone(&progress),
            Arc::clone(&committed),
            exact_am2_bm1362,
            false,
            1,
            true,
            DEFAULT_SERIAL_RX_FOLLOWUP_DRAIN,
            None,
            None,
            Arc::new(AtomicU64::new(0)),
            Arc::new(AtomicU8::new(0xFF)),
            None,
        );
        (
            exit,
            progress.load(Ordering::Acquire),
            committed.load(Ordering::Acquire),
        )
    }

    fn fake_s19k_pending_dispatch() -> S19kPendingDispatch {
        S19kPendingDispatch {
            ownership_epoch: 7,
            commit_sequence: 0,
            wrap_idx: 3,
            wire: vec![0x55, 0xAA, 0x21, 0x36],
            entry: WorkEntry {
                generation: 11,
                work_generation: dcentrald_stratum::WorkGeneration::UNTRACKED,
                job_id: "fake-pool-job".to_string(),
                extranonce2: "00000000".to_string(),
                ntime: 0,
                nbits: 0,
                version: 0,
                version_mask: 0,
                share_target: [0xFF; 32],
                prev_block_hash: [0; 32],
                merkle_root: [0; 32],
            },
        }
    }

    #[test]
    fn serial_actor_distinguishes_empty_poll_liveness_from_committed_work() {
        let shutdown = CancellationToken::new();
        let mut backend = FakeSerialActorBackend::new(Vec::new(), shutdown.clone());
        backend.cancel_after_reads = Some(3);
        let (nonce_tx, _nonce_rx) = mpsc::channel(4);
        let (exit, progress, committed) =
            run_fake_serial_actor(backend, Vec::new(), nonce_tx, shutdown, true);
        assert!(matches!(exit, SerialActorExit::Cancelled));
        assert_eq!(progress, 3);
        assert_eq!(committed, 0);
    }

    #[test]
    fn serial_actor_mints_commit_evidence_only_after_successful_tx() {
        let shutdown = CancellationToken::new();
        let mut backend = FakeSerialActorBackend::new(Vec::new(), shutdown.clone());
        backend.cancel_after_send = true;
        let (nonce_tx, _nonce_rx) = mpsc::channel(4);
        let (exit, progress, committed) =
            run_fake_serial_actor(backend, vec![vec![0x21, 0x56]], nonce_tx, shutdown, true);
        assert!(matches!(exit, SerialActorExit::Cancelled));
        assert!(progress >= 1);
        assert_eq!(committed, 1);

        let shutdown = CancellationToken::new();
        let mut failed = FakeSerialActorBackend::new(Vec::new(), shutdown.clone());
        failed.fail_send = true;
        let (nonce_tx, _nonce_rx) = mpsc::channel(4);
        let (exit, _, committed) =
            run_fake_serial_actor(failed, vec![vec![0x21, 0x56]], nonce_tx, shutdown, true);
        let SerialActorExit::Failed(reason) = exit else {
            panic!("failed TX must terminate the serial actor");
        };
        assert!(reason.contains("serial work send failed"));
        assert!(reason.contains("injected serial TX failure"));
        assert_eq!(committed, 0);
    }

    #[test]
    fn s19k_no_work_actor_refuses_any_queued_uart_transmit() {
        let shutdown = CancellationToken::new();
        let backend = FakeSerialActorBackend::new(Vec::new(), shutdown.clone());
        let (event_tx, _event_rx) = mpsc::channel(4);
        let exit = run_serial_io_actor(
            backend,
            Arc::new(Mutex::new(VecDeque::from([SerialQueuedTx::s19k_work(
                vec![0x21, 0x36],
                fake_s19k_pending_dispatch(),
            )]))),
            event_tx,
            shutdown,
            Arc::new(AtomicU64::new(0)),
            Arc::new(AtomicU64::new(0)),
            false,
            true,
            1,
            true,
            DEFAULT_SERIAL_RX_FOLLOWUP_DRAIN,
            None,
            None,
            Arc::new(AtomicU64::new(0)),
            Arc::new(AtomicU8::new(0xFF)),
            None,
        );
        assert!(matches!(
            exit,
            SerialActorExit::Failed(reason)
                if reason.contains("handoff-no-work invariant refused a queued UART transmit")
        ));
    }

    #[test]
    fn s19k_no_work_cli_must_match_the_immutable_runtime_binding() {
        for (deploy_mode, cli_no_work) in [
            ("mining-on-passthrough", false),
            ("install-custody-safeoff", false),
            ("handoff-no-work", true),
            ("bounded-work-proof", false),
            ("endurance-work-proof", false),
        ] {
            let binding = S19kTrack1RuntimeBinding {
                active_sha256: "a".repeat(64),
                active_bytes: 1,
                fields: BTreeMap::from([("deploy_mode".to_owned(), deploy_mode.to_owned())]),
            };
            assert!(binding.require_no_work_policy(cli_no_work).is_ok());
            let error = binding
                .require_no_work_policy(!cli_no_work)
                .expect_err("a mismatched CLI no-work flag must fail closed");
            assert!(error
                .to_string()
                .contains("does not match immutable runtime_active deploy_mode"));
        }

        let unsupported = S19kTrack1RuntimeBinding {
            active_sha256: "b".repeat(64),
            active_bytes: 1,
            fields: BTreeMap::from([("deploy_mode".to_owned(), "stage-only".to_owned())]),
        };
        assert!(unsupported.require_no_work_policy(false).is_err());
    }

