    #[test]
    fn s19k_bounded_work_completion_requires_every_required_uart() {
        let required = ["/dev/ttyS1", "/dev/ttyS2"];
        let mut accepted = BTreeSet::new();
        assert!(!s19k_bounded_work_proof_paths_complete(
            &required, &accepted
        ));
        accepted.insert("/dev/ttyS1".to_owned());
        assert!(!s19k_bounded_work_proof_paths_complete(
            &required, &accepted
        ));
        accepted.insert("/dev/ttyS2".to_owned());
        assert!(s19k_bounded_work_proof_paths_complete(&required, &accepted));
        assert!(!s19k_bounded_work_proof_paths_complete(&[], &accepted));
    }

