    #[test]
    fn s19k_endurance_segments_use_interval_not_lifetime_hashrate() {
        let source = include_str!("serial_mining.rs");
        let minute_branch = source
            .split_once("s19k_endurance_minute_timer.tick()")
            .expect("endurance minute timer")
            .1
            .split_once("_ = self.shutdown.cancelled()")
            .expect("endurance minute branch boundary")
            .0;
        assert!(minute_branch.contains("interval_nonces as f64"));
        assert!(minute_branch.contains("interval_elapsed.as_secs_f64()"));
        assert!(minute_branch.contains("s19k_endurance_last_sealed_nonces = total_nonces"));
        assert!(!minute_branch.contains("total_nonces as f64"));
        assert!(!minute_branch.contains("start_time.elapsed().as_secs_f64()"));
    }

