    #[test]
    fn s19k_actor_does_not_publish_failed_tx_and_receipts_partial_commit() {
        let shutdown = CancellationToken::new();
        let mut failed = FakeSerialActorBackend::new(Vec::new(), shutdown.clone());
        failed.fail_send = true;
        let (event_tx, mut event_rx) = mpsc::channel(4);
        let failed_queued =
            SerialQueuedTx::s19k_work(vec![0x21, 0x36], fake_s19k_pending_dispatch());
        let (exit, _, _) =
            run_fake_serial_actor_queued(failed, vec![failed_queued], event_tx, shutdown, false);
        assert!(matches!(exit, SerialActorExit::Failed(_)));
        assert!(
            matches!(
                event_rx.try_recv(),
                Err(mpsc::error::TryRecvError::Disconnected)
            ),
            "a zero-path TX failure must not publish ownership"
        );

        let shutdown = CancellationToken::new();
        let mut partial = FakeSerialActorBackend::new(Vec::new(), shutdown.clone());
        partial.partial_send = true;
        let (event_tx, mut event_rx) = mpsc::channel(4);
        let partial_queued =
            SerialQueuedTx::s19k_work(vec![0x21, 0x36], fake_s19k_pending_dispatch());
        let (exit, _, _) =
            run_fake_serial_actor_queued(partial, vec![partial_queued], event_tx, shutdown, false);
        assert!(matches!(exit, SerialActorExit::Failed(reason) if reason.contains("partial")));
        let SerialActorEvent::S19kWorkCommitted(commit) = event_rx
            .try_recv()
            .expect("partial physical commit receipt")
        else {
            panic!("partial physical commit must retain per-path ownership evidence");
        };
        assert!(commit.receipt.any_committed());
        assert!(!commit.receipt.all_required_committed());
        assert_eq!(commit.receipt.paths.len(), 2);
        assert!(commit.receipt.paths[0].committed);
        assert!(!commit.receipt.paths[1].committed);
    }

    #[test]
    fn s19k_watchdog_requires_recent_history_admitted_nonce_on_every_active_tx_path() {
        let grace = Duration::from_secs(90);
        let mut s1 = S19kSerialEndpointRuntime::opened("/dev/ttyS1", 77, true, true);
        let mut s2 = S19kSerialEndpointRuntime::opened("/dev/ttyS2", 77, true, true);
        let mut s3 = S19kSerialEndpointRuntime::opened("/dev/ttyS3", 0, false, false);
        assert!(s19k_all_active_tx_paths_have_recent_valid_nonce(
            &[s1.clone(), s2.clone(), s3.clone()],
            Duration::from_secs(89),
            grace,
        ));
        assert!(!s19k_all_active_tx_paths_have_recent_valid_nonce(
            &[s1.clone(), s2.clone(), s3.clone()],
            Duration::from_secs(90),
            grace,
        ));
        s1.last_valid_job_nonce_at = Some(Duration::from_secs(20));
        s2.last_valid_job_nonce_at = Some(Duration::from_secs(40));
        assert!(s19k_all_active_tx_paths_have_recent_valid_nonce(
            &[s1.clone(), s2.clone(), s3.clone()],
            Duration::from_secs(100),
            grace,
        ));
        s2.last_valid_job_nonce_at = None;
        s3.last_valid_job_nonce_at = Some(Duration::from_secs(99));
        assert!(
            !s19k_all_active_tx_paths_have_recent_valid_nonce(
                &[s1.clone(), s2, s3],
                Duration::from_secs(100),
                grace,
            ),
            "discover-only ttyS3 cannot substitute for a silent active TX path"
        );
        s1.last_valid_job_nonce_at = Some(Duration::from_secs(9));
        assert!(!s19k_all_active_tx_paths_have_recent_valid_nonce(
            &[s1],
            Duration::from_secs(100),
            grace,
        ));
        assert!(!s19k_all_active_tx_paths_have_recent_valid_nonce(
            &[],
            Duration::from_secs(1),
            grace,
        ));

        let source = include_str!("serial_mining.rs");
        let nonce_admission = source
            .split_once("let s19k_ticket_valid = if is_bm1366")
            .expect("S19k ticket-valid watchdog gate")
            .1
            .split_once("// Full 80-byte header validation.")
            .expect("S19k ticket-valid watchdog gate boundary")
            .0;
        assert!(nonce_admission.contains("&hardware_ticket_target"));
        assert!(nonce_admission.contains("else if is_bm1366 && s19k_ticket_valid"));
        assert!(source.contains("difficulty_to_target(hw_difficulty as f64)"));
    }

