    #[test]
    fn s19k_track1_exact_route_assigns_and_publishes_coverage_before_multi_handover() {
        let source = include_str!("serial_mining.rs");
        let arm_start = source
            .find("let serial = if braiins_bm1366_passthrough_handoff {")
            .expect("track-1 transport arm anchor");
        let arm_window = &source[arm_start..arm_start + 80_000];
        let admit = arm_window
            .find(".admit_s19k_track1_multi_execution(")
            .expect("track-1 arm must admit exact multi execution first");
        let ladder = arm_window
            .find("s19k_aml_linear_addresses()")
            .expect("track-1 arm must run the S19k AML address ladder");
        let coverage = arm_window
            .find("ValidatedSerialAssignedGeometry::from_window")
            .expect("track-1 arm must certify the assigned coverage window");
        let publish = arm_window
            .find("validated_serial_geometry = Some(")
            .expect("track-1 arm must publish the assigned geometry");
        let multi = arm_window
            .find("SerialWorkTransport::Multi(MultiTtyTransport")
            .expect("track-1 arm must hand over the multi transport");
        assert!(
            admit < ladder && ladder < coverage && coverage < publish && publish < multi,
            "track-1 arm ordering: admit < ladder < coverage < publish < multi"
        );
        let gate = source
            .find("reached work transport without execution authority")
            .expect("transport authority gate");
        let guard = source[..gate]
            .rfind("SerialActorTopology::ExactS19kTrack1) => {")
            .expect("gate must carry an ExactS19kTrack1-guarded Multi acceptance arm");
        assert!(guard < gate);
    }

    #[test]
    fn s19k_track1_coverage_probe_reads_immediately_and_retries_exact_plan() {
        let source = include_str!("serial_mining.rs");
        let probe = source
            .split_once("Track-1 coverage held no exact-plan window across retries")
            .expect("track-1 coverage probe retry fence")
            .0;
        let probe_start = probe
            .rfind("for attempt in 0..3")
            .expect("track-1 coverage retry loop");
        let probe_window = &probe[probe_start..];
        let get_address = probe_window
            .find("send_get_address_bm1397plus")
            .expect("track-1 probe must send GetAddress inside the retry loop");
        let read = probe_window
            .find("read_all_responses")
            .expect("track-1 probe must read responses inside the retry loop");
        assert!(
            get_address < read,
            "track-1 probe must read after the GetAddress TX"
        );
        assert!(
            !probe_window[get_address..read].contains("thread::sleep"),
            "track-1 probe must not sleep between the GetAddress TX and the \
             read: the S19k discovery capture proves all 77 frames only when \
             the reader is spinning before the burst arrives"
        );
        let exact_plan = probe_window
            .find("ValidatedSerialAssignedGeometry::from_window")
            .expect("track-1 probe must certify the exact plan inside the retry loop");
        assert!(
            read < exact_plan,
            "track-1 probe must certify the exact plan after each read, so a \
             unique-address subset (a valid window shape) still retries"
        );
    }

    #[test]
    fn s19k_track1_address_ladder_paces_each_set_address_step_like_the_stock_jig() {
        let source = include_str!("serial_mining.rs");
        let ladder = source
            .split_once("The ladder leaves set-address ACK/echo traffic on the")
            .expect("track-1 ladder-to-coverage boundary")
            .0;
        let loop_start = ladder
            .rfind("for address in")
            .expect("track-1 SetAddress ladder loop");
        let ladder_window = &ladder[loop_start..];
        let send = ladder_window
            .find("send_set_address_bm1397plus(address)")
            .expect("ladder must send one SetAddress per plan address");
        let pace = ladder_window
            .find("S19K_TRACK1_LADDER_STEP_MS")
            .expect("ladder must pace each SetAddress step");
        assert!(
            send < pace,
            "every SetAddress TX must be followed by the stock-cadence dwell: \
             Bitmain's software ladders never stream the ladder back-to-back \
             (S17 BM1397 jig usleep(2000) per step; S19k Pro BM1366 jig 10 ms \
             per step), and the live zero-gap burst deterministically left \
             mid-chain plan addresses unlatched"
        );
    }

    #[test]
    fn s19k_track1_coverage_retry_reenrolls_unclaimed_plan_addresses_before_next_probe() {
        let source = include_str!("serial_mining.rs");
        let probe = source
            .split_once("Track-1 coverage held no exact-plan window across retries")
            .expect("track-1 coverage probe retry fence")
            .0;
        let probe_start = probe
            .rfind("for attempt in 0..3")
            .expect("track-1 coverage retry loop");
        let probe_window = &probe[probe_start..];
        let exact_plan = probe_window
            .find("ValidatedSerialAssignedGeometry::from_window")
            .expect("track-1 probe must certify the exact plan inside the retry loop");
        let diff = probe_window
            .find("s19k_missing_plan_addresses")
            .expect("track-1 probe must diff observed responders against the plan");
        let reenroll = probe_window[diff..]
            .find("Track-1 re-enroll SetAddress")
            .map(|offset| diff + offset)
            .expect("track-1 probe must re-send SetAddress for unclaimed plan addresses");
        let pace = probe_window[reenroll..]
            .find("S19K_TRACK1_LADDER_STEP_MS")
            .map(|offset| reenroll + offset)
            .expect("track-1 re-enrollment must keep the paced ladder cadence");
        assert!(
            exact_plan < diff && diff < reenroll && reenroll < pace,
            "track-1 re-enrollment ordering: certify < diff < re-enroll TX < pace"
        );
        let expected_plan = probe
            .find("let expected_plan: Vec<u8>")
            .expect("track-1 coverage block must derive the plan it re-enrolls against");
        assert!(
            expected_plan < probe_start,
            "the re-enrollment plan must be derived before the retry loop, not \
             per attempt"
        );
    }

    #[test]
    fn s19k_missing_plan_addresses_diffs_and_refuses_off_plan_windows() {
        let plan = dcentrald_common::s19k_bm1366_wire_b::s19k_aml_linear_addresses();
        // Live attempt-7 window: 55 unique on-plan responders (56 frames with
        // one duplicate). The diff must be exactly the 22 unclaimed addresses.
        let observed_attempt7 = [
            0x00, 0x02, 0x04, 0x06, 0x08, 0x0A, 0x0E, 0x10, 0x12, 0x16, 0x1A, 0x1C, 0x1E, 0x20,
            0x22, 0x24, 0x28, 0x2C, 0x30, 0x32, 0x34, 0x36, 0x38, 0x3A, 0x3E, 0x42, 0x46, 0x4E,
            0x50, 0x52, 0x56, 0x5A, 0x5E, 0x60, 0x62, 0x64, 0x66, 0x68, 0x6A, 0x6E, 0x72, 0x76,
            0x78, 0x7A, 0x7C, 0x7E, 0x80, 0x82, 0x86, 0x88, 0x8A, 0x8E, 0x94, 0x96, 0x98,
        ];
        let missing = s19k_missing_plan_addresses(&plan, &observed_attempt7)
            .expect("on-plan subset window must be repairable");
        assert_eq!(
            missing,
            vec![
                0x0C, 0x14, 0x18, 0x26, 0x2A, 0x2E, 0x3C, 0x40, 0x44, 0x48, 0x4A, 0x4C, 0x54, 0x58,
                0x5C, 0x6C, 0x70, 0x74, 0x84, 0x8C, 0x90, 0x92
            ],
            "the re-enrollment diff must reproduce the live attempt-7 gap exactly"
        );
        // A complete window re-enrolls nothing.
        assert_eq!(
            s19k_missing_plan_addresses(&plan, &plan),
            Some(Vec::new()),
            "an exact-plan window must not trigger any re-enroll TX"
        );
        // Duplicated plan addresses still only fill the unclaimed slots (the
        // duplicate itself is a from_window failure the gate reports).
        let duplicated = [&observed_attempt7[..], &[observed_attempt7[0]][..]].concat();
        assert_eq!(
            s19k_missing_plan_addresses(&plan, &duplicated),
            Some(missing.clone()),
            "repeated responders are frames, not extra chips: the fill set is unchanged"
        );
        // Off-plan responders (shifted assignment) must suppress the fill.
        assert_eq!(
            s19k_missing_plan_addresses(&plan, &[0x9A]),
            None,
            "an off-plan responder set cannot be repaired by blind SetAddress fills"
        );
        // The runtime's derived plan must equal the shared SSOT plan.
        let derived = (0..77u8)
            .map(|index| {
                (u16::from(index)
                    * u16::from(dcentrald_common::s19k_bm1366_wire_b::S19K_AML_ADDR_INTERVAL))
                    as u8
            })
            .collect::<Vec<_>>();
        assert_eq!(
            derived, plan,
            "the re-enrollment plan must match s19k_aml_linear_addresses exactly"
        );
    }

    /// 2026-08-29 shared-contract rebase pin: the settled Track-1 path now
    /// CONSUMES `dcentrald-common`'s transport-neutral serial-chain contracts
    /// instead of carrying private duplicates — the re-enrollment diff
    /// delegates to `re_enrollment_addresses`, and both assigned-geometry
    /// construction sites mint the shared `ChainCoverageCertificate` on their
    /// accept paths. Behavior-preserving by construction: the delegation is
    /// the same subset/difference function, and the certificate (order-
    /// insensitive exact coverage) accepts every ordered exact-plan window
    /// the stricter from_window check already admitted.
    #[test]
    fn track1_reenrollment_and_coverage_back_onto_the_shared_serial_chain_contract() {
        let plan = [0x00u8, 0x02, 0x04, 0x06];
        // The delegation is behavior-identical on repairable, complete,
        // duplicated, and off-plan windows.
        for observed in [
            vec![0x00, 0x04],
            vec![0x00, 0x02, 0x04, 0x06],
            vec![0x00, 0x00, 0x06],
            vec![0x00, 0x05],
        ] {
            assert_eq!(
                s19k_missing_plan_addresses(&plan, &observed),
                dcentrald_common::serial_chain_proof::re_enrollment_addresses(&plan, &observed),
                "delegated diff must agree with the shared contract on {observed:02X?}"
            );
        }
        // Structural: exactly one delegation and exactly two certificate
        // mints (Track-1 from_window + the native BM1366 final geometry) —
        // the settled path cannot silently regrow a private copy.
        let source = include_str!("serial_mining.rs");
        let production = source
            .split("\n#[cfg(test)]\nmod tests")
            .next()
            .expect("production source");
        assert_eq!(
            production
                .matches("serial_chain_proof::re_enrollment_addresses")
                .count(),
            1,
            "the re-enrollment diff must delegate to the shared contract exactly once"
        );
        assert_eq!(
            production
                .matches("ChainCoverageCertificate::certify")
                .count(),
            2,
            "both assigned-geometry accept paths must mint the shared certificate"
        );
        // The shared certificate accepts what from_window accepts: an
        // ordered exact-plan observation certifies cleanly.
        dcentrald_common::serial_chain_proof::ChainCoverageCertificate::certify(
            &plan,
            &[0x00, 0x02, 0x04, 0x06],
        )
        .expect("exact-plan observation must certify");
    }

    /// The settled Track-1 ladder/probe cadence must be representable in the
    /// shared `PacedEnumerationPolicy` (step = stock-jig 10 ms ladder pace,
    /// settle = the probe's pre-read 50 ms, response window = the probe's
    /// 1000 ms read, attempts = the probe's three retries) — pinning that the
    /// shared policy can express the live-proven cadence without changing it.
    #[test]
    fn track1_ladder_cadence_is_representable_in_the_shared_paced_policy() {
        let policy = dcentrald_common::serial_chain_proof::PacedEnumerationPolicy::new(
            Duration::from_millis(S19K_TRACK1_LADDER_STEP_MS),
            Duration::from_millis(50),
            Duration::from_millis(1000),
            3,
        )
        .expect("the settled Track-1 cadence must be expressible in the shared policy");
        assert_eq!(
            policy.step_delay(),
            Duration::from_millis(S19K_TRACK1_LADDER_STEP_MS)
        );
        assert_eq!(policy.max_coverage_attempts(), 3);
        // The shared policy's non-zero invariants hold for the live cadence:
        // a zero-step or zero-attempt variant must keep being refused there.
        assert!(
            dcentrald_common::serial_chain_proof::PacedEnumerationPolicy::new(
                Duration::ZERO,
                Duration::from_millis(50),
                Duration::from_millis(1000),
                3,
            )
            .is_err()
        );
    }

    /// One CRC-clean BM1366 ChipAddress response body (9 bytes; the serial
    /// HAL strips `AA 55` before the validator sees frames).
    fn s19k_chip_address_body(address: u8) -> Vec<u8> {
        let mut body = vec![0x13, 0x66, 0x00, address, address, 0x00, 0x00, 0x00];
        let crc = dcentrald_asic::protocol::bm13xx_command_response_crc5(&body);
        body.push(crc);
        body
    }

    /// JobResponseTrailer-class garbage (bit 7 set), the exact rejection
    /// class of live attempt 9's trailing frames.
    fn s19k_garbage_tail_frame() -> Vec<u8> {
        vec![0x13, 0x66, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x89]
    }

    #[test]
    fn s19k_salvage_plan_prefix_window_accepts_exact_plan_with_unparseable_tail() {
        let plan = dcentrald_common::s19k_bm1366_wire_b::s19k_aml_linear_addresses();
        let mut responses: Vec<Vec<u8>> = plan
            .iter()
            .map(|&address| s19k_chip_address_body(address))
            .collect();
        for _ in 0..5 {
            responses.push(s19k_garbage_tail_frame());
        }
        let error = validate_serial_chip_address_window(responses.iter().map(Vec::as_slice))
            .expect_err("an unparseable tail must reject the whole burst");
        let window = s19k_salvage_plan_prefix_window(&error, &responses, plan.len())
            .expect("an exact-plan prefix with a pure-noise tail is salvageable");
        assert_eq!(
            window.responder_addresses(),
            plan.as_slice(),
            "the salvaged window must carry exactly the plan responders"
        );
        assert_eq!(
            window.shape(),
            SerialAddressWindowShape::UniqueAssignedAddresses
        );
    }

    #[test]
    fn s19k_salvage_plan_prefix_window_refuses_bad_frame_inside_the_plan() {
        let plan = dcentrald_common::s19k_bm1366_wire_b::s19k_aml_linear_addresses();
        let mut responses: Vec<Vec<u8>> = plan
            .iter()
            .map(|&address| s19k_chip_address_body(address))
            .collect();
        responses[3] = s19k_garbage_tail_frame();
        responses.push(s19k_garbage_tail_frame());
        let error = validate_serial_chip_address_window(responses.iter().map(Vec::as_slice))
            .expect_err("garbage inside the plan must reject the window");
        assert!(
            s19k_salvage_plan_prefix_window(&error, &responses, plan.len()).is_none(),
            "a bad frame inside the plan prefix stays fatal"
        );
    }

    #[test]
    fn s19k_salvage_plan_prefix_window_never_hides_a_parseable_tail_frame() {
        let plan = dcentrald_common::s19k_bm1366_wire_b::s19k_aml_linear_addresses();
        let mut responses: Vec<Vec<u8>> = plan
            .iter()
            .map(|&address| s19k_chip_address_body(address))
            .collect();
        responses.push(s19k_garbage_tail_frame());
        // A parseable duplicate responder after the garbage: the tail is not
        // pure noise, so the prefix slice must not be able to hide it.
        responses.push(s19k_chip_address_body(plan[0]));
        let error = validate_serial_chip_address_window(responses.iter().map(Vec::as_slice))
            .expect_err("a mixed tail must reject the window");
        assert!(
            s19k_salvage_plan_prefix_window(&error, &responses, plan.len()).is_none(),
            "a parseable frame beyond the prefix (a real duplicate) blocks salvage"
        );
    }

    #[test]
    fn s19k_salvage_plan_prefix_window_refuses_non_rejected_error_kinds() {
        let empty: Vec<Vec<u8>> = Vec::new();
        let error = validate_serial_chip_address_window(empty.iter().map(Vec::as_slice))
            .expect_err("an empty window errors");
        assert_eq!(error, SerialChipAddressWindowError::Empty);
        assert!(
            s19k_salvage_plan_prefix_window(&error, &empty, 77).is_none(),
            "non-Rejected error kinds are never salvageable"
        );
    }

    /// SYNTHETIC STRUCTURAL REPLAY of the live attempt-9 ttyS1 coverage
    /// windows (2026-08-28 22:33:31-33 UTC, sharecredit-v5 artifact
    /// 94d64c54…, pre-salvage code).
    ///
    /// Provenance — every tail trailer byte below is a REAL device byte
    /// recovered from the attempt-9 evidence transcript:
    /// `artifacts/s19k-office-gauntlet/attempt9-bounded-work-proof-20260828/
    /// trial-extract/dcentrald_bench_t1_20260828182135_52300/
    /// .startup_daemon_transcript.3485.63062`
    /// (37,372 B, sha256 7f16869dfbceb426e247f7ad86a0a19f2f594e0aaa1da40ded9e
    /// a4972ac7c809): attempt 0 at byte offset 21,465 / line 65 (96 frames,
    /// indices 77..95 rejected), attempt 1 at offset 23,695 / line 66 (92
    /// frames, indices 76 and 78..91 rejected — index 77 parsed clean), and
    /// the terminal attempt-2 window at offset 25,513 / line 67, re-logged by
    /// the init-failure error at offset 30,678 / lines 79-80 (103 frames,
    /// indices 77..102 rejected). Frame counts come from the same lines.
    ///
    /// NOT RECOVERED, and therefore reconstructed: the full 9-byte bodies.
    /// The content-bound bounded-work transcript that retains every
    /// CRC-admitted 11-byte RX frame (deploy-stage.log "Expected bounded
    /// proof" line) was never published — the wrapper deadlocked on the
    /// init-failure path before closeout (EVIDENCE_FACTS.md "Verifier
    /// results": S19K_BOUNDED_TRANSCRIPT_REFUSED) — and no other evidence
    /// file carries frame bytes. The reconstruction is still exact at the
    /// parser level: `parse_serial_chip_address_body` checks the trailer
    /// byte's bit 7 BEFORE reading any other body byte, so each tail frame's
    /// recorded trailer alone reproduces the device-side
    /// `JobResponseTrailer` rejection bit-for-bit (the zero-filled leading
    /// 8 bytes are provably unread by the rejection path), and the plan
    /// prefix uses the same BM1366 plan-address bodies the live window
    /// parsed clean.
    #[test]
    fn s19k_salvage_plan_prefix_window_replays_attempt9_tty_s1_coverage_windows() {
        let plan = dcentrald_common::s19k_bm1366_wire_b::s19k_aml_linear_addresses();
        let plan_prefix = || -> Vec<Vec<u8>> {
            plan.iter()
                .map(|&address| s19k_chip_address_body(address))
                .collect()
        };
        // Trailer byte is the ONLY body byte the rejection path reads.
        let attempt9_tail_frame = |trailer: u8| -> Vec<u8> {
            let mut body =
                vec![0u8; dcentrald_asic::serial_chip_address::SERIAL_CHIP_ADDRESS_BODY_BYTES - 1];
            body.push(trailer);
            body
        };

        // Terminal window (transcript offset 25,534/line 67 + 30,686/lines
        // 79-80): 103 frames = 77-frame plan + 26 tail frames rejected
        // JobResponseTrailer at indices 77..102 with these exact trailers.
        let terminal_tail_trailers = [
            137u8, 152, 130, 155, 129, 151, 155, 152, 134, 158, 152, 135, 148, 149, 143, 145, 152,
            137, 133, 157, 158, 145, 128, 146, 135, 154,
        ];
        let mut terminal = plan_prefix();
        assert_eq!(terminal.len(), 77);
        for &trailer in &terminal_tail_trailers {
            terminal.push(attempt9_tail_frame(trailer));
        }
        assert_eq!(terminal.len(), 103, "attempt-9 terminal window frame count");

        // (a) Attempt-9 reproduction: the whole-burst validator still
        // rejects this exact window, with the exact rejected list.
        let expected_rejected = terminal_tail_trailers
            .iter()
            .enumerate()
            .map(|(offset, &trailer)| {
                dcentrald_asic::serial_chip_address::RejectedSerialChipAddressResponse {
                    response_index: 77 + offset,
                    reason:
                        dcentrald_asic::serial_chip_address::SerialChipAddressResponseError::JobResponseTrailer {
                            trailer,
                        },
                }
            })
            .collect::<Vec<_>>();
        let error = validate_serial_chip_address_window(terminal.iter().map(Vec::as_slice))
            .expect_err("attempt-9 shape: whole-burst validation must still reject");
        assert_eq!(
            error,
            SerialChipAddressWindowError::Rejected(expected_rejected),
            "the replay must reproduce the attempt-9 rejection byte-for-byte"
        );

        // (b) v6 behavior: the salvage path admits exactly the plan-sized
        // prefix, and the downstream exact-plan gate certifies it.
        let window = s19k_salvage_plan_prefix_window(&error, &terminal, plan.len())
            .expect("the attempt-9 terminal window must be salvageable under v6");
        assert_eq!(window.observed_frames().get(), 77);
        assert_eq!(window.responder_addresses(), plan.as_slice());
        assert_eq!(
            window.shape(),
            SerialAddressWindowShape::UniqueAssignedAddresses
        );
        let geometry = ValidatedSerialAssignedGeometry::from_window(
            window,
            dcentrald_common::AsicProtocolIdentity::Bm1366,
            77,
            dcentrald_common::s19k_bm1366_wire_b::S19K_AML_ADDR_INTERVAL,
        )
        .expect("the salvaged prefix must clear the identical exact-plan admission gate");
        assert_eq!(geometry.observed_chip_count(), 77);
        assert_eq!(geometry.addresses, plan);

        // Attempt-0 window (offset 21,486/line 65): 96 frames = 77 plan +
        // 19 tail rejections at indices 77..95 — also salvageable.
        let first_tail_trailers = [
            145u8, 128, 146, 135, 154, 149, 156, 143, 156, 130, 138, 145, 131, 145, 129, 140, 138,
            144, 145,
        ];
        let mut first = plan_prefix();
        for &trailer in &first_tail_trailers {
            first.push(attempt9_tail_frame(trailer));
        }
        assert_eq!(first.len(), 96, "attempt-9 first window frame count");
        let error = validate_serial_chip_address_window(first.iter().map(Vec::as_slice))
            .expect_err("attempt-9 shape: first window must also reject whole-burst");
        assert!(
            s19k_salvage_plan_prefix_window(&error, &first, plan.len()).is_some(),
            "a pure-noise tail beyond an exact-plan prefix is salvageable"
        );

        // Attempt-1 window (offset 23,716/line 66): 92 frames whose rejected
        // count (15) EQUALS 92-77, but index 76 sits inside the plan — the
        // count guard alone would pass; the index guard must stay fatal.
        let mut second = plan_prefix();
        second[76] = attempt9_tail_frame(159);
        second.push(s19k_chip_address_body(plan[0])); // index 77 parsed clean live
        for &trailer in &[
            149u8, 141, 142, 155, 139, 158, 145, 128, 132, 147, 141, 134, 148, 147,
        ] {
            second.push(attempt9_tail_frame(trailer));
        }
        assert_eq!(second.len(), 92, "attempt-9 second window frame count");
        let error = validate_serial_chip_address_window(second.iter().map(Vec::as_slice))
            .expect_err("attempt-9 shape: second window must reject whole-burst");
        assert!(
            matches!(
                &error,
                SerialChipAddressWindowError::Rejected(list)
                    if list.len() == 15 && list[0].response_index == 76
            ),
            "the attempt-1 rejection shape must be reproduced (15 entries, first at index 76)"
        );
        assert!(
            s19k_salvage_plan_prefix_window(&error, &second, plan.len()).is_none(),
            "a bad frame inside the plan must block salvage even when the \
             rejected count equals the tail length (fail-closed)"
        );
    }

    #[test]
    fn s19k_track1_wrap_retired_no_clean_submit_allows_only_never_cleaned_sessions() {
        // Attempt-8d reproduction: nonce 0xD59CA636 (ttyS1 17:59:01.341 /
        // ttyS2 17:59:09.165) met its resolved entry's share target in a
        // session with zero pool cleans and was still refused at submit.
        assert!(
            s19k_track1_wrap_retired_no_clean_submit_allowed(0, true, true),
            "a never-cleaned session must submit a fully validated share whose \
             nonce also solves a wrap-retired (still pool-live) generation"
        );
        // Any observed mid-run clean arms the strict post-clean refusal.
        assert!(
            !s19k_track1_wrap_retired_no_clean_submit_allowed(1, true, true),
            "after a pool clean the wrap-retired refusal must stay intact"
        );
        // Never widen past full-header validation.
        assert!(
            !s19k_track1_wrap_retired_no_clean_submit_allowed(0, true, false),
            "a nonce that does not meet the resolved entry target must never submit"
        );
        assert!(
            !s19k_track1_wrap_retired_no_clean_submit_allowed(0, false, true),
            "the no-clean allowance only applies to wrap-retired meets"
        );
    }

    #[test]
    fn s19k_track1_duplicate_rx_share_credit_requires_submitted_or_accepted_share() {
        use S19kDuplicateSharePathCredit::*;
        // Attempt-8d: the pool accepted 0x1CC0FC36 at 17:57:17.009 via ttyS1;
        // ttyS2 rx-admitted the same frame at 17:57:18.248 (after the result).
        assert_eq!(
            s19k_track1_duplicate_rx_share_credit(false, true, true, false),
            CreditAcceptedNow,
            "an already-accepted share's duplicate extraction credits its path now"
        );
        // The duplicate arrived while the pool result was still pending.
        assert_eq!(
            s19k_track1_duplicate_rx_share_credit(true, false, true, false),
            RecordPendingResult,
            "a submitted-but-unresolved duplicate records its path for later credit"
        );
        // A duplicate of a share that was never submitted credits nothing.
        assert_eq!(
            s19k_track1_duplicate_rx_share_credit(false, false, true, false),
            NoCredit
        );
        // Only required TX paths are creditable, and only once.
        assert_eq!(
            s19k_track1_duplicate_rx_share_credit(true, true, false, false),
            NoCredit,
            "a non-required path must never enter accepted_paths"
        );
        assert_eq!(
            s19k_track1_duplicate_rx_share_credit(true, true, true, true),
            NoCredit,
            "an already-credited path is not credited twice"
        );
    }

    #[test]
    fn s19k_bounded_proof_credits_duplicate_rx_paths_on_pool_accept() {
        let source = include_str!("serial_mining.rs");
        // The dedup refusal must consult the duplicate-path credit before
        // dropping the extraction.
        let dedup = source
            .split_once("\"Duplicate serial share candidate ignored\"")
            .expect("serial share dedup site");
        let dedup_block = dedup.0;
        let credit_call = dedup_block
            .rfind("s19k_track1_duplicate_rx_share_credit")
            .expect("dedup site must decide duplicate-path credit");
        let admit = dedup_block
            .rfind("if !bookkeeping.admit_share")
            .expect("bookkeeping dedup refusal");
        assert!(
            admit < credit_call,
            "the duplicate-path credit decision must live inside the dedup \
             refusal branch, after full per-path validation"
        );
        // The pool-result accepted branch must drain the recorded duplicate
        // paths and credit required paths with a distinct evidence event.
        let pool_result_arm = source
            .split_once("S19K_BOUNDED_WORK_POOL_RESULT_EVIDENCE")
            .expect("pool result evidence marker")
            .1;
        let arm_window = &pool_result_arm[..pool_result_arm
            .find("S19k endurance evidence owner disappeared")
            .expect("end of the pool-result arm")];
        let drain = arm_window
            .find("s19k_take_duplicate_rx_share_paths")
            .expect("accepted result must drain duplicate-path records");
        let credit_insert = arm_window
            .find("s19k_bounded_accepted_paths.insert(origin.path.clone())")
            .expect("accepted result credits the submitting path");
        assert!(
            drain < credit_insert,
            "duplicate-path records are drained before the accepted-result path credit"
        );
        assert!(
            arm_window.contains("pool-result-duplicate-path-credit"),
            "duplicate-path credit must emit its own bounded-proof evidence event"
        );
        // The no-clean wrap-retired allowance must be wired from the funnel's
        // clean counter into the submit gate.
        let submit_gate = source
            .split_once("let mut post_clean_submit_ok")
            .expect("post-clean submit gate")
            .1;
        let gate_window = &submit_gate[..submit_gate
            .find("S19k leftover/ambiguous post-clean nonce refused at submit")
            .expect("end of the submit gate")];
        let wiring = gate_window
            .find("s19k_track1_wrap_retired_no_clean_submit_allowed")
            .expect("no-clean wrap-retired allowance is computed at the submit gate");
        let funnel_cleans = gate_window
            .find("clean_funnel.cleans")
            .expect("allowance must read the funnel clean counter");
        assert!(
            wiring < funnel_cleans,
            "the allowance consumes clean_funnel.cleans at the submit gate"
        );
    }

    #[test]
    fn s19k_coverage_denial_detail_renders_duplicate_and_off_plan_addresses() {
        // Attempt-7 shape: one duplicated plan responder plus an off-plan
        // responder must both be visible in the rendered coverage error.
        let detail = s19k_coverage_denial_detail(&[0x0C, 0x14], &[0x9A]);
        assert!(
            detail.contains("duplicate_addresses=[0C,14]"),
            "duplicate assigned addresses must render in the coverage error: {detail}"
        );
        assert!(
            detail.contains("off_plan_responders=[9A]"),
            "off-plan responders must render in the coverage error: {detail}"
        );
        assert_eq!(
            s19k_coverage_denial_detail(&[], &[]),
            " duplicate_addresses=[none] off_plan_responders=[none]",
            "empty sets render an explicit none"
        );
        // The live attempt-7 window was entirely on-plan.
        let plan = dcentrald_common::s19k_bm1366_wire_b::s19k_aml_linear_addresses();
        let observed_attempt7 = [
            0x00, 0x02, 0x04, 0x06, 0x08, 0x0A, 0x0E, 0x10, 0x12, 0x16, 0x1A, 0x1C, 0x1E, 0x20,
            0x22, 0x24, 0x28, 0x2C, 0x30, 0x32, 0x34, 0x36, 0x38, 0x3A, 0x3E, 0x42, 0x46, 0x4E,
            0x50, 0x52, 0x56, 0x5A, 0x5E, 0x60, 0x62, 0x64, 0x66, 0x68, 0x6A, 0x6E, 0x72, 0x76,
            0x78, 0x7A, 0x7C, 0x7E, 0x80, 0x82, 0x86, 0x88, 0x8A, 0x8E, 0x94, 0x96, 0x98,
        ];
        assert!(
            s19k_off_plan_responders(&plan, &observed_attempt7).is_empty(),
            "the attempt-7 observed set was on-plan, so its off-plan render is empty"
        );
        assert_eq!(
            s19k_off_plan_responders(&plan, &[0x9A]),
            vec![0x9A],
            "an off-plan responder is surfaced for desk triage"
        );
        // Both coverage-error sites must render the detail (attempt-7
        // follow-up: the parsed sets were computed but never shown).
        let source = include_str!("serial_mining.rs");
        let coverage = source
            .split_once("Track-1 coverage held no exact-plan window across retries")
            .expect("coverage retry fence")
            .0;
        let coverage_block = &coverage[coverage
            .rfind("for attempt in 0..3")
            .expect("coverage retry loop")..];
        let from_window_error = coverage_block
            .find("&observed_duplicates,")
            .expect("from_window denial must render duplicate/off-plan sets");
        let rejected_error = coverage_block[from_window_error..]
            .find("&rejected_window_duplicates,")
            .map(|offset| from_window_error + offset)
            .expect("validator rejection must render the raw-body duplicate set");
        assert!(from_window_error < rejected_error);
    }

    #[test]
    fn s19k_runtime_drains_actor_events_before_terminal_exit() {
        let source = include_str!("serial_mining.rs");
        let runtime = source
            .split_once("let mut last_serial_actor_progress")
            .expect("serial runtime progress marker")
            .1
            .split_once("info!(\"=== SHUTDOWN ===\");")
            .expect("serial runtime shutdown marker")
            .0;
        let biased = runtime.find("biased;").expect("biased runtime select");
        let event = runtime
            .find("Some(event) = serial_event_rx.recv()")
            .expect("ordered serial actor event consumer");
        let exit = runtime
            .find("exit = serial_actor_exit_rx.recv()")
            .expect("serial actor terminal consumer");
        assert!(
            biased < event && event < exit,
            "a ready terminal channel must not overtake queued commit/RX events"
        );
    }

    #[test]
    fn s19k_partial_receipt_cannot_publish_global_ownership() {
        let source = include_str!("serial_mining.rs");
        let consumer = source
            .split_once("Some(event) = serial_event_rx.recv()")
            .expect("serial actor event consumer")
            .1
            .split_once("let resp = &hit.body;")
            .expect("physical commit consumer boundary")
            .0;
        let partial_guard = consumer
            .find("refusing global outstanding/history publication because ownership is path-specific")
            .expect("partial-commit publication refusal");
        let publish = consumer
            .find("outstanding_s19k_tx.insert_wire_retiring")
            .expect("global outstanding publication");
        assert!(
            partial_guard < publish,
            "path-specific partial commit must terminate before global publication"
        );
    }

    #[test]
    fn s19k_clean_gate_uses_header_resolved_attribution() {
        let source = include_str!("serial_mining.rs");
        let attribution = source
            .split_once("let retry_slots = if is_bm1366")
            .expect("S19k attribution start")
            .1
            .split_once("S19k local-share attribution")
            .expect("S19k attribution end")
            .0;
        let resolve = attribution
            .find("let resolved_share =")
            .expect("header-resolved candidate search");
        let history = attribution
            .find("let history_job_id = resolved_share")
            .expect("resolved history preference");
        let clean_gate = attribution
            .find("let mut post_clean_submit_ok")
            .expect("post-clean gate");
        assert!(
            resolve < history && history < clean_gate,
            "clean policy must consume the target-valid attribution, not the first occupied slot"
        );
        assert!(attribution.contains("resolved_share.as_ref()"));
    }

    #[test]
    fn serial_actor_receiver_loss_and_three_read_errors_are_terminal() {
        let shutdown = CancellationToken::new();
        let backend =
            FakeSerialActorBackend::new(vec![Ok(Some(vec![0xAA, 0x55]))], shutdown.clone());
        let (nonce_tx, nonce_rx) = mpsc::channel(1);
        drop(nonce_rx);
        let (exit, _, _) = run_fake_serial_actor(backend, Vec::new(), nonce_tx, shutdown, true);
        assert!(matches!(
            exit,
            SerialActorExit::Failed(reason) if reason.contains("nonce receiver closed")
        ));

        let shutdown = CancellationToken::new();
        let backend = FakeSerialActorBackend::new(
            vec![
                Err(anyhow::anyhow!("read one")),
                Err(anyhow::anyhow!("read two")),
                Err(anyhow::anyhow!("read three")),
            ],
            shutdown.clone(),
        );
        let (nonce_tx, _nonce_rx) = mpsc::channel(1);
        let (exit, _, _) = run_fake_serial_actor(backend, Vec::new(), nonce_tx, shutdown, true);
        assert!(matches!(
            exit,
            SerialActorExit::Failed(reason) if reason.contains("3 consecutive times")
        ));
    }

    #[test]
    fn bm1362_nonce_safety_distinguishes_startup_midrun_and_disabled() {
        let mut guard = Am2NonceSafetyGuard::new(10, Some(Duration::from_secs(300)));
        assert_eq!(guard.evaluate(Duration::from_secs(100)), None);
        guard.observe_dispatch(Duration::from_secs(100));
        assert_eq!(guard.evaluate(Duration::from_secs(109)), None);
        assert_eq!(
            guard.evaluate(Duration::from_secs(110)),
            Some(Am2NonceSafetyTrip::StartupNoNonce)
        );
        assert_eq!(guard.evaluate(Duration::from_secs(999)), None);

        let mut midrun = Am2NonceSafetyGuard::new(10, Some(Duration::from_secs(300)));
        midrun.observe_dispatch(Duration::from_secs(5));
        midrun.observe_valid_nonce(Duration::from_secs(12));
        assert_eq!(midrun.evaluate(Duration::from_secs(311)), None);
        assert_eq!(
            midrun.evaluate(Duration::from_secs(312)),
            Some(Am2NonceSafetyTrip::MidRunNonceStall)
        );

        let mut paused = Am2NonceSafetyGuard::new(10, Some(Duration::from_secs(300)));
        paused.observe_dispatch(Duration::ZERO);
        paused.pause_for_missing_pool_authority();
        assert_eq!(paused.evaluate(Duration::from_secs(10_000)), None);

        let mut disabled = Am2NonceSafetyGuard::new(0, None);
        disabled.observe_dispatch(Duration::ZERO);
        disabled.observe_valid_nonce(Duration::from_secs(1));
        assert_eq!(
            disabled.evaluate(Duration::from_secs(u32::MAX as u64)),
            None
        );
    }

