    #[test]
    fn serial_rolled_version_reconstructs_when_pool_did_not_negotiate_mask() {
        // Updated 2026-05-15 (cross-platform Protocol fix sweep):
        // BM1362-family chips roll BIP320 unconditionally regardless of
        // pool `mining.configure` negotiation. The previous test asserted
        // a "drop on version_bits_raw != 0 when version_mask == 0" early
        // return, which was the silent-drop bug responsible for the .135
        // Amlogic 0.023% accept rate (per
        //  F1).
        // Now we reconstruct the rolled version unconditionally;
        // validate_full_header is the SOLE gate.
        let entry = sample_entry(0x2000_0000, 0);

        // vbits=0 â†’ base_version (no rolling, identity).
        assert_eq!(
            serial_rolled_version(&entry, 0, false, 0, false),
            Some(0x2000_0000)
        );
        // vbits=1, mask=0 â†’ reconstruct rolled version: (1 << 13) & 0x1FFFE000 = 0x2000;
        // rolled = (0x2000_0000 & !0x1FFFE000) | 0x2000 = 0x2000_2000.
        assert_eq!(
            serial_rolled_version(&entry, 1, false, 0, false),
            Some(0x2000_2000)
        );
        // vbits with the BIP320 field maximally set (vbits=0xFFFF) â†’
        // delta = 0x1FFFE000 (full mask); rolled = 0x2000_0000 | 0x1FFFE000.
        assert_eq!(
            serial_rolled_version(&entry, 0xFFFF, false, 0, false),
            Some(0x2000_0000 | 0x1FFF_E000)
        );
    }

    #[test]
    fn serial_rolled_version_retains_full_field_for_later_pool_admission() {
        let entry = sample_entry(0x2000_0000, 0x0000_6000);

        assert_eq!(
            serial_rolled_version(&entry, 1, false, 0, false),
            Some(0x2000_2000)
        );
        assert_eq!(
            serial_rolled_version(&entry, 4, false, 0, false),
            Some(0x2000_8000)
        );
        // : BM1366 fill is midstate0 OR, not BIP320 strip. vbits 0x0304
        // ORs onto packed ver0 (same as reconstruct when base has no 13..28).
        assert_eq!(
            serial_rolled_version(&entry, 0x0304, false, 0, true),
            Some(0x2000_0000 | 0x0060_8000)
        );
        // Pool nVersion bits 13..28 must survive UART vbits=0 (packed ver0).
        let packed = sample_entry(0x2000_6000, 0x0000_6000);
        assert_eq!(
            serial_rolled_version(&packed, 0, false, 0, true),
            Some(0x2000_6000)
        );
        assert_eq!(
            serial_rolled_version(&packed, 0, false, 0, false),
            Some(0x2000_0000)
        );
    }

    #[test]
    fn serial_pool_version_checks_both_set_and_cleared_base_bits() {
        for (base, mask, field, permitted) in [
            (0x2000_0000, 0, 0, true),
            (0x2000_0000, 0, 1, false),
            (0x2000_2000, 0, 1, true),
            (0x2000_2000, 0, 0, false),
            (0x2000_2000, 0x4000, 1, true),
            (0x2000_2000, 0x4000, 0, false),
            (0x2000_6000, 0x2000, 2, true),
            (0x2000_6000, 0x2000, 0, false),
            (0x2000_0000, 0x6000, 3, true),
            (0x2000_0000, 0x6000, 4, false),
        ] {
            let entry = sample_entry(base, mask);
            let rolled = serial_rolled_version(&entry, field, false, 0, false)
                .expect("pool permission must not suppress full-header reconstruction");
            assert_eq!(
                serial_pool_version_admitted(&entry, rolled, false, false),
                permitted,
                "base={base:08x} mask={mask:08x} field={field:04x}"
            );
        }
    }

    #[test]
    fn serial_pool_version_genesis_matches_the_actual_v1_wire_header() {
        for (base, mask, permitted) in [
            (1, 0, true),
            (0x2001, 0, false),
            (0x2001, 0x2000, true),
            (0x2001, 0x4000, false),
        ] {
            let mut entry = sample_entry(base, mask);
            entry.prev_block_hash = [0; 32];
            entry.merkle_root = [
                0x3b, 0xa3, 0xed, 0xfd, 0x7a, 0x7b, 0x12, 0xb2, 0x7a, 0xc7, 0x2c, 0x3e, 0x67, 0x76,
                0x8f, 0x61, 0x7f, 0xc8, 0x1b, 0xc3, 0x88, 0x8a, 0x51, 0x32, 0x3a, 0x9f, 0xb8, 0xaa,
                0x4b, 0x1e, 0x5e, 0x4a,
            ];
            entry.ntime = 1231006505;
            entry.nbits = 0x1d00ffff;
            entry.share_target = dcentrald_stratum::work::difficulty_to_target(256.0);
            let rolled = serial_rolled_version(&entry, 0, false, 0, false).unwrap();
            assert_eq!(rolled, 1);
            let header = serial_build_header(&entry, rolled, 2083236893);
            assert!(dcentrald_stratum::share_pipeline::validate_full_header(
                &header,
                &entry.share_target
            ), "the independent Genesis header remains a valid ticket even when pool submission is forbidden");
            let version_bits = dcentrald_stratum::work::bip310_version_bits(rolled, mask);
            let request = dcentrald_stratum::v1::messages::submit_request(
                1,
                "worker.native",
                &entry.job_id,
                &entry.extranonce2,
                &format!("{:08x}", entry.ntime),
                "7c2bac1d",
                version_bits.as_deref(),
            );
            let json: serde_json::Value =
                serde_json::from_str(&serde_json::to_string(&request).unwrap()).unwrap();
            let params = json["params"].as_array().unwrap();
            assert_eq!(params.len(), if mask == 0 { 5 } else { 6 });
            let wire_version = if mask == 0 {
                base
            } else {
                (base & !mask)
                    | (u32::from_str_radix(params[5].as_str().unwrap(), 16).unwrap() & mask)
            };
            assert_eq!(wire_version == rolled, permitted);
            assert_eq!(
                serial_pool_version_admitted(&entry, rolled, false, false),
                permitted
            );
            let wire_header = serial_build_header(&entry, wire_version, 2083236893);
            assert_eq!(wire_header == header, permitted);
        }
    }

    #[test]
    fn serial_pool_version_leaves_bm1398_and_s19k_reconstruction_unchanged() {
        let entry = sample_entry(0x2000_6000, 0x6000);
        for midstate in 0..4 {
            let mut expected = entry.version;
            for _ in 0..midstate {
                expected =
                    dcentrald_stratum::work::increment_bitmask_pub(expected, entry.version_mask);
            }
            assert_eq!(
                serial_rolled_version(&entry, 0xffff, true, midstate, false),
                Some(expected)
            );
            assert!(serial_pool_version_admitted(&entry, expected, true, false));
        }
        assert!(serial_rolled_version(&entry, 0, true, 4, false).is_none());
        let entry = sample_entry(0x2000_6000, 0);
        for field in [0, 1, 0x0304, 0xffff] {
            let actual = serial_rolled_version(&entry, field, false, 0, true).unwrap();
            assert_eq!(actual, s19k_braiins_midstate0_version(entry.version, field));
            assert!(serial_pool_version_admitted(&entry, actual, false, true));
        }
    }

    #[test]
    fn live407_uart_vbits_hash_is_ticket_valid_not_434faee1() {
        // WORK #1 Closed11d + Nonce #1. Drives shipped parse + midstate0 OR +
        // validate_full_header. Does not invent an accepted share.
        let body = [0x87, 0xD9, 0x6C, 0x10, 0x00, 0x00, 0x00, 0xA0, 0x94];
        let share = parse_bm1366_braiins_fill_share_from_body(&body, 0x2000_0000).unwrap();
        let wire: [u8; 88] = [
            0x55, 0xAA, 0x21, 0x36, 0x00, 0x01, 0x00, 0x00, 0x00, 0x00, 0x3D, 0x35, 0x02, 0x17,
            0x01, 0x12, 0x82, 0x6A, 0xBC, 0x3E, 0x86, 0x1D, 0x0D, 0x83, 0xEE, 0xD4, 0x32, 0xBB,
            0xE1, 0xDD, 0x7E, 0x09, 0x0C, 0xB1, 0xA3, 0x64, 0x5B, 0x00, 0x67, 0xDE, 0x69, 0x0D,
            0xB0, 0xB4, 0xE5, 0x2C, 0xE6, 0xFD, 0xD4, 0xD1, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
            0x00, 0x00, 0xF4, 0x23, 0x01, 0x00, 0x01, 0x0A, 0x87, 0xED, 0x09, 0xC3, 0x3B, 0x48,
            0x99, 0x2E, 0x9A, 0x7B, 0xA7, 0x70, 0xD1, 0x53, 0xE2, 0xA2, 0xC8, 0xDD, 0x00, 0x00,
            0x00, 0x20, 0x3F, 0xB0,
        ];
        let mut merkle = [0u8; 32];
        merkle.copy_from_slice(&wire[18..50]);
        let mut prev = [0u8; 32];
        prev.copy_from_slice(&wire[50..82]);
        let entry = WorkEntry {
            generation: 1,
            work_generation: dcentrald_stratum::WorkGeneration::UNTRACKED,
            job_id: "6a72bdc000008958".to_string(),
            extranonce2: String::new(),
            ntime: u32::from_le_bytes(wire[14..18].try_into().unwrap()),
            nbits: u32::from_le_bytes(wire[10..14].try_into().unwrap()),
            version: 0x2000_0000,
            version_mask: 0,
            share_target: [
                0x00, 0x00, 0x00, 0x00, 0x00, 0x06, 0x8D, 0xB8, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
                0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
                0x00, 0x00, 0x00, 0x00,
            ],
            prev_block_hash: reverse_32bit_words(&prev),
            merkle_root: reverse_32bit_words(&merkle),
        };
        let zeroed = serial_rolled_version(&entry, 0, false, 0, true).unwrap();
        let rolled =
            serial_rolled_version(&entry, share.version_bits as u16, false, 0, true).unwrap();
        assert_eq!(zeroed, 0x2000_0000);
        assert_eq!(rolled, 0x2014_0000);
        let bad = serial_build_header(&entry, zeroed, share.nonce_le);
        let good = serial_build_header(&entry, rolled, share.nonce_le);
        assert!(!dcentrald_stratum::share_pipeline::validate_full_header(
            &bad,
            &entry.share_target
        ));
        let good_be = serial_full_header_hash_be(&good);
        assert_eq!(&good_be[..5], &[0x00, 0x00, 0x00, 0x00, 0x00]);
        // Ticket-valid prefix is exactly five zero bytes; byte 5 (0x9B) sits
        // above the share target's 0x06, which is what keeps line-19031's
        // "does not validate" true — this is a ticket, not an accepted share.
        assert_eq!(good_be[5], 0x9B);
        assert_eq!(
            &good_be[..8],
            &[0x00, 0x00, 0x00, 0x00, 0x00, 0x9B, 0x6F, 0x81]
        );
        assert!(!dcentrald_stratum::share_pipeline::validate_full_header(
            &good,
            &entry.share_target
        ));
        assert!(dcentrald_stratum::share_pipeline::validate_full_header(
            &good,
            &dcentrald_stratum::work::difficulty_to_target(256.0),
        ));
    }

