    #[test]
    fn bm1366_native_route_requires_configured_request_then_evidence_joined() {
        let source = include_str!("serial_mining.rs")
            .split("\n#[cfg(test)]\nmod tests {")
            .next()
            .expect("production serial-mining source");
        let identity = source
            .find("let is_bm1366_family = resolved_chip_id == 0x1366;")
            .expect("BM1366 catalog identity boundary");
        let request_gate = source[identity..]
            .find("if is_bm1366 && !passthrough")
            .map(|offset| identity + offset)
            .expect("BM1366 native request gate");
        let optional_observation = source[identity..]
            // Re-anchored 2026-09-01 (Lane-F): production drifted to the
            // install-custody branch form in 25ea0e9b1, so the historical
            // `let nopic = is_nopic(&self.config)?;` literal only self-matched
            // test bodies. Same statement, same ordering intent.
            .find("let nopic = if s19k_install_custody_safeoff || is_bm1362_aml || is_bm1366_xp {")
            .map(|offset| identity + offset)
            .expect("optional EEPROM-backed NoPic observation");
        assert!(request_gate < optional_observation);
        let gate = &source[request_gate..optional_observation];
        assert!(gate.contains("self.s19k_native_cold_start_requested()"));
        assert!(gate.contains("native BM1366 requires an admitted am3-s19k serial configuration"));
        assert!(gate.contains("the flag alone grants no hardware authority"));
        for forbidden in [
            "read_hashboard_eeprom",
            "enable_psu",
            "release_mapped_resets_checked",
            "SerialChainBackend::open",
        ] {
            assert!(
                !gate.contains(forbidden),
                "request gate gained hardware authority: {forbidden}"
            );
        }

        let transport_chain = source
            .find("let serial = if braiins_bm1366_passthrough_handoff {")
            .expect("serial transport branch chain");
        assert_eq!(
            source
                .matches("let serial = if braiins_bm1366_passthrough_handoff {")
                .count(),
            1,
            "serial transport chain anchor is no longer unique; re-anchor this contract"
        );
        let branch_end = source[transport_chain..]
            .find("} else if is_bm1362_aml || is_bm1366_xp || is_bm1368 || is_bm1370 {")
            .map(|offset| transport_chain + offset)
            .expect("end of BM1366 transport branch");
        assert_eq!(
            source[transport_chain..branch_end]
                .matches("} else if is_bm1366 {")
                .count(),
            1,
            "BM1366 transport-arm anchor must appear exactly once inside the transport chain"
        );
        let branch_start = source[transport_chain..branch_end]
            .find("} else if is_bm1366 {")
            .map(|offset| transport_chain + offset)
            .expect("BM1366 transport branch inside the serial transport chain");
        let branch = &source[branch_start..branch_end];
        assert_eq!(
            branch.matches("} else if ").count(),
            1,
            "BM1366 transport-arm window re-anchored; it must span exactly one arm"
        );
        assert!(branch.contains("let native_bringup_result"));
        assert!(branch.contains("S19kNativeColdStartOwner::join("));
        assert!(branch.contains(".promote_s19k_native_cold_start(&mut cold_owner)"));
        assert!(branch.contains("Self::init_bm1366_chains(native_backends, target_freq)"));
        assert!(branch.contains("closeout_native_nopic_failure("));
        assert!(!branch.contains("non-passthrough BM1366 is refused before"));
        assert!(!source.contains("pending_bhb56_endpoints"));
        assert!(!source.contains("legacy_dspic_sessions"));
    }

    #[test]
    fn bm1398_native_route_consumes_exact_admission_before_generic_hardware() {
        let source = include_str!("serial_mining.rs");
        let production = source.split("\n#[cfg(test)]\nmod tests {").next().unwrap();
        let run = production
            .split("pub async fn run(&mut self)")
            .nth(1)
            .unwrap();
        let branch = run.find("if is_bm1398 && !passthrough").unwrap();
        let dispatch = run[branch..]
            .find("return crate::s19_bm1398_native_mining::run(")
            .unwrap()
            + branch;
        let observation = run
            .find("let nopic = if s19k_install_custody_safeoff || is_bm1362_aml || is_bm1366_xp {")
            .unwrap();
        assert!(
            dispatch < observation,
            "BM1398 must hand off before generic serial hardware discovery"
        );
        let admission: String = run[branch..dispatch].split_whitespace().collect();
        assert!(admission.contains("runtime_dispatch_admission.take()"));
        assert!(admission
            .contains("admission.identity()==dcentrald_common::AsicProtocolIdentity::Bm1398"));
        // R07 family extension: the join is the exact BM1398 platform table,
        // not a per-target string compare.
        assert!(admission.contains(
            "crate::s19_bm1398_native_mining::platform::Bm1398Platform::from_admission(admission.board_target(),admission.identity(),)"
        ));
        assert!(!admission.contains("s19pro_native_cold_start_opt_in"));
        // Positive work, factory matching, faults and terminal closeout are
        // exercised in the actual native module and retained-owner executors.
    }

    #[test]
    fn exact_am2_bm1362_init_uses_constructor_plan_and_retained_observations() {
        let source = include_str!("serial_mining.rs");
        let capture_start = source
            .find("impl Am2Bm1362DirectSerialAdmission")
            .expect("exact route constructor");
        let capture_end = source[capture_start..]
            .find("pub struct SerialMiner")
            .map(|offset| capture_start + offset)
            .expect("exact route constructor boundary");
        let capture = &source[capture_start..capture_end];
        let discover = ["discover_system_am2_", "controller_plan"].concat();
        assert!(capture.contains(&discover));

        let get_version_call = [
            "Self::pic_read_fw_version_service",
            "(i2c_service, pic_addr)",
        ]
        .concat();
        assert_eq!(
            source.matches(&get_version_call).count(),
            1,
            "AM2 endpoint binding must not add a second GET_VERSION transaction"
        );

        let branch_start = source
            .find("let (detected_fw, detected_fw_reply)")
            .expect("existing BM1362 firmware observation");
        let branch_end = source[branch_start..]
            .find("observation.observe_preserve_state(pic_addr)?;")
            .map(|offset| branch_start + offset)
            .expect("BM1362 post-enable proof boundary");
        let branch = &source[branch_start..branch_end];
        assert_eq!(
            branch.matches(&discover).count(),
            0,
            "the exact BM1362 branch must consume the constructor-captured plan, never rediscover controller identity"
        );
        assert!(branch.contains("route.controller_plan()"));
        assert!(branch.contains("retained_eeprom_bytes"));
        assert!(branch.contains("bind_am2_hashboard_presence("));
        assert!(branch.contains("bind_am2_controller_endpoint_from_observation("));
        assert!(branch.contains("&detected_fw_reply"));
        assert!(branch.contains("Pic0x89EndpointSession::new"));
        assert!(branch.contains("refusing raw-address fallback"));
        assert!(!branch.contains("Pic0x89Service::new_with_fw"));
        assert!(!branch.contains("DspicService::new("));
    }

